-- Fill missing zhTW page_text_locale rows, converted from zhCN via OpenCC s2twp,
-- with known-official zone-name corrections applied
DELETE FROM `page_text_locale` WHERE `ID` = 15 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (15,'zhTW','你好，摩根。$B$B閃金鎮的交易非常繁忙，所以我根本抽不出時間來幫你送貨！$B$B我已委託幫我送這封信的人給你帶去一包大蜡燭（你知道，可笑的狗頭人總喜歡把這些東西戴在頭上）。$B$B請向這位送貨的人表示我們的感謝，並給予他合理的報酬。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 16 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (16,'zhTW','致尊敬的克雷利安校長，$B$B我以前的主人，我寫這封信是為了讓您瞭解到您的學生最近都做了些什麼。我聽從您的建議離開了我深愛的暴風城，在世界各地到處遊歷，以此來歷練我的知識與智慧。我去過許多地方，最後決定在月溪鎮這個可愛的小鎮定居。隨著收穫季節的到來，西部荒野的農田景色是如此的美麗。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 17 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (17,'zhTW','剛到這裡沒幾天，我就開始為附近農場中的孩子們上課了。我的課程進行得很順利，鎮長便委任我設立了一所學校，而且現在已經開始動工修建一所全新的校舍了！我從銀松森林到暴風城，現在又來到月溪鎮——誰能想到我會在艾澤拉斯經歷那麼多的事情！$B$B向您致意，$B$B斯塔文·密斯特曼託',0);
DELETE FROM `page_text_locale` WHERE `ID` = 18 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (18,'zhTW','尊貴的大人，$B$B我聽說您需要為您的孩子找個老師。現在我暫時住在閃金鎮的獅王之傲旅店裡，由於目前月溪鎮糟糕的狀況，我被迫放棄了學校校長一職。我願做您孩子的老師，希望您能接受我的申請。如果有必要，克雷利安校長可以向您證明我的能力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 19 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (19,'zhTW','當冬天的雨季過後，道路適合旅行的時候，我會親自前去找您。$B$B屆時再見，$B$B斯塔文·密斯特曼託寫於銀松森林',0);
DELETE FROM `page_text_locale` WHERE `ID` = 20 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (20,'zhTW','……那個叫基爾斯的男孩似乎很難管教，對我來說也許是個挑戰。他的姐姐蒂羅亞則是個非常聰明的孩子，她的美貌也格外引人注目，蒂羅亞渾身都散發著女人獨有的氣質，而他們家可能已經安排她在明年結婚了。我有點跑題了。這個星期我會陪他們一家人到他們那座艾爾文森林東谷伐木場附近的夏季別墅去度假，那裡離赤脊山很近。我希望能在那兒再給您寫信。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 21 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (21,'zhTW','……奇特，無法自控，今天我感受到了這種以前從未有過的感覺。在我輔導基爾斯學習歷史的時候，蒂羅亞正在外面照料著她的花園。過了一會，她走了進來，把鮮紅的秋海棠放在我的手心上，對我嫣然一笑，我感到自己的心在猛烈地跳動……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 22 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (22,'zhTW','……我敢肯定，她和我有著相同的感覺。今天早晨，她甚至把手放在了我的手掌中。當她微笑的時候，她的眼眸像鑽石一樣閃亮。我們進行著無言的交流，她已經佔據了我的心，她讓我的全身熱血沸騰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 23 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (23,'zhTW','……我從未想過自己會這麼憤怒！她怎麼敢這樣對我！我教基爾斯數學的時候，蒂羅拉來了，還帶著她的一個求婚者，他們竟公然手拉著手！真是個沒教養的年輕人。蒂羅亞也沒怎麼介紹我，只是輕描淡寫地說了句，“哦，這是我的家庭教師，斯塔文叔叔。他是個不錯的老人。”老人！一聽到這個詞，我的臉就漲得通紅。我不過比她大了幾歲而已，而她竟背叛了我……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 24 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (24,'zhTW','……我的心彷彿隨著絕望而跌入了無底的深淵。她欺騙了我的感情，現在竟然還訂了婚。這個可惡的騙子，她假裝自己陷入了愛河，其實她一直以來只是想要傷害我而已。我的心裡只有黑壓壓的一片，每過一分鐘，這種感覺就更加強烈一分。我要讓她付出血的代價，但是與我流過的眼淚相比，那是多麼的蒼白無力……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 25 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (25,'zhTW','托米·喬：$B$B隨著時間不斷流逝，我的心因為沒有你的存在而越發的失落。啊，只願我們的家人能夠超越他們之間愚蠢的仇恨，並且能認識到真正的罪惡其實就是這種仇恨。仇恨吞噬了我們的幸福，而且我擔心受難的並非只有我們兩個家族而已。$B$B如果他們能夠明白這些，那麼也許有一天我們可以走到一起。我希望能等到那一天，我將為此而活著。$B$B深愛你的梅貝爾',0);
DELETE FROM `page_text_locale` WHERE `ID` = 26 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (26,'zhTW','你好，威廉，$B$B距離上次我們見面已經過了好幾年，但是我相信你和你的兄弟都一切安好，你的藥劑生意也一定很興旺。$B$B威廉，現在我需要你的幫助。長話短說吧，我的孫子托米·喬與年輕的梅貝爾·馬科倫相愛了。他們互相愛慕……但是我們兩個家族之間已經明爭暗鬥了好幾年。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 27 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (27,'zhTW','我擔心斯通菲爾德和馬科倫家族之間的勾心鬥角會毀掉托米·喬和梅貝爾之間的愛情，在現在這個時代中，即使面對再多黑暗的威脅和戰爭的陰影，我們也應該努力去呵護愛情和年輕的生命。$B$B所以，我希望你能幫忙製作一些隱身藥水，讓這兩個年輕人能夠相聚。$B$B謝謝你，威廉。還有，當你空閒的時候別忘了多來我這裡玩玩。我們已經有好久沒見過面了，我十分懷念以前與你一起度過的快樂時光。$B$B——米爾德麗德',0);
DELETE FROM `page_text_locale` WHERE `ID` = 28 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (28,'zhTW','阿古斯，$B$B正如你所知，我一直因為提供軍隊的補給需求而焦頭爛額。我不應該對自己的工作有所抱怨，但是我們儲備的鐵即將用完。$B$B我已經沒有足夠的鐵來製造馬蹄鐵了。我知道你有大量的儲備，因此我想在下一批鐵運到之前先向你借50雙馬蹄鐵。$B$B對你表示萬分感激，$B$B——弗納',0);
DELETE FROM `page_text_locale` WHERE `ID` = 29 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (29,'zhTW','板條箱上附著一張紙條。上面寫著：$B$B“弗納——聽說赤脊山遇到這樣的麻煩，我感到甚是遺憾。這裡是你所需要的馬蹄鐵。如果方便的話，請你儘快付給我100銀幣。”$B$B“如果你願意的話，也可以用黑色雛龍的下腹部鱗片來支付報酬（我聽說黑色雛龍在赤脊山十分常見）。既然我們是朋友……4塊鱗片就夠了。謝謝你。$B$B——阿古斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 30 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (30,'zhTW','尊敬的大人，$B$B戰爭已經降臨到我們的頭上了。厄運正在一步步地向我們走來。$B$B作為湖畔鎮的鎮長，我有責任向您彙報最近在王國最東部地區所發生的軍事活動。$B$B從我的信中，您可以瞭解到赤脊山地區和湖畔鎮的現狀。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 31 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (31,'zhTW','石堡的失守是一件非常嚴重的事。在以前的報告中，我已經向您詳細說明了黑石氏族的獸人與名為莫甘斯的術士勾結的情況。黑石獸人作戰時兇猛殘暴，此次顯然又得到了莫甘斯的邪惡法術的幫助。陛下的許多勇士都為了保衛要塞不惜犧牲自己的性命，但最後還是沒能守住。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 32 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (32,'zhTW','奇怪的是，在獲得了這場卑鄙的勝利之後，莫甘斯很快就開始轉而攻擊獸人軍團。這個術士在東北方建造了一座神秘的塔樓，並組建了一支小型的暗皮豺狼人軍隊來調遣。獸人和人類都成了這些野蠻而骯髒的怪物的受害者。關於莫甘斯和黑石氏族首領加塞爾佐格之間到底發生了什麼事情，我們也只能推測到以上這樣的程度了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 33 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (33,'zhTW','野蠻的獸人似乎非常傾向於屠殺國王陛下的子民，在過去的兩個星期裡，黑石氏族向湖畔鎮發動了多次進攻，許多勇士都付出了生命。獸人軍隊推進的速度驚人，而且攻勢猛烈，他們甚至將橫跨止水湖的大橋都毀了。我們的補給十分缺乏，連給傷患包紮傷口的繃帶都告罄了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 34 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (34,'zhTW','我請求國王陛下在這個危難的時刻能給予湖畔鎮的人民足夠的支援。我們需要更多的戰士來保衛領土，需要更多的武器裝備來武裝部隊，也需要更多的食品和建築物資。大人，請您幫助我們在構築人類抵禦野蠻獸人的最後一道堡壘。我們決不能讓敵人進入暴風王國的領土。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 35 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (35,'zhTW','北方的土地已經變成了邪惡力量的溫床，我擔心還會有更強大更黑暗的敵人接踵而來。暴風王國必須採取行動，以免讓我們的城鎮淪陷，人民淪為奴役。$B$B此致，$B$B所羅門鎮長$B湖畔鎮$B暴風王國',0);
DELETE FROM `page_text_locale` WHERE `ID` = 36 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (36,'zhTW','尊敬的所羅門鎮長：$B$B我和您一樣為死去的人而哀悼。我會確保讓國王陛下瞭解到目前的狀況，同時我也衷心希望能為湖畔鎮增派援軍。不過奇怪的是，陛下最近沒有什麼舉動，這件事我只能私下對您說說。$B$B請多加保重，$B$B馬庫斯·喬納森將軍$B暴風王國',0);
DELETE FROM `page_text_locale` WHERE `ID` = 37 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (37,'zhTW','尊敬的所羅門鎮長：$B$B我和您一樣為死去的人而哀悼。我會確保讓國王陛下瞭解到目前的狀況，同時我也衷心希望能為湖畔鎮增派援軍。不過奇怪的是，陛下最近沒有什麼舉動，這件事我只能私下對您說說。$B$B請多加保重，$B$B馬庫斯·喬納森將軍$B暴風王國',0);
DELETE FROM `page_text_locale` WHERE `ID` = 38 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (38,'zhTW','斯托曼：$B$B某些膽大的傢伙竟然找了個陌生人來跟我談關於迪菲亞盜賊的事。你曾經救過我一命，而現在你又讓我處於極度的危險中。$B$B不過我還是欠你的人情。迪菲亞兄弟會的勢力遠比你想像中的要大。從西部荒野到艾爾文森林，每座礦坑都在他們的控制之下。他們還徵召了狗頭人和豺狼人執行命令，還有地精為他們鑄造金屬怪物，用於在西部荒野農場上劫掠當地的居民。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 39 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (39,'zhTW','他們有一個龐大的地下網路。斯托曼，這個網路比你所知道的更為龐大。從藏寶海灣到暴風要塞都有他們的勢力。也許你是個勇敢的聖騎士，不過如果你以為憑你的一己之力就能阻止他們，那你就太傻了。他們正在研究一種大規模殺傷性武器。總之，那些石匠的看家本領就是如何製造大傢伙。你不會以為他們的興趣只是南瓜田和葡萄園吧？我已經報答了你為我提供的幫助。現在，離我遠點吧！$B$B——W',0);
DELETE FROM `page_text_locale` WHERE `ID` = 40 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (40,'zhTW','斯托曼大人——$B$B石匠公會由技術最為熟練的建築師組成，其領導者是艾德溫·範克里夫。在第一次獸人戰爭中，暴風城被獸人夷為平地，這些石匠參與了暴風城的重建工作。範克里夫和他的工匠都是出類拔萃的建築師，他們在建築方面的造詣和藝術性從光明大教堂和暴風要塞這兩座建築中就可見一斑。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 41 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (41,'zhTW','斯托曼大人——$B$B石匠公會由技術最為熟練的建築師組成，其領導者是艾德溫·範克里夫。在第一次獸人戰爭中，暴風城被獸人夷為平地，這些石匠參與了暴風城的重建工作。範克里夫和他的工匠都是出類拔萃的建築師，他們在建築方面的造詣和藝術性從光明大教堂和暴風要塞這兩座建築中就可見一斑。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 42 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (42,'zhTW','然而，暴風城的軍事力量從艾爾文森林一直擴張到荊棘谷，這使得暴風城的貴族們背上了沉重的債務。高額債務削弱了整個王國的經濟實力，使他們無法兌現之前對範克里夫和他的石匠所承諾的酬勞。為了重建這座光輝的城市而辛勤工作了數年之後，這些石匠卻心碎地離開了，被城市腐敗的官員們徹底地遺忘。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 43 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (43,'zhTW','我個人和艾德溫·範克里夫相處了很久，根據我對他的瞭解，這麼說吧，與他為敵不是那麼容易的。要知道，他是我兒時的夥伴，是我親自訓練他的，因為我以為有一天他會和我並肩工作。如果範克里夫就是迪菲亞兄弟會的首腦，那麼只能希望聖光憐憫我們的靈魂了。$B$B馬迪亞斯·肖爾大師$B暴風城刺客公會',0);
DELETE FROM `page_text_locale` WHERE `ID` = 44 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (44,'zhTW','我個人和艾德溫·範克里夫相處了很久，根據我對他的瞭解，這麼說吧，與他為敵不是那麼容易的。要知道，他是我兒時的夥伴，是我親自訓練他的，因為我以為有一天他會和我並肩工作。如果範克里夫就是迪菲亞兄弟會的首腦，那麼只能希望聖光憐憫我們的靈魂了。$B$B馬迪亞斯·肖爾大師$B暴風城刺客公會',0);
DELETE FROM `page_text_locale` WHERE `ID` = 45 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (45,'zhTW','幹得好，朋友！現在你需要朝東方前進，沿著懸崖一直向東走。找到路邊廢棄的煙囪，那裡有一隻舊木桶，它可以為你提供下一步行動的線索。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 46 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (46,'zhTW','現在，從這隻桶所在的地方向北方行進。筆直地向前走，當你看到海邊懸崖上的那座風車時，找到風車旁邊的一隻空壺。四處看一下，也許你就能找到你要的東西。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 47 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (47,'zhTW','找到了這隻威士忌酒瓶，你離寶藏就不遠了！從酒瓶的位置向西前進，走到海岸邊，然後下水繼續前進！一直向西邊遊，你就可以看到藏有寶箱的島嶼！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 48 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (48,'zhTW','黑爪：$B$B海洋在等待著我們，而我們需要你從北方運來的補給。盡力收集所有物資，一根鐵軌一隻水桶都不要放過，我們需要足夠的金屬。藏寶海灣那邊本應有貨物運來，但遲遲未到。黑爪，幫幫我，這次把你的補給直接運到“穀倉”去。我們不能再浪費時間了。$B$B——範克里夫',0);
DELETE FROM `page_text_locale` WHERE `ID` = 49 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (49,'zhTW','斯托曼大人：$B$B湖畔鎮請求您的民兵的援助。在我寫這封信的時候，我們正受到黑石氏族獸人和莫甘斯率領的暗皮豺狼人的夾擊。如果形勢不是如此嚴峻的話，我也不會向您求助。我們也在等待暴風城的援助，不過在他們的援軍到來之前，我懇求您能對我們施以援手。暴風王國一旦腹背受敵，整個人類都將面臨著危險。$B$B所羅門鎮長',0);
DELETE FROM `page_text_locale` WHERE `ID` = 50 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (50,'zhTW','尊敬的閣下：$B$B西部荒野為您的失利而哀悼，但是我們這裡也飽受戰爭的困擾，農夫都被盜賊和收割傀儡趕走了，暴風城也撤走了他們的駐軍，留下毫無防禦的我們。在暴風城遺棄了我們之後，我召集組建了西部荒野人民軍，試圖奪回曾經屬於我們的領土。如果我將人民軍調往赤脊山的話，西部荒野必將遭受毀滅。$B$B我表示萬分的遺憾和歉意。$B$B格里安·斯托曼',0);
DELETE FROM `page_text_locale` WHERE `ID` = 51 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (51,'zhTW','埃伯洛克公爵大人：$B$B湖畔鎮請求守夜人的援助。我們正受到黑石氏族獸人和莫甘斯率領的暗皮豺狼人的夾擊。如果形勢不是如此嚴峻的話，我也不會向您求助。我們也在等待暴風城的援助，不過在他們的援軍到來之前，我懇求您能對我們施以援手。暴風王國一旦腹背受敵，整個人類都將面臨著危險。$B$B所羅門鎮長',0);
DELETE FROM `page_text_locale` WHERE `ID` = 52 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (52,'zhTW','尊敬的閣下：$B$B我只能非常遺憾地告知您，守夜人部隊現在不能離開夜色鎮。也許您還沒有注意到，暴風城已經不再為我們這個地區提供軍事支援了。守夜人是完全由鎮中的人民自發組建和訓練的，他們的職責是在沒有暴風城幫助的情況下保衛夜色鎮。沒有守夜人，夜色鎮一定會淪陷。但願您在困境中能有好運。$B$B——艾爾羅·埃伯洛克公爵',0);
DELETE FROM `page_text_locale` WHERE `ID` = 53 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (53,'zhTW','這封信上的字彷彿在不斷地跳動和扭曲，你根本無法看清它們……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 54 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (54,'zhTW','夜色鎮的鎮長埃伯洛克公爵，$B$B您好。$B$B恐怕我有個壞訊息要捎給夜色鎮。$B$B您知道，我是一個創造天才。我欺騙了給您送信的這個蠢貨，騙他幫我完成了我最強大而恐怖的創造——一個用血肉和扭曲的金屬製成的惡魔！當您讀著這封信的時候，它就在我簡陋的屋子外面，張牙舞爪，隨時準備血洗夜色鎮。$B$B您很快就可以看見它了。$B$B——藏屍者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 55 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (55,'zhTW','這是一張西部荒野地產的契約。它賦予在契約上簽名的擁有一塊土地的所有權，以及該土地上面所有農作物和建築物的所有權。$B$B在這份檔案上簽字的人是：$B$B$B$B 瑟多爾·法布隆$B$B$B 弗娜·法布隆',0);
DELETE FROM `page_text_locale` WHERE `ID` = 56 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (56,'zhTW','[契約的背後潦草地寫著以下文字]$B$B我們從法布隆那裡弄到了他的契約，如果你想為自己偽造一份契約的話也很容易，法布隆不會給我們帶來任何麻煩的。我上一次看到他們的時候，他們一家人正在離開西部荒野，不過因為四輪貨車壞掉而不得不停了下來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 57 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (57,'zhTW','[契約的背後潦草地寫著以下文字]$B$B我們從法布隆那裡弄到了他的契約，如果你想為自己偽造一份契約的話也很容易，法布隆不會給我們帶來任何麻煩的。我上一次看到他們的時候，他們一家人正在離開西部荒野，不過因為四輪貨車壞掉而不得不停了下來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 58 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (58,'zhTW','月亮照耀著山谷$B月光灑滿了叢林$B驕傲的戰士響應號召$B保衛我們的國家和神聖的大地$B$B月亮照耀山谷$B遠離戰爭的哭泣$B這裡流淌著$B敵人和我們的鮮血。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 59 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (59,'zhTW','當我們的同胞永遠離去$B走進未知的土地$B在山谷的深處$B靈魂與精神變得堅強$B當我們的同胞永遠離去$B$B來到山上的聖殿$B我們將保衛他們永恆的精神$B將它鑲入神聖的藍水晶$B當我們的同胞永遠離去$B月亮照耀著山谷',0);
DELETE FROM `page_text_locale` WHERE `ID` = 61 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (61,'zhTW','當我們的同胞永遠離去$B走進未知的土地$B在山谷的深處$B靈魂與精神變得堅強$B當我們的同胞永遠離去$B$B來到山上的聖殿$B我們將保衛他們永恆的精神$B將它鑲入神聖的藍水晶$B當我們的同胞永遠離去$B月亮照耀著山谷',0);
DELETE FROM `page_text_locale` WHERE `ID` = 62 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (62,'zhTW','月光和火光，$B肉體和骨頭，$B在鮮血中書寫，$B在石頭上雕刻。$B$B要麼遠離這片土地$B要麼遭遇厄運$B死亡守衛著$B國王的陵墓。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 63 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (63,'zhTW','卡爾文大人：$B$B這位信差已證明自己信仰正義與聖光之道，並有能力與侵擾暮色森林的亡靈和惡魔戰鬥，$g他:她也願意加入卡爾文家族的偉大事業。$B$B我建議您給這位聖光的戰士派遣更多工——有些鎮民可能在暗中幫助與聖光為敵的勢力，不如讓這位$c去調查一下。$B$B您忠誠的卡洛爾',0);
DELETE FROM `page_text_locale` WHERE `ID` = 64 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (64,'zhTW','摩根·拉迪莫爾曾經是一個偉大而高尚的騎士，他為了保衛無辜、貧窮和飽受痛苦的人而戰鬥。多年來，他幾乎跑遍了艾澤拉斯的所有邊遠地區，為受苦的人民帶來安慰，懲戒那些作惡多端的人。$B$B在他十八歲那年的夏天，摩根與一位名叫莉絲的年輕女孩結婚了。他們彼此相愛，後來生了一個兒子和兩個女兒。$B$B在摩根三十二歲那年，洛丹倫的戰爭爆發了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 65 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (65,'zhTW','摩根被召入聖騎士光明使者烏瑟爾的部隊，與獸人和不死生物作戰。因為戰爭，他離開了妻子和兒女，離開了安寧的家園。$B$B數年過去了，戰爭依然沒有結束，摩根親眼目睹了許多可怕的事，他目睹了白銀之手騎士團的解散，目睹了烏瑟爾的死，也目睹了瘟疫的蔓延。只有一件事可以讓他遠離瘋狂和崩潰的邊緣，那就是他相信自己總有一天可以和妻子兒女團聚。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 66 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (66,'zhTW','摩根最終回到了家鄉，但那裡已經不再是他熟悉的景象了。曾經青翠的樹林變得枯萎凋零，散發著墮落的氣息，不死生物和其他黑暗的勢力到處橫行。遍地都是已被損毀的房屋與農場，烏鴉嶺附近的墓地佔據了大片的土地。摩根懷著震驚和迷惑，艱難地回到家中，卻只發現那裡已成廢墟。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 67 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (67,'zhTW','摩根不知道自己的家遭遇了什麼樣的災難，他趕去村莊裡尋找答案，尋找他的妻子和孩子們的訊息。$B$B摩根詢問了許多人，但是沒有找到任何線索。就在現在被稱為夜色鎮的這個地方，有一位牧師告訴他應該到烏鴉嶺的墓地去搜尋一下是否有他妻兒的墓碑。摩根不願相信他的家人會死去，他走遍了暮色森林的每一片農場和每一所房子，但還是一無所獲。$B$B他相信自己的家人已經出去逃難了，於是騎馬從夜色鎮趕往毗鄰的湖畔鎮。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 68 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (68,'zhTW','就在去湖畔鎮的路上，他最終決定到烏鴉嶺的墓地去一次。摩根在墓碑之間穿行了數個小時，看到了許多熟悉的人名被刻在墓碑上，這讓他變得幾近發狂。最後他看到了眾多的墓碑中間有一小片由三塊墓碑組成的墓地，看起來已經很久無人打理了。當他靠近那片墓地的時候，他全身充滿了恐懼。摩根擦去了墓碑上的灰塵，顯出了上面的名字。墓碑上簡單地雕刻著幾行字母，那是他最不願看到的名字：',0);
DELETE FROM `page_text_locale` WHERE `ID` = 69 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (69,'zhTW','莉絲·拉迪莫爾$B$B我們深愛著的妻子與母親$B$B摩根的憂慮立刻變成了沮喪，進而變成了無比的悲痛，他不禁癱在地上開始哭泣。摩根一連幾個小時望著墓碑，一邊哭泣，一邊對著墓碑請求原諒和寬恕。又過了幾個小時，他突然情緒大變，開始發狂，他拔出佩劍，一邊怒吼一邊用劍如狂風暴雨一般砍向墓碑。憤怒讓他變得盲目，他瘋狂地揮舞著劍，不斷地攻擊著。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 70 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (70,'zhTW','他的舉動引起了三個墓地值班人的注意，他們試圖阻止他。摩根注意到了他們，於是他把自己的憤怒和對罪惡的譴責統統傾瀉這些無辜的人身上，最後殺害了他們。$B$B殺人之後，摩根的憤怒逐漸散去，他的腦子也恢復了正常的意識。在看到自己的劍血淋淋地插在一個值班人的胸膛裡時，激烈的情緒將他推向了崩潰的邊緣，他抽出匕首猛然刺入了自己的心臟。$B$B第二天，有人發現了摩根·拉迪莫爾和另外三個無辜者的屍體。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 71 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (71,'zhTW','他被埋葬在墓地旁邊一個匆匆挖掘的墓穴裡，沒有舉行任何葬禮。摩根殺了無辜的人，這完全違背了他的信仰與天性，再加上他因為不能挽救家人而感到了巨大的悲痛，這些使得摩根死後也無法得到安寧。$B$B只過了幾天，人們便發現他的墓穴被破壞，他的屍體也不知所蹤。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 72 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (72,'zhTW','如今，摩根·拉迪莫爾被失去妻兒的痛苦和對自己的仇恨煎熬著，每日都在暮色森林中游蕩。現在他稱自己為摩拉迪姆，滿懷仇恨在暮色森林中徘徊，毫無理智地肆意進行屠殺。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 73 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (73,'zhTW','在過去的幾個星期裡所遭遇到的恐怖令我幾乎要崩潰了，然而寫下我所看見的這些事也許會讓我感到舒服一點。所以我就這麼做了，這也是在現在這段陰冷的日子裡我所能得到的唯一安慰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 74 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (74,'zhTW','第一天$B今天我和學徒來到了寒脊山谷，平安無事地穿過了洞穴之後，我們在巨魔巢穴外面的安全地帶紮了營。$B$B第二天$B該死的狼嚎聲讓我整晚都沒睡著。$B$B明天我就要去弄一套狼皮做的衣服。$B$B今天那個年輕的學徒與石顎怪作戰相當英勇，也成功地戰勝了那些醜陋的東西，不過他的胳膊受傷了，得好好休養一下。看來這陣子得由我來打理了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 77 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (77,'zhTW','第一天$B今天我和學徒來到了寒脊山谷，平安無事地穿過了洞穴之後，我們在巨魔巢穴外面的安全地帶紮了營。$B$B第二天$B該死的狼嚎聲讓我整晚都沒睡著。$B$B明天我就要去弄一套狼皮做的衣服。$B$B今天那個年輕的學徒與石顎怪作戰相當英勇，也成功地戰勝了那些醜陋的東西，不過他的胳膊受傷了，得好好休養一下。看來這陣子得由我來打理了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 78 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (78,'zhTW','這個護甲標誌十分適於綴在皮甲或布甲上，東谷伐木場中的迪博雷恩家族的人可以對它進行加工。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 79 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (79,'zhTW','以下是迪菲亞盜賊從艾爾文森林的礦坑中開採金礦並送往西部荒野總部的日程表。$B$B徵收日程：$B$B週日：中午12：30$B週二：中午12：30$B$B在指定的日子裡，從艾爾文森林的礦坑中開採出來的金礦將被集中在布萊克威爾南瓜田中。負責收取這些貨物的“收貨人”會佩戴一枚我交給他的特殊戒指。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 80 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (80,'zhTW','格瑞林：$B$B我的時間很緊張，很多事情堆積在一起，讓我抽不出身來，希望你對巨魔的調查不會讓我更加繁忙。我授權你對付巨魔，你可以使用任何你認為必要的手段——只要你能找出一個有利的解決方案來。$B$B$B麥格尼·銅鬚',0);
DELETE FROM `page_text_locale` WHERE `ID` = 81 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (81,'zhTW','第三天$B天氣很冷。中午下了點雪。$B$B第四天$B$B小夥子終於恢復了一些，今天他的精神看來不錯，所以我們出去對巨魔進行了第一次偵查。根據它們皮膚上塗抹的標記和所戴的裝飾品，我可以確定他們是霜鬃巨魔。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 82 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (82,'zhTW','第五天$B年輕的學徒守著營地，而我則潛入洞穴觀察了一番。巨魔的數量很多，這是個大麻煩，我們得召集大批巡山人才能把他們從洞穴裡清除掉。$B$B最近我似乎沒有提到過穴居人，他們在這一帶的數量也越來越多了，不過穴居人是個非常原始的種族，不足為患。也許時間可以證明我的看法是對還是錯。另外我一個星期都沒喝過一滴啤酒了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 83 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (83,'zhTW','第六天$B又是寒冷的一天。有雪，有巨魔，沒有酒。$B$B第七天$B地上的雪很白，$B$B天很藍，$B$B狼群又會在夜晚嚎叫，$B$B一滴酒也沒有。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 84 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (84,'zhTW','第八天$B巨魔的麻煩可能不像我們之前所想的那麼嚴重。他們雖然數量眾多，不過沒有很好的裝備和組織。只要組織小股力量就足以解決他們帶來的威脅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 85 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (85,'zhTW','我的日記$B$B過去幾個星期所遭遇的恐怖讓我幾乎崩潰；為什麼在書裡寫下這些文字能讓我免於陷入瘋狂？也許這樣就好像是在對一個沉默的同伴懺悔我的罪行，又像是將那些折磨我的思想從腦中清除，把它們都推到紙上去。$B$B在此之前，我還寫過一次日記，不過那本日記被我放在一個',0);
DELETE FROM `page_text_locale` WHERE `ID` = 86 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (86,'zhTW','關於寒脊山谷地區霜鬃巨魔活動狀況的報告$B$B由參議院外交特使格瑞林·白鬚提交$B$B根據我對寒脊山谷地區霜鬃巨魔的觀察結果來看，我認為他們對這個地區的矮人沒有太大的威脅。只要軍隊施以一點援助就可以消除他們的威脅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 87 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (87,'zhTW','有了駐紮在寒脊山谷的巡山人和我們的僱傭兵（由參議院撥給我的行動基金來支付必需的費用），我相信我們在短時間內就能解決這個問題。$B$B銅鬚陛下已經授權由我來指揮這次行動。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 88 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (88,'zhTW','關於丹莫洛地區霜鬃巨魔活動狀況的報告$B$B丹莫洛的巨魔大部分聚集在霜鬃巨魔要塞，那是本地區西部的一座巨大的山洞。他們的數量眾多，這必須引起我們的注意，但是巨魔們似乎更樂意待在洞內。毫無疑問，這是因為他們不想冒著被滅絕的風險去招惹矮人。即使他們有所行動，那也應該是基於保衛自己領地的原因。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 89 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (89,'zhTW','我認為只要我們不要去侵犯他們的領地，巨魔對我們就不會構成實際的威脅。一般的矮人平民對這種情形可能並不感興趣，不過考慮到軍事資源的分散，為了謹慎行事，我們應該將消滅巨魔的問題放在一個較為次要的位置去考慮，對我們來說，主要的威脅仍然來自穴居怪和黑鐵矮人。$B$B這裡還一併附上了我兄弟格瑞林關於安威瑪爾情況報告的副本。$B$B森內爾·白鬚',0);
DELETE FROM `page_text_locale` WHERE `ID` = 90 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (90,'zhTW','關於寒脊山谷地區霜鬃巨魔活動狀況的報告$B$B由參議院外交特使格瑞林·白鬚提交$B$B根據我對寒脊山谷地區霜鬃巨魔的觀察結果來看，我認為他們對這個地區的矮人沒有太大的威脅。只要軍隊施以一點援助就可以消除他們的威脅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 91 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (91,'zhTW','有了駐紮在寒脊山谷的巡山人和我們的僱傭兵（由參議院撥給我的行動基金來支付必需的費用），我相信我們在短時間內就能解決這個問題。$B$B銅鬚陛下已經授權由我來指揮這次行動。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 92 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (92,'zhTW','親愛的塔雷爾：$B$B請原諒，這封信我寫得很匆忙，但時間對於我們來說真的很寶貴。$B$B挖掘隊對泰坦史前古器物的挖掘工作進展迅速。不過我們還發現了其他的史前遺物——一些巨大的骨頭。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 93 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (93,'zhTW','在挖出巨骨後不久，我們遭到了迅猛龍的攻擊。來自丹莫德軍團的部隊英勇作戰，但最後他們還是被打敗了，幾乎全軍覆沒。我們只有三個人倖存了下來。一個名叫奧莫爾·鐵衣的工人非常英勇，是他保護了我和勘察員維爾加的安全。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 94 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (94,'zhTW','我們在一處隱蔽的洞穴避難，這裡目前似乎挺安全。不過在有軍隊控制住迅猛龍之前，我們還是隻能被困在這裡。維爾加還在想辦法繼續工作，但我知道他可能還心有餘悸。塔雷爾，這就是我們的處境。請布萊德·長鬚立刻派一隻軍隊來營救我們。$B$B即使在這艱難的時刻，我也希望你一切都好。$B$B——麥琳',0);
DELETE FROM `page_text_locale` WHERE `ID` = 95 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (95,'zhTW','荊棘谷的青山$B$B第一天和我們預想中的完全一樣。我們大部分時間都忙於為建立營地做一些必要的準備。我在一條淡水河的入口處找到了理想的駐紮點。根據旁邊被廢棄的古老碼頭判斷，這個地方曾經有人住過，不過只有時間才能說明這裡究竟住過些什麼人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 97 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (97,'zhTW','荊棘谷的青山$B$B第一天和我們預想中的完全一樣。我們大部分時間都忙於為建立營地做一些必要的準備。我在一條淡水河的入口處找到了理想的駐紮點。根據旁邊被廢棄的古老碼頭判斷，這個地方曾經有人住過，不過只有時間才能說明這裡究竟住過些什麼人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 98 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (98,'zhTW','接下來的幾年，在暴風城背叛了石匠公會後，埃爾加丁爵士開始厭惡他的貴族身份。他不願因繼承了他父親的高貴血統而在貴族中獲得崇高的地位。不過我跑題了。這個故事的主題不是政治文章或者人物傳記，而是要敘述我在荊棘谷的青山中獵捕的經歷。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 99 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (99,'zhTW','接下來的幾年，在暴風城背叛了石匠公會後，埃爾加丁爵士開始厭惡他的貴族身份。他不願因繼承了他父親的高貴血統而在貴族中獲得崇高的地位。不過我跑題了。這個故事的主題不是政治文章或者人物傳記，而是要敘述我在荊棘谷的青山中獵捕的經歷。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 100 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (100,'zhTW','正在我準備問艾耶克為什麼一整天都無精打采的時候，她突然從箭囊中抽出一支箭，向可憐的巴尼爾射去——當然她的目標並非巴尼爾。瞠目結舌的巴尼爾向後退了幾步，看著自己身後的一隻巨大的鱷魚浮出水面，艾耶克的箭正好射在了它的兩隻眼睛的中間。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 101 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (101,'zhTW','埃爾加丁爵士似乎被絆了一下，將手重重地拍在巴尼爾的肩膀上。我和艾耶克瞥了一眼，以為他會責備粗心大意的巴尼爾。然而埃爾加丁爵士卻擺了擺頭，示意我們觀察旁邊的一棵倒下的大樹。那裡正有一雙炯炯有神的黑眼睛瞪著我們，眼睛下面還有一口如剃刀般鋒利的牙齒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 102 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (102,'zhTW','埃爾加丁爵士似乎被絆了一下，將手重重地拍在巴尼爾的肩膀上。我和艾耶克瞥了一眼，以為他會責備粗心大意的巴尼爾。然而埃爾加丁爵士卻擺了擺頭，示意我們觀察旁邊的一棵倒下的大樹。那裡正有一雙炯炯有神的黑眼睛瞪著我們，眼睛下面還有一口如剃刀般鋒利的牙齒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 103 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (103,'zhTW','這次成功的獵殺給探險隊帶來了一些愉快的心情，巴尼爾給大家倒了些蜜酒，但是這種喜悅只是暫時的。當我們準備把屍體運回營地時，叢林裡傳來了一陣可怕的嚎叫聲。在我的一生中，我從來都沒有聽到過如此可怕的、幾乎讓人全身血液都凝固的聲音。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 104 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (104,'zhTW','這次成功的獵殺給探險隊帶來了一些愉快的心情，巴尼爾給大家倒了些蜜酒，但是這種喜悅只是暫時的。當我們準備把屍體運回營地時，叢林裡傳來了一陣可怕的嚎叫聲。在我的一生中，我從來都沒有聽到過如此可怕的、幾乎讓人全身血液都凝固的聲音。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 105 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (105,'zhTW','在遍佈岩石的懸崖上，一頭迄今為止我見過的最巨大的豹子在晚霞的映襯中冒了出來。我笨拙地開了槍，但是那頭豹子絲毫未動。它又咆哮了一聲，比第一次的聲音更大，然後就消失了。$B$B我們把東西收好，然後神色黯然地返回了營地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 107 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (107,'zhTW','在遍佈岩石的懸崖上，一頭迄今為止我見過的最巨大的豹子在晚霞的映襯中冒了出來。我笨拙地開了槍，但是那頭豹子絲毫未動。它又咆哮了一聲，比第一次的聲音更大，然後就消失了。$B$B我們把東西收好，然後神色黯然地返回了營地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 108 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (108,'zhTW','這一天，我們沿著一些新的黑豹足跡向南進發。很快我們就來到了一座架著巨大索橋的峽谷。看到這個工程奇蹟的時候，我忍不住想起了布萊恩對這一帶的描寫。我們常常認為巨魔是原始而無知的族類，然而當我認識到這座索橋所體現的精湛技術時，我開始認為巨魔的建造技術已經達到令人難以想像的地步。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 109 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (109,'zhTW','這一天，我們沿著一些新的黑豹足跡向南進發。很快我們就來到了一座架著巨大索橋的峽谷。看到這個工程奇蹟的時候，我忍不住想起了布萊恩對這一帶的描寫。我們常常認為巨魔是原始而無知的族類，然而當我認識到這座索橋所體現的精湛技術時，我開始認為巨魔的建造技術已經達到令人難以想像的地步。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 110 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (110,'zhTW','艾耶克和埃爾加丁爵士悄無聲息地用槍瞄準著正在晃動的樹叢。正午的強烈陽光照在我們身上，當埃爾加丁爵士終於扣動扳機的時候，他的額頭流下了一絲汗水。一聲槍響過後，濃密的樹葉被打得亂飛，一頭非常漂亮的大黑豹向離弦的箭一般衝向了平原。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 111 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (111,'zhTW','他的槍重重地擊在他的肩膀上，槍管歪向一邊，正好落在在艾耶克的槍下面。艾耶克瞄準樹冠適時地扣動了扳機，一聲清晰的槍響過後，樹冠上的一群鳥尖叫著四處飛散，樹上冒出了一陣煙，我們驚異地看到一根巨大的樹枝掉落下來，正好砸中了疾馳的黑豹。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 112 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (112,'zhTW','他的槍重重地擊在他的肩膀上，槍管歪向一邊，正好落在在艾耶克的槍下面。艾耶克瞄準樹冠適時地扣動了扳機，一聲清晰的槍響過後，樹冠上的一群鳥尖叫著四處飛散，樹上冒出了一陣煙，我們驚異地看到一根巨大的樹枝掉落下來，正好砸中了疾馳的黑豹。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 113 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (113,'zhTW','我們在黎明時動身向南出發，一路穿過了伽什廢墟。巴尼爾說他擔心會遇到血頂部族的巨魔。我告訴巴尼爾，比起生吃我們這些冒險者來，血頂部族更關心的是如何摧毀他們的敵人，劈顱部族。不過巴尼爾顯然沒有因此而感到一絲的寬慰。但是，我有一把上好膛的火槍、滿袋的黑火藥，還有三個本領高強的獵人做伴，所以我一點也不擔心會遭遇敵人的埋伏。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 114 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (114,'zhTW','我們在黎明時動身向南出發，一路穿過了伽什廢墟。巴尼爾說他擔心會遇到血頂部族的巨魔。我告訴巴尼爾，比起生吃我們這些冒險者來，血頂部族更關心的是如何摧毀他們的敵人，劈顱部族。不過巴尼爾顯然沒有因此而感到一絲的寬慰。但是，我有一把上好膛的火槍、滿袋的黑火藥，還有三個本領高強的獵人做伴，所以我一點也不擔心會遭遇敵人的埋伏。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 115 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (115,'zhTW','我曾經在戰場上面對過巨大的地獄火，還有從四面八方衝過來的燃燒軍團。如今對我而言，一群蠻橫的巨魔就跟丹莫洛的長耳大野兔一樣不值一提。$B$B我們平靜地穿過伽什廢墟，巴尼爾總算是放下了他那顆惴惴不安的心。我們繼續向西邊的無盡之海前進，並繞了南邊的祖昆達廢墟。當我們攀上海邊的懸崖之後，第一隻迅猛龍出現在我們面前。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 117 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (117,'zhTW','我們匆忙射出的子彈為巴尼爾贏得了足夠的逃跑時間。他大聲叫嚷著跑下山丘，重新回到隊伍之中。我們急忙離開了叢林，因為有一群兇殘的鞭尾迅猛龍正在追尋著我們的足跡。$B$B現在攻守易位，獵手變成了獵物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 118 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (118,'zhTW','我們匆忙射出的子彈為巴尼爾贏得了足夠的逃跑時間。他大聲叫嚷著跑下山丘，重新回到隊伍之中。我們急忙離開了叢林，因為有一群兇殘的鞭尾迅猛龍正在追尋著我們的足跡。$B$B現在攻守易位，獵手變成了獵物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 119 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (119,'zhTW','我帶著隊伍繼續往海邊走去，希望在那裡的海岸線旁找到某個可以避開迅猛龍的地方。但是在匆忙之中，我們跑到了一處危險的高地，這是個可怕的錯誤，全都是我的錯。我們停在了一個陡峭的懸崖邊，而那些迅猛龍距離我們僅有幾步之遙。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 120 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (120,'zhTW','我舉著槍緩緩地前進。是我將這些勇敢的獵人帶向了死亡的邊緣，我至死都要保護他們！鞭尾迅猛龍異常兇殘，它們一向都以殘酷嗜血而聞名，而且現在它們的數量遠遠多於我們。但是，我決不能就讓這些野獸輕易地殺了我和我的同伴。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 121 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (121,'zhTW','艾耶克和埃爾加丁爵士拿起他們的武器，守在我的兩側，我們的背後就是大海。巴尼爾沮喪地嘆了一口長氣，然後拿起了他的斧頭。迅猛龍在慢慢地逼近，它們高傲地注視著我們，因為它們知道我們已經無路可逃了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 124 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (124,'zhTW','荊棘谷的青山$B$B$B$B——赫米特·奈辛瓦里著',0);
DELETE FROM `page_text_locale` WHERE `ID` = 125 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (125,'zhTW','第一天和我們預想的完全一樣。我們大部分時間都忙於為建立營地做一些必要安排。我在一條淡水河的入口處找到了一個理想的駐紮點。根據旁邊被廢棄的古老碼頭判斷，這個地方曾經有人住過，不過只有時間才能說明這裡究竟住過什麼人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 126 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (126,'zhTW','我為這次探險召集了艾耶克·羅歐克、埃爾加丁爵士和我忠實的僕人巴尼爾·石罐。我曾經在保衛聯盟的戰鬥中與艾耶克的父親並肩作戰，看著艾耶克成長起來讓我有種很特別的感覺，她父親對她進行了嚴格的武器技能訓練。看到她熟練地使用弓箭，我不禁懷疑她的血管裡是否流淌著精靈的血。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 127 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (127,'zhTW','埃爾加丁爵士來自人類的貴族家庭。他的父親埃爾加丁伯爵以慷慨大方而著稱。第二次獸人戰爭之後，正是因為他父親的遊說和疏通，石匠公會才在重建暴風城時獲得了更好的工作條件。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 128 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (128,'zhTW','接下來的幾年，在暴風城背叛了石匠公會後，埃爾加丁爵士開始厭惡他的貴族身份。他不願因繼承了他父親的高貴血統而在貴族中獲得崇高的地位。不過我離題了。這個故事的主題不是政治文章或者人物傳記，而是要敘述我在荊棘谷的青山中獵捕的經歷。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 129 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (129,'zhTW','天一亮我們就起來了，巴尼爾開始準備早飯。我注意到艾耶克有點心煩意亂。今天的旅途將會漫長而危險，我們的狩獵行動也許會把我們帶向危險。注意力不集中就很容易導致錯誤，甚至是災難。艾耶克一直都在盯著在河邊清洗餐具的巴尼爾。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 130 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (130,'zhTW','正在我準備問艾耶克為什麼一整天都無精打采的時候，她突然從箭囊中抽出一支箭，向可憐的巴尼爾射去——當然她的目標並非巴尼爾。瞠目結舌的巴尼爾向後退了幾步，看著自己身後的一隻巨大的鱷魚浮出水面，艾耶克的箭正好射在了它的兩隻眼睛的中間。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 131 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (131,'zhTW','我們向西部進發，在繁茂的枝葉之間穿行。我們小心翼翼地走在厚厚的落葉上尋找獵物。整個早上都在令人沮喪的沉默中度過，山谷裡沒有任何激動人心的東西，連一陣微風都沒有。到了下午，探險隊開始變得不安，巴尼爾的腳步不再像一個追蹤獵物的獵手那樣謹慎，而是笨拙地踏著步，在枯葉或落枝上踩出響亮的聲音來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 132 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (132,'zhTW','埃爾加丁爵士似乎被絆了一下，將手重重地拍在巴尼爾的肩膀上。我和艾耶克瞥了一眼，以為他會責備粗心大意的巴尼爾。然而埃爾加丁爵士卻擺了擺頭，示意我們觀察旁邊的一棵倒下的大樹。那裡正有一雙炯炯有神的黑眼睛瞪著我們，眼睛下面還有一口如剃刀般鋒利的牙齒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 133 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (133,'zhTW','那是一隻雄性的荊棘谷猛虎。我還沒來得及拿起槍，埃爾加丁已經拉開他的弩，向那頭野獸射出了箭矢。這一下未能射中要害，不過還是重重地射入了猛虎的左腹。老虎想要逃跑，但是它傷得太重，只蹣跚走了幾步就被巴尼爾的斧頭擊中，倒地身亡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 134 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (134,'zhTW','這次成功的獵殺給探險隊帶來了一些愉快的心情，巴尼爾給大家倒了些蜜酒，但是這種喜悅只是暫時的。當我們準備把屍體運回營地時，叢林裡傳來了一陣可怕的嚎叫聲。在我的一生中，我從來都沒有聽到過如此可怕的、幾乎讓人全身血液都凝固的聲音。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 135 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (135,'zhTW','在遍佈岩石的懸崖上，一頭迄今為止我見過的最巨大的豹子在晚霞的映襯中冒了出來。我笨拙地開了槍，但是那頭豹子絲毫未動。它又咆哮了一聲，比第一次的聲音更大，然後就消失了。$B$B我們把東西收好，然後神色黯然地返回了營地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 136 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (136,'zhTW','我向探險隊員保證我們第二天將去狩獵黑豹，因為整個艾澤拉斯地區的豹皮都非常搶手而緊俏。正是因為有這種需求的存在，才有那麼多的獵人、捕獸者和毛皮商人以聯盟的名義勇敢地獻出了他們的生命。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 137 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (137,'zhTW','艾耶克和埃爾加丁爵士很想知道如何有效地使用矮人火槍狩獵。所以我讓這兩個對此一無所知的人類把他們的弓箭留在營地中，然後讓巴尼爾給他們裝備了一些鐵爐堡最好的武器。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 138 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (138,'zhTW','這一天，我們沿著一些新的黑豹足跡向南進發。很快我們就來到了一座架著巨大索橋的峽谷。看到這個工程奇蹟的時候，我忍不住想起了布萊恩對這一帶的描寫。我們常常認為巨魔是原始而無知的族類，然而當我認識到這座索橋所體現的精湛技術時，我開始認為巨魔的建造技術已經達到令人難以想像的地步。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 139 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (139,'zhTW','很快艾耶克就發現在西南方有獵豹出現。我們緊握住手中的槍，悄無聲息地前進，隨時準備對付突然冒出來的獵物。附近樹叢裡發出的樹枝斷裂的劈啪聲立刻引起了我們注意，那裡一定有什麼東西！我瞥了巴尼爾一眼，他就明白了我的意思。這個獵物不是我們的，而是留給我們的人類同伴的。已經有無數獵豹死在我們的槍管下，這一次輪到人類夥伴開開殺戒了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 140 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (140,'zhTW','艾耶克和埃爾加丁爵士悄無聲息地用槍瞄準著正在晃動的樹叢。正午的強烈陽光照在我們身上，當埃爾加丁爵士終於扣動扳機的時候，他的額頭流下了一絲汗水。一聲槍響過後，濃密的樹葉被打得亂飛，一頭非常漂亮的大黑豹向離弦的箭一般衝向了平原。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 141 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (141,'zhTW','當黑豹沿著林木邊緣奔走時，有兩個獵人一直瞄準著它。他們互相照應著一起行動，巴尼爾看看我，用眼光詢問是否要開火，我搖了搖頭。這次狩獵行動是要鍛鍊那些人類，而不是我或者巴尼爾。埃爾加丁扣動了扳機，但沒能打中黑豹。顯然，他對獵槍所產生的強大後坐力還沒有足夠的認識和準備。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 142 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (142,'zhTW','他的槍重重地擊在他的肩膀上，槍管歪向一邊，正好落在在艾耶克的槍下面。艾耶克瞄準樹冠適時地扣動了扳機，一聲清晰的槍響過後，樹冠上的一群鳥尖叫著四處飛散，樹上冒出了一陣煙，我們驚異地看到一根巨大的樹枝掉落下來，正好砸中了疾馳的黑豹。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 143 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (143,'zhTW','過了幾個星期，我們的豹皮和虎皮儲備已經相當充足了。於是我決定將探險隊的注意力轉向一個新的挑戰：迅猛龍。$B$B隊伍中的兩個人類雖然十分感激我和巴尼爾對他們進行的訓練，不過他們還是決定不使用我們提供的火槍去打獵。艾耶克更喜歡她那調校完美的強弓，而埃爾加丁爵士離開營地的時候總是拿著他的弩。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 144 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (144,'zhTW','我們在黎明時動身向南出發，一路穿過了伽什廢墟。巴尼爾說他擔心會遇到血頂部族的巨魔。我告訴巴尼爾，比起生吃我們這些冒險者來，血頂部族更關心的是如何摧毀他們的敵人，劈顱部族。不過巴尼爾顯然沒有因此而感到一絲的寬慰。但是，我有一把上好膛的火槍、滿袋的黑火藥，還有三個本領高強的獵人做伴，所以我一點也不擔心會遭遇敵人的埋伏。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 145 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (145,'zhTW','我曾經在戰場上面對過巨大的地獄火，還有從四面八方衝過來的燃燒軍團。如今對我而言，一群蠻橫的巨魔就跟丹莫洛的長耳大野兔一樣不值一提。$B$B我們平靜地穿過伽什廢墟，巴尼爾總算是放下了他那顆惴惴不安的心。我們繼續向西邊的無盡之海前進，並繞了南邊的祖昆達廢墟。當我們攀上海邊的懸崖之後，第一隻迅猛龍出現在我們面前。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 146 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (146,'zhTW','這頭野獸壓根沒有發現我們的存在，事實上，它從我們這兒收到的第一個問候就是射入它雙眼間的子彈。$B$B埃爾加丁爵士大聲歡呼，艾耶克則讚許地向我點了點頭。我從包裡拿出菸斗，想好好慶祝一番。巴尼爾奔上山坡去拖迅猛龍的屍體。我看著被擊倒的野獸，心裡就像以前每一次殺死獵物時那樣充滿著興奮和滿足。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 147 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (147,'zhTW','但是我還沒有時間體會這次獵殺的愉悅，就赫然發現山頂上出現了幾個影子——就在可憐的巴尼爾的正上方。$B$B“快跑，巴尼爾！”我大叫道。艾耶克、埃爾加丁和我立刻向追逐巴尼爾的迅猛龍射擊，一時間子彈和箭矢亂飛，混亂之中，我們當中的某人還射殺了一隻迅猛龍。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 148 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (148,'zhTW','我們匆忙射出的子彈為巴尼爾贏得了足夠的逃跑時間。他大聲叫嚷著跑下山丘，重新回到隊伍之中。我們急忙離開了叢林，因為有一群兇殘的鞭尾迅猛龍正在追尋著我們的足跡。$B$B現在攻守易位，獵手變成了獵物。',0);
