INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (154,'zhTW','我為這次探險召集了艾耶克·羅歐克、埃爾加丁爵士和我忠實的僕人巴尼爾·石罐。我曾經在保衛聯盟的戰鬥中與艾耶克的父親並肩作戰，看著艾耶克成長起來讓我有種很特別的感覺，她父親對她進行了嚴格的武器技能訓練。看到她熟練地使用弓箭，我不禁懷疑她的血管裡是否流淌著精靈的血。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 155 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (155,'zhTW','埃爾加丁爵士來自人類的貴族家庭。他的父親埃爾加丁伯爵以慷慨大方而著稱。第二次獸人戰爭之後，正是因為他父親的遊說和疏通，石匠公會才在重建暴風城時獲得了更好的工作條件。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 156 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (156,'zhTW','接下來的幾年，在暴風城背叛了石匠公會後，埃爾加丁爵士開始厭惡他的貴族身份。他不願因繼承了他父親的高貴血統而在貴族中獲得崇高的地位。不過我離題了。這個故事的主題不是政治文章或者人物傳記，而是要敘述我在荊棘谷的青山中獵捕的經歷。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 157 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (157,'zhTW','天一亮我們就起來了，巴尼爾開始準備早飯。我注意到艾耶克有點心煩意亂。今天的旅途將會漫長而危險，我們的狩獵行動也許會把我們帶向危險。注意力不集中就很容易導致錯誤，甚至是災難。艾耶克一直都在盯著在河邊清洗餐具的巴尼爾。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 158 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (158,'zhTW','正在我準備問艾耶克為什麼一整天都無精打采的時候，她突然從箭囊中抽出一支箭，向可憐的巴尼爾射去——當然她的目標並非巴尼爾。瞠目結舌的巴尼爾向後退了幾步，看著自己身後的一隻巨大的鱷魚浮出水面，艾耶克的箭正好射在了它的兩隻眼睛的中間。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 159 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (159,'zhTW','我們向西部進發，在繁茂的枝葉之間穿行。我們小心翼翼地走在厚厚的落葉上尋找獵物。整個早上都在令人沮喪的沉默中度過，山谷裡沒有任何激動人心的東西，連一陣微風都沒有。到了下午，探險隊開始變得不安，巴尼爾的腳步不再像一個追蹤獵物的獵手那樣謹慎，而是笨拙地踏著步，在枯葉或落枝上踩出響亮的聲音來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 160 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (160,'zhTW','埃爾加丁爵士似乎被絆了一下，將手重重地拍在巴尼爾的肩膀上。我和艾耶克瞥了一眼，以為他會責備粗心大意的巴尼爾。然而埃爾加丁爵士卻擺了擺頭，示意我們觀察旁邊的一棵倒下的大樹。那裡正有一雙炯炯有神的黑眼睛瞪著我們，眼睛下面還有一口如剃刀般鋒利的牙齒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 161 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (161,'zhTW','那是一隻雄性的荊棘谷猛虎。我還沒來得及拿起槍，埃爾加丁已經拉開他的弩，向那頭野獸射出了箭矢。這一下未能射中要害，不過還是重重地射入了猛虎的左腹。老虎想要逃跑，但是它傷得太重，只蹣跚走了幾步就被巴尼爾的斧頭擊中，倒地身亡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 162 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (162,'zhTW','這次成功的獵殺給探險隊帶來了一些愉快的心情，巴尼爾給大家倒了些蜜酒，但是這種喜悅只是暫時的。當我們準備把屍體運回營地時，叢林裡傳來了一陣可怕的嚎叫聲。在我的一生中，我從來都沒有聽到過如此可怕的、幾乎讓人全身血液都凝固的聲音。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 163 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (163,'zhTW','在遍佈岩石的懸崖上，一頭迄今為止我見過的最巨大的豹子在晚霞的映襯中冒了出來。我笨拙地開了槍，但是那頭豹子絲毫未動。它又咆哮了一聲，比第一次的聲音更大，然後就消失了。$B$B我們把東西收好，然後神色黯然地返回了營地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 164 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (164,'zhTW','我向探險隊員保證我們第二天將去狩獵黑豹，因為整個艾澤拉斯地區的豹皮都非常搶手而緊俏。正是因為有這種需求的存在，才有那麼多的獵人、捕獸者和毛皮商人以聯盟的名義勇敢地獻出了他們的生命。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 165 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (165,'zhTW','艾耶克和埃爾加丁爵士很想知道如何有效地使用矮人火槍狩獵。所以我讓這兩個對此一無所知的人類把他們的弓箭留在營地中，然後讓巴尼爾給他們裝備了一些鐵爐堡最好的武器。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 166 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (166,'zhTW','這一天，我們沿著一些新的黑豹足跡向南進發。很快我們就來到了一座架著巨大索橋的峽谷。看到這個工程奇蹟的時候，我忍不住想起了布萊恩對這一帶的描寫。我們常常認為巨魔是原始而無知的族類，然而當我認識到這座索橋所體現的精湛技術時，我開始認為巨魔的建造技術已經達到令人難以想像的地步。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 167 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (167,'zhTW','很快艾耶克就發現在西南方有獵豹出現。我們緊握住手中的槍，悄無聲息地前進，隨時準備對付突然冒出來的獵物。附近樹叢裡發出的樹枝斷裂的劈啪聲立刻引起了我們注意，那裡一定有什麼東西！我瞥了巴尼爾一眼，他就明白了我的意思。這個獵物不是我們的，而是留給我們的人類同伴的。已經有無數獵豹死在我們的槍管下，這一次輪到人類夥伴開開殺戒了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 168 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (168,'zhTW','艾耶克和埃爾加丁爵士悄無聲息地用槍瞄準著正在晃動的樹叢。正午的強烈陽光照在我們身上，當埃爾加丁爵士終於扣動扳機的時候，他的額頭流下了一絲汗水。一聲槍響過後，濃密的樹葉被打得亂飛，一頭非常漂亮的大黑豹向離弦的箭一般衝向了平原。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 169 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (169,'zhTW','當黑豹沿著林木邊緣奔走時，有兩個獵人一直瞄準著它。他們互相照應著一起行動，巴尼爾看看我，用眼光詢問是否要開火，我搖了搖頭。這次狩獵行動是要鍛鍊那些人類，而不是我或者巴尼爾。埃爾加丁扣動了扳機，但沒能打中黑豹。顯然，他對獵槍所產生的強大後坐力還沒有足夠的認識和準備。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 170 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (170,'zhTW','他的槍重重地擊在他的肩膀上，槍管歪向一邊，正好落在在艾耶克的槍下面。艾耶克瞄準樹冠適時地扣動了扳機，一聲清晰的槍響過後，樹冠上的一群鳥尖叫著四處飛散，樹上冒出了一陣煙，我們驚異地看到一根巨大的樹枝掉落下來，正好砸中了疾馳的黑豹。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 171 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (171,'zhTW','過了幾個星期，我們的豹皮和虎皮儲備已經相當充足了。於是我決定將探險隊的注意力轉向一個新的挑戰：迅猛龍。$B$B隊伍中的兩個人類雖然十分感激我和巴尼爾對他們進行的訓練，不過他們還是決定不使用我們提供的火槍去打獵。艾耶克更喜歡她那調校完美的強弓，而埃爾加丁爵士離開營地的時候總是拿著他的弩。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 172 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (172,'zhTW','我們在黎明時動身向南出發，一路穿過了伽什廢墟。巴尼爾說他擔心會遇到血頂部族的巨魔。我告訴巴尼爾，比起生吃我們這些冒險者來，血頂部族更關心的是如何摧毀他們的敵人，劈顱部族。不過巴尼爾顯然沒有因此而感到一絲的寬慰。但是，我有一把上好膛的火槍、滿袋的黑火藥，還有三個本領高強的獵人做伴，所以我一點也不擔心會遭遇敵人的埋伏。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 173 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (173,'zhTW','我曾經在戰場上面對過巨大的地獄火，還有從四面八方衝過來的燃燒軍團。如今對我而言，一群蠻橫的巨魔就跟丹莫洛的長耳大野兔一樣不值一提。$B$B我們平靜地穿過伽什廢墟，巴尼爾總算是放下了他那顆惴惴不安的心。我們繼續向西邊的無盡之海前進，並繞了南邊的祖昆達廢墟。當我們攀上海邊的懸崖之後，第一隻迅猛龍出現在我們面前。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 174 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (174,'zhTW','這頭野獸壓根沒有發現我們的存在，事實上，它從我們這兒收到的第一個問候就是射入它雙眼間的子彈。$B$B埃爾加丁爵士大聲歡呼，艾耶克則讚許地向我點了點頭。我從包裡拿出菸斗，想好好慶祝一番。巴尼爾奔上山坡去拖迅猛龍的屍體。我看著被擊倒的野獸，心裡就像以前每一次殺死獵物時那樣充滿著興奮和滿足。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 175 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (175,'zhTW','但是我還沒有時間體會這次獵殺的愉悅，就赫然發現山頂上出現了幾個影子——就在可憐的巴尼爾的正上方。$B$B“快跑，巴尼爾！”我大叫道。艾耶克、埃爾加丁和我立刻向追逐巴尼爾的迅猛龍射擊，一時間子彈和箭矢亂飛，混亂之中，我們當中的某人還射殺了一隻迅猛龍。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 176 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (176,'zhTW','我們匆忙射出的子彈為巴尼爾贏得了足夠的逃跑時間。他大聲叫嚷著跑下山丘，重新回到隊伍之中。我們急忙離開了叢林，因為有一群兇殘的鞭尾迅猛龍正在追尋著我們的足跡。$B$B現在攻守易位，獵手變成了獵物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 177 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (177,'zhTW','我帶著隊伍繼續往海邊走去，希望在那裡的海岸線旁找到某個可以避開迅猛龍的地方。但是在匆忙之中，我們跑到了一處危險的高地，這是個可怕的錯誤，全都是我的錯。我們停在了一個陡峭的懸崖邊，而那些迅猛龍距離我們僅有幾步之遙。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 178 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (178,'zhTW','我舉著槍緩緩地前進。是我將這些勇敢的獵人帶向了死亡的邊緣，我至死都要保護他們！鞭尾迅猛龍異常兇殘，它們一向都以殘酷嗜血而聞名，而且現在它們的數量遠遠多於我們。但是，我決不能就讓這些野獸輕易地殺了我和我的同伴。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 179 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (179,'zhTW','艾耶克和埃爾加丁爵士拿起他們的武器，守在我的兩側，我們的背後就是大海。巴尼爾沮喪地嘆了一口長氣，然後拿起了他的斧頭。迅猛龍在慢慢地逼近，它們高傲地注視著我們，因為它們知道我們已經無路可逃了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 180 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (180,'zhTW','突然之間，奇蹟發生了。我們聽見一隻白虎清晰而可怕的吼聲從對面傳來。雖然迅猛龍數量眾多，但它們一聽到叫聲便立刻四散逃竄。那隻老虎像一道白色閃電般從我們身前跑過，撲向一隻迅猛龍。不需要任何命令和溝通，我們四個人都明白：這正是逃跑的最佳時機。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 181 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (181,'zhTW','我們一路狂奔回到了營地，絲毫不敢放慢速度。深夜，我們圍著篝火靜靜地坐在一起，大家心裡都明白，我們是被奇異的命運所拯救，這就是狩獵高手活動所帶來的風險：我們在和命運玩遊戲。然而，我們之中的每一個人都可能會在未來的某一時刻面對命運嚴峻的考驗。我這個老矮人感到高興的是，這一時刻並非發生在荊棘谷的青山中。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 182 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (182,'zhTW','尊貴的同僚和求知者們：$B$B挖掘工作仍在繼續中，但是由於我最近報告中提到過的穴居人所帶來的麻煩，挖掘進度變慢了。雖然一些穴居人比其它的同類更具有攻擊性，我依然有信心解決他們。$B$B最近我們發現了很多神器，除了其中一件以外（這件我會在下面進行說明），其它的都和以前發現的區別不大——很有趣，但是沒什麼啟發性。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 183 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (183,'zhTW','有一件東西很特殊——那就是我們最近發現的一個十分特別的神像（我在上次報告中對它作過簡單的描述），這個神像似乎對這裡的穴居人有某種影響力。他們都受到它的吸引，有些甚至變得極度瘋狂！$B$B我們還需要進行更深入的研究才能瞭解這些神像的真正作用。不過我相信，我們可以從中找到穴居人和泰坦之間的聯絡',0);
DELETE FROM `page_text_locale` WHERE `ID` = 184 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (184,'zhTW','最後，我必須再次強調我對炸藥粉的迫切需求。我這裡的存貨已經非常少了，這會嚴重地阻礙挖掘行動的進展。我聽說新的炸藥粉補給會很快送來，但是我一直都沒有收到。$B$B能否告訴我到底是什麼原因導致這批貨還沒有運達我這裡？$B$B此致，$B勘察員基恩薩·鐵環',0);
DELETE FROM `page_text_locale` WHERE `ID` = 185 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (185,'zhTW','所有的事情都是從我找到羅蘭之墓裡那把被詛咒的鐮刀時開始的。對，就是從那時開始……在找到它之前，這個地區看起來與北郡山谷一樣平靜。$B$B但是當我發現了露在碎石堆外的那把鐮刀的柄之後，一切都變了，該死的，當時我居然把它拔了出來，從此之後，羅蘭之墓就變成了恐怖滋生之地！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 186 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (186,'zhTW','所有的事情都是從我找到羅蘭之墓裡那把被詛咒的鐮刀時開始的。對，就是從那時開始……在找到它之前，這個地區看起來與北郡山谷一樣平靜。$B$B但是當我發現了露在碎石堆外的那把鐮刀的柄之後，一切都變了，該死的，當時我居然把它拔了出來，從此之後，羅蘭之墓就變成了恐怖滋生之地！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 187 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (187,'zhTW','如果我早知道會發生這樣的事，我當初就算把自己的手砍了也決不會去抓那塊雕著符文的木柄。我真是追悔莫及啊！後悔，我一直以為這是老人的特權，但現在我明白了，其實讓人被後悔所纏繞的不是年歲，而是絕望，它讓你再也無法擺脫後悔，只能飽受痛苦的煎熬。$B$B不過我已經像個詩人般喋喋不休好半天了。現在，我得繼續我的日記……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 188 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (188,'zhTW','自從拔出那把鐮刀之後，礦坑裡就開始發生變化。火把的光焰總是向一邊傾斜，而我們對自己的聲音也失去了控制。有時一個人的細聲低語會突然變成吼叫聲，傳遍整個隧道，讓人不得不掩住耳朵；而有時即使我們放聲大喊，那聲音卻傳不了多遠就變得極其微弱，直至消失在風中。$B$B這讓我們十分緊張，不過我們很快就不再擔心這件事情了。因為有另一種力量將我們從礦坑裡趕了出去——那就是狼人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 189 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (189,'zhTW','狼人從四面八方向我們襲來，從洞裡冒出來抓向我們，或是從樹上跳下來撲向我們。我們中的半數人在驚恐中被瞬間幹掉，剩下的人都開始沒命地逃跑。我看到自己的兄弟一個個喪身在狼人的尖牙或利爪之下，慘叫聲不斷劃破寂靜的森林。$B$B據我所知，我是唯一一個逃出那個地方的人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 190 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (190,'zhTW','我不知道那個晚上為什麼獨有我能生還。我一直都很小心，靈敏地避開狼人的襲擊，每一次閃躲都準確無誤。我的綽號“膽小鬼”就來自於我的這個特點。也許正是我的謹慎小心救了我……$B$B也許是我從碎石堆裡挖出來的鐮刀救了我。不過，這不可能是鐮刀本身的作用，因為我在逃跑途中把它給弄丟了。但如果是我把狼人引到暮色森林的話，那麼也許它們是因為這一點而放了我一條生路。這些該死的狼人！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 191 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (191,'zhTW','也許我命中註定應該活下來親眼看著我給暮色森林帶來的鉅變，親眼看著狼人撕裂這片土地，以邪惡將這裡玷汙。$B$B如果這就是我的命運，那我的命運遠不止這麼糟糕。將魔爪伸向暮色森林的不僅僅是狼人——還有來自逆風小徑的惡魔。$B$B我的下一谷？日記就要記述這些，我希望那也是最後一章……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 192 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (192,'zhTW','從羅蘭之墓僥倖逃出來後，我躲在一個斯溫家的穀倉裡。我在那裡面過了好幾個星期，一直都被恐懼所籠罩，也不敢讓斯溫和他的家人知道我的存在。雖然從我對他們的觀察來看，這些農夫都是些很本分的平民，而且如果我從藏身的地方走出去，他們也一定會接納我住在他們家裡，不過對我而言，要信任別人是十分困難的——尤其是經歷了礦坑裡那恐怖的一幕之後。$B$B因此我躲在那兒，一直沒有現身。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 193 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (193,'zhTW','在我來到這座農場幾天後，斯溫準備去一次夜色鎮。他吻了吻他的妻子，然後微笑著和孩子們告別，並保證會很快帶著玩具和糖果回來。可憐的人，那是他和全家人最後一次在一起……$B$B至少他們是快樂地分別的，至少他的妻子第一個死去，沒有親眼看到她的孩子們被屠殺。但這對我來說沒有用。我看到了所有的慘劇，而這一切從此一直不斷在我的夢裡出現。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 194 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (194,'zhTW','現在回憶起當晚的細節，我的手還禁不住顫抖。斯溫離開之後，他的家人不得不獨自面對可怕的黑騎士。悔恨的感覺一直纏繞著我，當時我就在那裡，我本應該跳出來與那些從逆風小徑來的惡魔戰鬥。也許這是一種虛假的悔恨，對於每一個逃過悲劇的倖存者來說，情形也許都是一樣的。我知道，如果我從藏身的地方走出來，我也會和他們一樣被殺戮，我的身體也會被撕得粉碎。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 195 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (195,'zhTW','不過，雖然我很清楚自己無法阻止那場殘酷的殺戮，我的心中還是懷著深深的悔恨：是我將黑騎士引到了斯溫的農場。我發現的鐮刀不僅將狼人引到了暮色森林，它還引來了逆風小徑的黑騎士。$B$B那時，斯溫的妻子緊緊摟著孩子們，想給他們一些安慰，但是她知道死亡必將來臨。黑騎士殺害他們之前還問了斯溫的妻子一個問題，這讓我知道了所有的一切。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 196 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (196,'zhTW','“月神的鐮刀。”一個騎士用淒厲刺耳的聲音叫道，就像在石頭上磨斧頭的那種聲音。當喊出“鐮刀”這個詞的時候，這個聲音變得嘶啞起來，好像窒息了一樣。$B$B我一聽到那個聲音，立刻就被恐懼籠罩了，一方面是因為那個聲音非常可怕，另一方面……我知道那個騎士所說的鐮刀是什麼。那一定就是幾天前我在羅蘭之墓的碎石中拔出的那件該死的東西，那就是黑騎士們所要尋找的東西！$B$B它就是給斯溫一家人帶來滅頂之災的罪魁禍首。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 197 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (197,'zhTW','我一直以來都不知道她的名字，因為她的丈夫和孩子總是叫她“親愛的”，“寶貝”和“媽媽”。但是我很希望知道她的名字，我是唯一一個見證她當時的英勇行為的人。雖然她只是一個農夫的妻子，但是我從來沒看到過有人能像她這麼勇敢。$B$B她當然不知道那把鐮刀是什麼東西，但是當她知道黑騎士在尋找鐮刀時，就突然想到了一個計劃。$B$B那是個大膽而聰明的計劃，如果她能成功的話，那該有多好！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 198 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (198,'zhTW','“鐮刀？”她平靜地問道。“我當然知道。這兒誰不知道？”她的雙眼堅定地望著騎士，如果不是因為我知道實情的話，我一定也會相信她所說的話——雖然她根本不知道關於鐮刀的事情。$B$B她的這一招奏效了。那個提出問題的騎士輕微地低下頭湊向她，然後尖聲說道：“在哪裡？”$B$B“我可以帶你去，帶你們一起去。”她回答道。我看到她的眼中閃過一絲希望。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 199 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (199,'zhTW','“不過路很遠，帶著孩子會拖累我們，必須得把他們留下。”$B$B她的計劃很簡單，不過簡單的計劃成功的可能性最大。如果她成功了，就能讓那些強盜遠離農場。她可能會因此而死，可是孩子們就安全了。如果強盜相信了她那崇高的謊言，這個計劃就能成功。$B$B雖然我從未信仰過聖光之道，但是當斯溫的妻子勇敢地站在那幫可怕的強盜面前時，我仍然虔誠地為她祈禱。$B$B“讓他們相信吧。”我祈禱著。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 200 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (200,'zhTW','他們站在那兒一動不動，而她也平靜地面對著他們的凝視。這時一個騎士抬起眼，彷彿在聆聽遠方的召喚。他從衣服裡拿出一塊寶石，向它望去。他用寶石在斯溫妻子的面前晃動。一股光芒從騎士的身上緩緩冒出，隨即變成了一隻恐怖的白色的手，伸向那個女人。她毫無畏懼地望著這股光芒，不過我已經看出她自信背後的一絲不安。那隻手伸向她，用手指罩住了她的臉龐。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 201 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (201,'zhTW','斯溫的妻子像一尊雕像一樣直直地站在那裡，眼睛睜得大大的。雖然她的嘴唇張開著，似乎是在尖叫，但是她卻始終無法發出聲音。過了一會兒，那隻折磨著她的手終於鬆了下來，把她丟在地上。拿著寶石的那個騎士巍然正坐在馬鞍上，一個聲音從他口中傳出。$B$B“這個女人在撒謊，”那個可怕的聲音時常在我夢裡出現，“她沒有見過鐮刀。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 202 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (202,'zhTW','然後，騎士的肩膀癱軟了下去，好像軀殼中的靈魂突然離它而去。隨後，那個蒼老而尖厲的嗓音又響了起來，他說的最後一句話是：$B$B“大人下令了，殺掉他們。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 203 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (203,'zhTW','我無法描述接下來所發生的事情。它深深地刻在我的腦海裡，但是我脆弱的靈魂無法把它寫下來，那是短暫而又無比恐怖的時刻。$B$B我只能寫下事情的結局：斯溫的一家都被殺害了。沒過多久，斯溫回來了，他看到了這一片死亡的慘景，悲痛欲絕，這使我不敢現身。我不敢讓他找到我，於是我就從農場裡逃走了。我也不知道斯溫現在在哪裡，但是我希望有一天他能平靜下來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 204 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (204,'zhTW','我無法描述接下來所發生的事情。它深深地刻在我的腦海裡，但是我脆弱的靈魂無法把它寫下來，那是短暫而又無比恐怖的時刻。$B$B我只能寫下事情的結局：斯溫的一家都被殺害了。沒過多久，斯溫回來了，他看到了這一片死亡的慘景，悲痛欲絕，這使我不敢現身。我不敢讓他找到我，於是我就從農場裡逃走了。我也不知道斯溫現在在哪裡，但是我希望有一天他能平靜下來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 205 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (205,'zhTW','鐮刀被拔出之後，狼人從四面八方向我們襲來，從洞裡伸出爪子抓向我們的腿，或是突然從樹上跳下來撲向我們。我們中有一半人在驚恐中被殺掉，包括我在內的倖存者都在沒命地逃跑。在逃跑時，我看到自己的兄弟一個個喪身在狼人的尖牙或利爪之下，尖叫聲不斷劃破寂靜的森林。$B$B據我所知，我是唯一一個逃出那個地方的人。',0);
