INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (207,'zhTW','從羅蘭之墓僥倖逃出來後，我躲在一個斯溫家的穀倉裡。我在那裡面過了好幾個星期，一直都被恐懼所籠罩，也不敢讓斯溫和他的家人知道我的存在。雖然從我對他們的觀察來看，這些農夫都是些很本分的平民，而且如果我從藏身的地方走出去，他們也一定會接納我住在他們家裡，不過對我而言，要信任別人是十分困難的——尤其是經歷了礦坑裡那恐怖的一幕之後。$B$B因此我躲在那兒，一直沒有現身。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 208 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (208,'zhTW','<書中剩餘的部分是空白的>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 209 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (209,'zhTW','報告：關於狗頭人$B$B北郡山谷中狗頭人的活動日益增加。他們在修道院的北面和迴音山礦坑裡建立了營地，而且數量眾多。我已經召集了一些聖騎士、戰士以及當地居民去幫助我們對付這幫歹徒。$B$B現在一切進行得很順利。我會及時向您彙報最新進展的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 210 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (210,'zhTW','報告：關於盜賊$B$B比狗頭人更令人擔憂的是，一群人類的盜賊出現在山谷裡。他們帶著紅色的面罩，自稱為兄弟會的成員。這種組織會給本地和整個艾爾文森林帶來威脅。$B$B我們已經查到了他們的一個首領——加瑞克·帕德弗特，希望能夠很快對他進行審判。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 211 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (211,'zhTW','報告：關於狼群$B$B關於狼群襲擊北郡的報告最近有所增加。伊根認為狼群數量的增加主要是由於許多狼都從暮色森林來到了山谷中。$B$B雖然狼群很少襲擊人類，但是它們數量的激增給農夫增加了很多麻煩。這段時間來已經發生多宗家畜失蹤事件了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 212 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (212,'zhTW','嘉獎：$B$B傳遞此公文者將會被授予暴風城軍隊代表的頭銜，以證明$g他:她曾全力幫助過北郡。我相信您將會發現這個人也可以幫助艾爾文森林。$B$B署名：$B——治安官杜格拉斯·瑪克布萊德$B暴風城防衛軍，北郡',0);
DELETE FROM `page_text_locale` WHERE `ID` = 213 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (213,'zhTW','雜味燉肉$B$B3份禿鷲肉條$B3個血牙野豬的頭$B3顆魚人人的眼球$B3根秋葵$B$B把以上各種材料都混在一起烹煮至少兩小時後方可食用。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 214 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (214,'zhTW','親愛的伊維特：$B$B我將委託我們這裡最迅捷的信差將這封信交給你，希望他能設法穿越我們之間茂密的森林。我希望你能讀到這個，因為這將是你最後一次收到我的訊息了。$B$B在這黑暗的日子裡，只有當我知道了你不會再經受我所經受的厄運，我才能感到些許的安慰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 217 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (217,'zhTW','親愛的伊維特：$B$B我將委託我們這裡最迅捷的信差將這封信交給你，希望他能設法穿越我們之間茂密的森林。我希望你能讀到這個，因為這將是你最後一次收到我的訊息了。$B$B在這黑暗的日子裡，只有當我知道了你不會再經受我所經受的厄運，我才能感到些許的安慰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 218 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (218,'zhTW','我擔心斯通菲爾德和馬科倫家族之間的勾心鬥角會毀掉湯米·喬和梅貝爾之間的愛情，在現在這個時代中，即使面對再多黑暗的威脅和戰爭的陰影，我們也應該努力去呵護愛情和年輕的生命。$B$B所以，我希望你能幫忙製作一些隱身藥水，讓這兩個年輕人能夠相聚。$B$B謝謝你，威廉。還有，當你空閒的時候別忘了多來我這裡玩玩。我們已經有好久沒見過面了，我十分懷念以前與你一起度過的快樂時光。$B$B——米萊德',0);
DELETE FROM `page_text_locale` WHERE `ID` = 219 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (219,'zhTW','由暴風城建築官員巴隆斯·阿歷克斯頓親自提交$B$B陛下：$B$B我之所以寫這樣一份報告，是因為我覺得應該對迪菲亞兄弟會這個組織最近的動向及其在王國領地內的所有活動向您做一彙報。$B$B為了把他們的情況解釋清楚，請允許我我首先介紹一下這個組織的一些背景。或許您並不知道，我以前曾是暴風城石匠公會的會員。經過多年的辛勤工作，我們完成了暴風城的重建，而石匠公會卻沒有收到分毫的報酬，甚至根本沒有人提及。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 220 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (220,'zhTW','當時任石匠公會會長的艾德溫·範克里夫多次索要暴風城拖欠的報酬，而暴風城貴族議會的回應卻是命令石匠公會解散，這當然激怒了範克里夫。他發起了一場暴亂，帶領石匠公會的人離開了暴風城。$B$B在我繼續講述之前，還有一些發生在那時的其他事情應該讓你瞭解一下。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 221 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (221,'zhTW','首先，正是在那個時候，暴風城的貴族向我許諾說，如果我能脫離範克里夫的組織，他們就可以讓我擔任城市建築師的職位。由於和他的一些思想有分歧，我便選擇了留在暴風城。$B$B暴亂期間，範克里夫最信任的助手巴基爾·斯瑞德被俘，一直關在監獄裡等待審判和盤問，現在幾乎已經被人遺忘了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 222 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (222,'zhTW','話題還是回到範克里夫吧。在他帶領石匠公會的殘部逃出了暴風城，當時西部荒野幾乎沒有駐紮任何暴風城的軍隊，他就利用這種情況驅逐了那裡的農夫，並且控制了當地的金礦。$B$B利用他所掌握的資源，範克里夫計劃對暴風城政府進行復仇。$B$B這些情報是由送交這份檔案的人收集到的，這個人也及時幫助我們揭露了這個大陰謀。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 223 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (223,'zhTW','可根據情況決定是否公佈以下訊息。$B$B提瑞斯法林地區命令$B麥羅斯隊長$B瓦松隊長$B派瑞恩隊長$B$B由總指揮官下達的命令。$B$B派瑞恩隊長，進一步加強西南城堡的防禦（按計劃行事）。更多的補給將在稍晚些時候送達。同時，在附近的農場徵收必需的物資，並對布瑞爾地區的亡靈進行必要的偵察和情報蒐集工作。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 224 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (224,'zhTW','瓦松隊長，北部城堡一帶的不死生物活動日益增加，必須快速果斷地消滅這種活動。$B$B麥羅斯隊長，瘟疫之地邊界地區的不死生物正在不斷集結。增援部隊將在接下來的幾周內到達你的轄區。$B$B為聖光的榮耀而戰！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 228 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (228,'zhTW','第1天$B$B我的坦克壞了，但是我知道我們要找的那種礦石就在山中的某個地方，我讓塞克·錘足留在這裡看著坦克。$B$B我要繼續獨自尋找。如果我不能回來的話，這將成為我最後的遺囑。$B$B駕駛員莫里·鐵鑽$B鐵爐堡攻城坦克旅',0);
DELETE FROM `page_text_locale` WHERE `ID` = 229 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (229,'zhTW','第1天$B$B我的坦克壞了，但是我知道我們要找的那種礦石就在山中的某個地方，我讓塞克·錘足留在這裡看著坦克。$B$B我要繼續獨自尋找。如果我不能回來的話，這將成為我最後的遺囑。$B$B駕駛員莫里·鐵鑽$B鐵爐堡攻城坦克旅',0);
DELETE FROM `page_text_locale` WHERE `ID` = 230 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (230,'zhTW','第2天$B$B我繼續尋找，但沒有找到礦石。我不知道這是不是石輪那傢伙跟我們開的玩笑，如果是這樣的話，等我回到鋼架補給站，他可就慘了！$B$B今夜，在我搭建營地的時候，我聽見有一聲咆哮在山谷中迴盪。$B$B那聽起來不像是狼，似乎更像是一隻熊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 231 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (231,'zhTW','第3天$B$B那個咆哮聲持續了一夜，今天白天還一直跟著我，讓我沒法專心尋找礦石。我想確實是有一頭熊跟著我！$B$B我希望它能靠近點，那樣我就可以把手裡的鋤頭插在它的腦袋上了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 232 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (232,'zhTW','第4天$B$B我的補給越來越少了。我有足夠的食物，不過我從沒想到會離開我的坦克在野外待這麼久的時間，而且還只帶了兩小桶酒。$B$B前兩個晚上我都沒有睡覺，一直在聽著那該死的咆哮聲，我的酒都差不多喝光了！$B$B我明天得回到我們的坦克那兒去，我可不想在沒有酒喝的情況下在這裡迷路。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 233 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (233,'zhTW','第5天$B$B我碰到了那頭該死的熊！它在光天化日之下向我發起攻擊，咆哮著從我身後襲來。$B$B要不是風向不對的話，我肯定可以聞到它的氣味。它那身臭毛皮和腐爛的氣味就足以讓我發暈了！$B$B我和它打鬥了一番，但它咬住了我的腿。現在我不能動了，我的酒也沒了，而且更糟糕的是我還沒有找到那塊礦石。該死！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 234 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (234,'zhTW','第6天$B$B那頭熊沒有回來——我一定是把它打成重傷了！不過我還能聽到它的咆哮，它大概是在等著我死掉！$B$B不管是誰發現這本書，我都要託付給你一個任務。殺了那頭骯髒的熊！殺了它，再把這本書交給我的朋友塞克·錘足，讓他知道發生了什麼事。$B$B拿著我的護甲，你會用得到它的！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 235 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (235,'zhTW','夜色鎮的鎮長埃伯洛克公爵，$B$B您好。$B$B恐怕我有個壞訊息要捎給夜色鎮。$B$B您知道，我是一個創造天才。我欺騙了給您送信的這個蠢貨，騙他幫我完成了我最強大而恐怖的創造——一個用血肉和扭曲的金屬製成的惡魔！當您讀著這封信的時候，它就在我簡陋的屋子外面，張牙舞爪，隨時準備血洗夜色鎮。$B$B您很快就可以看見它了。$B$B——藏屍者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 236 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (236,'zhTW','透過對各種生物化石的研究，我已經推測出在很久很久以前曾有一場大瘟疫橫掃了整個洛丹米爾湖。是什麼導致了這次瘟疫？我們也許永遠都不會知道。但是根據散佈在湖床裡的殘留物可以知道，當時汙染的程度是非常高的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 237 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (237,'zhTW','為了揭開這個秘密，我已經開始對現存的生物進行研究，以此來尋找線索。湖岸潛藏者和湖岸爬行者都是居住在洛丹米爾湖中央的古老動物，它們身上長著一種苔蘚，和某些化石的痕跡有些相似。我還需要進行更多研究才能推測出其中的聯絡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 238 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (238,'zhTW','在蒐集苔蘚標本的時候，我經歷了一場血腥的戰鬥。邪鰭部族的魚人遭到了一群豺狼人的襲擊，戰場上留下了無數魚人和豺狼人的屍體。我注意到某個魚人的傷口上長著一個堅硬的腫瘤。仔細觀察這個腫瘤之後，我發現它和我收集的苔蘚的特性差不多。不幸的是，除了這具屍體之外，我在別的屍體上找不到類似的腫瘤了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 243 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (243,'zhTW','比索·埃斯沙德大人：$B$B遵照您的指令，我派遣這個$c來為您效力。$B$B$g他:她非常可靠，而且聽從指揮，在對付天災軍隊的過程中證明了自己的實力，所以我選擇$g他:她來協助您完成任務。$B$B祝您安好，$B——執政官塞弗倫',0);
DELETE FROM `page_text_locale` WHERE `ID` = 244 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (244,'zhTW','比索·埃斯沙德大人：$B$B遵照您的指令，我派遣這個$c來為您效力。$B$B$g他:她非常可靠，而且聽從指揮，在對付天災軍隊的過程中證明了自己的實力，所以我選擇$g他:她來協助您完成任務。$B$B祝您安好，$B——執政官塞弗倫',0);
DELETE FROM `page_text_locale` WHERE `ID` = 245 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (245,'zhTW','失蹤：基沙恩下士$B$B 他在石堡要塞的血腥戰役中失蹤，據說已被黑石獸人俘虜。$B$B基沙恩下士應該是被關押在湖畔鎮北面的黑石營地中，也就是通往燃燒平原隘口的西邊。$B$B根據所羅門鎮長的命令，任何救回基沙恩下士的勇士都將受到治安官馬瑞斯的嘉獎。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 246 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (246,'zhTW','我花了好幾個星期到處逃跑，因為害怕黑騎士追殺，所以我從不敢在一個地方逗留太長的時間。我現在躲在烏鴉嶺的一座廢棄的小鎮裡，和平常一樣東躲西藏。我不敢面對他們殺死斯溫妻子時所用的那種未知魔法，而且我知道他們還在暮色森林中搜尋鐮刀。讓我感到慶幸的是，它已經不在我手裡了，否則的話我肯定會被他們發現。即使是現在，我也知道自己終究會被別人發現。$B$B我實在是太累了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 247 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (247,'zhTW','您好，主人。$B$B請原諒我用這種方式給您寫信。奧特蘭克的暗影法師正在忙於他們的計劃，我不得不使用外面的——從我們新的“盟友”中招募的——信差給您送信。但我用了我們最深奧的密碼來撰寫這封信的具體內容，所以由這些鄉巴佬送信是非常安全的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 248 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (248,'zhTW','您好，主人。$B$B請原諒我用這種方式給您寫信。奧特蘭克的暗影法師正在忙於他們的計劃，我不得不使用外面的——從我們新的“盟友”中招募的——信差給您送信。但我用了我們最深奧的密碼來撰寫這封信的具體內容，所以由這些鄉巴佬送信是非常安全的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 249 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (249,'zhTW','瓦里克：$B管好那些奴隸，等我們回來。繼續在這裡儲存它是很危險的。我們將到北方去，到一個不可能被發現的地方去。$B$B它們只不過是動物，不過是兇殘的動物——只要它們有了一定的數量，我們就有大麻煩了。絕對不能讓它們集結起來，這是我最不想看到的事情。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 250 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (250,'zhTW','迪菲亞總部來的一隊人會與收貨人聯絡，後者會將他收到的黃金進行轉交。$B$B一定要確保這個過程謹慎無誤地完成。負責轉移黃金的是收貨人，不過迪菲亞兄弟會的每個成員都有責任幫助他完成任務。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 251 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (251,'zhTW','我的兄弟們，記住，我們曾經是值得驕傲的工匠。我們要用工匠慣有的縝密和謹慎來完成現在的任務。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 252 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (252,'zhTW','恐怕當初我父親決定留下來守衛家園是個嚴重的錯誤。亡靈的部隊已經席捲了提瑞斯法林地，雖然我們做好了防禦的準備，而且補給也很充足，但是由於我兄弟代弗林的背叛行為，現在我們缺少足夠的人手來抵抗亡靈的不斷襲擊。$B$B伊維特，如果你接到了這封信，那麼你一定要明白，代弗林是叛徒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 253 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (253,'zhTW','代弗林因為感到絕望而臨陣逃脫，他與亡靈簽訂了一份協議。我不知道他的背叛行為到底給他帶來了多少好處，但是我知道其中必定有詐。$B$B如果你看到我的兄弟，那就快點逃跑吧，因為他已經變成了一個惡魔。幾天前的一個夜晚，他殺死了兩個看守，趁我們都在睡覺時把一小隊亡靈帶了進來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 254 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (254,'zhTW','他們發起了凌厲的攻勢。在我們幹掉這些偷襲者之前，他們又殺了一個人。現在我們沒有足夠人來守衛邊界。要不了多久，我們就會筋疲力盡，而亡靈又會發起攻擊。$B$B雖然那天晚上我在那些拼死作戰的人和麵色憔悴的亡靈中看到了代弗林的臉，但是在我抓到他之前，這個懦夫就溜走了。也許他已經死了，也許他還活著，給亡靈當間諜。$B$B不管怎樣，他都是個怪物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 255 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (255,'zhTW','代弗林警告過我們，與亡靈為敵必死無疑。早在我們被包圍之前——大概就是亡靈剛剛進入提瑞斯法林地的時候，他就說過這話。也許他是想懇求我們離開，也許他是在幸災樂禍。$B$B我總是很難理解代弗林的動機，他從小就是那麼神秘。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 256 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (256,'zhTW','不過他是對的，我們的確失敗了，阿加曼德家族將會從此消亡。雖然我現在還活著，但我知道自己的死期也不遠了。$B$B我並不害怕，也不後悔留下來和家人待在一起，不過我最後牽掛的還是你。$B$B你要好好活下去，我親愛的伊維特，那樣我才能安息，$B——索爾曼',0);
DELETE FROM `page_text_locale` WHERE `ID` = 257 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (257,'zhTW','我們的計劃進行得很順利，正如以前提到過的一樣，我們與一隊自稱辛迪加組織的人類結了盟。他們的首領以前曾是奧特蘭克的貴族，他們希望能再次控制這裡。$B$B因此，這些愚蠢的人類與我們達成了一個協議，他們將會為此而後悔。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 258 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (258,'zhTW','現在辛迪加組織在這邊的勢力還很小，不過他們對這一帶非常瞭解，並且有充足的人力。我相信只需加以適當的引導，辛迪加就能再次統治奧特蘭克。$B$B而且，我們已經督促辛迪加向附近阿拉希高地的激流堡城進軍。我們的軍隊、食人魔，還有激流堡的人類在那裡展開了一場曠日持久的戰鬥，不過我認為，只要有正確的策略，我們就能佔據那座曾經偉大的城市。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 259 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (259,'zhTW','完成了這一步，我們就可以開始下一階段的計劃。在擁有了自己的國家和這個地區的前沿基地之後，我們就可以為第三次入侵作準備了。$B$B不久，軍團的首領將會表彰我們，讓從天而降的烈焰吞噬整個世界！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 260 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (260,'zhTW','希爾斯布萊德城鎮文件$B$B希爾斯布萊德的人民發誓將永遠效忠於偉大的鐵爐堡國王麥格尼·銅鬚和暴風城國王安度因·烏瑞恩所建立的聯盟。$B$B此檔是為管理奧特蘭克地區的城市而建立，併為國王和聯盟的納稅人服務。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 261 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (261,'zhTW','希爾斯布萊德城鎮文件$B$B希爾斯布萊德的人民發誓將永遠效忠於偉大的鐵爐堡國王麥格尼·銅鬚和暴風城國王安度因·烏瑞恩所建立的聯盟。$B$B此檔是為管理奧特蘭克地區的城市而建立，併為國王和聯盟的納稅人服務。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 262 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (262,'zhTW','教師盧瑟福·博塞德$B債務已還清。$B$B鐵匠埃沃裡·維林塔$B債務已還清。$B$B書記員霍拉斯·懷特斯蒂$B債務已還清。$B$B議員吉利斯$B債務已還清。$B$B議員胡克斯$B債務已還清。$B$B農夫蓋斯$B債務已還清。$B$B農夫雷恩$B欠款，收穫時以農作物償還。$B$B農夫萊恩$B欠款。租地被收回。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 263 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (263,'zhTW','農夫卡拉巴$B欠款，收穫時以農作物償還。$B$B平民維爾克斯$B債務已還清。$B$B平民博諾安$B債務已還清。$B$B礦工威爾迪$B欠款，碧玉礦坑送來下批礦石時償還。$B$B礦工西尼$B欠款，碧玉礦坑送來下批礦石時償還。$B$B礦工哈克特$B欠款，碧玉礦坑送來下批礦石時償還。$B$B第二行$B$B礦工奧維爾$B欠款，碧玉礦坑送來下批礦石時償還。$B$B礦工菲格拉德$B欠款，碧玉礦坑送來下批礦石時償還。$B$B平民奈杉德$B債務已還清。$B$B平民梅恩$B債務已還清。$B$B工頭邦德斯$B欠款，碧玉礦坑送來下批礦石時償還。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 265 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (265,'zhTW','一支亡靈小隊毫不顧忌人類和亡靈之間的對立關係，到我們這裡來躲避他們的“同胞”。克甘達瑪是這支小隊的隊長，他的皮膚已經腐爛，他的血液早已停止了流淌，但他卻顯得彬彬有禮，他對同伴安全的關心甚至勝於關心他自己。$B$B實際上，我甚至覺得他擁有我周圍的人已經喪失許久的人性。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 266 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (266,'zhTW','一支亡靈小隊毫不顧忌人類和亡靈之間的對立關係，到我們這裡來躲避他們的“同胞”。克甘達瑪是這支小隊的隊長，他的皮膚已經腐爛，他的血液早已停止了流淌，但他卻顯得彬彬有禮，他對同伴安全的關心甚至勝於關心他自己。$B$B實際上，我甚至覺得他擁有我周圍的人已經喪失許久的人性。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 267 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (267,'zhTW','但是我為什麼要提到這個？我之所以這樣做是為了表明我將要寫下的東西是可信的，因為這些話來自克甘之口，我希望我的同胞看到這本日記，知道我為什麼要相信他的話：$B$B“還有一些上古之神在世界的深淵中游蕩，新的勢力在尋找支配這些古老力量的方法，誰成功了，誰就將得到一件可怕的武器去對付他的敵人。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 268 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (268,'zhTW','這就是克甘達瑪將他的血石墜飾遞給我時所說的話，那時他的眼裡還帶著某種恐懼或是敬畏。他的手接觸到我的手時猶豫了片刻，好像不願放棄那個墜飾。一股反感的力量傳遍了我的全身，而至今我還不清楚當時是我自己排斥他那已死亡的肉體，還是墜飾本身讓我毛骨悚然。$B$B因為我感到了墜飾中隱藏的力量，那是一股深沉、隱蔽、飢渴的力量，它似乎極度希望被釋放出來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 269 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (269,'zhTW','我在達拉然的同事對研究克甘帶來的血石不太感興趣，而是很快隔離了那四個流亡者，並把血石繼續留在他們身上。但是克甘的真誠促使我開始著手研究他的血石墜飾。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 270 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (270,'zhTW','我希望能夠和我的同事透過研究證明那種石頭確實具有某種魔法特性，如果達拉然的巫師不希望發掘血石的能量，那麼我們至少應該瞭解它的特性，因為我們的敵人也許會利用血石對付我們。$B$B所以我的研究開始了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 271 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (271,'zhTW','在實驗的第一階段，我假定血石是一種岩石，比如石英石或黑曜石之類的。於是我做了一系列實驗以確定血石所含的礦物成分，以及與其顏色、硬度等特性有關的成分。令我沮喪的是，這塊血石和一般的礦石不一樣，我的實驗毫無結果。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 272 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (272,'zhTW','事實上，血石常常出現和我的預期完全相反的反應！它好像在故意和我的實驗作對。$B$B它似乎是具有生命的，而且還會思考。$B$B雖然很惱怒，但我並不氣餒，我決定不再把它當作一塊沒有生命的岩石來研究。$B$B然而我又一次失敗了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 273 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (273,'zhTW','我的所有新實驗都無法揭示這塊血石的來歷。我那時所解開的唯一一個謎就是：血石既不是活的，也不是死的！$B$B不過正是在失敗的邊緣，我迎來了一個大突破。我最近的實驗裡使用了一隻玻璃杯，杯口邊有個小小的鋸齒狀的缺口，在實驗又一次以失敗告終之後，我去打掃工作臺，結果一不小心被那個杯子割傷了手。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 274 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (274,'zhTW','傷口不深，但是血流不止。在我開始用繃帶包紮受傷的手指時，已經有很多血流到了工作臺上。$B$B此時我發現了一件很奇怪的事情……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 275 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (275,'zhTW','濺在血石墜飾周圍的血似乎受到了某種引力的作用，全部都被吸向那塊寶石。血液一碰到墜飾就消失了，而在吸收了我的血之後，石頭的紅色變得更深了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 276 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (276,'zhTW','看到這個，我的頭腦一下子清醒了不少，也許是因為我的新傷口（雖然我不敢相信自己居然流了那麼多血），也許是因為在屢遭挫折之後終於發現了血石的秘密。我坐下來開始思考，腦中不斷湧現各種想法和問題，這讓我頭暈目眩、搖搖欲墜。$B$B血石會吸收鮮血？它渴望鮮血嗎？它還會吸引鮮血？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 277 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (277,'zhTW','或許血石是用血製成的？如果是這樣的話，那它所用的是誰的血呢？我的？任何人類的血？或是隨便什麼動物的血？$B$B也許血石是用某種未知事物的血製成的，就是克甘將墜飾交給我時又懼怕又崇敬的那個東西。$B$B我一定要找到這個問題的答案，它是一切的關鍵。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 278 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (278,'zhTW','這重新激起了我的熱情，我又投入到研究之中。這次我沒有做假設，而是系統地完成了各項試驗。這需要我更加努力地工作，當然也意味著會有更大的發現。$B$B另外，儘管我的實驗室很小，而且沒有助手的幫助，但是我終於發現了血石的另一個有趣的特點。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 279 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (279,'zhTW','除了血，還有一些自然力量附在這塊石頭上。火，水，雷，石，它們與血混合在一起（但這個問題仍然存在：到底是誰的血？），雖然這種混合物外表上看起來很平靜，但是各種力量在它內部相互爭鬥著。這讓我對這個奇怪的不祥之物有了更多的疑惑。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 280 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (280,'zhTW','不過要回答這些問題，還需要對墜飾進行更多的研究和實驗，洛丹米爾收容所恐怕無法提供相應的人力和裝置。因此我派了一個信差把血石墜飾送到達拉然去，並給他們提供了關於如何進行實驗的具體說明，以免他們重複我曾經犯過的錯誤。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 281 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (281,'zhTW','在等待那裡的實驗結果的日子裡，我又去找克甘談了談。儘管我不斷逼問他關於血石的事，他卻沒有再多說一句。他也很少提及在他所屬的不死生物群體——他稱之為“被遺忘者”——那邊度過的日子。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 282 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (282,'zhTW','但是克甘看起來更喜歡談點別的東西，特別是在洛丹倫淪陷之前他在那裡成長的時光。$B$B他依然深深地愛著那個現在已經變成一片廢墟的王國。$B$B克甘越來越吸引我，這使我不再那麼焦急地等待實驗結果了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 283 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (283,'zhTW','可是過了幾個星期還是沒有收到訊息，我的耐心開始動搖了。向達拉然詢問之後，我才得知血石居然根本沒有送到我同僚的手上。我的信差在半路失蹤，血石也和他一起消失了！$B$B這是個沉重的訊息。雖然克甘和他的人還有血石樣本可以供我實驗，不過我擔心這枚墜飾會落在邪惡勢力的手中。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 284 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (284,'zhTW','我已經派了另一個信差去達拉然，並且聽說他們現在已經開始在我們的保護範圍之外的廢墟中搜尋那枚墜飾了。$B$B我只希望我們行動得不是太晚。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 285 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (285,'zhTW','遊蕩者格里雷克的故事$B$B[……碑文的頭幾行已經被磨損得無法看清了，不過最後幾行還可以辨識……]$B$B格里雷克跺著腳穿越叢林。因為憤怒，他的雙眼冒著火，嘴裡發出低沉的聲音。$B$B他高舉左手朝天怒吼著。經過長期的狩獵，他的左臂顯得異常強壯。$B$B格里雷克很久之前就永遠地失去了他的右臂。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 286 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (286,'zhTW','巨魔傳說，第三卷$B海潮之石$B$B作者：大法師安斯雷姆·魯因維沃爾$B達拉然$B$B序言$B$B古老的古拉巴什帝國是許多令人著迷的傳說的發源地，這些傳說毫無疑問和他們周圍的環境有關，因為透過對他們的信仰和社會習慣的研究，我發現他們對於自然表現出了極度的尊崇。$B$B在上一卷中，我已經詳細描述了巨魔對於蛇的崇拜，在這一卷中我要談的是他們與大海的有趣而獨特的關係。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 287 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (287,'zhTW','庫德蘭·蠻錘$B$B著名的巨龍戰士，鷹巢山的獅鷲飛行員，進攻德拉諾獸人世界的聯盟遠征軍獅鷲分隊的指揮官。可能已陣亡。$B$B“我們將聽到風中傳來獅鷲的召喚，我們將聽到戰錘敲擊的聲音迴響在山間。勇敢地面對困境吧，我的兄弟。祖先的聖堂在召喚著你。”$B$B——弗斯塔德·蠻錘，鷹巢山國王',0);
DELETE FROM `page_text_locale` WHERE `ID` = 288 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (288,'zhTW','遊俠隊長奧蕾莉亞·風行者$B$B奎爾薩拉斯著名的遊俠，令巨魔聞風喪膽的獵人。進攻德拉諾獸人世界的聯盟遠征軍偵查隊長兼情報特派員。可能已陣亡。$B$B“你的心如利箭，在風中筆直地飛翔，我的姐妹。你是我們軍隊中最聰慧的勇士，也是我們族人中最受敬愛的領袖。”$B$B——希爾瓦娜斯·風行者，奎爾薩拉斯遊俠將軍',0);
DELETE FROM `page_text_locale` WHERE `ID` = 289 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (289,'zhTW','肯瑞託的卡德加大法師$B$B麥迪文的學徒，進攻德拉諾獸人世界的聯盟遠征軍最高指揮官。可能已陣亡。$B$B“沒有人能夠如此無私地深入最黑暗而危險的戰場。不管你在哪裡，我們都希望你一路順風，勇敢的流浪者。”$B$B——安東尼達斯，達拉然大法師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 290 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (290,'zhTW','圖拉揚將軍$B$B安杜因·洛薩公爵的將官，白銀之手騎士團的聖騎士，進攻德拉諾獸人世界的聯盟遠征軍的高階將領。可能已陣亡。$B$B“Esarus thar No\'Darador——我們以鮮血捍衛榮譽。我的朋友，你是公正與美德的化身。你的名字將是我們永遠的榮耀。”$B$B——光明使者烏瑟爾，白銀之手騎士團',0);
DELETE FROM `page_text_locale` WHERE `ID` = 291 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (291,'zhTW','達納斯·托爾貝恩$B$B激流堡的民兵指揮官，進攻德拉諾獸人世界的聯盟遠征軍總指揮官圖拉揚將軍的戰略顧問。可能已陣亡。$B$B“孩子，你的經歷和犧牲將永遠被我們銘記。自我們的光輝帝國建立之日起，英雄的鮮血便浸透了整個帝國的歷史。”$B$B——索拉斯·托爾貝恩，激流堡公爵',0);
DELETE FROM `page_text_locale` WHERE `ID` = 292 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (292,'zhTW','光明使者烏瑟爾在此安息$B$B第一聖騎士，白銀之手騎士團的奠基人$B$B烏瑟爾誓死保衛洛丹倫王國，儘管他最心愛的學生背叛了他，但我們相信他的靈魂永生。即使厄運降臨於我們的故土，他依然在關注著我們。他的光芒將照亮所有人類前行的路途——只要我們依然以他為榜樣，它就永遠不會消失。$B$B——無名氏',0);
DELETE FROM `page_text_locale` WHERE `ID` = 293 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (293,'zhTW','無盡之海$B$B古拉巴什帝國三面環海，因而水就自然成為了巨魔部落元素信仰中的一個重要組成部分。雖然巨魔能夠在他們叢林帝國的廣袤土地上肆意妄為，可是大海卻絲毫不受他們的影響。大海是如此浩瀚而又神秘莫測，即使對強大的巨魔來說，它也是個令人不安的鄰居。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 294 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (294,'zhTW','值得注意的是，最近的發現表明，巨魔對跨越無盡之海的興趣似乎非常小。雖然在整個艾澤拉斯、洛丹倫和卡茲莫丹地區都有巨魔出沒，但是在新大陸卡利姆多及南海的島嶼上卻沒有巨魔文明的跡象。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 295 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (295,'zhTW','這是否證明巨魔不願冒險離開他們的領土，或是他們缺乏長途旅行所必需的相應技術？這一點還有待進一步研究分析，但它已經不是本文要探討的了。$B$B不過有一樣東西會引起所有人的注意，最近在荊棘谷的大片巨魔廢墟中找到的線索顯示了巨魔和大海相關的一面，這一面以前從未為人所知，也沒有相關的史料記載。$B$B海潮之石$B$B最近在荊棘谷巨魔廢墟中的發現涉及到了一件叫做“海潮之石”的東西。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 296 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (296,'zhTW','將巨魔傳說中的許多片段結合在一起，我們便可以得到關於這塊石頭的完整描繪、以及它對古老的古拉巴什帝國的重要意義。$B$B海潮之石似乎可以將支配各種形式的水的力量賦予其擁有者，包括對河流、雨水和潮汐等形式的支配。根據這些和海潮之石的用途有關的故事，我猜測它實際上是水之領主的力量的物質表現形式。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 297 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (297,'zhTW','這件東西如何乃至何時擺脫水之領主的控制而落入巨魔的手中，這則是另外一個問題，對我來說也還是個謎。$B$B控潮者$B$B和潮汐的漲落一樣，海潮之石進入了巨魔的世界，然後又消失，每一次在巨魔手中停留？？時間決不會超過一代。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 298 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (298,'zhTW','根據巨魔的傳說，海潮之石第一次來到古拉巴什帝國，是被一個巨魔戰士在荊棘谷海岸邊閒逛時發現的。他看到了這塊神奇的藍色石頭，石中還浮動著乳白色的線條。戰士帶著這塊有趣的石頭繼續旅程。$B$B過了一段時間，戰士發現這塊石頭能給他帶來控制水的能力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 299 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (299,'zhTW','他可以藉此召喚完全由水組成的生物：水元素——原本只有肯瑞託的大法師才具有這種能力。$B$B這個戰士來到了帝國的核心地帶祖爾格拉布，向國王展示他的能力。顯然，他迅速成為了全帝國關注的焦點。古拉巴什的國王也被他的能力折服，立刻給他封了一個榮譽職位：“控潮者”，而他原來的名字則逐漸被遺忘了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 300 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (300,'zhTW','接下來的很多年裡，控潮者都在為古拉巴什帝國效力，他在戰鬥中召喚水元素助陣，為了帝國改變荊棘谷的水流。不過時間久了，控潮者開始喜歡隱居獨處，他離開皇宮的時間也越來越久。$B$B控潮者對古拉巴什帝國隱瞞了一個秘密——海潮之石在賦予他強大能力的同時還對他施加了一個詛咒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 301 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (301,'zhTW','隨著時間的流逝，控潮者的身體開始漸漸消失。隨著潮汐的每次漲落，他都會失落一部分肉身——身體一會兒出現一會兒消失——直到臨死時，他來到了最初找到石頭的那片海灘，步入大海，從此消失。$B$B又經歷了好幾代的時間之後，海潮之石再一次被衝到荊棘谷的海岸上，又被另一個控潮者拾得，然後這個巨魔又將它帶到祖爾格拉布去。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 302 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (302,'zhTW','這樣的過程一代接一代地不斷髮生，石頭隨著潮汐出現，控潮者隨著潮汐離開。$B$B今天，到處都有關於潮汐之石的故事，但是依然有一個疑問，為什麼這個具有如此強大能量的東西會出現得這麼有規律？這一切究竟是由誰掌控的？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 303 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (303,'zhTW','血帆命令$B$B親愛的水手們，請仔細看好這篇命令中的內容，因為我們在藏寶海灣發財的機會只有一次。$B$B我已經派鄧肯守在北邊，並告訴他等待行動的訊號。$B$B達姆希的好運號將停靠在南邊的海角旁等待補給命令。小個子的斯蒂沃特船長會讓他的船員做好運送戰利品的準備。我相信布魯圖斯那個蠢貨會是我們最大的麻煩。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 305 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (305,'zhTW','我讓尼哈魯船長把斬浪號從東南方向開到岸邊去。等訊號發出後，我們就讓他的船員衝出來。$B$B加爾·鹽蹄那個壯漢可以打前鋒，我們要讓裡維加茲和卡拉·海角措手不及，把他們送到海底餵魚去。$B$B你們幾個負責把一切對範克里夫的計劃有價值的東西都搶走。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 306 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (306,'zhTW','我讓尼哈魯船長把斬浪號從東南方向開到岸邊去。等訊號發出後，我們就讓他的船員衝出來。$B$B加爾·鹽蹄那個壯漢可以打前鋒，我們要讓裡維加茲和卡拉·海角措手不及，把他們送到海底餵魚去。$B$B你們幾個負責把一切對範克里夫的計劃有價值的東西都搶走。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 307 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (307,'zhTW','我會命令艾隆帕開火，防止任何黑水海盜的船隻進出港口。$B$B紅霧號的彈藥打光之後，我會將她開到斬浪號旁邊對她進行補給。$B$B等鹽蹄和他的人在鎮子上放了火之後，所有人都回到船上去，我們就立刻開船，還可以在野人海岸給藏寶海灣再來一次炮擊。$B$B——艦隊指揮官菲爾拉倫',0);
DELETE FROM `page_text_locale` WHERE `ID` = 308 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (308,'zhTW','坐著那條破船從贊吉爾身邊逃跑似乎是很明智的，但是現在我開始覺得死亡也許是個更好的選擇。$B$B我想是我祖先的恩賜讓我逃脫了他們的懲罰。但是現在我又覺得，如果我能經受住監獄生活的考驗，沒準我能獲得無比珍貴的智慧。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 309 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (309,'zhTW','統治這座小島的野獸……它的力量實在是太強大了。其他的生靈都在它面前退縮，就連兇猛的黑豹也一樣。現在我似乎還是可以聽到它的吼叫聲，這聲音總是讓我魂飛魄散。$B$B那些生物會阻止任何想要到這座小島上來的人，我必須對我的祖先充滿信心。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 310 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (310,'zhTW','我想念我的部族，還有我的家人。我會愉快地迎接空曠平原上吹過的風，或是雷霆崖的日落，而不是這座溼熱的叢林。$B$B我能看見不遠處清澈的海水，但那並不能使我平靜下來，它只能勾起我對被關押的那段日子的記憶。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 311 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (311,'zhTW','第1天：$B早上6點到11點——收拾營地$B上午11點到11點半——休息，吃午飯$B上午11點半到下午4點——經過一條峽谷$B$B第2天：$B與第一天的安排一樣$B$B第3天：$B同樣的安排$B$B第4天：$B同樣的安排，但有一個例外。日落前，在索爾森經過峽谷時，他要我掩護他一下。我猜他要去見我們的人。$B$B讓我感到意外的是，他一小時之後就回來了。我原本希望他見過我們的人之後能夠和庫爾森重新會合，但看來事情並不是這樣。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 312 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (312,'zhTW','第5天：$B索爾森今天顯得十分不安。一定是他昨天值勤途中遇到的什麼人或什麼東西讓他感到恐懼。$B$B我以為我們的人已經和他談過了，不過當我詢問索爾森在我掩護他時去了哪裡的時候，他卻默不作聲。他把我當作朋友，所以他認為不告訴我這個危險的秘密可以保護我。$B$B他的忠誠用錯了地方，但是這種忠誠卻十分強大。他和我們重新匯合之後一定會成為庫爾森軍隊有力的增援。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 313 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (313,'zhTW','第6天：$B一大早，索爾森與尤瓦中士進行了一次長談。我不得不假裝睡覺，因此不敢移動身體去偷聽他們的談話。但是我猜他們正在談論索爾森前幾天的那次值勤。$B$B我在午餐時近距離地觀察尤瓦，發現他也在觀察我。不久，多倫又叫上了索爾森。多倫和尤瓦肯定知道索爾森正在與你的人會面。$B$B他在為叛軍做間諜。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 314 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (314,'zhTW','我們不能再給索爾森提供更多情報了，必須除掉他。他對我們已經不再有用。$B$B如果有機會的話，我會殺了索爾森，但是如果你收到了這封信，那就表示我還沒找到機會。$B$B在這種情況下，我建議在索爾森與我們的人下一次見面時給他致命的一擊。$B$B——M',0);
DELETE FROM `page_text_locale` WHERE `ID` = 315 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (315,'zhTW','議會將任用您來統御人類和矮人領地的部隊，這是個明智的決定。我很榮幸可以在奧特蘭克擔任您的助手。$B$B以薩格拉斯的名義。$B$B納伽德',0);
DELETE FROM `page_text_locale` WHERE `ID` = 316 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (316,'zhTW','蠢貨！$B$B我的計劃是同時摧毀那兩座橋。你們這些頭腦簡單的蠢貨都幹了些什麼？你們只完成了一半的任務，還讓整個聯盟都對我們產生了警惕。你們全都是蠢貨！$B$B你們只有一次彌補錯誤的機會。我們在離橋不遠處的阿拉希高地還有個秘密據點，那裡還藏有一些炸藥。$B$B如果你們還想繼續活下去，就得給我完成任務！$B$B——卡姆·深怒',0);
DELETE FROM `page_text_locale` WHERE `ID` = 317 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (317,'zhTW','我親愛的薩拉：$B$B我想我們這幾天要去看守薩多爾橋。也許我從此就無法再給你寫信了，所以現在我很想給你寫點東西，讓你知道我在生命中最後的日子裡都在想念著你。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 318 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (318,'zhTW','我們的任務可能要持續好幾天，並且充滿了樂趣，但是對我而言，它也許意味著殘酷的戰鬥和死亡。如果我必須在戰場上為聯盟而犧牲的話，那麼我隨時都作好了這種準備。$B$B對於我所從事的事業，我充滿了信心，勇氣永遠與我同在。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 319 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (319,'zhTW','我知道鐵爐堡王國非常需要聯盟的勝利，而我們欠那些在惡魔戰爭中浴血奮戰的犧牲者很多東西，我多麼希望能放棄此生所有的快樂去維繫這個聯盟，並還清欠那些犧牲者的債。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 320 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (320,'zhTW','薩拉，我對你的愛是永遠不滅的，它如同無形的繩索束縛著我，沒有東西能夠解開它。而我對王國的熱愛則像強風一樣襲來，讓我在戰場上也無法不想念著你和我們的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 321 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (321,'zhTW','我不斷想起和你一起度過的美好時光。我感激聖光，也感激你。我和你度過了那麼多美妙的日子，而現在我卻不得不放棄這一切。我們本來還可以生活在一起，相親相愛，看著我們的兒子在身邊慢慢成長，然而現在我不得不放棄這些希望，這對我來說是多麼困難的一件事啊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 322 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (322,'zhTW','我對於我神聖的使命沒有什麼抱怨，不過我總是聽到有人在對我輕聲低語——也許是風吹來了我的小愛德格的祈禱，它告訴我一定要安然回到我所愛的人身邊。我親愛的薩拉，如果我不能回去，請你不要忘記我對你的愛有多深。即使我在戰場上永遠停止了呼吸，我也會在那之前輕輕呼喊你的名字。$B$B請原諒我以前所犯的錯和我給你帶來的那些痛苦，我那時總是那麼愚蠢，那麼自私。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 323 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (323,'zhTW','如果我能用眼淚清洗影響你快樂的那些汙點，如果我能和這個世界上的所有災禍鬥爭，保護你和我心愛的孩子免受傷害，那對我該是多麼快樂的事啊。$B$B但是我做不到。$B$B當你帶著我們的孩子與殘酷的命運鬥爭時，我會在扭曲虛空中看著你，在你身邊徘徊，悲傷而又耐心地等待著我們再也不用分開的那一天。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 324 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (324,'zhTW','一座海水之塔從海中升起，獵潮者耐普圖隆派出巨型章魚去消滅伊拉萊。它們的體型是如此的巨大，如叢林一般巨大的海藻纏繞著它們的觸手，海中的巨獸在它們的身體上游走。$B$B最大的一隻章魚高高舉起它的觸手拍打水面，激起了一層層比山還高的海浪。它們憤怒地衝向伊拉萊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 325 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (325,'zhTW','章魚咆哮著，發出了雷霆般的響聲：$B$B“我們來了。”$B$B米洛斯毫不動搖地矗立著，不斷地施展他的魔法力量。海浪分成兩股向伊拉萊襲去，淹沒了它們前面的叢林。米洛斯命令他的手下開始施展法術，喧鬧聲瞬間變成無數巨魔的齊聲吟唱。$B$B這時在所有聲音中有一個聲音顯得尤其突出。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 326 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (326,'zhTW','米洛斯怒吼著，他手下的力量都被彙集起來向章魚釋放過去。$B$B大海被一劈為二，米洛斯的法術以光的速度投向耐普圖隆的僕從。閃電撕破了天空，這股力量正中大章魚，瞬間雷霆萬鈞，海水也被蒸發得一乾二淨，大地上留下的只有一個燃燒的巨坑。$B$B米洛斯相信他的法術可以擊垮這些巨大的章魚，於是他大叫著慶祝勝利。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 327 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (327,'zhTW','但是這些章魚都非常古老，它們看著大陸從海洋中升起。$B$B它們看著上古之神統治世界，又看著陌生的旅者將它們擊敗，它們看著魔法時代的興起。$B$B它們經歷了歲月蹉跎，它們掌握著許多秘密。雖然米洛斯的法術十分強大，但是他和巨魔一樣終究只是肉身。$B$B於是他的法術失敗了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 328 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (328,'zhTW','法術沒有制服章魚，反而激怒了它們。千萬年來，沒有任何凡人能夠帶給它們痛苦，而巨魔的法術卻令它們如此痛苦。$B$B因此它們擺脫了米洛斯的法術束縛，咆哮著展開了復仇。$B$B隆隆聲從海底傳來，那是滔天海浪來襲的預兆。在它們到達伊拉萊時，陰影籠罩了整座城市。$B$B然而在海浪摧毀城市之前，章魚泰然自若地停下了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 329 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (329,'zhTW','巨魔巫醫開始顫抖，充滿恐懼地呼喚他們的主人。米洛斯凝視著重重海浪，雖註定失敗卻仍面露藐視。他又開始施展自己擅長的那一套，默唸著咒語，巨魔將他最後的話語蝕刻成石。然後米洛斯泰然面對來襲的章魚。$B$B他面部扭曲，奮力投出所有的力量，這是他的最後一擊。$B$B章魚將它們的憤怒都傾瀉在米洛斯身上，接著整個大海都向伊拉萊撲了過去。$B$B一切都結束了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 330 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (330,'zhTW','水淹沒了叢林，沖走了所有的東西。巨魔和野獸尖叫著被大水衝過、淹沒。$B$B許多古拉巴什的居民還沒搞清楚大海為什麼吞沒他們，就已經葬身海底了。$B$B最終海水衝到山前停了下來，然後撤回到它們原本所在的地方，留下的只有死一般的寂靜。$B$B海水退去了，但是它們依然在伊拉萊四周湧動，時刻準備著將它永遠淹沒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 331 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (331,'zhTW','瓦加祖爾安全地躲在山後的祖爾格拉布，當他走入叢林時，他發現自己的人民已經全部被海浪捲走了。$B$B他絕望了，因為他征服的夢想已經破碎。$B$B從此之後，也沒有人再看見過聖蛇米洛斯。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 332 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (332,'zhTW','瓦加祖爾安全地躲在山後的祖爾格拉布，當他走入叢林時，他發現自己的人民已經全部被海浪捲走了。$B$B他絕望了，因為他征服的夢想已經破碎。$B$B從此之後，也沒有人再看見過聖蛇米洛斯。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 333 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (333,'zhTW','尊敬的陛下：$B$B作為一個普通戰士的妻子，我明白自己是不能向您這樣偉大的領導者的行為提出疑問的。從洛克莫丹的湖畔到丹莫洛的雪峰，我們的國土上正在發生的戰爭是為了保護我們的朋友與愛人的生命而進行的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 334 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (334,'zhTW','但是我們以保衛生命的名義所發動的戰爭需要付出多大的代價？要犧牲多少戰士才能讓我們認識到，我們拼命想要保護的生命正在從戰場上離開我們？$B$B我們還要在刀光劍影下撕碎多少未來的希望？究竟需要多少被鮮血浸溼的土地才能讓我們把過去的恩怨埋葬？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 335 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (335,'zhTW','這不是一個普通戰士的妻子應該提的問題。$B$B然而我現在是作為一個普通戰士的遺孀給您寫這些的。我的丈夫只是您成千上萬個士兵中的一員，而對於我來說，他就是偉大的蘇利·巴魯，是我孩子的父親，是我心愛的丈夫，是要和廝守終生的伴侶。$B$B偉大的陛下，如果我的問題對您不敬，請原諒我。但是逝者已經不能親自來問這些問題了……$B$B您忠誠的臣民，$B薩拉·巴魯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 336 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (336,'zhTW','施涅德：$B$B你好。我相信運河地區的生意很興隆，我們這兒的貿易區一直都很熱鬧。$B$B我們的存貨幾乎都用光了，現在急需布匹。請你儘快為我們供貨。$B$B祝你好運，另外，希望你的孩子索爾曼學業進步。$B$B——哈蘭·巴格雷',0);
DELETE FROM `page_text_locale` WHERE `ID` = 337 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (337,'zhTW','給庫爾提拉斯艦隊的正式命令$B$B我，普羅德摩爾將軍，將率領第一批部隊登陸卡利姆多海岸。$B$B我離開時，本尼迪克上尉負責全權指揮，並負責庫爾提拉斯軍隊的所有內部事務。如果12個月內我還沒有從提拉加德城堡傳回訊息，本尼迪克上尉將發動第二輪攻擊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 338 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (338,'zhTW','同時，我還派出了阿維羅德上尉在卡利姆多大陸執行偵察任務。他的部隊完成任務之後會與我們在提拉加德城堡的部隊會合。$B$B阿維羅德上尉的任務可能需要很長時間，因為這片新大陸幅員遼闊、充滿危機。如果我或者本尼迪克遭遇不幸的話，阿維羅德將接手城堡的指揮權。$B$B我們會發動一輪接一輪的攻擊，直到佔領這座要塞！$B$B——普羅德摩爾上將',0);
DELETE FROM `page_text_locale` WHERE `ID` = 339 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (339,'zhTW','部落徵兵通知$B$B以部落的名義，持此通知者已被證明具備出眾的力量和戰鬥技巧，我建議將其分派到十字路口去執行任務。$B$B此致$B$B——卡加爾·戰痕批准。——塔克林·尋路者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 340 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (340,'zhTW','部落徵兵通知$B$B以部落的名義，持此通知者已被證明具備出眾的力量和戰鬥技巧，我建議將其分派到十字路口去執行任務。$B$B此致$B$B——卡加爾·戰痕批准。——塔克林·尋路者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 341 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (341,'zhTW','部落徵兵通知$B$B以部落的名義，持此通知者已被證明具備出眾的力量和戰鬥技巧，我建議將其分派到十字路口去執行任務。$B$B此致$B$B——卡加爾·戰痕批准。——塔克林·尋路者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 342 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (342,'zhTW','巴爾莫丹的挖掘$B$B我們探險者協會派出的勘探員所發現的東西看來很有價值，這一帶埋藏著的文物對我們來說是無價之寶。無疑，我們可以在巴爾莫丹的沙土之下找到一些關鍵的線索。$B$B這個地區的地質情況使得我們不得不採取一些極端措施，因為許多沙地都因為長期處於荒蕪的環境和多變的天氣下而變得十分堅硬了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 343 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (343,'zhTW','解決的方法非常簡單。我們製作了強力的爆炸物，它的威力足以炸破最堅硬的物質。$B$B這項爆破工作開展起來必定會非常吵鬧，但是我們的工作顯然要比當地居民的生活安定更加重要。事實上，我們已經把一群牛頭人趕出了這個地區，而且這些牛頭人也確實是一群禍害。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 344 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (344,'zhTW','由於在這裡碰到了種種問題，我認為我們需要後方軍隊的支援。不僅僅是因為挖掘場需要軍隊的保護，另外巴爾莫丹的所在地對於聯盟來說也具有很大的戰略價值，因此，國王應該派兵駐守這裡。$B$B啊，我扯得太遠了。還有很多挖掘工作等著我去做呢。我已經花了太多時間來寫這個東西，沒時間去進行挖掘了……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 349 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (349,'zhTW','由於在這裡碰到了種種問題，我認為我們需要後方軍隊的支援。不僅僅是因為挖掘場需要軍隊的保護，另外巴爾莫丹的所在地對於聯盟來說也具有很大的戰略價值，因此，國王應該派兵駐守這裡。$B$B啊，我扯得太遠了。還有很多挖掘工作等著我去做呢。我已經花了太多時間來寫這個東西，沒時間去進行挖掘了……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 350 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (350,'zhTW','主動式負載平衡器控制檯可以自動調節燃料、燃氣、液體的流動及相關的機器裝置。在完成了初始化設定之後，只需簡單維護即可進行日常的執行。$B$B控制檯的主要部件（從左到右）依次是：$B$B主動力杆$B$B處於連線位置時，啟動主動式負載平衡器。將動力杆調至“關閉”位置時，機械裝置也不會自動鬆開，它只會',0);
DELETE FROM `page_text_locale` WHERE `ID` = 351 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (351,'zhTW','菲茲普羅克主管，你提交的裝置申請表已經拉茲杜克總裁批准。$B$B他讓我提醒你注意風險投資公司在整個卡利姆多大陸的既得利益。我們在貧瘠之地的鑽井和採礦業是有利可圖的，而且效益卓著，但是你所管轄的莫高雷地區還是需要為我們提供足夠的生產量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 352 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (352,'zhTW','菲茲普羅克主管，你提交的裝置申請表已經拉茲杜克總裁批准。$B$B他讓我提醒你注意風險投資公司在整個卡利姆多大陸的既得利益。我們在貧瘠之地的鑽井和採礦業是有利可圖的，而且效益卓著，但是你所管轄的莫高雷地區還是需要為我們提供足夠的生產量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 353 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (353,'zhTW','顧問委員會可以理解在如此靠近牛頭人領地的地方進行大規模的商業活動非常困難，但他們不會阻礙我們在該地區的總體計劃。$B$B我們很高興聽說你們已經開始在礦物儲量豐富的莫高雷平原上採礦了。正因為這樣，委員會才批准了你的物資申請。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 354 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (354,'zhTW','除了採礦，我們還希望莫高雷分公司能夠提供木材，另外還為你提供了原材料和幾臺新型粉碎機，用以建立一座伐木場。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 355 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (355,'zhTW','進入冷卻過程，要等一到兩分鐘才會完全關閉（視實際情況而定）。$B$B特別注意：只有當機器上的三個控制閥都鬆開的時候才能操作主動力杆。這些控制閥可以按照任意順序關閉。$B$B第一個是主控制閥，在垂直的巨大煙窗底部。接下來是燃料控制閥，在燃料箱（應有三個）和煙窗之間的管道上。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 356 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (356,'zhTW','最後是調節閥，在通往煙窗的兩個圓柱形油箱中的較低的那個上面。$B$BII.燃料指示計$B$B顯示主燃料箱、第二燃料箱和第三燃料箱的當前壓力。$B$BIII.流量計$B$B顯示當前系統內的流量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 357 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (357,'zhTW','IV.流量控制器$B$B升高或降低流量。由主動式負載平衡器自動控制。$B$BV. 溫度指使計$B$B顯示系統的操作溫度。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 358 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (358,'zhTW','星辰的孩子已經在永恆之井閃光的湖水邊定居了很久。眾所周知，象徵永恆曙光的艾露恩在就在這水中休憩。岸邊住著星辰的孩子們，艾露恩眷顧著他們，給他們安家，而他們也總在夜晚虔誠地凝望月空。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 359 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (359,'zhTW','當森林中的古樹被連根拔起的時候，由塞納留斯的兒女們看守的樹林，還有星辰之子們的石塔，整個世界都在顫抖。我們的女王即使在絕望和混亂的戰爭期間仍保持著她的優雅。在魔法的作用下，天空都變了顏色，爆炸好像要將世界撕成碎片。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 360 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (360,'zhTW','當森林中的古樹被連根拔起的時候，由塞納留斯的兒女們看守的樹林，還有星辰之子們的石塔，整個世界都在顫抖。我們的女王即使在絕望和混亂的戰爭期間仍保持著她的優雅。在魔法的作用下，天空都變了顏色，爆炸好像要將世界撕成碎片。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 361 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (361,'zhTW','德爾格倫大人：$B$B事情正像您所擔憂的那樣。您關於奧薩拉克斯之塔的猜測是正確的。有一群邪惡的信徒聚集在奧薩拉克斯之塔一帶，他們當中有許多術士，甚至還有一個兇殘的薩特。我不清楚是何種邪惡的力量將他們聚集在一起，但是我對此感到十分憂慮。$B$B他們自稱是暗灘教派的信徒。$B$B請原諒我這封信寫得很簡短，但是危險正潛藏在森林中，我只能簡單地描述一下這裡的情景。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 363 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (363,'zhTW','德爾格倫大人：$B$B事情正像您所擔憂的那樣。您關於奧薩拉克斯之塔的猜測是正確的。有一群邪惡的信徒聚集在奧薩拉克斯之塔一帶，他們當中有許多術士，甚至還有一個兇殘的薩特。我不清楚是何種邪惡的力量將他們聚集在一起，但是我對此感到十分憂慮。$B$B他們自稱是暗灘教派的信徒。$B$B請原諒我這封信寫得很簡短，但是危險正潛藏在森林中，我只能簡單地描述一下這裡的情景。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 364 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (364,'zhTW','雖然在湖岸周圍有許多城鎮，但其中最重要的就是亞米薩蘭和巴莎蘭，艾薩拉——卡多雷敬愛的女王——也賜福於這兩座城鎮。她將自己的僕人和貴族們安排到這兩座城鎮中居住，並派遣埃瑟裡克斯·納拉辛統治他們，不過埃瑟裡克斯一般都住在遠離城鎮的奧薩拉克斯之塔。$B$B他的助手是法師阿斯特利安，他以自己強大的戰鬥力以及對於魔法的熟練掌握而著稱。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 365 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (365,'zhTW','阿斯特利安和巴莎蘭的居民住在一起，另外他還多次造訪亞米薩蘭，他關心那裡人民的需要。$B$B就這樣，這兩座永恆之井岸邊的小鎮不斷發展繁榮，而星空下的其它地方卻漸漸陷入了瘋狂。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 366 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (366,'zhTW','兄弟相殘，同族征戰。並不是所有上層精靈都參與了戰鬥，有些人呆呆地站著，由於這極度的瘋狂而不能動彈，他們的城市和鄉村在他們身邊土崩瓦解。$B$B亞米薩蘭化作了一片廢墟，它的居民們緊緊依附著大地，彷彿大地可以讓他們倖免於難。直到這時，艾薩拉賜福的埃瑟裡克斯·納拉辛出現了，他要保護同胞們的安全。$B$B他告訴那些驚慌失措的同胞，只需施展一個簡單的法術，他就能保護他們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 367 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (367,'zhTW','當他們周圍的兄弟姐妹、父親母親一個個倒下的時候，他們將獲得永恆的生命，不必畏懼即將來臨的大爆炸……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 371 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (371,'zhTW','上面命令我們對聯盟的那些蠢貨加強攻勢。下面是進攻南海鎮的任務中所需要的物資列表：$B$B20人一星期旅途所需的補給$B20套夜行服$B20雙新鞋$B25把新劍$B30副飛刀$B20副黑色面具$B10瓶燃燒油$B50份毒藥$B如果可能的話，偷取5件南海鎮衛兵的制服$B100枚銀幣$B$B - V男爵，軍需官',0);
DELETE FROM `page_text_locale` WHERE `ID` = 372 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (372,'zhTW','希爾耶之星$B$B這顆星在守財奴格雷爾伯格的手上，這個貪婪的巨魔總是在奧特蘭克城的廢墟中搜尋各種珍奇的玩意。他的大部分收藏品都與垃圾無異，只有希爾耶之星例外，它有著非常珍貴的特殊能力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 373 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (373,'zhTW','達古恩之手$B$B古書上說達古恩的爪子會分泌一種毒液，這種毒液不會毒死它的獵物，不而會令它突變成另一種東西——上古種族中的一員。毫無疑問，這種毒液對我們很有價值。$B$B達古恩住在深海中，不過他經常被塵泥沼澤的魚人召喚到水面上來，它們的先知會使用一種附有魔法的海藻召喚達古恩。只要你殺掉足夠多的魚人智者，就應該可以找到這種海藻。把海藻放在魚人的祭壇上，然後達古恩就會被你召喚來了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 374 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (374,'zhTW','遺產之心$B$B死靈莫格是荊棘谷的一個巨魔法師，遺產之心就在他的手上。據說解開遺產之心中包含的謎團就可以擺脫死亡的威脅。你可以在祖瑪維廢墟里找到莫格。如果你能打敗他的話，把遺產之心帶來給我。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 375 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (375,'zhTW','把這三樣東西——希爾耶之星、達古恩之手和遺產之心——交給我，然後你就將得到雅格因的筆記。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 376 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (376,'zhTW','希爾耶之星$B$B守財奴格雷爾伯格是奧特蘭克的一個巨魔，這塊寶石就在他的手上，寶石的主人可以擁有與其他世界溝通的能力。情報顯示，格雷爾伯格在奧特蘭克城的廢墟里徘徊，不斷地搜尋更多的遺蹟。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 377 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (377,'zhTW','達古恩之手$B$B達古恩是深海中的一種巨獸，它為塵泥沼澤的魚人所崇拜。它們的薩滿對一種特殊的海藻施了魔法，然後用這種海藻把達古恩引到水面上來。去獵殺那些魚人，從它們身上找到附有魔法的海藻，然後把它放在魚人的祭壇上，然後等待達古恩出現。$B$B我需要他的手。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 378 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (378,'zhTW','遺產之心$B$B古書上說擁有遺產之心的人就會長生不老，它的擁有者是死靈莫格。莫格是劈顱部族的巫師，他住在荊棘谷的祖瑪維廢墟里。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 379 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (379,'zhTW','把這三樣東西——希爾耶之星、達古恩之手和遺產之心——交給我，然後你就將得到雅格因的筆記。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 380 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (380,'zhTW','亡靈哨兵任務報告$B$B偵察員：蘭妮·尤瑞克，奎恩·尤瑞克，埃蘭德·瑪科雷$B$B主要任務：完成對銀松森林北部的偵查工作，並且判斷天災軍團和野生動物的威脅程度。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 381 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (381,'zhTW','偵察員發現了大量狼人的存在。建議派出捕獵小隊掃除這個威脅。$B$B在亡者曠野的農場上發現了不死生物豺狼人。雖然我們還不知道它們在農場聚集的目的，但是根據其動向和準備程度來看，它們很快就有可能開始軍事行動。在我們觀察豺狼人的這段時間裡，並未發現它們當中有明顯的首領。也許它們是在等待指揮官或是增援的到來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 382 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (382,'zhTW','我們的偵察員繼續搜尋時，在伊瓦的農場遭遇了阻擊。伊瓦和他的家人，還有他的工人們，都成了天災軍團的爪牙。$B$B我們的偵察員遭到他們的襲擊，雖然最後成功地擊退了伏兵，但是均身負重傷，尤其是奎恩。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 383 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (383,'zhTW','他們在伊瓦的舊房子裡設定了一處防守點，蘭妮負責警戒工作，埃蘭德則繼續偵查任務。$B$B埃蘭德在北邊的一座果園中被狼人困住，後來在一個$R$C的幫助下才得以逃脫——也就是向您遞交這份報告的信差。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 386 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (386,'zhTW','另外，這位信差不僅協助我們完成了任務，而且幫助我們擊敗了邪惡的伊瓦、營救了埃蘭德，並且負責遞送了這份報告。$B$B我們對$g他:她充滿感激之情，希望上層能對其卓越表現給予相應的嘉獎。$B$B——亡靈哨兵蘭妮·尤瑞克$B行動負責人',0);
DELETE FROM `page_text_locale` WHERE `ID` = 387 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (387,'zhTW','於是他到處遊蕩、尋找。而他還是沒有找回那隻手臂。於是他一邊走一邊咒罵怒號著。$B$B但是格里雷克已經很久沒有聽從神靈的教誨，他們因此而憤怒，不再理會他的詛咒。$B$B格里雷克的命運就是這樣，命運讓他不斷遊蕩，讓他缺少一隻手臂。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 393 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (393,'zhTW','一個邪惡的力量造成了這一切$B他的元素生物永不停歇$B他悠閒地坐在鬼霧峰$B對著你露出輕蔑的笑容$B$B你很快就要面對這個法師$B只有他的死亡才能終結這件瘋狂的事',0);
DELETE FROM `page_text_locale` WHERE `ID` = 394 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (394,'zhTW','一個邪惡的力量造成了這一切$B他的元素生物永不停歇$B他悠閒地坐在鬼霧峰$B對著你露出輕蔑的笑容$B$B你很快就要面對這個法師$B只有他的死亡才能終結這件瘋狂的事',0);
DELETE FROM `page_text_locale` WHERE `ID` = 395 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (395,'zhTW','邁薩迪斯神殿$B$B“願月神的光芒如遠古時那樣永遠照耀著山谷，照亮森林中的道路。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 396 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (396,'zhTW','月神滿足了我的願望。我的同伴不應白白犧牲，我將用月神鐮刀為他們復仇。這是一件古老的物品，一根粗糙的螺旋狀的木頭，可能比卡多雷還要古老。$B$B我花了很長時間來研究神賜給我的這件東西。它不是一件普通的武器，也不是一個簡單的法器。有了它……彷彿時空的障礙都變得微弱了許多。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 397 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (397,'zhTW','我手中握著鐮刀，看到了一片混亂的景象。狼人……對抗著一個不可思議的敵人。狼人以他們一貫的狂暴發動攻擊，但他們面對的是一個毫無畏懼的對手：碧火之王。$B$B這時我才意識到了鐮刀的真實力量，注視著它，我就能和狼人交流。不過我所用的交流工具並非語言，而是一種不同的方式……一種難以描述的方式。$B$B重要的是，狼人能聽見我、理解我。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 398 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (398,'zhTW','我將能量引入鐮刀，時空的障礙越發減弱，於是我就可以將狼人召喚到我們的世界來。第一次我召喚了三十個狼人，並帶領他們上了戰場。我支配著他們無窮的蠻力，向費伍德森林中的惡魔發起猛烈的攻擊。$B$B月神滿足了我的願望，森林將被徹底淨化。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 399 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (399,'zhTW','一切都進行得很順利。我召喚了大群狼人和我一起戰鬥。雖然他們思維簡單，但是作為一個整體，狼人顯示出了強大的攻擊能力。$B$B我任命了一些首領，讓他們各自領導一小隊狼人行動。我們同時在森林的許多地方展開了戰鬥，在與惡魔的對抗中獲得了豐厚的戰果。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 400 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (400,'zhTW','有一隊狼人失蹤了，我派他們在整個森林裡巡查以找出惡魔的巢穴，可是他們沒有回來。我開始擔心那些首領，我把控制權交給他們，然而他們的頭腦非常簡單，也許會濫用我給他們的那點權力。我是不是已經失去了對他們的控制？也許我應該暫停召喚其他的狼人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 401 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (401,'zhTW','雖然我沒有再召喚狼人，但它們的數量還是在繼續增加。似乎鐮刀已經不需要我參與召喚的過程了，這一點很麻煩。我盡力召回狼人小隊，讓他們留在神殿附近。$B$B同時，我去了一趟達納蘇斯的圖書館，還諮詢了黑海岸的古樹議會，但沒有找到任何關於這些狼人的資訊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 402 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (402,'zhTW','我聽說過一個名叫阿魯高的肯瑞託法師，似乎這個法師也召喚過狼人。雖然去找他是件令我不快的事，但我還是想問問他對狼人有什麼瞭解。$B$B狼人很危險，我一定要抑制它們數量激增的趨勢。次日，我就去了貧瘠之地的港口，預定了前往新世界的船票。$B$B$B願月神的賜福護佑我完成任務。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 403 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (403,'zhTW','我寫這本日記是為了記錄我肩負的幫助梣谷的任務。不久前發生的事有些奇怪，不過我希望能幫助我的同胞解開這個謎。$B$B讓我先記下這些事情，免得以後忘記。$B$B我最近發現了有關法師達圖爾的傳聞的真相。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 404 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (404,'zhTW','我曾經覺得人類來到我們的土地上學習我們的東西是一件荒謬的事，然而這個法師，這個惡魔，他不僅在這裡紮了根，還學到了我們的一些知識。我仍然無法確定他是如何……$B$B我一直沒有搞清楚他的目的是什麼，但是他的計劃好像很簡單：利用德魯伊法術成為熊怪的朋友，然後控制它們。如果他企圖傷害我的族人，或者有其他什麼險惡的打算，那麼我希望在我的生命終結之前能找到答案。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 405 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (405,'zhTW','不管怎樣，他所執行的計劃顯然已經獲得了一定的成功。他是不是想先在熊怪身上施展他的詭計，然後再用到我的同胞身上？抑或他垂涎熊怪手上的某種東西？誰知道呢？$B$B他試圖利用他所創造的東西（一種法杖或是別的什麼）滲入到梣谷的熊怪部落中去。雖然具體的細節還不清楚，但是可以確定的一點是：當他試圖操縱熊怪互相攻擊的時候，他被熊怪們發現了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 406 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (406,'zhTW','我知道如果精靈發現自己被如此擺弄的話，他們一定會勃然大怒，熊怪也是如此，不過它們的反應更為強烈，還將達圖爾殺掉了。$B$B至少在那一刻，熊怪表現得並不像通常那樣墮落。它們還是保持了理智與智慧，而且和我們的關係也很融洽。$B$B我希望如果能在林精莎爾蒂恩的幫助下重鑄達圖爾的魔棒，我就可以利用它的力量來幫助我們的同胞……還有可憐的熊怪。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 407 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (407,'zhTW','並非所有熊怪都墮落了，有些倖存者還在保衛著森林。在它們墮落的時候，有些熊怪逃走了，有些被殺，其他的則被迫離開了自己的部族。$B$B我在密斯特拉湖畔發現了一個令人尊敬的汙林部族熊怪，他的名字叫做克羅格。$B$B我觀察了他好幾天。如果我能扮作熊怪接近他的話，我想我可以為他提供一些幫助，並重新建立我們和熊怪之間的聯絡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 408 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (408,'zhTW','殺了達圖爾之後，熊怪把他的魔棒分成三部分，使得它不能再對他們造成影響。事情變得有些困難了，但是我知道那三個部分放在哪裡。$B$B寶石$B魔棒的第一部分，也就是那塊神奇的寶石，它被藏在？q谷西北部的一座神殿中。我知道這座神殿現在已經成了法拉希姆湖中央的一座廢墟，哨兵告訴我，有大批魚人在那裡遊蕩。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 409 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (409,'zhTW','如果我在神殿中找不到寶石的話，那它有可能是被某個魚人拿走了。$B$B魔棒的杆$B這個部分落在了樹人手中，他們現在生活在費伍德森林附近。熊怪和我的同胞都沒有想過，侵襲了這片土地的墮落也會影響到高貴的樹人。$B$B我的調查表明，樹人將魔棒的杆藏在了一小片樹林中的一個上鎖的箱子裡。要想了解更多細節的話，我還得和莎爾蒂恩交談。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 410 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (410,'zhTW','1、找到一個或八個人$B$B2、使勁打人$B$B3、繼續打人$B$B4、把人扔到火裡$B$B5、吃人',0);
DELETE FROM `page_text_locale` WHERE `ID` = 411 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (411,'zhTW','莎爾蒂恩是在伊瑞斯湖東北部保護月井的林精。她拒絕離開森林，也不願讓森林變得墮落。我知道她有能力修復魔棒，至少她能告訴我如何修復它。$B$B魔棒的圓頭已經交給了朵丹尼爾的德魯伊。問題在於，那些德魯伊都已經死了。$B$B他們的靈魂現在盤踞在那裡，已經遠沒有原來那樣友好了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 412 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (412,'zhTW','這些還需要進一步調查。我不敢肯定自己是否能對付得了這些死去的同胞……更不用說在朵丹尼爾的深處找到圓頭了。$B$B（備註：我最近在阿斯特蘭納作準備的時候曾遇到了一個矮人獵人，他在？q谷花了很多時間來幫助我們的同胞。他來自一個叫作暴風城的地方。$B$B有一晚，我們喝著啤酒聊了一會兒，他的故事讓我看到了找回圓頭的希望……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 413 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (413,'zhTW','他告訴我說，他已經走遍了整個朵丹尼爾，但從未看到過箱子或任何可能用來放置圓頭的容器。$B$B他還告訴我那個地區已經有了腐爛的軟泥怪，它們會吞食任何比它們小的東西。這個矮人親眼看到它們“吃掉”桌子、雕塑、熊，甚至還有幾個地精！$B$B那些軟泥怪似乎擁有很強的魔法力量。如果裝圓頭的箱子被施了魔法，那麼它有可能已經被軟泥怪吃掉了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 414 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (414,'zhTW','這是一場賭博，但是我此時沒有其他的線索了……$B$B等我查出真相之後，我會記下詳細的資料，但是在那之前，我得先找到魔棒的各個部分，幫助阿斯特蘭納。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 415 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (415,'zhTW','金吉爾：$B好久不見了，但是我想，當你知道血羽部族的最後一個鷹身人已經被殺死的時候應該會很高興吧。不用感謝我，送信的這個$c才是功臣。如果你願意的話，在商隊經過貧瘠之地的時候，我可以把她的頭顱捎給你。我知道你的巫毒魔法需要那種東西。$B老朋友，保重。$B$B——達索克·快刀',0);
DELETE FROM `page_text_locale` WHERE `ID` = 416 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (416,'zhTW','金吉爾：$B好久不見了，但是我想，當你知道血羽部族的最後一個鷹身人已經被殺死的時候應該會很高興吧。不用感謝我，送信的這個$c才是功臣。如果你願意的話，在商隊經過貧瘠之地的時候，我可以把她的頭顱捎給你。我知道你的巫毒魔法需要那種東西。$B老朋友，保重。$B$B——達索克·快刀',0);
DELETE FROM `page_text_locale` WHERE `ID` = 417 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (417,'zhTW','好吧，你得把你的NG-5炸藥和雷管準備好。我已經給它們作好了標記……藍色的用在伐木場，紅色的用在風剪礦山。$B$B我事先進行了一些偵察工作，發現狂風峭壁那邊已有足夠的炸藥了，你要潛入那裡，放入炸藥，然後在引爆之前跑出來，這應該不是件難事。$B$B記住，這樣做只是為了聲東擊西。在地精去那兒檢查發生了什麼事之前要離貨車遠點，然後偷偷從他們後面繞進去。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 418 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (418,'zhTW','路上小心點，單是複合式硝酸塑膠炸藥就能把你炸成粉末。我把一些液體裝在銅管裡，以保證炸藥的安全穩定。$B$B我已經把你從科林那邊給我拿來的卷軸應用在引爆裝置上了，在你安置炸藥之後，引爆裝置會負責引爆NG-5炸藥。我用簡單的斯塔瑟瓦格機制保證最佳的引線傳導性，並保證不同的複合式硝酸塑膠炸藥之間的電流傳導率高於一般水準。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 419 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (419,'zhTW','在我詳細說明整個設計之前，讓我先告訴你該把炸藥放在哪裡。$B$B一號計劃——伐木場：$B在伐木場門前有一架貨車（伐木場位於他們採伐森林和收集木材的設施的東北部），我懷疑工程設計圖就在伐木場裡。放好炸藥之後就趕緊跑遠點。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 420 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (420,'zhTW','準備好之後就點燃炸藥。$B$B透過使用梅爾蘇斯天線連線銅線和銀線，可以保持較強的訊號，這樣你就能在安全的距離之外引爆了，只要小心附近的地精即可。如果他們把你抓了個正著，那你可就吃不了兜著走了。$B$B哦，為了以防萬一，我還是提醒你一句吧，不要在貨車爆炸的時候接近它……你會很慘的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 421 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (421,'zhTW','二號計劃——風剪礦山：$B$B我看到地精北面礦山的入口處停放了另一車炸藥。我想那個地方應該適合放置NG——5炸藥（紅色）。把炸藥放到貨車後面，然後離遠一點，按下按鈕。$B$B如果地精沒有過來的話，那就可能是爆炸的山石砸開了他們的腦袋瓜。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 422 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (422,'zhTW','風險投資公司的函件在礦坑的外面……可能在底層的什麼箱子裡。$B$B祝你好運，記住……$B$B藍色炸藥：伐木場$B紅色炸藥：礦坑$B$B哦，完成任務之後別忘了把信也毀了。嗯，也許我該想個辦法讓這些東西在被人讀過之後就自我銷燬，這個主意不錯……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 423 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (423,'zhTW','——第一天——$B$B我從鐵爐堡出發，經過漫長的旅途之後，終於到達了卡利姆多！$B$B巴爾莫丹的勘礦員卡茲戈姆那邊的進展相當不錯。他今天又挖出了一塊化石，挖掘站裡的學者們認為這是某位古代神靈的骨骼碎片，卡茲戈姆則認為這塊化石是某種神秘生物的一部分。身為這座挖掘站的管理者，他決定派我去尋找更多的碎片以揭開這個秘密。$B$B我的任務就是：到南方去尋找更多的線索。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 424 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (424,'zhTW','——第一天——$B$B我從鐵爐堡出發，經過漫長的旅途之後，終於到達了卡利姆多！$B$B巴爾莫丹的勘礦員卡茲戈姆那邊的進展相當不錯。他今天又挖出了一塊化石，挖掘站裡的學者們認為這是某位古代神靈的骨骼碎片，卡茲戈姆則認為這塊化石是某種神秘生物的一部分。身為這座挖掘站的管理者，他決定派我去尋找更多的碎片以揭開這個秘密。$B$B我的任務就是：到南方去尋找更多的線索。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 425 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (425,'zhTW','——第二天——$B$B貧瘠之地是如此廣袤無垠，到目前為止，我的旅程艱辛又無聊，也沒什麼有趣的事可以寫進探險者協會的檔案裡去。$B$B唯一值得一提的事情發生在黃金之路附近。我遠遠地看見了一些奇怪的生物朝我這邊走了過來，它們一半像人，一半像豬。於是我迅速藏了起來，等它們過去。天哪，那幫傢伙身上的臭味真是臭死了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 426 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (426,'zhTW','——第三天——$B$B啊，這是多偉大的發現呀！$B$B我在旅途中偶然發現了很令人驚詫的東西：某種野豬類生物的巨大遺骸。它的骨頭堆得極高，幾乎成了一座小山。矮人站在這隻野獸的獠牙旁邊會顯得像個……呃，像個矮人。從這種尺寸來看，我堅信這是傳說中的某位古代神靈的遺骸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 427 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (427,'zhTW','我記得不久前，首席考古學家杜瑟·灰須在鐵爐堡的探險者協會總部做了一次講座。那個老傢伙提到過一位神靈，傳說那位神靈具有無私的品性，因此受到達納蘇斯的那些精靈的崇敬……$B$B噓！等一下，我聽見帳子外面有鼻息聲，一定是些土頭土腦的野豬想要偷我的蘋果……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 428 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (428,'zhTW','——第四天——$B$B我被抓住了！$B$B必須……趕緊……寫下來。$B$B我被剃刀部族的野豬人襲擊。我以為他們會把我帶到野豬遺骸那裡，不過，他們卻繞過它，直接穿過黃金之路去了西邊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 429 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (429,'zhTW','我被粗魯地拖到一個被稱作剃刀沼澤的地方，這裡充滿了惡臭和荊棘。我被扔進一間簡陋的小屋，和一個垂死的暗夜精靈關在一起。$B$B我身上的東西都丟了，除了這本日記和我的筆、懷錶……$B$B好像有什麼人來了……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 430 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (430,'zhTW','——第五天——$B$B我的暗夜精靈獄友傷得很重。野豬人不斷鞭打他，我覺得他不久就會死去，除非奇蹟從天而降，營救隊來到這個兇險的地方。他不斷地昏迷又不斷地醒過來，當他醒著的時候，我就儘可能扶著他多喝點水。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 431 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (431,'zhTW','昨晚他第一次開口說話。他叫赫爾拉斯，是一個德魯伊。他被派到這裡來調查關於野豬人之神的傳聞。$B$B他用虛弱的聲音告訴我，他相信大野豬殘骸那裡就是一萬多年前的上古戰爭時期野豬之神阿迦瑪甘和燃燒軍團激戰的地方。阿迦瑪甘的龐大身體最終倒下了，他的血慢慢滲入了大地，血流過的地方都長出了巨大而扭曲的荊棘……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 432 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (432,'zhTW','赫爾拉斯和他的同伴尋找在這一地區的墮落之源。他告訴我說，阿迦瑪甘應該是個純潔的神，但是這片土地為什麼會遭到這些邪惡的野獸和惡性荊棘的汙染呢？現在這還是一個謎。$B$B我還想詢問更多的訊息，可是赫爾拉斯又一次失去了知覺……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 433 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (433,'zhTW','——第六天——$B$B赫爾拉斯的情況變得更糟了。$B$B他今天只醒過一次。他痛苦地呻吟著，不過他所要表達的資訊很明顯：如果我能從剃刀沼澤逃出去，那麼我就必須必須把訊息傳達給薩蘭納爾的法芬德爾，卡爾加·刺肋的勢力正在南貧瘠之地不斷膨脹，它的力量正在迅速壯大。在這股邪惡而墮落的勢力湧出剃刀沼澤之前，我們必須阻止它！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 434 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (434,'zhTW','可憐的赫爾拉斯看起來蒼白得就像一把骨頭，發燒也越來越厲害。野豬人一直在為某種軍事行動做準備，我擔心如果我還不快點逃跑的話，我將會遭遇和我的精靈獄友一樣的命運。$B$B我的計劃是在野豬人下一次出去打獵的時候逃跑。守衛我的野豬人很懶，經常在當班的時候呼呼大睡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 435 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (435,'zhTW','從沼澤跑出來之後，我就往千針林的方向走，然後向西到菲拉斯森林邊界的薩蘭納爾去。我要到那裡去找到那個名叫法芬德爾的德魯伊。$B$B起初我只是在尋找我們的過去，而現在事情變得愈加複雜和艱鉅了。聯盟的安危就掌握在我手中……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 436 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (436,'zhTW','訂單號：45TK—3$B買家：克拉維爾·濃須$B$B發貨單：$B$B水棘輪（3）$B轉發栓（50）$B深怒牌鼻菸粉（1）$B高階稜鏡（3）',0);
DELETE FROM `page_text_locale` WHERE `ID` = 437 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (437,'zhTW','我很想親自把信交給您，不過我擔心如果我離開這裡的話，也許會錯過一些重要的事情。$B$B如果你想要瞭解到更多關於奧薩拉克斯之塔的資訊，可以問問遞送這封信的信差，$g他:她協助我完成了任務，你應該可以信任$g他:她。$B$B巴蘇爾·影擊',0);
DELETE FROM `page_text_locale` WHERE `ID` = 438 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (438,'zhTW','地精納茲·斯迪波爾據稱是某位商業大亨的兒子（哪位商業大亨？這條情報的價錢可高了）。$B$B看起來，他非常喜歡花家裡的錢，而不是花自己掙到的錢。所以他從他家裡的藏寶室裡偷了出一些財產出來，現在就把它藏在閃光平原上。$B$B如果他的父親知道了他的去向，那老爺子肯定會去把他揪出來，拖回家……然後砍掉他的一根腳趾，以懲罰他的傲慢。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 439 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (439,'zhTW','菲茲巴布先生：$B$B送來這封信的$r和我希望您能夠參與我們的一樁生意。$B$B正如您所知道的那樣，我在閃光平原上待了不少日子了——我剛剛提到的生意是和這裡進行的賽車比賽有關的。$B$B如果賽車以及與之相關的賭博能讓你感興趣的話，那就請繼續讀下去，我相信您的知識對於我們的計劃來說是非常有用的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 440 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (440,'zhTW','菲茲巴布先生：$B$B您交給我的合作人的那些酒非常棒。酒味醇厚，而且很容易讓人上癮。我相信喝過它的人一定會想要喝更多的。$B$B我們為此向您表示感謝，克蘭克。$B$B我誠心邀請您來閃光平原來和我們一起把握這裡的賭車機會，或者如果你公務繁忙的話，也可以讓某位好友來這裡玩一玩。$B$B——克拉維爾',0);
DELETE FROM `page_text_locale` WHERE `ID` = 441 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (441,'zhTW','善良的馬特克：$B$B現在我遇到了一些困難，所以需要你的幫助。$B$B我兄弟和我要造一輛賽車，所以我們需要一些強力的活塞。我試過的那些都不夠結實，用那種破玩意根本沒辦法把我們新車的速度給提起來，而且引擎還老拋錨！$B$B你是最優秀的金屬工匠，你一定能幫上忙，而且你是我們唯一的指望啦！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 442 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (442,'zhTW','如果你想要找到霜喉雪人的話，就必須用它最喜歡的食物把它引誘出來。$B$B前往奧特蘭克山脈，在那裡殺掉一隻巨型山地獅，把它的肉帶到無草洞去。$B將山地獅的肉放到尤基爾之焰上燒烤，很快，香味就會引來霜喉雪人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 443 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (443,'zhTW','利用仇恨來利用別人實在是太簡單了，我對此深有體會。獸人和巨魔就是最好的例證，他們對聯盟的仇恨已經使他們願意對暗灘教派的任何指示無條件地服從，但是他們對自己所效忠的物件有哪怕一丁點的瞭解嗎？$B$B那個總是給我們帶來麻煩的聖騎士——淨化者德爾格倫——如今已經卷入了梣谷森林的事情裡，而他的侍從巴蘇爾卻正在我的塔外偵察，他還以為為我不知道他在這裡呢。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 444 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (444,'zhTW','德爾格倫認為我們的威脅不大，沒準只是又一個崇拜死亡的小教團而已。他根本不知道我們其實是暗影議會下的一個分支。$B$B當我還是個孩子的時候，別人就告訴我，昆蟲也能殺人，儘管它看起來根本就不起眼。你最忽視的東西往往傷害你最深，並且還會讓你死得很慘。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 445 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (445,'zhTW','這種用於平原賽車的火箭車需要高度的協調性和十分細緻的維護。所以說，工作站裡的維修人員們一直沒法休假也是很正常的。$B$B維修人員們一直在測試他們的車子，並且正在儘可能地對其進行改進和調校，這是保持車子具有上佳表現的唯一方法。$B$B所以……我們得用點什麼手段讓他們的工作人員出點小差錯，這些小差錯會讓車子徹底報廢，並讓他們退出比賽。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 446 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (446,'zhTW','如果我們能夠控制哪輛車的狀態好哪輛車的狀態糟的話，那麼……我想，不用再多解釋，你也應該知道這對於我們賭車有多大的好處。$B$B所以，善良的菲茲巴布，我們需要由你來找到一種能把他們的工作人員搞糊塗的方法。$B$B你知道荊棘谷裡有什麼植物、藥草或者飲料可以讓侏儒和地精們變成笨蛋嗎？$B$B——克拉維爾·濃須',0);
DELETE FROM `page_text_locale` WHERE `ID` = 447 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (447,'zhTW','我對於守護神龍和泰坦進行了大量的研究——幾乎花費了我一生的時間。在泰坦離開這個世界的時候，他們留下了五頭守護神龍。這些強大的龍負責守衛著艾澤拉斯這個世界。它們的傳說廣為流傳，直到今日。除了現在我所收集到的資訊之外，關於這種神奇的生物還有很多需要研究的東西。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 448 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (448,'zhTW','藥劑師林度恩：$B$B我希望這封信能安然地送達你那裡，遙遠的卡利姆多大陸需要你的幫助。$B$B現在在離我們牛頭人盟友的老家莫高雷地區很近的石爪山一帶出現了重大的危機，地精風險投資公司在山裡肆意砍伐樹木，開採礦物，這已經激怒了那裡的山靈。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 449 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (449,'zhTW','我猜想牛頭人薩滿和德魯伊正在努力平息這些山靈的憤怒，牛頭人認為石爪山的地精風險投資公司是個可怕的威脅。$B$B無論他們的觀點是否正確，我們都必須去幫助我們的盟友。$B$B林度恩，你在毒藥方面頗有建樹，能否推薦一種可以在石爪山的地精中傳播的毒藥？$B$B扎瑪',0);
DELETE FROM `page_text_locale` WHERE `ID` = 450 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (450,'zhTW','單靠我自己絕對無法學到如此多的知識，因此我要感謝那些暗夜精靈。他們幫助我學到了許多東西，透過與他們的交流，我發現他們的起源與守護巨龍有很密切的關係，這一點是我所沒有料到的。然而，他們似乎對這一秘密顯得非常謹慎，即使對我也從未多透露些什麼。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 451 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (451,'zhTW','關於我所瞭解到的守護巨龍的資訊，我將在下文中進行詳細的敘述，以便供後世的讀者參考。我認為它將會非常有用，因為我感覺到隨著時間的流逝，這些龍將會對我們的世界產生非常重要的影響。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 452 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (452,'zhTW','阿萊克斯塔薩：$B$B阿萊克斯塔薩，強大的上古紅龍女王，被泰坦賜予生命守護者的稱號。她是第一頭被泰坦巨人創造出來的守護巨龍。據說她見證了艾澤拉斯世界中的所有現代種族的誕生。她那優雅而高傲的紅龍軍團曾經統治著所有的龍類。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 453 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (453,'zhTW','在暗夜精靈的傳說中，阿萊克斯塔薩與半神塞納留斯是非常親密的朋友，在燃燒軍團第一次入侵的過程中，正是塞納留斯召喚她參戰的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 454 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (454,'zhTW','伊瑟拉：$B$B夢境之龍伊瑟拉象徵著所有生物的潛意識，翡翠夢境就是她的傑作。雖然她鼓勵普通的生物族群發展自己的想像力、創造力和雄心壯志，但她和她的後代卻認為真實的世界只是一個幻象而已。伊瑟拉是世界上最優雅和強大的生物之一。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 455 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (455,'zhTW','瑪裡苟斯：$B$B瑪裡苟斯被稱為魔法使者或織法者，他的外形看起來並不是一頭典型意義上的龍，據說他可以隨意改變自己的外形。自從他在極北之地隱居之後就很少有人見過他，他幾乎總是以一種昆蟲的形態出現，但是當顯出龍形的時候，瑪裡苟斯與他的後代總是覆著藍色的鱗片。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 456 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (456,'zhTW','諾茲多姆：$B$B諾茲多姆是時間之王。這頭青銅色的龍對所有舊日的事物都很感興趣，他專注於收集各個時代的神器，而對現實中的事情不感興趣——即使是其他守護巨龍的事情對他來說也無關緊要。但是，他的這種性格並不意味著他只沉迷於過去的事務。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 457 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (457,'zhTW','作為保護者，青銅龍對於有文明跡象的地區非常感興趣。他們具有與生俱來的耐性，在每次行動之前都會進行仔細的觀察和計劃。諾茲多姆一直致力於保護時間流和那些面臨巨大危機的普通種族。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 458 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (458,'zhTW','耐薩里奧：$B$B耐薩里奧被稱為大地的守衛者，他比其他的守護巨龍更加兢兢業業地守衛著艾澤拉斯世界。他的黑龍軍團的職責是創造山嶺，以及為各種普通的種族構築疆界。他的墮落至今仍然是個謎，究竟是外在的原因還是內在的原因造成了他的墮落，這一點尚無定論。我猜想，上古之神也許曾涉足其中。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 459 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (459,'zhTW','這條黑龍發生了完全的改變，最後耐薩里奧徹底消失了，取而代之的是死亡之翼，一頭充滿憎恨與哀怨的惡龍。他不再是大地的守衛者，而變成了死亡的象徵。死亡之翼是混亂與邪惡的化身，他永遠渴望著進行毀滅。他成為了自上古之神被驅逐後的最邪惡的勢力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 466 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (466,'zhTW','恭喜您！$B$B您已經成為了這隻地鼠的新主人！雖然它看起來很害羞，但我們確信您會發現它非常可愛，而且具有出色的能力。$B$B在接下來的幾頁中，您將找到關於地鼠的詳細資訊：$B$B$B再一次對您表示祝賀。您是絕對不會對它失望的。$B$B——瑪維格·銅栓$B地鼠有限公司',0);
DELETE FROM `page_text_locale` WHERE `ID` = 467 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (467,'zhTW','恭喜您！$B$B您已經成為了這隻地鼠的新主人！雖然它看起來很害羞，但我們確信您會發現它非常可愛，而且具有出色的能力。$B$B在接下來的幾頁中，您將找到關於地鼠的詳細資訊：$B$B$B再一次對您表示祝賀。您是絕對不會對它失望的。$B$B——瑪維格·銅栓$B地鼠有限公司',0);
DELETE FROM `page_text_locale` WHERE `ID` = 506 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (506,'zhTW','恭喜您！$B$B您已經成為了這隻地鼠的新主人！雖然它看起來很害羞，但我們確信您會發現它非常可愛，而且具有出色的能力。$B$B在接下來的幾頁中，您將找到關於地鼠的詳細資訊：$B$B$B再一次對您表示祝賀。您是絕對不會對它失望的。$B$B——瑪維格·銅栓$B地鼠有限公司',0);
DELETE FROM `page_text_locale` WHERE `ID` = 507 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (507,'zhTW','——第十三天$B塞拉摩附近的軍隊活動開始變得頻繁起來。許多人匆忙地離開了城市，朝西邊去了。$B$B——第十四天$B更多的軍隊離開了城市。我跟蹤了一支小隊，看見他們在離開塞拉摩之後很快脫去了制服。也許他們是被驅逐出去了？$B$B——第十五天$B我聽到一些塞拉摩計程車兵在討論，說是今天有些衛兵要離開他們的崗位。看來我的猜測是正確的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 527 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (527,'zhTW','失血麻雀：卸貨單$B$B（20）酒桶。目的地：塞拉摩$B（50）麵粉袋。目的地：塞拉摩$B（2）地精工具箱。目的地：棘齒城$B（30）棉衣。目的地：塞拉摩$B（4）香料。目的地：塞拉摩$B（3）乘客。目的地：塞拉摩',0);
DELETE FROM `page_text_locale` WHERE `ID` = 528 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (528,'zhTW','喬貞：$B$B我的擔心變成了現實，他們以我沒有想到的方式行動了。我從來沒有想過他們能夠做到這一步，但他們確實做到了。$B$B請指點給你帶來這封信的信差，讓$g他:她去找那個人。他會幫助我們的。假如事情不是這麼緊急，他會繼續袖手旁觀，但這次他肯定不會。$B$B謝謝你，老漁夫，你總是那樣無私地幫助我。$B$B你的朋友，$B德拉維',0);
DELETE FROM `page_text_locale` WHERE `ID` = 547 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (547,'zhTW','船長：$B$B願幸運之神在此次旅途中能眷顧您。可惜的是，在我們第一次行動的時候，它卻似乎對我們閉上了雙眼。$B$B我們的小隊在暴風城與鐵爐堡的隧道中試圖與我們的目標接觸，但他們卻撞進了一個圈套中。顯然，這表明他的謀略能力遠比我們所估計的要高。$B$B不過，我們已經啟動了第二套計劃。迪菲亞兄弟會的密探們已經準備等他在塞拉摩入境的時候將他截住。很快暴風城就會重新評估我們的實力……$B$B——M',0);
DELETE FROM `page_text_locale` WHERE `ID` = 548 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (548,'zhTW','第十六天$B烏里克和薩吉爾已經完成了任務，從塞拉摩港回來了。他們在港口中發現了一條名叫“失血麻雀”的新船，這條船來自於艾澤拉斯大陸的米奈希爾港。$B$B明天烏里克和薩吉爾會回到港口並偷偷地上船。他們希望能找到一些政治檔案，從而搞清楚塞拉摩和聯盟之間的關係。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 571 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (571,'zhTW','第十六天$B烏里克和薩吉爾已經完成了任務，從塞拉摩港回來了。他們在港口中發現了一條名叫“失血麻雀”的新船，這條船來自於艾澤拉斯大陸的米奈希爾港。$B$B明天烏里克和薩吉爾會回到港口並偷偷地上船。他們希望能找到一些政治檔案，從而搞清楚塞拉摩和聯盟之間的關係。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 572 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (572,'zhTW','隨著克爾蘇加德在洛丹倫方面的節節勝利，巫妖王同時也已經完成了毀滅人類文明的最後準備工作。耐奧祖已經將他的致疫能量體分裝入了數個名為瘟疫爐的可攜式容器之中，並命令克爾蘇加德將這些瘟疫爐運至洛丹倫大陸，他們應該會把它們藏在被教會控制的村民那裡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 573 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (573,'zhTW','這些瘟疫爐由一些忠誠的信徒們守衛著，它們將起到一個產生瘟疫，並將瘟疫散佈到從鄉村到城市的整個洛丹倫大陸北部地方的作用。$B$B巫妖王的計劃目前進展非常順利。目前瘟疫已經在大陸北部的許多村落中爆發了。與諾森德大陸目前的狀況完全相同，所有感染上瘟疫的人都已經死亡，成為巫妖王的奴隸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 574 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (574,'zhTW','克爾蘇加德麾下的信徒們正渴望著死亡並被轉化為亡靈，繼續為他們的黑暗領主服務。他們為由經轉化為亡靈所以獲得的永恒生命而狂喜。隨著瘟疫的繼續傳播，更多的未被兇悍的殭屍出現在了諾森德大陸之上。克爾蘇加德將這些殭屍編入成了一支只效忠於巫妖一人的軍隊，這支軍隊正逐漸壯大起來，並有了名字——天災軍團。很快，他們將遠征洛丹倫大陸……並將給全世界的人類帶來真正意義上的天災。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 575 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (575,'zhTW','沒有人知道宇宙到底是怎樣形成的。一些人認為，最初是在宇宙的中心產生了一次劇烈的宇宙爆炸，從而將無窮無盡，繁華萬千的世界送入到了混沌黑暗裡的巨大物質空洞之中，將那個本與現在的世界有著巨大的差距，並有著大量奇異的生命形式存在於其中的另一個世界——混沌黑暗所徹底取代了。另一些人認為正入宇宙本身的存在與運轉一般，宇宙是由某種人們認知之外的單一的，絕對的，至高無上的精神所創造的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 576 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (576,'zhTW','儘管這個混沌宇宙的真正起源仍不得人們所知，但可以確定的是，是一個強大的種族將未來萬物的存在之基石帶到了當初仍處於混沌狀態的世界中來，並按自己的意願為他們之後的生物設計了生存的模式與發展的軌道。$B$B是的，他們就是泰坦巨人，那種有著巨大的身形與金屬質的皮膚，從宇宙之盡頭來到這裡的神們。他們來到這裡並改變了這個世界。他們以自己的力量創造出了巍峨的高山與廣闊的大海。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 577 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (577,'zhTW','他們擎起了天空並聚集起了大氣——他們所做的一切，都是為了他們神秘的長遠計劃，他們要用秩序取代這世上的一切混沌。他們甚至加強了某些原始生物種群的力量，以便利用他們幫助自己完成工作，並使他們的理想世界的達到最終的完善。$B$B泰坦巨人們由一個名為“萬神殿”的精英組織所領導著，自第一創造紀元之後，他們已經秩序化了近乎一千萬個從混沌黑暗中分離出來的世界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 578 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (578,'zhTW','仁慈的萬神殿尋求的是維持他們所創造出的世界的和平，因此他們必須永遠與那些來自穢惡而黑暗的異次元空間——扭曲虛空中的陰險生物為敵。扭曲虛空是一處充斥著混亂魔法效果的，由乙太質構成的次元空間，它與多元宇宙中無數的世界都聯絡在一起，它也是許多隻知毀滅其他生命體與吞噬宇宙中一切能量的邪惡生物或惡魔類存在的地方。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 579 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (579,'zhTW','——第十七天$B烏里克回到了這裡，他失敗了。薩吉爾被抓住了。我只好派烏里克去把他的任務報告遞交給納澤爾。$B$B我必須要留在這裡，我必須得監視塞拉摩海岸的船隻活動情況。我會繼續監視，並及時彙報任何有價值的情報。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 580 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (580,'zhTW','第一套計劃已經失敗了！$B$B我們的臥底成功地修改了值班表，並得以在那天晚上輪入隧道值勤，但是由於來自暴風城的某些不可預料力量的干擾，目標竟然在我們的眼皮底下安然逃脫了。好在我們對這種情況早有準備，在伏兵撤離暴風城之前，已經秘密地啟動了第二套計劃，並且進展非常順利。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 581 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (581,'zhTW','第二套計劃非常簡單，但需要我們付出更多的耐心。我們安插在米奈希爾港的人已經竭盡全力了，而且他幹得非常漂亮。我們很容易就可以跟上我們的目標，並在起程的時候把他抓住。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 582 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (582,'zhTW','攻擊行動最好能在離他們的目的地不遠的地方展開，據說我們的盟友也埋伏在那一帶。我真是不明白，我們為什麼要和那種生物結成同盟，但我也沒有什麼辦法，我們是迫不得已。不過算了，這也沒什麼。只要我們能把目標握在我們自己的手掌中，就一定可以從暴風城那裡拿回當初他們從我們手中偷走的東西！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 606 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (606,'zhTW','攻擊行動最好能在離他們的目的地不遠的地方展開，據說我們的盟友也埋伏在那一帶。我真是不明白，我們為什麼要和那種生物結成同盟，但我也沒有什麼辦法，我們是迫不得已。不過算了，這也沒什麼。只要我們能把目標握在我們自己的手掌中，就一定可以從暴風城那裡拿回當初他們從我們手中偷走的東西！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 607 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (607,'zhTW','長鬚先生：$B$B正如閣下所知，我們雷矛家族有著全大陸最挑剔的眼光和品味，您所製作的盾牌品質之高也是令我們非常欣賞的。$B$B因此，我非常希望能得到一面由您親手打造的盾牌。以下是我對盾牌的一些個人要求：',0);
DELETE FROM `page_text_locale` WHERE `ID` = 626 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (626,'zhTW','長鬚先生：$B$B正如閣下所知，我們雷矛家族有著全大陸最挑剔的眼光和品味，您所製作的盾牌品質之高也是令我們非常欣賞的。$B$B因此，我非常希望能得到一面由您親手打造的盾牌。以下是我對盾牌的一些個人要求：',0);
DELETE FROM `page_text_locale` WHERE `ID` = 627 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (627,'zhTW','在洛丹倫聯盟與獸人部落之間爆發的慘烈的第二次大戰留給聯盟的只有激烈的動盪與巨大的混亂。那些嗜血的獸人在他們優秀的酋長奧格瑞姆·毀滅之錘的領導下，不僅攻陷了矮人們的卡茲莫丹，甚至還攻入了洛丹倫王國中部的好幾個省。那些冷酷的獸人甚至還在他們的暴行最終結束之前成功地劫掠了遠在大陸一隅的精靈王國奎爾薩拉斯。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 628 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (628,'zhTW','聯盟軍隊在三位最高指揮官安度因·洛薩爵士，光明使者烏瑟爾，以及戴林·普羅德摩爾海軍上將的領導下，將那些獸人們驅趕向艾澤拉斯南方的那片焦土之上——那裡也是當初被獸人所毀滅了的第一王國的遺址。$B$B最終，在洛薩爵士的領導下，聯盟軍將毀滅之錘麾下的諸多氏族又趕回了當初的獸人在艾澤拉斯大陸上控制的區域裡。而洛薩的軍隊則一直追擊著獸人，直到他們退回獸人的主城黑石塔，在那裡，雙方進行了最後一次攻防戰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 629 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (629,'zhTW','毀滅之錘決定進行最後的一搏，他和他的軍官們領軍從塔中主動出擊，並與洛薩手下的聖騎士們在燃燒平原的正中央展開了一場史詩般的戰爭。毀滅之錘與洛薩都傾其所有兵力投入了此次大戰，並留下了無數的屍體。儘管最後毀滅之錘以極其微弱的優勢擊敗了洛薩，但這位大英雄的死卻並不是這位酋長所希望得到的結果。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 630 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (630,'zhTW','圖拉揚，洛薩最信任的一位上尉，拾起了沾滿了鮮血的洛薩的盾牌，並將重新聚集起了他那些悲痛欲絕的同袍們展開了一次絕地大反擊。墳墓遍佈整個艾澤拉斯與洛丹倫，圖拉揚的軍隊最終在一次正面戰鬥中擊潰了毀滅之錘最後的殘餘部隊，帶著光榮與鮮血取得了最後的勝利。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 631 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (631,'zhTW','那場大戰之後，被擊潰了的獸人們已經一無所有了，只得帶著憤怒逃向獸人在大陸上的最後一處堡壘——黑暗之門。$B$B圖拉揚和他的戰士們將獸人殘部一直驅趕到了悲傷沼澤之中，並進入了黑暗之門所在的詛咒之地。在那裡，巨大的黑暗之門腳下，為了生存的部落殘兵與為了復仇的聯盟先鋒展開了第二次大戰中最後一場血腥的戰役。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 632 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (632,'zhTW','獸人的數量遠遠少於聯盟，而且他們的腦海已經徹底被伴隨著復仇而生的嗜血之詛咒所佔據住了，於是，獸人無可避免地倒在了憤怒的聯盟軍腳下。毀滅之錘被俘虜了，並被押往洛丹倫，但他手下的各氏族此時卻又重新在北方聚集了起來，他們回到了洛丹倫大陸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 633 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (633,'zhTW','僅僅在守望堡完成後的幾個月，黑暗之門的能量再度高漲起來，並且開啟了一條通向德拉諾的通道。部落中殘餘的獸人們在薩滿長老耐奧祖的領導下，再次對艾澤拉斯的產生了野心。為了增加耐奧祖的法力，獸人計劃去偷取一些的古老的法器，他們計劃在德拉諾開啟一個新的入口，以便使他們永遠地逃離那個命中註定的紅色世界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 634 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (634,'zhTW','在得知了耐奧祖再次計劃侵攻聯盟的領地之後，洛丹倫王國國王泰瑞納斯決定派出大軍遠征德拉諾，以一勞永逸地徹底剷除獸人勢力對艾澤拉斯的任何威脅。在大法師卡德加與大將軍圖拉揚的領導下，聯盟軍在這個燃燒的世界裡徹底擊敗了獸人勢力。但儘管有著精靈遊俠奧蕾莉亞與矮人庫德蘭麾下的精銳部隊加盟聯盟軍，卡德加還是未能阻止耐奧祖開啟傳送門並逃到其他大陸去。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 635 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (635,'zhTW','由於入口聚積的能量過於劇烈，因此德拉諾世界中驟然出現了巨大的風暴。當卡德加正竭盡全力帶領著他的同袍們為回到艾澤拉斯而拼命地戰鬥時，耐奧祖卻僅僅帶著他最信任的僕人們成功地從一個傳送門中逃走了。瞭解到他們的最終命運只有死亡之時，卡德加與他絕望的同伴們無私地決定毀掉黑暗之門，以使艾澤拉斯不會受到德拉諾被毀滅的波及。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 636 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (636,'zhTW','想盡了各種辦法，英雄們終於成功地毀掉了黑暗之門，拯救了艾澤拉斯。然而，他們是否能逃脫德拉諾唯一能賦予他們的死亡之命運，這就不得而知了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 637 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (637,'zhTW','在人類與獸人之間爆發第一次大戰的一千年以前，艾澤拉斯世界上的所有文明都孕育於一片為無盡且暴戾的海洋之中的一片廣袤大陸之上。而當時的卡利姆多大陸上只有一些奇異的種族和生物，它們還在為了和這片覺醒之地上的元素進行著生存的鬥爭。在這邊黑暗大陸的中心，有著一個洶湧著熾熱能量的神秘湖泊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 638 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (638,'zhTW','被稱為永恆之井的湖是世界魔力和自然力的中心。這口井從無窮無盡的渾沌黑暗之中汲取能量，並以獨特的方式用這些能量滋養著整個世界。$B$B有一天，一個古老的崇拜著黑夜的人形生物氏族小心翼翼地來到了這個充斥著超自然力量的魔法之湖的邊上。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 639 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (639,'zhTW','這個當時尚未開化的，過著遊牧生活的類人生物族群被井中的奇異能量所吸引而來，並在它寧靜海岸邊上建立起了永久性的居所。隨著時間的流逝，井中的大宇宙力量對這個族群產成了潛移默化的影響，讓他們更加強壯，睿智並擁有了不朽的生命。這個部族自稱為卡多雷，這個名字在他們的語言中意為“星辰之子”。為了慶賀新的社會制度的誕生，他們沿著湖泊建立起雄偉的居所與廟宇。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 640 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (640,'zhTW','卡多雷，或稱呼他們為暗夜精靈，崇拜月神艾露恩。他們相信她白天就睡在井中心最閃光的地方。由於受到井中所蘊涵著的秘密與魔力所吸引，早期的暗夜精靈祭司和先知們總是對井充滿好奇，並孜孜不倦地研究著它。隨著他們社會的發展，暗夜精靈終於瞭解到了卡利姆多大陸的寬廣幅度並發現了生活在這片大陸上的無數居民。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 641 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (641,'zhTW','唯一能阻止他們探索這片大陸的只有古老而強大的龍了。雖然這些身形巨大而蜿蜒的生物總是過著遁世隱居的生活，但它們會為防止任何潛在的威脅波及這片大陸而做出努力。暗夜精靈們認為這些龍正是這個世界的守護者，並且最好不要打擾它們和它們的秘密。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 642 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (642,'zhTW','無疑，正是暗夜精靈的好奇心使他們和具有強大能力的神祗們相遇，並且成為了好朋友。例如塞納留斯，一位在原始森林中頗有勢力的半神。塞納留斯很喜歡這些好奇的暗夜精靈，並花了許多時間教他們認識這個美麗而富饒的大自然。天性喜好寧靜的卡多雷也對卡利姆多的森林產生出了共鳴一般的感覺，併為大自然的和諧感到欣喜。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 643 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (643,'zhTW','隨著看似無盡的時間的流失，暗夜精靈的文明無論是在土地還是文化上都有了長足的發展。他們的廟宇，道路以及居所正逐漸遍佈整塊黑暗大陸。暗夜精靈們美麗而天賦鼎異的女王艾薩拉在永恆之井的岸邊建立起了一座龐大而雄偉的宮殿，並帶著她最寵幸的僕人們住進了這座金碧輝煌的宮殿中。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 644 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (644,'zhTW','她最寵幸的那些僕人們被喚作“奎爾多雷”，或叫他們貴族，他們只對她一個人宣誓效忠，從不違揹她的任何旨意，並堅信他們比其他的低階暗夜精靈同族要強。儘管艾薩拉女王能夠得到所有暗夜精靈的愛戴，但這些貴族們卻是在被某些抱著妒意的族人所嫉恨著的。$B$B貴族們與祭司們同樣對永恆之井充滿了好奇，於是艾薩拉女王也樂得命令這些貴族一同去研究井中奧秘，並揭露開它與這個世界的真正聯絡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 645 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (645,'zhTW','奎爾多雷們全力工作，日夜不停地研究月井。再這個過程中，他們得到了一種能夠控制井中宇宙能量的能力。在不斷的研究與實驗程序結束之後，卡多雷發現這種新的能量既可以用於創造萬物，也可以用於摧毀萬物。奎爾多雷們對於那些原始魔力感覺無從入手，所以他們下定決心要掌握這種新生的力量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 646 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (646,'zhTW','儘管他們明白，如果不負責的使用這種新生的力量，將會給世界帶來極大的威脅，但是艾薩拉女王和她的貴族們還是不計後果地繼續練習他們的施法能力。塞納留斯和許多暗夜精靈學者都警告他們說，若不能正確地對待這種魔法的話，必定會導致災難。但是，艾薩拉女王和她的手下此時已經什麼都聽不進去了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 647 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (647,'zhTW','隨著他們的力量變得越來越強大，艾薩拉女王和她身邊的貴族們身上發生了劇變。這些高傲的上位者們開始對他們的臣民們越來越冷淡，越來越殘忍。似乎是有一塊黑色的面紗罩住了艾薩拉那曾經令人痴迷的美麗。她開始不再在意她曾喜歡過的東西，並拒絕與她唯一信任的貴族祭司們以外的任何人接觸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 648 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (648,'zhTW','一位名叫瑪法里奧·怒風的年輕且無畏的學者也花了大量的時間來研究永恆之井。他開始懷疑永恆之井的力量已經使得貴族們——甚至是他所敬愛的女王陛下的精神墮落了。儘管他還不能確信這種邪惡力量是什麼，但他確信暗夜精靈們的生活很快就要發生永久的變化了……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 649 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (649,'zhTW','——漂亮的邊緣，長度從拳到肘。$B$B——邊上是銀色的鉚釘。$B$B——中間有一枚三指寬的銀色大鉚釘。$B$B——橡木材料，用鐵加固。$B$B——把我的名字，格林戈·雷矛，嵌在盾牌頂部邊緣。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 650 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (650,'zhTW','我們會使用和往常一樣的管道來完成支付。順及，請給這位信差支付一份標準的報酬，您可以把它算進盾牌的價格中。$B$B$B$B非常感謝！$B您真誠的格林戈·雷矛',0);
DELETE FROM `page_text_locale` WHERE `ID` = 669 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (669,'zhTW','艾澤拉斯大陸上的亡靈們並非是隨著阿爾薩斯王子的墮落而誕生的，他們的誕生還可以追溯到更早些的時候。這件導致了洛丹倫大陸淪陷的時間很早以前就埋下了種子；它在獸人諸多氏族及燃燒軍團來到大陸的時候就開始了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 670 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (670,'zhTW','來自德拉諾（獸人原本居住的世界）的獸人們本是信奉著薩滿教的，並有著高貴的傳統。他們都是強大的戰士，無論是肉體還是精神都十分的堅韌。因此燃燒軍團找到了他們。軍團中最強大的一位惡魔基爾加丹希望能將駕馭這些獸人氏族為他所用，利用他們的武力來為燃燒軍團征服一個又一個的世界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 671 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (671,'zhTW','基爾加丹找到那些氏族的領袖，一位名為耐奧祖的強大薩滿。他向耐奧祖許諾以神秘的力量與知識來換取獸人諸多氏族為燃燒軍團效力，耐奧祖答應了他，與他簽定了條約。這份條約不僅就此註定了他們的命運，也毀滅了他們的世界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 672 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (672,'zhTW','隨著時間的流逝，耐奧祖意識到了氏族的命運已經落入了燃燒軍團的手中，並且，這位獸人中最偉大的薩滿開始逐漸對基爾加丹表示出了不滿。基爾加丹被耐奧祖的反叛行為徹底激怒了，他決定換一個手下，於是便轉向了耐奧祖的學徒古爾丹，古爾丹顯然比耐奧祖更加墮落。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 673 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (673,'zhTW','正是古爾丹應該為氏族中的薩滿之道的逐漸沒落而負全部的責任。對力量的渴求與試圖控制一切的野心使他徹底拜倒在這些誘惑前。在基爾加丹的幫助下，古爾丹開始了他對諸多氏族的統治。曾經高貴的獸人們就此而墮落了，成為了一群沒有心智的野蠻人。自惡魔的血液被注入了他們的身體之後，獸人們比以前更加野蠻和殘忍了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 674 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (674,'zhTW','儘管基爾加丹在耐奧祖身上遭遇了失敗之後立刻轉向古爾丹仍是墮落，但他仍然非常憎惡那位老薩滿，併發誓一定要讓耐奧祖履行他們之間的合約。基爾加丹最終抓住了耐奧祖，並使用了一系列殘酷的刑罰來折磨他，迫使這位老薩滿就範。耐奧祖只求一死，但基爾加丹提醒他，合約仍然束縛著兩人。基爾加丹最終還是殺死了他，但這僅僅是在肉體上，這位老薩滿的靈魂在進入扭曲虛空之前卻被基爾加丹擒獲了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 675 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (675,'zhTW','基爾加丹將耐奧祖的靈魂封入了一塊由扭曲虛空採集來的冰塊中。然而在被封入冰塊時，耐奧祖從中汲取到更多的力量。肉體上的傷害與如此強大力量的灌注使得耐奧祖徹底變了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 676 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (676,'zhTW','基爾加丹將這塊封鎖著耐奧祖靈魂的冰塊透過次元門丟回了艾澤拉斯，落在一片名為諾森德大陸的地方。此舉無疑是將這個最邪惡的人引入我們的世界。耐奧祖就此留在了那裡；在他的位置下出現了冰霜與憎恨相結合的王座。曾經最受愛戴與尊敬的薩滿領袖如今成了一位無比強大的巫妖王。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 677 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (677,'zhTW','因為基爾加丹仍對巫妖王心存忌憚，於是他派出了他手下恐懼魔王們去監視耐奧祖的靈魂，並確保這位巫妖王能乖乖服從他的命令。這些吸血鬼般的僕人帶著毀滅巫妖王的陰謀與對他無比力量的慾望，非常興奮地來到艾澤拉斯大陸，並計劃將這個世界上現存的所有種族全部消滅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 678 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (678,'zhTW','一段時間過去了。在這段時間中，巫妖王利用他強大的法力徹底控制了諾森德大陸上所有生物的心智，強迫著它們在他的冰封王座周圍建立了一座宏大的根據地。如今，諾森德大陸如今已經完全落入了巫妖王的統治之下，耐奧祖也已經決定了，他的下一個目標將是洛丹倫大陸。由於被封在冰中，這位前獸人薩滿開始尋找更多可供他操縱與擺佈的思想。他的誘惑與召喚已經跨越了大海，遍及各個大陸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 679 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (679,'zhTW','沒有人能夠忽視巫妖王的召喚，這一點在一小部分擁有著強大力量的人群中尤其明顯。在這其中有一人特別值得一提，他就是達拉然法師的執政團體肯瑞託中的重要一員，大法師克爾蘇加德。他熱衷於追尋包括黑魔法在內的各種魔法，甚至不惜為此與肯瑞託的政策為敵。克爾蘇加德為了能從巫妖王那裡學到更多的東西而不顧肯瑞託的阻撓，他切斷了他與大陸上其他任何人的聯絡，來到到巫妖王的身邊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 680 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (680,'zhTW','於是，兩人之間簽定下了一份合約。克爾蘇加德以對巫妖王的效忠換取到了不朽的生命與無窮的力量。而克爾蘇加德第一個任務就利用他在洛丹倫大陸上的財產與影響力在大陸上建立一個教派——詛咒教派。這個教派向他們的信徒們承諾，只要宣誓永遠追隨與崇拜詛咒教派的神——耐奧祖，他們就將得到平等的對待與永恆的生命。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 681 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (681,'zhTW','耐奧祖隨後製造出了一種用於向洛丹倫大陸上的人類文明散佈瘟疫的器物，並將這些器物交給克爾蘇加德。他命令法師將這種瘟疫傳遍大陸。而他的信徒們則將不計代價的保護好這些器物，以便傳播行動的進行。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 682 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (682,'zhTW','一旦進入了適當的地區，瘟疫病毒便會滲透入地表並開始在那些對此一無所知的市民進行傳播。而在克爾蘇加德的管理下，巫妖王的軍隊迅速壯大起來，並控制了洛丹倫的大部分土地。這支軍隊就是後來的天災軍團，它的唯一目標就是將艾澤拉斯大陸上的人類全部都清除乾淨。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 689 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (689,'zhTW','墓碑上被潦草地刻上了“叛徒”這兩個字，除此之外，碑文還清晰可見：$B尤瑞夫安眠於此。$B摯愛的父親，丈夫，聖騎士。$B讓他的孩子們見證他對聖光奉獻的事實是無庸置疑的。$B他從不要求他的孩子們做他自己做不到的事。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 690 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (690,'zhTW','墓碑上被潦草地刻上了“叛徒”這兩個字，除此之外，碑文還清晰可見：$B尤瑞夫安眠於此。$B摯愛的父親，丈夫，聖騎士。$B讓他的孩子們見證他對聖光奉獻的事實是無庸置疑的。$B他從不要求他的孩子們做他自己做不到的事。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 695 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (695,'zhTW','墓碑上被潦草地刻上了“叛徒”這兩個字，除此之外，碑文還清晰可見：$B尤瑞夫安眠於此。$B摯愛的父親，丈夫，聖騎士。$B讓他的孩子們見證他對聖光奉獻的事實是無庸置疑的。$B他從不要求他的孩子們做他自己做不到的事。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 696 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (696,'zhTW','日記——第4天$B$B我已經在這個島上被困4天了，我很孤獨，只有我的思想與我為伴。香蕉的味道很好，但我得爬上很高的樹才能摘到。等到我不能再去尋找食物，也不能再保護自己免受陣雨之苦時，我滿腦子想的，都是如何逃出這裡。$B$B要是不再有紙和瓶子被衝上海灘來，我就要徹底絕望了。我坐的那條該死的船，居然裝滿了鍊金藥劑和藥方，它們對我一點用都沒有。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 697 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (697,'zhTW','日記——第512天$B$B我最近和香蕉們聊了很多，我也從它們的話中瞭解到了許多有關它們文化的東西。我對自己無意之間毀滅了它們的家園、吃了它們的孩子表示萬分的歉意。對於這個差點被我毀滅的文明，我瞭解得實在是太少了。$B$B似乎我的紙和瓶子都快用光了。我第一眼看到海灘上堆著的這些紙和瓶子的時候，還以為那是取之不盡用之不竭的呢。我的生命快要結束了，我的日記也是。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 698 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (698,'zhTW','艾澤拉斯世界中總是會有著各式各樣的奇蹟。植物、動物、文明、魔法，這些都是永遠不變的主題。事實上，世界上有著無窮無盡可以勾起人們好奇心的東西，很難把它們看盡。$B$B但只要一個人能真正深入地觀察，他的面前就會出現無數全新的世界，而每一個世界中都還有屬於它們自己的奇蹟。$B$B這就如同每個世界都有屬於它們的恐怖一般。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 699 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (699,'zhTW','我寫這本書的目的就是將這些東西仔細歸類，這些來自異世界的惡魔們的唯一目的就是摧毀我們的世界，所以當冒險者們遇到它們時，一定要能準確地認出它們來。$B$B所以，如果你也願意承擔起保衛艾澤拉斯的職責，就請仔細閱讀這本書，以瞭解你的敵人。$B$B——烏爾$B達拉然法師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 700 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (700,'zhTW','我所寫的這種怪物是狼人。$B$B古老的鄉村民謠或傳說裡經常會提到類似的生物，哪個農村裡的孩子會沒有聽說過這種半人形直立行走的野獸呢？$B$B事實就是隱藏在這類傳說背後的——或許人們正是利用這種故事來警告狼人，就好像用這些故事來嚇唬小孩子一樣。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 701 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (701,'zhTW','在你將這些故事當作耳旁風而不屑一故之前，請先允許我告訴讀者們：狼人是確實存在的。它們或許與我們不處在同一個世界中，但他們的家鄉與我們的世界之間卻存在著某種通路，而某種強力的魔法力量則可以透過它將狼人帶到我們這裡來。$B$B這種魔法最好永遠無人知曉，因為狼人所到之處，留下的只有恐懼與鮮血。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 702 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (702,'zhTW','將它們與我們世界中的狼對比後，你會對它們有更多瞭解。當你看見狼人的時候，你很快就會發現它那捲曲的毛髮、尖銳的耳朵、修長的口鼻部位，這些都與我們所熟知的狼非常類似。$B$B但你也很容易地看出兩者的區別：它們的毛皮下包裹著一副更加強健的軀體，它們可以雙足直立行走，並有著如匕首一般鋒利的尖牙利爪。在它們悽慘的嚎叫聲中隱藏著一種其他野生獸類絕不會有的兇殘。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 703 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (703,'zhTW','狼人生存的世界是個充斥著夢魘的黑暗之所。如果你要問那個世界上有什麼地方可以不被這些狼人肆虐，我的研究顯示：沒有。$B$B其實，只要想一想狼人這種生物是多麼的殘忍與邪惡，就知道那種地方是不可能存在的了。$B$B不過，狼人似乎很滿足於留在它們自己的世界裡，儘管它們中間的一部分成員掌握著強大的魔法力量，但卻從沒有試圖向艾澤拉斯世界進軍。$B$B這對我們來說未嘗不是一件幸事。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 704 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (704,'zhTW','正如之前所提到的，一些狼人有相當成熟的魔法造詣，而且他們的魔法中蘊涵著黑暗與墮落的力量。$B$B詛咒與超自然的毒素是他們經常使用的東西，所以在面對這些狼人魔法師的時候，你必須要有對抗暗影魔法的準備。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 705 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (705,'zhTW','我真希望再也沒有其他的達拉然法師召喚狼人了——即使是出於良好的目的。只要不再簽訂更多的契約，就不會有更多的秘密被洩露出去，這些野獸是不會為我們帶來任何好處的。$B$B它們最好永遠留在它們的世界裡。如果它們來到我們的世界，那我們無疑將面臨毀滅的劫難……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 710 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (710,'zhTW','我真希望再也沒有其他的達拉然法師召喚狼人了——即使是出於良好的目的。只要不再簽訂更多的契約，就不會有更多的秘密被洩露出去，這些野獸是不會為我們帶來任何好處的。$B$B它們最好永遠留在它們的世界裡。如果它們來到我們的世界，那我們無疑將面臨毀滅的劫難……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 712 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (712,'zhTW','身為卡加斯派出的斥候，我對周圍環境的描述如下：$B$B——紅色的岩石丘陵與乾燥的平原，只有極少數生物才能在此生存。$B——陽光熾烈，強風。$B——沒有湖泊和溪流，也沒有任何池塘。想要找水的話，就必須挖出泥濘的深井，或者從仙人掌與其他針刺類植物中榨水。$B$B簡而言之：燥熱，難以生存。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 713 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (713,'zhTW','荒蕪之地中滿是我們的敵人。巨魔會從沙中咆哮著突然鑽出，伏擊任何缺乏警惕的冒險者。黑鐵矮人則在卡加斯的東部建立了一處基地，並和他們那些淺色皮膚的表親們在洛克莫丹北部地方交戰。某種野蠻且原始的名為穴居人的種族瘋狂地佔據著這裡的每一片土地，並寸步不讓地保護著他們的領地。$B$B那麼荒蕪之地東部的萊瑟羅峽谷呢？它徹底被龍佔據了。我們不知道那裡的龍有多少，也不知道他們有多強大，因為派去那邊偵查的斥候沒有一個能活著回來的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 714 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (714,'zhTW','不用說就知道，我們卡加斯衛戍部隊對能夠被部署在這裡感到非常高興。我們已經在這裡堅強地紮下了根，因為只要我們略微示弱，就會死在這裡。$B$B在這裡也沒有別的辦法可以生存下去了。$B$B尼卡·血痕$B斥候隊長，卡加斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 730 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (730,'zhTW','赫格拉姆，$B$B無論是誰提議在荒蕪之地的卡加斯建立一片基地，都將得到我的贊同。這個計劃將使我們在那裡擁有常備的駐軍。那裡的天氣很糟，到處都是兇惡的野生動物與好戰的土著，也沒有什麼補給，的確是一處非常惡劣的危險場所，但我們最好的戰士與斥候無疑可以在那裡立足。$B$B這計劃很好。幹得漂亮。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 731 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (731,'zhTW','伊莉莎$B$B親愛的妻子，希望大地可以撫慰你飢渴的靈魂。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 750 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (750,'zhTW','伊莉莎$B$B親愛的妻子，希望大地可以撫慰你飢渴的靈魂。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 751 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (751,'zhTW','活塞的技術引數：$B$B長度：32胡展$B寬度：12胡展$B重：23.5豆克 - 25.5豆克$B傳導：70趾曲$B杆部強度：大於等於98$B連結指數：烈酒級或更高$B$B若你忘了侏儒的度量衡單位，說明如下：$B胡展 - 一根鬍子的長度$B豆克 - 一塊鷹嘴豆的重量$B趾曲 - 腳趾的曲度',0);
DELETE FROM `page_text_locale` WHERE `ID` = 752 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (752,'zhTW','我帶著隊伍繼續往海邊走去，希望在那裡的海岸線旁找到某個可以避開迅猛龍的地方。但是在匆忙之中，我們跑到了一處危險的高地，這是個可怕的錯誤，全都是我的錯。我們停在了一個陡峭的懸崖邊，而那些迅猛龍距離我們僅有幾步之遙。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 770 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (770,'zhTW','我帶著隊伍繼續往海邊走去，希望在那裡的海岸線旁找到某個可以避開迅猛龍的地方。但是在匆忙之中，我們跑到了一處危險的高地，這是個可怕的錯誤，全都是我的錯。我們停在了一個陡峭的懸崖邊，而那些迅猛龍距離我們僅有幾步之遙。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 771 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (771,'zhTW','餵食和照料須知：$B$B我們鄭重承諾為您提供照料寵物所需的一切資訊，讓您從地鼠有限公司得到專業的服務！$B$B為了達到這一目標，我們為牢固的地鼠籠設計了一些小孔，這讓您的寵物可以在其中安逸地生活，而且不用受日曬雨淋之苦。$B$B為了您的方便起見，每隻籠子中都安裝了一個餵食器，它帶有誘人的藍葉薯的味道（這是地鼠最喜歡的食物）！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 790 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (790,'zhTW','餵食和照料須知：$B$B我們鄭重承諾為您提供照料寵物所需的一切資訊，讓您從地鼠有限公司得到專業的服務！$B$B為了達到這一目標，我們為牢固的地鼠籠設計了一些小孔，這讓您的寵物可以在其中安逸地生活，而且不用受日曬雨淋之苦。$B$B為了您的方便起見，每隻籠子中都安裝了一個餵食器，它帶有誘人的藍葉薯的味道（這是地鼠最喜歡的食物）！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 794 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (794,'zhTW','我們的世界有著悠久的歷史，一段由新生的種族與古老的種族共同譜寫的歷史，一段神祗之間互相征伐的歷史。$B$B一段秩序之神從天而降的歷史，一段有關長眠地下的上古之神的歷史。$B$B我要講述的就是這些上古之神的故事，他們在艾澤拉斯世界形成之初就居住於此。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 795 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (795,'zhTW','上古之神代表了我們這個世界的意志。他們的笑聲從暴風中傳出，他們的氣息蘊含在烈焰中。當上古之神走動的時候，地表也隨之振顫，所有的生靈都絕望地悲鳴，將自己的血肉撕裂。$B$B他們確實應該感到絕望，因為就像烈火會無情地灼傷好奇的小孩子那樣，上古之神是不會關心那些卑賤的生物的。說得好聽一些，我們只是一些走卒。說得難聽一些，我們就是玩物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 796 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (796,'zhTW','上古之神是這個世界最早的主宰，他們控制了所有的力量。雖然他們現在被困住，處於長眠之中，但他們的僕從依舊在橫行，而我們弱小脆弱的凡人，是無法和他們的力量相比擬的。$B$B膽敢挑戰他們的蠢貨都被吞噬了。只有那些為了自保而去逢迎上古之神的僕人的人才能生存，雖然其代價是犧牲自己的靈魂和意志……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 797 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (797,'zhTW','阿庫麥爾一直以來都為上古之神效力，她運用上古的智慧為自己的洞穴祈禱。阿庫麥爾是由古老的凡人帶入黑暗深淵的，她是神的象徵。雖然她只擁有上古之神的很小一部分的力量，但是她已經是如此的深不可測。$B$B她被信徒們崇拜著，畏懼著，熱愛著。$B$B$B——洛迦里斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 810 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (810,'zhTW','阿庫麥爾一直以來都為上古之神效力，她運用上古的智慧為自己的洞穴祈禱。阿庫麥爾是由古老的凡人帶入黑暗深淵的，她是神的象徵。雖然她只擁有上古之神的很小一部分的力量，但是她已經是如此的深不可測。$B$B她被信徒們崇拜著，畏懼著，熱愛著。$B$B$B——洛迦里斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 811 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (811,'zhTW','計劃正在實施中。$B$B控制那座偉大的堡壘——英雄哨崗，將它作為我們的基地，一旦你準備完畢之後，就可以要求我們從西部荒野派遣增援力量。$B$B這塊區域已經被暴風城的人完全遺忘了，所以正好可以作為我們發動攻擊的起點。$B$B迪菲亞兄弟會必將再次進入暴風城！$B$B我等待你的回覆。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 812 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (812,'zhTW','那些骯髒的石顎怪實在是太好唬弄了。它們對於我們的極端憎恨使得我們可以反過來利用它們……看來什麼樣的同盟都可以形成啊，但是我們的那些同胞對於石顎怪來說確實有很大的威脅，至少現在是如此。$B$B戰鬥開始之後，他們雙方的力量必然都會被削弱，然後我們就可以進軍盔枕湖並等待下一步的指示了。$B$B鐵爐堡終將是我們的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 830 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (830,'zhTW','那些骯髒的石顎怪實在是太好唬弄了。它們對於我們的極端憎恨使得我們可以反過來利用它們……看來什麼樣的同盟都可以形成啊，但是我們的那些同胞對於石顎怪來說確實有很大的威脅，至少現在是如此。$B$B戰鬥開始之後，他們雙方的力量必然都會被削弱，然後我們就可以進軍盔枕湖並等待下一步的指示了。$B$B鐵爐堡終將是我們的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 831 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (831,'zhTW','在接下來的幾頁中，你可以找到製造淬火護甲所需的各種材料清單。祝你好運，戰士。$B$B$B——弗倫·長鬚',0);
DELETE FROM `page_text_locale` WHERE `ID` = 832 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (832,'zhTW','燒焦的蜘蛛牙：$B$B在瑟根石附近的一個洞穴中發現的火巖礦石對棲息在那裡的蜘蛛產生了燒灼影響。$B$B它們毒牙中的毒素被蒸發，並與牙齒本身產生了反應，因而造就出了一種非常堅硬的物質。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 833 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (833,'zhTW','燒焦的奇美拉角：$B$B與燒焦的蜘蛛牙類似，卡利姆多石爪山地區的焦炭谷中有許多奇美拉，它們身上的燒焦的奇美拉角也有著驚人的高品質。$B$B只要把它敲平並進行妥善的處理，它就將是最具延展性的上好材料。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 834 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (834,'zhTW','光滑的奇美拉角：$B$B光滑的奇美拉角非常稀有，也非常堅硬，我可以用它製造出渾然一體的整片鎧甲來，所以這種材料是我必需的。$B$B你可以在焦炭谷中的奇美拉身上找到這種材料。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 835 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (835,'zhTW','燃素：$B$B製造鎧甲的最後一步需要用到一種特製的高溫爐。要生成那種程度的高溫，必須要使用燃素才行。$B$B我知道的唯一一個會製造這種東西的工匠是個名叫魯古格的野豬人，恐怕你得打敗他才能拿到東西。魯古格就住在貧瘠之地南方的剃刀沼澤裡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 850 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (850,'zhTW','赫格拉姆，$B$B無論是誰提議在荒蕪之地的卡加斯建立一片基地，都將得到我的贊同。這個計劃將使我們在那裡擁有常備的駐軍。那裡的天氣很糟，到處都是兇惡的野生動物與好戰的土著，也沒有什麼補給，的確是一處非常惡劣的危險場所，但我們最好的戰士與斥候無疑可以在那裡立足。$B$B這計劃很好。乾的漂亮。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 851 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (851,'zhTW','燒焦的蜘蛛牙：$B$B在瑟根石附近的一個洞穴中發現的火巖礦石對棲息在那裡的蜘蛛產生了燒灼影響。$B$B它們毒牙中的毒素被蒸發，並與牙齒本身產生了反應，因而造就出了一種非常堅硬的物質。',0);
