INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (852,'zhTW','燒焦的奇美拉角：$B$B與燒焦的蜘蛛牙類似，卡利姆多石爪山地區的焦炭谷中有許多奇美拉，它們身上的燒焦的奇美拉角也有著驚人的高品質。$B$B只要把它敲平並進行妥善的處理，它就將是最具延展性的上好材料。',0);
