INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (854,'zhTW','燃素：$B$B製造鎧甲的最後一步需要用到一種特製的高溫爐。要生成那種程度的高溫，必須要使用燃素才行。$B$B我知道的唯一一個會製造這種東西的工匠是個名叫魯古格的野豬人，恐怕你得打敗他才能拿到東西。魯古格就住在貧瘠之地南方的剃刀沼澤裡。',0);
