INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (855,'zhTW','以下是我施放召喚塞克隆尼亞的法術所必需的物品列表。祝你好運。$B$B——捕風者巴斯拉',0);
DELETE FROM `page_text_locale` WHERE `ID` = 856 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (856,'zhTW','活根草：$B$B這種草可以在野外採集到，或者在塵泥沼澤中的枯藤獸身上收集到。它的力量可以幫助我們將塞克隆尼亞的生命精華抽取到這個世界中來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 857 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (857,'zhTW','血頂巨魔的獠牙：$B$B荊棘谷中的血頂巨魔長著高品質的獠牙。血頂巨魔的墮落特質主要集中在他們的獠牙上，如果把這種獠牙磨成粉末，其中的邪惡力量就會被釋放出來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 858 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (858,'zhTW','流放精華：$B$B提煉這種精華所必需的符咒可以從阿拉希高地的那些被放逐的元素生物身上找到。我們需要雷霆符咒、燃燒符咒和海浪符咒，每樣八個，然後把它們放進我的容器中。$B$B有了符咒之後，我就可以合成流放精華了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 870 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (870,'zhTW','流放精華：$B$B提煉這種精華所必需的符咒可以從阿拉希高地的那些被放逐的元素生物身上找到。我們需要雷霆符咒、燃燒符咒和海浪符咒，每樣八個，然後把它們放進我的容器中。$B$B有了符咒之後，我就可以合成流放精華了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 871 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (871,'zhTW','$N：$B首先，請允許我對你為我和我的妻子所做的一切再次表示感謝。你救了她的命，單憑這個，我就永遠也無法償還你這個人情了。她對我來說就意味著一切。如果她死了……我都不知道我會幹出些什麼。$B$B以下是鑄造一把神聖武器所必需的材料，你把這些東西都找齊，我就可以馬上幫你把它鑄造出來。我按照從易到難的順序對它們進行了排列——希望這樣可以讓你更加便捷地找到它們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 872 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (872,'zhTW','白石橡木：在西部荒野的月溪鎮被迪菲亞盜賊佔領之前，那裡的礦井中有很多這樣的木材。它具有良好的耐熱耐壓能力，經常用來製作礦井的支撐架和其它工具。$B$B那些白石橡木應該是從別的地方運過去的。這是一種稀有而堅硬的木材，可以用於你的武器。如果礦井中還有這種木材的話，你應該可以在地精木匠身上找到它們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 873 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (873,'zhTW','精煉礦石：在塞爾薩瑪有個叫白洛爾·石手的矮人鐵匠，我曾經在他手下接受過訓練。他能夠製作一種非常特殊的合金，這種合金在你的武器中也是一個非常重要的組成部分。原本應該有一批這種合金被運到鐵爐堡來的，但至今我還沒有得到相關的訊息。$B$B去找到他，幫我詢問一下那批貨的下落。如果他不在洛克莫丹的話，那我至少想要知道我的老師去哪裡了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 874 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (874,'zhTW','鐵匠之錘：在大瘟疫來襲和阿爾薩斯墮落之前，我居住在銀松森林裡的焚木村。現在這座森林已經不再美麗，而我學習鍛造技術的城堡也早就被可怕的邪惡力量玷汙了。$B$B當我和我的妻子離開影牙城堡的時候，我把一些非常重要的工具留在了那裡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 875 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (875,'zhTW','在這些東西中，鐵匠之錘是我父親留給我的。他曾告訴我說這把錘是被附過魔法的，我也曾懷疑過這一點，但是不管怎麼樣，它是我父親留給我的最後一件東西。$B$B$N，請找到它，把它交給我，這樣我就能找回往日的激情了。如果它確實被附加了魔法，那對於你我來說都是有利的。$B$B我把它留在了城堡庭院的馬廄裡了。那裡的怪物理論上是不會做鐵匠活的，所以我相信那把錘子應該還在那裡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 876 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (876,'zhTW','科爾寶石：從我所知道的一些傳說來看，這種寶石是法師用來儲存能量所用的，這可以極大地增強他們的力量。我曾經幫助過一個名叫桑迪斯·織風的暗夜精靈，他可以告訴你更多有關寶石的資訊，只要你和他提到我，他就一定會幫忙的。我相信這些寶石中一定蘊藏了可以幫你鑄造武器的力量。$B$B我和桑迪斯上次見面的時候，他住在黑海岸的奧伯丁，那裡是暗夜精靈的家園，周圍都是被汙染的森林。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 877 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (877,'zhTW','科爾寶石：從我所知道的一些傳說來看，這種寶石是法師用來儲存能量所用的，這可以極大地增強他們的力量。我曾經幫助過一個名叫桑迪斯·織風的暗夜精靈，他可以告訴你更多有關寶石的資訊，只要你和他提到我，他就一定會幫忙的。我相信這些寶石中一定蘊藏了可以幫你鑄造武器的力量。$B$B我和桑迪斯上次見面的時候，他住在黑海岸的奧伯丁，那裡是暗夜精靈的家園，周圍都是被汙染的森林。',0);
