INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (911,'zhTW','一塊翡翠。很多地方都有翡翠。它們很稀有，但是如果你去找某位鐵匠或工程師談談的話，他們或許會有多餘的翡翠可以賣給你。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 930 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (930,'zhTW','一塊翡翠。很多地方都有翡翠。它們很稀有，但是如果你去找某位鐵匠或工程師談談的話，他們或許會有多餘的翡翠可以賣給你。',0);
