INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (931,'zhTW','$N，你需要以下的東西來鑄造你的護甲：$B$B石爪山狂風礦坑裡的狗頭人身上攜帶的煙霧鐵錠。$B$B希爾斯布萊德礦坑裡的藍銅粉。$B$B鐵錠則要從礦工們那裡獲取，當然如果你自己也會採礦的話就更好了。$B$B至於燃素，你必須從剃刀沼澤那邊的一個名叫魯古格的野豬人身上搶來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 950 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (950,'zhTW','$N，你需要以下的東西來鑄造你的護甲：$B$B石爪山狂風礦坑裡的狗頭人身上攜帶的煙霧鐵錠。$B$B希爾斯布萊德礦坑裡的藍銅粉。$B$B鐵錠則要從礦工們那裡獲取，當然如果你自己也會採礦的話就更好了。$B$B至於燃素，你必須從剃刀沼澤那邊的一個名叫魯古格的野豬人身上搶來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 951 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (951,'zhTW','（這本又髒又破的日誌只有一部分能夠認清楚了。）$B$B奧達曼，第三天$B$B我不敢相信自己居然會有那麼愚蠢。只有沒經驗的新手才會被暗爐矮人偷襲！我的傷口遲遲不能痊癒，顯然我中了毒。我感到自己的體力越來越不行了。即使如此，我還得繼續前行……$B$B……事情變的更糟了，侏儒為我製作的項鍊被打碎了！項鍊上最大的三顆寶石都不見了。我必須找到寶石，沒有它們的話，項鍊根本沒有用……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 953 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (953,'zhTW','星辰的孩子已經在永恆之井閃光的湖水邊定居了很久。眾所周知，象徵永恆曙光的艾露恩在就在這水中休憩。岸邊住著星辰的孩子們，艾露恩眷顧著他們，給他們安家，而他們也總在夜晚虔誠地凝望月空。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 954 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (954,'zhTW','當森林中的古樹被連根拔起的時候，由塞納留斯的兒女們看守的樹林，還有星辰之子們的石塔，整個世界都在顫抖。我們的女王即使在絕望和混亂的戰爭期間仍保持著她的優雅。在魔法的作用下，天空都變了顏色，爆炸好像要將世界撕成碎片。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 970 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (970,'zhTW','（這本又髒又破的日誌只有一部分能夠認清楚了。）$B$B奧達曼，第三天$B$B我不敢相信自己居然會有那麼愚蠢。只有沒經驗的新手才會被暗爐矮人偷襲！我的傷口遲遲不能痊癒，顯然我中了毒。我感到自己的體力越來越不行了。即使如此，我還得繼續前行……$B$B……事情變的更糟了，侏儒為我製作的項鍊被打碎了！項鍊上最大的三顆寶石都不見了。我必須找到寶石，沒有它們的話，項鍊根本沒有用……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 971 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (971,'zhTW','奧達曼，第四天$B$B…………在奧達曼深處，我發現了第一條線索，那裡有一頭兇猛的石顎怪正在擺弄一大塊藍寶石 - 這塊藍寶石正好能夠安在項鍊上。我記得暗爐矮人曾經提起過這頭石顎怪的名字：格瑞姆托克。它長得真是非常強壯……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 972 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (972,'zhTW','奧達曼，第五天$B$B……那頭石顎怪拿著從它那被殺掉的同族身上搶來的黃玉進入了大廳前面的側室……$B$B……它把黃玉放進了一隻很顯眼的、正對著墓室後面的石棺中……$B$B……不過，有三個矮人守在那裡！他們擋住了石顎怪的去路。引起他們的注意無異於自殺，我真怕現在這樣虛弱的我被石顎怪一口給吞了。不過，如果我知道了第三塊寶石的下落，我就要……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 973 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (973,'zhTW','奧達曼，第六天$B$B……好餓啊。我已經斷水斷糧很多天了，現在即使給我一塊發黴的麵包，我也會當它是盛宴。我剛才甚至把一個石顎怪的頭看成一塊肉排……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 974 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (974,'zhTW','奧達曼，第七天$B$B……這是我最後一次彌補自己犯下的錯誤的機會了。我相信紅寶石就藏在矮人們上次擋住石顎怪不讓它進入的地方。他們的戰鬥無疑就是因為這塊寶石和其他寶物而展開的。那些可惡的矮人肯定把它藏在什麼地方了。不管這些了，我無論如何也得從這裡走出去。或許直接向上挖條出路是最好的選擇……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 990 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (990,'zhTW','奧達曼，第七天$B$B……這是我最後一次彌補自己犯下的錯誤的機會了。我相信紅寶石就藏在矮人們上次擋住石顎怪不讓它進入的地方。他們的戰鬥無疑就是因為這塊寶石和其他寶物而展開的。那些可惡的矮人肯定把它藏在什麼地方了。不管這些了，我無論如何也得從這裡走出去。或許直接向上挖條出路是最好的選擇……',0);
