INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (991,'zhTW','去找一把電能草莓來。要想得到這個東西的話，你必須從阿拉希高地上的枯木巨魔那裡收集10根冰木圖騰，把這些圖騰柱帶到那裡的外禁錮法陣去。將圖騰柱放在法陣中心的石頭上，等著它被雷擊中。然後一把電能草莓就這麼形成了。',0);
