INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1011,'zhTW','我發現了進入卡茲穆爾大廳的方法！$B$B從我的箱子中拿到尼基夫徽章。$B$B擊敗那個放著地圖的房間前面小房間裡的石顎怪魯維羅什，然後拿到索爾之杖。$B$B將這兩者合成史前法杖。$B$B在那個佈置著地圖的房間裡使用法杖，就可以開啟卡茲穆爾大廳的門。$B$B只要按照以上步驟來做，你就可以進入那個房間了！$B——巴爾洛戈',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1030 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1030,'zhTW','我發現了進入卡茲穆爾大廳的方法！$B$B從我的箱子中拿到尼基夫徽章。$B$B擊敗那個放著地圖的房間前面小房間裡的石顎怪魯維羅什，然後拿到索爾之杖。$B$B將這兩者合成史前法杖。$B$B在那個佈置著地圖的房間裡使用法杖，就可以開啟卡茲穆爾大廳的門。$B$B只要按照以上步驟來做，你就可以進入那個房間了！$B——巴爾洛戈',0);
