INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1071,'zhTW','指揮官：$B$B速回奧格瑪。現在不宜採取行動，我們必須根據最新情報重新分析我們的戰略部署。$B$B在那裡有很多惡魔的信徒和巨魔出沒，還有許多惡魔守護著黑暗之門。$B$B——索爾，部落酋長',0);
