INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1211,'zhTW','遛地鼠$B$B地鼠喜歡狹窄黑暗的地方，它非常害羞。$B$B如果您希望讓地鼠到處走走的話，那麼您一定要把它帶到有家的感覺的地方，要讓它聞到它最喜歡的食物——藍葉薯的味道！$B$B這附近最適合的地方就是剃刀沼澤附近的溝槽。如果您在那裡開啟籠子，您的地鼠就會聞到周圍藍葉薯的味道，然後它就會走出來跟著您了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1212 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1212,'zhTW','地鼠指揮棒$B$B地鼠是一種非常驚人的動物，它不僅能激起心胸最狹窄的平原陸行鳥的關愛，還能嗅出50碼以內的藍葉薯的味道！$B$B如果您想要讓你的地鼠找到一塊藍葉薯，那麼您可以使用我們的專利產品：地鼠指揮棒（不包含在本產品中，需另外購買）。$B$B請參考後面幾頁的詳細使用說明……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1213 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1213,'zhTW','我們所有的地鼠都經過嚴格訓練，您只需簡單地揮動指揮棒，就可以讓身旁的地鼠進入“搜尋狀態”。它會用嗅覺搜尋藍葉薯，並會自己去把它挖出來。$B$B如果您在地鼠搜尋藍葉薯的時候再次揮舞指揮棒，那麼它就會停止搜尋，回到您的身邊。$B$B我們相信您一定會發現我們的地鼠都是經過嚴格訓練的搜尋專家，實乃居家旅行、發財致富的必備伴侶！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1214 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1214,'zhTW','對我們地鼠有限公司來說，最讓我們傷心的是，我們收到報告說有一些貪婪的藍葉薯獵人不顧自己寵物的安全，把它們送入危險的地方搜尋藍葉薯。$B$B我們決不能寬恕這樣的行為，但是為了保證顧客對我們售出的每一隻地鼠滿意，我們鄭重承諾：所有購買本公司產品的顧客都可以拿著購買憑證隨時領取新的地鼠。$B$B祝您狩獵愉快！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1231 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1231,'zhTW','這份契約是為了證明$N殺掉灼熱峽谷中的一大禍害：狂暴的瑪爾戈。$B$B鐵爐堡博物館特此頒發獎狀，以表示我們對此舉的認可，並對這份獎狀的獲得者表示感謝。$B$B——館長 杜里奧斯·裂石',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1251 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1251,'zhTW','這幾個月以來，我花了很多時間進行思考，我以前的信念和固執的理念開始動搖。聯盟？部落？正義？邪惡？這些對我來說曾經含義清晰的辭彙，現在看來卻如同無盡之海那樣朦朧而模糊。$B$B現在我知道什麼是最重要的了。我後面都是香蕉。$B$B它們棲息在樹木上，用惡毒的眼光盯著我。我剛才吃的那一隻香蕉差點把我噎死了！當我把它扔到礁石上的時候，我甚至可以聽到它的慘叫。$B$B這是戰爭，我會獲勝的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1270 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1270,'zhTW','對我們地鼠有限公司來說，最讓我們傷心的是，我們收到報告說有一些貪婪的藍葉薯獵人不顧自己寵物的安全，把它們送入危險的地方搜尋藍葉薯。$B$B我們決不能寬恕這樣的行為，但是為了保證顧客對我們售出的每一隻地鼠滿意，我們鄭重承諾：所有購買本公司產品的顧客都可以拿著購買憑證隨時領取新的地鼠。$B$B祝您狩獵愉快！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1271 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1271,'zhTW','工程學分支$B$B也許“哪個種族首先在艾澤拉斯大陸開創了工程學這門學科”的問題在學術界依然沒有定論，但是對於支撐工程學的兩大重要支柱，想必大家都有共識——那就是侏儒和地精。他們所創造的工程學發明不僅給這個魔法時代新增了許多色彩，而且還使兩個種族之間的爭端進一步加劇。他們兩個種族的分歧在這一點上顯得尤其突出。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1272 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1272,'zhTW','侏儒工程學$B$B侏儒這個種族非常善於設計那些供使用者控制和操作各種物體的裝置。雖然他們也把一部分注意力放在爆炸品和武器上，但總的來說，侏儒工程學主要的方向是設計那些使生活更加簡便的物品。所有的侏儒設計都會經過嚴密的可行性分析，而實際上有許多設計根本就沒有付諸於執行。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1273 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1273,'zhTW','地精工程學$B$B作為一箇中立種族，地精成功地將科學轉化為他們的利潤。他們將工程學的理論運用於實際的生產中，並將其轉化為可觀而穩定的利潤——這些理論包括他們廣泛應用的爆破、火器和機械科學。地精工程學對於工程學理論的興趣很小，因為他們的發明幾乎不存在無法工作的問題，它們只是工作得太出色了。顯然，這些發明不是為了懦夫而設計的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1274 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1274,'zhTW','理論學習$B$B侏儒和地精互相之間保持著知識的隔閡，所以你根本無法同時學習到這兩套理論。無論你持何種政治觀點，只有當你同意永遠不接觸另一個種族的工程學理論時，你才能學習某個分支的工程學。如果一個學生選擇了侏儒工程學，那麼他就永遠不能學習地精工程學。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1275 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1275,'zhTW','永久性的選擇$B$B前面的部分強調了兩個工程學派系的主要區別。選擇任何一種分支，都等於永遠放棄另一個分支。雖然這有可能造就一個二流的工程師，但是你應該可以理解，侏儒和地精是在儘自己的所能來保護自己的工程學秘密：有一點知識總比什麼都沒有要好。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1276 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1276,'zhTW','引用$B$B“你想要了解更多關於地精工程學的東西？那就問問我們最優秀、最聰明的工程師吧——我想他的名字應該是努比·斯塔普芬格斯。想要知道他為什麼叫這個名字嗎？這就是地精工程學！”$B——林戈·特拉格迪克，地精工程師$B$B“如果你想要知道什麼就直說，但是我會告訴你：我們有炸彈！”$B——雅茲·尼託斯伯克，地精投彈手',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1277 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1277,'zhTW','更多引用！$B$B“完成某件超強的發明並親身感受它的力量，你知道這樣的感覺是多麼美妙嗎？侏儒可不知道”$B——尼克斯·斯普克斯賓，加基森高階工程師$B$B“工程學就是讓幻想變得更加奇妙的東西！”$B——洛維斯，侏儒發明家',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1291 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1291,'zhTW','召喚：$B$B想要召喚地獄尋蹤犬，你就必須使用魔珠。$B$B注：$B召喚而來的地獄尋蹤犬只能在這個世界上存在30分鐘。$B它只會協助你尋找艾薩拉晶體物質。$B它不會做以下事情：玩耍，攻擊任何目標，協助任何人，跳舞，摧毀魔法物品。$B$B請繼續閱讀下一頁……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1292 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1292,'zhTW','控制：$B$B地獄尋蹤犬隻對野獸般的吼叫有反應。為了讓你的地獄尋蹤犬幫你找尋艾薩拉晶體物質，你必須用力對它吼叫！（點選地獄尋蹤犬，然後輸入/roar指令）$B$B當地獄尋蹤犬找到艾薩拉晶體物質之後，它會不顧一切地衝到目標旁邊。雖然你並不需要保護地獄尋蹤犬，但你也需要和它靠得夠近，從而不至於失去它。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1293 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1293,'zhTW','解散：$B$B30分鐘之後，這頭野獸會自動回到扭曲虛空中。$B$B注：$B它的能量十足，因此有可能掉落山崖，或者從山上墜落。不要為此而感到悲傷，你可以馬上召喚另外一個。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1310 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1310,'zhTW','更多引用！$B$B“完成某件超強的發明並親身感受它的力量，你知道這樣的感覺是多麼美妙嗎？侏儒可不知道”$B——尼克斯·斯普克斯賓，加基森高階工程師$B$B“工程學就是讓幻想變得更加奇妙的東西！”$B——洛維斯，侏儒發明家',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1311 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1311,'zhTW','致讀此信者：$B$B如果你讀到了這封信，那麼你只可能在兩個地方：$B$B（1）在艾薩拉的南部半島上。$B$B（2）在峭壁巨人的胃裡。$B$B這兩處都不是什麼好地方。$B$B你要知道，我曾經在前面的那個地方待過，至於寫這份信的時候，我在後面的那個地方。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1312 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1312,'zhTW','在一個巨人的胃裡待久了，我身上起了不少反應。$B$B隨著我的身體逐漸變得水晶化，我開始認為這世上應該有許多的英雄。如果我能逃出這裡的話，我一定會扭斷那個獸人的脖子！$B$B——溫丹·沙恩',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1313 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1313,'zhTW','我在想什麼？$B$B也許這個問題應該有更好的問法：我坐在巨人的胃裡還寫什麼便箋？$B$B這兩個問題都很好，而且我都不能馬上回答……$B$B我承認，我來這裡並沒有什麼崇高的目的。我是來找艾薩拉水晶的，這是一種艾薩拉南部特產的水晶。我找到它之後就可以富甲天下了！$B$B不過，看看我現在的樣子……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1314 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1314,'zhTW','任何一個有智慧的生物找到這張便箋的時候，他們都一定會自問道：“為什麼他們會去招惹具有暴力傾向的30尺高的巨人呢？”$B$B——穆克',0);
