INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1392,'zhTW','尼爾斯修士：$B$B我的葡萄得救了！$N，也就是這封信的攜帶者，勇敢地闖入我那滿是盜賊的園子，然後帶著我的葡萄殺了出來。雖然迪菲亞兄弟會的人依然在河岸上巡邏，但是我所有的收成幾乎全都保住了。$B$B你可以在你的商店中再次供應葡萄了。$B$B願聖光保佑我們，$B——米莉·奧斯沃斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1430 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1430,'zhTW','尼爾斯修士：$B$B我的葡萄得救了！$N，也就是這封信的攜帶者，勇敢地闖入我那滿是盜賊的園子，然後帶著我的葡萄殺了出來。雖然迪菲亞兄弟會的人依然在河岸上巡邏，但是我所有的收成幾乎全都保住了。$B$B你可以在你的商店中再次供應葡萄了。$B$B願聖光保佑我們，$B——米莉·奧斯沃斯',0);
