INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1431,'zhTW','沃弗克·鐵壺$B$B沃弗克在黑鐵酒窖的儲藏室工作，他為黑暗守護者做出的犧牲意義重大。$B$B願他的靈魂堅定而頑強。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1432 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1432,'zhTW','比塞克·雷眉$B$B比塞克的遊蕩將他引入了黑石深淵，山脈的秘密在召喚著他。$B$B願他的靈魂永遠不要躊躇。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1433 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1433,'zhTW','尤格爾·錘手$B$B尤格爾是一位技巧高超的鑿工，當他還沒有遇到黑暗之鑰的時候，他在工匠大廳中雕琢偉大的作品。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1434 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1434,'zhTW','希姆雷爾·暗齒$B$B當黑暗之鑰的瘋狂佔據希姆雷爾時，只有死者的尖叫可以使他平靜。$B$B希姆雷爾總是在競技場旁坐著。願我們的血腥搏殺可以平息他心中的怒氣。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1435 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1435,'zhTW','奧弗加特·石拳$B$B喪命於黑暗守護者奧弗加特錘下的挑戰者不計其數。$B$B西部兵營計程車兵們在他走過時卑躬屈膝。他們之中有誰敢直視奧弗加特的雙眼並看到黑暗之鑰的秘密呢？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1436 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1436,'zhTW','佩沃爾·鐵足$B$B黑暗守護者佩沃爾是我們最為尊重的信徒。他攜帶黑暗之鑰的時間遠遠超過其他黑暗守護者，這使他付出了驚人的代價。$B$B他的犧牲讓我們感到惋惜，對他的懷念會一直留在我們心中……自從黑暗佔據了他。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1470 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1470,'zhTW','佩沃爾·鐵足$B$B黑暗守護者佩沃爾是我們最為尊重的信徒。他攜帶黑暗之鑰的時間遠遠超過其他黑暗守護者，這使他付出了驚人的代價。$B$B他的犧牲讓我們感到惋惜，對他的懷念會一直留在我們心中……自從黑暗佔據了他。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1471 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1471,'zhTW','所羅門鎮長：$B$B這封命令的攜帶者已經被授予暴風城官方代表的資格。您可以讓$g他:她尋找黑龍和黑石獸人之間的聯絡。如果發現了此類證據，請讓這個代表把證據帶回暴風城，親自交給我，屆時我再酌情派遣部隊來協助湖畔鎮。$B$B此致，$B$B$B$B伯瓦爾·弗塔根公爵',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1490 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1490,'zhTW','所羅門鎮長：$B$B這封命令的攜帶者已經被授予暴風城官方代表的資格。您可以讓$g他:她尋找黑龍和黑石獸人之間的聯絡。如果發現了此類證據，請讓這個代表把證據帶回暴風城，親自交給我，屆時我再酌情派遣部隊來協助湖畔鎮。$B$B此致，$B$B$B$B伯瓦爾·弗塔根公爵',0);
