INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1512,'zhTW','北部水晶組合$B$B可能產生兩種效果：一種製造傷害，另一種則可以抵消傷害。$B$B爆炸水晶：需要紅色和黃色水晶。它將產生大爆炸，並且令你的敵人昏迷。$B$B恢復水晶：需要黃色和綠色水晶。它將為你提供一個治療光環。$B$B$B',0);
