INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1515,'zhTW','東部水晶組合$B$B可能產生兩種效果：一種提高你的精神屬性，另一種則能夠製造一種護盾。$B$B精神水晶：需要藍色和綠色水晶。它可以提高你的精神屬性。$B$B尖刺水晶：需要藍色和黃色水晶。它可以為你提供一層能對攻擊你的敵人造成傷害的護盾。',0);
