INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1532,'zhTW','西部水晶組合$B$B可能產生兩種效果：一種可以增強你抵抗傷害的能力，另一種則能降低敵人的防禦力。$B$B防禦水晶：需要紅色和綠色水晶。它將提高你的護甲值。$B$B破甲水晶：需要藍色和紅色水晶。它將降低指定目標的護甲值。',0);
