INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1551,'zhTW','你好，冒險者，我向你致敬！$B$B我，克林科·古德斯迪爾，需要一些人幫我完成一些艱鉅的任務。因為我自己有很多工作，因此得由一個足夠勇敢的冒險者來找到清單裡列出的物品，並把它們交給我，我保證支付豐厚的報酬。$B$B清單將在下幾頁中列出……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1552 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1552,'zhTW','水晶蜘蛛腿——$B$B灼熱峽谷中生活著許多晶網蜘蛛，它們的身體是由堅固的水晶構成的。如果你在殺死它們的時候沒有打斷它們的腿，就可以幫我的夥伴收集這種在工程學中必不可少的傳導材料。$B$B我需要一定數量的水晶蜘蛛腿來進行實驗，對於一名堅定的戰士或者訓練有素的法師來說，從八條腿的蜘蛛身上找到一條完整的腿似乎不是什麼問題。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1553 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1553,'zhTW','延誤的包裹——$B$B我僱傭了一個我原以為足夠可靠的飛行員，讓他幫我從塞拉摩帶一個包裹過來。顯然我錯了。雖然那個飛行員活了下來，但他是在放棄了自己的飛艇和上面所有的貨物之後才保住自己性命的……$B$B好吧，重點是，我要我的包裹。根據比吉爾的描述，他的飛艇就墜毀在塞拉摩海港西邊的塵泥沼澤裡，是在翻過水邊的小山時開始墜落的。$B$B嗯……我根本不知道他的飛艇是怎麼墜毀的……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1554 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1554,'zhTW','古德斯迪爾的長劍——$B$B最後，我要找回的是我最好的武器。我將這把神奇的長劍給了一名我非常尊重的戰士。嗯，不過他被一個名叫加奎亞還是什麼的魚人給襲擊了。$B$B當他在悲傷沼澤那一帶的海邊旅行的時候遭到了那個傢伙的攻擊。他被打得落荒而逃，但是他沒有把那把武器也一起帶走，而是留給了那個魚人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1555 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1555,'zhTW','古德斯迪爾的長劍——$B$B最後，我要找回的是我最好的武器。我將這把神奇的長劍給了一名我非常尊重的戰士。嗯，不過他被一個名叫加奎亞還是什麼的魚人給襲擊了。$B$B當他在悲傷沼澤那一帶的海邊旅行的時候遭到了那個傢伙的攻擊。他被打得落荒而逃，但是他沒有把那把武器也一起帶走，而是留給了那個魚人。',0);
