INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1611,'zhTW','<這個頁面上寫滿了古代精靈文字。>$B$B這些書頁中記述了在製作次級秘藥的過程中所發生的事件。$B$B願我的敵人永遠無法得到這些資料。$B$B願我有生之年能夠重見潔白的月光照耀奎爾薩拉斯。$B$B願我能以凱爾薩斯之名奮戰。$B$B願我能為伊利丹的榮耀而戰死。$B$B——卡里爾·溫薩魯斯',0);
