INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1691,'zhTW','你好，菲諾克！$B$B我在燃燒平原的研究進行得非常順利。而且我欠了$N很多因為$g他的:她的大力幫忙！以下是我繼續研究所需要的物資：$B$B鋼螺釘若干$B17號扳手一個$B12磅重的鴨毛$B一罐你製造的膠水$B$B非常感謝你，菲諾克，下次我們碰面的時候記得提醒我，不要把煤放在你的鞋子裡！$B$B——丁奇',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1710 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1710,'zhTW','你好，菲諾克！$B$B我在燃燒平原的研究進行得非常順利。而且我欠了$N很多因為$g他的:她的大力幫忙！以下是我繼續研究所需要的物資：$B$B鋼螺釘若干$B17號扳手一個$B12磅重的鴨毛$B一罐你製造的膠水$B$B非常感謝你，菲諾克，下次我們碰面的時候記得提醒我，不要把煤放在你的鞋子裡！$B$B——丁奇',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1711 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1711,'zhTW','給峭壁衛兵圖林·長角的急件$B$B一大群半人馬部隊從伊索克營地出發並襲擊了我們的補給營地。所有的守衛都已戰死，所有的資源全部被劫掠一空。這是半人馬發起的空前大膽的襲擊，我擔心將來還會有更多這樣的襲擊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1730 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1730,'zhTW','給峭壁衛兵圖林·長角的急件$B$B一大群半人馬部隊從伊索克營地出發並襲擊了我們的補給營地。所有的守衛都已戰死，所有的資源全部被劫掠一空。這是半人馬發起的空前大膽的襲擊，我擔心將來還會有更多這樣的襲擊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1731 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1731,'zhTW','洛丹倫的最後一位國王，泰瑞納斯·米奈希爾二世在此長眠。$B$B他的一生做出了無數偉大的功績，他的隕落令人扼腕嘆息。$B$B$B$B$B$B$B$B“願這位父王寬恕其子嗣所做的一切。$B$B$B$B$B$B$B 願血染的王冠永遠被遺失和忘卻。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1750 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1750,'zhTW','洛丹倫的最後一位國王，泰瑞納斯·米奈希爾二世在此長眠。$B$B他的一生做出了無數偉大的功績，他的隕落令人扼腕嘆息。$B$B$B$B$B$B$B$B“願這位父王寬恕其子嗣所做的一切。$B$B$B$B$B$B$B 願血染的王冠永遠被遺失和忘卻。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1751 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1751,'zhTW','在格瑞姆巴托的戰鬥結束之後不久，這頭巨大的紅龍遺體在溼地被發現了。據傳聞，塔蘭尼斯塔茲是阿萊克斯塔薩較年長的配偶。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1752 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1752,'zhTW','這隻鳥爪化石發現於荊棘谷的南岸。生態學家認為它是屬於古代陽鵬的。雖然陽鵬主要出現在牛頭人的神話之中，但是這隻爪子證明它確實存在過。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1753 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1753,'zhTW','作為世界上體型最大的陸行鳥，格魯陸行鳥的數量稀少，非常罕見。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1754 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1754,'zhTW','這是磨齒羊的骨骼複製模型。這種傳說中的山羊是卡茲莫丹的奇蹟，也是許多矮人傳說中的主角。直到今天，生態學家都無法對這種山羊的體積或力量做出估算。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1755 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1755,'zhTW','這枚卵是在遙遠的安戈洛環形山的雨林中找到的，其中孕育著一隻胚胎狀態下的魔暴龍。其中包含的蜥蜴類基因對於探險者協會的生態學家來說是無價之寶，因為它可以提供中和魔暴龍毒液所需的血清。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1756 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1756,'zhTW','這具完整的翼手龍骨架是從遙遠的安戈洛環形山發掘出來的。根據骨架的結構來看，顯然這種特殊的生物從未在我們的時代出現過。在安戈洛爾環形山的特殊土壤中，這副骨架可以永遠地儲存下去。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1757 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1757,'zhTW','這枚從蘇拉瑪水下遺蹟中找來的星盤是在一萬兩千年前由暗夜精靈中的高等精靈所製造的。那些痴迷於魔法、超自然現象和星象學的高等精靈發明了一系列令人匪夷所思的物品。這些創造為我們提供了關於古代暗夜精靈科學認識水準的研究依據。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1758 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1758,'zhTW','這些陶器發現於奧達曼挖掘場。雖然它們的表面上並未包含很多有用的符文或者象形文字，但是我們可以由此得到有關古代矮人的手工藝水準和日常活動的記錄。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1759 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1759,'zhTW','這些浮雕也許是奧達曼第一大廳中最引人注目的發現了。它們清晰地顯示了矮人與如同石像一般的土靈之間的關係。隨著調查研究的不斷深入，我們對於泰坦創造矮人的假說終會得到有力的證據。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1760 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1760,'zhTW','這枚特別的卵是在塔納利斯沙漠的一處悶熱的廢墟中發現的，它至今對於生態學家來說都是一個謎。日期鑑定顯示這枚卵可能有一千年的歷史，雖然從某些方面來看，它具有昆蟲的結構特徵，但是其真實的來源還無從考證。何種生物產下了這樣一枚奇怪的卵也是個讓人疑惑不解的謎。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1761 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1761,'zhTW','這些第二次獸人戰爭時留下的遺蹟時刻提醒我們，當時部落距攻克鐵爐堡只有一步之遙。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1762 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1762,'zhTW','這些惡魔的鎧甲曾經由那個詛咒了我們的生物所穿戴著。一名英勇的獸人戰士擊敗了他，毀滅者瑪諾洛斯已不復存在。讓這副鎧甲時刻提醒我們，我們經歷了多少苦難，我們經過了多麼艱苦的鬥爭才奪回了我們的榮譽。$B$B——索爾，部落的酋長',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1771 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1771,'zhTW','這些第二次獸人戰爭時留下的遺蹟時刻提醒我們，當時部落距攻克鐵爐堡只有一步之遙。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1772 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1772,'zhTW','維姆薩拉克：$B$B我從你的主人奈法利安那裡得到直接命令，如果再有任何外來者進入城堡內部的話，你就要受到懲罰。$B$B不要忘記是誰在命令你，爬蟲。$B$B黑手之子，刀鋒和戰爭的主人，真正的酋長。$B$B—— 雷德·黑手',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1773 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1773,'zhTW','為了與來自扭曲虛空不斷侵犯泰坦世界的邪惡力量作戰，萬神殿選中了他們最強大的戰士薩格拉斯作為他們的第一道防線。由熔化的青銅鑄造的高貴戰士薩格拉斯在上百萬年的時間裡一絲不苟地履行著他的職責，搜尋並摧毀一切他能找到的惡魔。在度過了無盡的歲月之後，薩格拉斯遭遇了兩支從實體世界中獲得了巨大能量的強大惡魔種族。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1774 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1774,'zhTW','邪惡的巫術種族埃瑞達使用他們的巫術侵入並控制了許多世界，這些世界中的原住民都被埃瑞達的混亂力量變成了惡魔。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1775 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1775,'zhTW','強大的泰坦無法感知這種惡毒和腐化到底有多麼深重，他自己也陷入了不斷膨脹的消極情緒之中。儘管如此，薩格拉斯仍然堅強地振作起來，盡全力與埃瑞達的術士們作戰，並將他們逼到了扭曲虛空的一個角落裡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1776 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1776,'zhTW','在薩格拉斯的疑惑與消沉日益加深時，他又被迫與另一組試圖破壞泰坦秩序的惡魔作戰。黑暗的吸血惡魔納斯雷茲姆（他們也被稱作恐懼魔王）透過控制敵人的思想征服了許多世界，並將敵人變成了自己的爪牙。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1777 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1777,'zhTW','邪惡狡詐的恐懼魔王可以讓整個國家的人由於莫名其妙的憎恨和猜疑而互相殺戮，雖然薩格拉斯輕易擊敗了納斯雷茲姆，但他們的引誘卻對他產生了巨大的影響。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1778 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1778,'zhTW','高貴的薩格拉斯無法控制思想中不斷翻騰的疑惑和失落，繼而失去了他的信仰和作為泰坦的理智。薩格拉斯開始認為秩序的教條本身就是愚蠢的，並且開始認為只有混亂和墮落才是黑暗寂寞的宇宙中唯一的真理。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1779 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1779,'zhTW','雖然他的泰坦夥伴們試圖勸說他放棄錯誤的想法並平息憤怒的火焰，但他堅持認為他們的說辭都是謊言。在和泰坦永遠決裂後，薩格拉斯開始尋找自己在宇宙中的位置。雖然諸神對他的背叛感到很悲傷，但他們永遠也不會想到他們這位迷失的兄弟今後會變成什麼樣子。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1780 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1780,'zhTW','當薩格拉斯的瘋狂吞噬了他最後的一點高貴的靈魂之後，他開始認為泰坦才是導致造物失敗的 罪魁禍首。他最終決定組織一支不可阻擋的大軍，以地獄的烈焰毀滅所有世界，以此來糾正泰坦們犯下的“錯誤”。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1781 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1781,'zhTW','薩格拉斯巨大的身軀也因為侵蝕他心智的墮落力量而發生了扭曲。他的眼睛、頭髮和鬍鬚變成了燃燒的烈焰，他的青銅皮膚也裂開，從裂縫中噴出了無盡的仇恨和烈焰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1782 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1782,'zhTW','瘋狂的薩格拉斯摧毀了囚禁埃瑞達和納斯雷茲姆惡魔的牢籠，這些狡詐的惡魔匍匐在這位黑暗泰坦的暴怒和力量面前，發誓要披肝瀝膽地為他服務。薩格拉斯從強大的埃瑞達惡魔中挑選了兩名勇士來領導他那邪惡的毀滅勢力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1783 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1783,'zhTW','欺詐者基爾加丹負責尋找宇宙中最黑暗的種族，並將他們收入薩格拉斯麾下。汙染者阿克蒙德負責帶領薩格拉斯的大軍與任何膽敢抵抗黑暗泰坦的敵人作戰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1784 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1784,'zhTW','基爾加丹的第一步行動就是用他可怕的力量奴役吸血的恐懼魔王，這些基爾加丹的精英衛隊和遍佈宇宙的爪牙很樂意為他們的主人尋找可以引誘的原始種族。恐懼魔王中的首領，黑暗魔王提克迪奧斯是基爾加丹夢寐以求的優秀戰士，他也宣誓效忠於薩格拉斯的意志。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1785 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1785,'zhTW','強大的阿克蒙德也有屬於自己的強大軍隊。他控制著殘暴的深淵領主和他們野蠻殘暴的領導者——瑪諾洛斯，致力於建立一支可以毀滅一切生命的精英部隊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1786 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1786,'zhTW','薩格拉斯在看到他的部隊已經足夠強大、並且對他的所有命令都絕對服從之後，率領他的大軍進入了無邊的黑暗。他將這支部隊稱為燃燒軍團，不知有多少個世界被他們跨越整個宇宙的邪惡遠征所毀滅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1787 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1787,'zhTW','泰坦似乎並沒有察覺薩格拉斯毀滅秩序的計劃，他們繼續從一個世界來到另一個世界，按照他們的意願塑造這些世界，並且讓它們歸於秩序的統御。在旅途中，他們來到了一個較小的世界——這個世界後來被稱為艾澤拉斯。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1788 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1788,'zhTW','在這片混亂的土地上，泰坦們遇到了大量與他們為敵的元素生物。這些元素生物信仰著一個被稱為上古之神的無比邪惡的種族，並且拒絕讓泰坦改造它們的世界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1789 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1789,'zhTW','諸神對上古之神的邪惡嗜好感到憂慮，於是他們派出部隊與元素生物和他們邪惡的主人作戰。上古之神的軍隊由最強的元素首領率領：炎魔拉格納羅斯、石母瑟拉塞恩、馭風者奧拉基爾和獵潮者耐普圖隆。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1790 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1790,'zhTW','他們的混亂力量席捲大地，直衝巨大的泰坦而去。不過，雖然元素生物的力量非常可怕，但那也遠遠不敵強大的泰坦。元素首領們接連倒下，他們麾下的軍隊四散而逃。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1791 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1791,'zhTW','諸神摧毀了上古之神的城堡，並把藏在城堡中的四個邪惡生物囚禁在遠離地面的地下監獄中。元素生物失去了上古之神的力量，無法在實體世界中保持自己的形態，很快就紛紛化為烏有，溶入了大地。整個世界頓時恢復了一派和諧的景象。泰坦看到危機消除，就開始了他們的工作。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1792 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1792,'zhTW','為了幫助自己改造世界，泰坦創造了許多種族。為了在大地上挖掘深不可測的洞穴，泰坦用具有魔力的石頭創造了土靈；為了創造海洋並將陸地從海床上搬走，泰坦創造了巨大溫順的海巨人。泰坦們花費了數個世紀來改造這個世界，直到最後，艾澤拉斯世界上出現一塊完美的大陸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1793 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1793,'zhTW','泰坦在這塊大陸的中心鑿出了一片充滿魔法能量的湖泊，並將它命名為永恆之井，以此作為這個世界生命的源泉。湖中蘊含的無限能量可以支撐世界的骨架，並幫助各種生命在這片肥沃的土壤上生根發芽。隨著時間的推移，樹木、小草、怪物和各種生物都在這片大陸上繁盛起來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1794 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1794,'zhTW','當夜色降臨時，泰坦為這片大陸起了一個名字：卡利姆多——“永爍星光之地”。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1795 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1795,'zhTW','泰坦對他們在這片大陸上建立的秩序感到滿意，於是決定啟程離開艾澤拉斯。在他們動身之前，泰坦們決定賦予這片大陸上最強大的物種以守護世界、保衛這裡的平衡和諧不被破壞的職責。在那個時代有許多巨龍。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1796 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1796,'zhTW','它們由五條巨龍分別統治。泰坦選擇了這五條巨龍來守護這個嶄新的世界。最強的神們分別將自身的一部分神力贈與一條巨龍，這五條巨龍就是廣為人知的守護巨龍。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1797 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1797,'zhTW','眾神之父阿曼瑟爾將他的一部分力量賦予巨大的青銅龍諾茲多姆。這位眾神之父賦予諾茲多姆以守護時間和命運之路的職責，淡泊高貴的諾茲多姆成為了永恆之王。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1798 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1798,'zhTW','生命的賦予者艾歐納爾將她的一部分力量賦予紅龍阿萊克斯塔薩。此後阿萊克斯塔薩成為生命之王，守護世界上所有的生物。由於她無窮的智慧和對所有生物的無限憐憫，阿萊克斯塔薩成為了統治所有紅龍的女王。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1799 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1799,'zhTW','艾歐納爾也以一部分自然的力量祝福了阿萊克斯塔薩的姐妹，優雅的綠龍伊瑟拉。伊瑟拉陷入了永恆的迷思之中，與實體世界中所有生物的睡夢聯絡在一起。伊瑟拉成為了夢幻之王，在翡翠夢境中守護著生機勃勃的世界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1800 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1800,'zhTW','掌御著知識和魔法的諾甘農將他巨大力量的一部分賦予藍龍瑪裡苟斯，從此瑪裡苟斯成為魔法之王，守護著魔法和神秘的聖殿。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1801 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1801,'zhTW','世界的鍛造者卡茲格羅斯將他的一部分力量賦予了強大的黑色巨龍耐薩里奧。耐薩里奧成為大地之王，統御著艾澤拉斯世界的大地與深淵。他代表著世界的力量，是阿萊克斯塔薩最強大的支持者。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1802 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1802,'zhTW','五個守護者被賦予在泰坦離開後守衛世界的責任。泰坦在巨龍做好守護世界後的準備之後永遠地離開了艾澤拉斯。不幸的是薩格拉斯不久之後就會察覺到這個新生世界的存在……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1803 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1803,'zhTW','高等精靈無節制地使用魔法，使得永恆之井的魔法波動傳入了渾沌黑暗中，並且傳播到了扭曲虛空，最終被盤踞在那裡的惡魔感覺到了。薩格拉斯——所有生命的死敵，世界的毀滅者——感覺到了這股強大的魔法波動，並且找到了這股波動的來源。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1804 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1804,'zhTW','在觀察了艾澤拉斯世界並感受了永恆之井的無限能量之後，薩格拉斯急切地渴望佔有這一切，他要摧毀這個世界，將它的能量據為己有。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1805 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1805,'zhTW','薩格拉斯糾集了他的惡魔大軍——燃燒軍團，開始向艾澤拉斯進軍。燃燒軍團由數以百萬計的咆哮著的惡魔組成，他們來自宇宙的各個角落，思想中燃燒著的全都是征服的慾望。薩格拉斯的副官——汙染者阿克蒙德和毀滅者瑪諾洛斯——已經準備好要率領他們的爪牙發起進攻了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1806 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1806,'zhTW','被自己強大的魔法能量折騰得筋疲力盡的艾薩拉女王成為了薩格拉斯的第一個犧牲品，她同意為他提供進入艾澤拉斯世界的入口，甚至連她的僕從都放棄了對魔法的追求，轉而將薩格拉斯作為神來膜拜。為了表示對燃燒軍團的忠誠，他們協助女王在永恆之井裡開啟了一扇巨大的、漩渦般的傳送門。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1807 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1807,'zhTW','在所有事情都準備妥當之後，薩格拉斯開始了他對艾澤拉斯毀滅性的入侵。燃燒軍團的惡魔們從永恆之井中湧出來，對暗夜精靈的城市發動了突然襲擊。在阿克蒙德和瑪諾洛斯的率領下，燃燒軍團橫掃卡利姆多大陸，所到之處片瓦無存。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1808 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1808,'zhTW','惡魔術士從天空中召喚灼熱的地獄火，它們像隕石一樣撞擊著暗夜精靈優雅的神殿。末日守衛穿過卡利姆多的原野，屠殺它們看到的一切生物。狂暴的地獄犬在鄉村中狂奔，沒有遇到任何抵抗。雖然勇敢的卡多雷戰士迅速組織起來為保衛他們古老的家園而戰，但是在勢不可擋的燃燒軍團面前，他們只能節節敗退。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1809 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1809,'zhTW','瑪法里奧·怒風在此刻擔任起了為他的那些被圍困的同胞尋求幫助的任務，他的兄弟伊利丹曾經學習過高等精靈的魔法，但他因為對在上層階級中逐漸滋生的墮落感到憤怒而離開了他們。在確信伊利丹已經放棄了對這種力量的追求之後，瑪法里奧開始啟程去尋找塞納留斯並組織了一支反抗軍。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1810 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1810,'zhTW','年輕美麗的女祭司泰蘭妲同意在月亮女神月神的的名義下與這兩個兄弟同行。雖然瑪法里奧和伊利丹都愛著這位美麗的女祭司，但泰蘭妲的芳心只屬於瑪法里奧。伊利丹很嫉妒他的兄弟與泰蘭妲的愛情，但他知道這點傷心與他嗜之如命的魔法給他帶來的痛苦相比，是微不足道的事情……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1811 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1811,'zhTW','伊利丹對魔法能量有很大的依賴性，他為了剋制自己重新汲取永恆之井中的魔法能量的強烈慾望而時刻遭受著巨大的痛楚。儘管如此，在泰蘭妲的耐心幫助下，他仍然能夠保持足夠的理智來協助他的兄弟找到隱居的半神塞納留斯。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1812 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1812,'zhTW','在遙遠的海加爾山中的月光林地裡，他們找到了定居於此的塞納留斯。塞納留斯決定幫助暗夜精靈找到古老的巨龍並尋求他們的幫助，由紅龍阿萊克斯塔薩領導的巨龍答應派出它們強大的龍群，與惡魔和它們的首領作戰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1813 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1813,'zhTW','塞納留斯透過呼喚森林之靈集結了一支由古老樹人組成的部隊，並帶領它們對燃燒軍團發動了一次大膽的突襲。暗夜精靈的盟軍都聚集在永恆之井和艾薩拉的神殿旁準備進行戰鬥。雖然這些新的盟友擁有強大的力量，但瑪法里奧和他的同伴們意識到僅靠軍事力量是無法擊敗燃燒軍團的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1814 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1814,'zhTW','當規模空前的戰鬥在艾薩拉的首都打響時，被迷惑的女王還在靜靜地等待薩格拉斯的到來。燃燒軍團的首領準備穿越永恆之井來到這個飽經蹂躪的世界，當他那無比巨大的陰影在永恆之井那波濤澎湃的水面下出現時，艾薩拉召集了最強大的高等精靈。只有將他們的魔法能量集中在一起，才能開啟一個足夠巨大的傳送門，讓薩格拉斯順利地踏入艾澤拉斯世界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1815 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1815,'zhTW','在戰鬥席捲卡利姆多燃燒的大地時，出現了可怕的轉折。具體情形已經無從考據，據說大地的巨龍守護者耐薩里奧在對抗燃燒軍團的一場激戰中發瘋了。他的身體裂開，火焰和熱量從他黑色的皮膚下噴湧而出。這條燃燒的巨龍將自己改名為死亡之翼，轉身對付自己的同胞，將其他的巨龍趕離戰場。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1816 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1816,'zhTW','死亡之翼的突然背叛造成的傷害非常巨大，五色巨龍再也沒有恢復元氣。阿萊克斯塔薩和其他高貴的巨龍在傷痛和震驚下被迫離開了聯軍，瑪法里奧和他的夥伴無助地處於劣勢，僥倖在隨後的攻擊中存活了下來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1817 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1817,'zhTW','在確認永恆之井就是使惡魔進入這個世界的大門之後，瑪法里奧堅持認為應該摧毀它。他的同伴們被他這個瘋狂的想法嚇呆了——永恆之井是他們長壽和力量的源泉。但是泰蘭妲知道這是一個明智的抉擇，於是她請求塞納留斯和巨龍摧毀艾薩拉的神殿，並找到關閉永恆之井傳送門的方法。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1827 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1827,'zhTW','從大爆炸中倖存的暗夜精靈爬上做工粗糙的木筏，緩慢地向視野中唯一可見的陸地劃去。值得慶幸的是，在月亮女神月神的護佑下，瑪法里奧、泰蘭妲和塞納留斯在大爆炸中倖存了下來。疲憊的英雄們同意領導他們倖存的人民建立一個新的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1828 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1828,'zhTW','從大爆炸中倖存的暗夜精靈爬上做工粗糙的木筏，緩慢地向視野中唯一可見的陸地劃去。值得慶幸的是，在月亮女神月神的護佑下，瑪法里奧、泰蘭妲和塞納留斯在大爆炸中倖存了下來。疲憊的英雄們同意領導他們倖存的人民建立一個新的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1829 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1829,'zhTW','在暗夜精靈們沉默的旅途中，他們看到了大地的殘骸，並且意識到是他們對魔法的狂熱導致了這場可怕的災難。雖然薩格拉斯和他的燃燒軍團被永恆之井的毀滅摧毀了，瑪法里奧和他的同伴卻不得不思考他們為這次勝利付出的代價。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1830 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1830,'zhTW','仍然有許多高等精靈在大爆炸中倖存了下來，他們和其他暗夜精靈們一起到達了陸地上。雖然瑪法里奧並不相信這些高等精靈，但他知道，沒有永恆之井，這些精靈無法興風作浪。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1831 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1831,'zhTW','當疲憊的暗夜精靈們在新大陸的海岸登陸時，他們發現聖山海加爾在大爆炸中倖存了下來。為了尋找一片新的定居點，瑪法里奧和其他暗夜精靈一起攀登到了海加爾山的最高峰頂端。當他們俯視山下無邊的森林時，精靈們發現了一片平靜的小湖泊。令他們恐懼的是，這片湖泊的湖水充滿了魔法能量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1832 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1832,'zhTW','伊利丹也從大爆炸中倖存了下來，並且在瑪法里奧之前到達了海加爾山。他瘋狂地想要延續這個世界上的魔法源泉，於是他將永恆之井的湖水倒入了這片小湖泊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1833 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1833,'zhTW','這些湖水所蘊含的能量迅速溶入了這片小湖泊的湖水中，形成了一個新的永恆之井。興奮的伊利丹認為這個新的永恆之井是一個為他的後代準備的豐厚禮物，在他手舞足蹈時，瑪法里奧擊倒了他。瑪法里奧向他的兄弟解釋道，魔法是天生的混亂之源，使用魔法最終將導致墮落和紛爭，但固執的伊利丹仍然不願放棄他的魔法力量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1834 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1834,'zhTW','瑪法里奧知道伊利丹的邪惡計劃將會導致什麼樣的後果，於是他決定永遠地解決他那瘋狂的兄弟帶來的問題。在塞納留斯的幫助下，瑪法里奧將伊利丹囚禁在一個巨大的地下室中，直到他生命的終結。為確保他兄弟的監禁，瑪法里奧授權年輕的典獄官瑪維·影歌為伊利丹的專職守衛。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1835 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1835,'zhTW','考慮到摧毀這個新的永恆之井可能導致更大的災難，暗夜精靈決定留下它。但是瑪法里奧宣佈，暗夜精靈永遠都不能進行魔法研究。在塞納留斯的關注下，他們開始學習古老的德魯伊法術，學習如何治癒傷痕累累的大地，並開始在海加爾山腳下種植他們喜愛的樹木。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1836 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1836,'zhTW','在這之後的許多年裡，暗夜精靈們不知疲倦地為重建他們的古老家園而工作。他們遺棄了破損的神殿和道路，在海加爾山腳下的茂密叢林和隱蔽的山脈中修建了新的家園。一段時間之後，在大爆炸中倖存下來的龍來到了暗夜精靈的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1837 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1837,'zhTW','紅龍阿萊克斯塔薩、綠龍伊瑟拉以及青銅龍諾茲多姆俯視著德魯伊的寧靜家園和暗夜精靈種植的水果。擁有強大力量的大德魯伊瑪法里奧歡迎這些巨龍的到來，並且將有關新永恆之井的事情告訴了他們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1838 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1838,'zhTW','巨龍們在聽到這個可怕的訊息時大吃一驚，它們認為只要永恆之井仍然存在，燃燒軍團就不會放棄征服這個世界的念頭。瑪法里奧和三條巨龍定下了一個契約，以此保證永恆之井的安全，並確保燃燒軍團的爪牙永遠也無法找到重回這個世界的門路。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1839 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1839,'zhTW','生命的賜予者，紅龍阿萊克斯塔薩，在永恆之井的中心投下了一顆附有魔法的橡子，這顆橡子一遇到充滿魔法力量的湖水就開始生根發芽，長成了一棵巨大的橡樹。大樹的根鬚深入湖底，而巨大的樹冠幾乎要籠罩整個天空。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1840 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1840,'zhTW','這棵巨大的橡樹是暗夜精靈與自然和諧關係的永恆象徵，它所散發的生命能量可以慢慢地擴散並治癒整個世界的創傷。暗夜精靈將他們的世界之樹命名為“諾達希爾”，這在暗夜精靈語中的意思是“蒼穹之冠”。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1841 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1841,'zhTW','時間之王諾茲多姆對世界之樹附加了魔法——只要這棵世界之樹仍然存在，暗夜精靈就永遠不會衰老，也不會生病。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1842 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1842,'zhTW','“一門可以讓你度過重重難關的技能。”菲琳薩就是這樣描述她的那套本事的。$B$B如果你相信她所說的，那麼就到達納蘇斯北部的塞納里奧區去吧，她在那裡傳授她的課程。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1843 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1843,'zhTW','包括瑪法里奧在內的暗夜精靈德魯伊都透過世界之樹和翡翠夢境建立了連線，作為神秘契約的一部分，德魯伊們同意進行每次持續時間長達數百年的休眠，他們的靈魂可以在伊瑟拉的夢幻國度中自由徘徊。雖然暗夜精靈對耗費如此漫長的時間進行休眠感到惋惜，但他們仍然無私地接受了和伊瑟拉訂下的契約。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1844 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1844,'zhTW','數百年過去了，暗夜精靈的社會逐漸發展壯大，並從他們世代生活的梣谷拓展到更廣闊的疆域。在大爆炸前分佈廣泛的野生動物——比如熊怪和野豬——在這片土地上重新出現並日益活躍起來。在德魯伊的英明領導之下，暗夜精靈享受著與世無爭的寧靜生活。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1845 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1845,'zhTW','但是，許多原先的上層精靈越來越不安分。他們無法忍受失去魔法能量的空虛感，開始重新汲取永恆之井的能量，並沉浸在使用魔法的喜悅之中。上層精靈那直率急躁的領導人達斯雷瑪開始公開抨擊德魯伊，稱他們為不敢使用魔法的懦夫。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1846 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1846,'zhTW','瑪法里奧和德魯伊們對達斯雷瑪的挑釁一笑了之，並警告上層精靈，任何使用魔法的行為都將招致死亡的懲罰。傲慢的達斯雷瑪和他的追隨者們對梣谷施放了一場可怕的魔法風暴，妄圖迫使德魯伊廢除他們的法律。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1847 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1847,'zhTW','德魯伊們無法對數量如此眾多的同胞痛下殺手，只好決定流放這些魯莽的上層精靈。達斯雷瑪和他的追隨者們對擺脫他們保守的同胞感到十分高興，他們登上了經過特殊加工的船隻並駛向了大海。雖然他們之中沒人知道在狂暴的大漩渦對面有什麼樣的命運在等待他們，但起碼他們可以找到一片屬於自己的家園，一片可以使他們在不受干擾的情況下盡情練習魔法的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1848 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1848,'zhTW','上層精靈——或者說是數百年前艾薩拉女王所說的“奎爾多雷”——最終登上了東方大陸的海岸，這塊大陸後來被稱為洛丹倫大陸。他們計劃在這裡建立他們自己的魔法王國——奎爾薩拉斯，並廢除暗夜精靈對月亮女神的信仰和夜間活動的習慣。從此之後，他們的身份就變成了“高等精靈”。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1849 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1849,'zhTW','在與他們的同胞決裂之後，暗夜精靈們將注意力轉回了對他們家園的保護上。這些德魯伊在感到他們的休眠期又將來臨之後，準備離開他們的愛人和家人去進行休眠。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1850 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1850,'zhTW','月亮女神月神的首席女祭司泰蘭妲央求他的愛人瑪法里奧不要離開她而陷入伊瑟拉的夢境世界，但充滿榮譽感的瑪法里奧仍然堅持向女祭司告別，並且發誓在有生之年永遠不會與她分離。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1851 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1851,'zhTW','泰蘭妲獨自承擔起保護卡利姆多大陸的重任。她挑選了她的暗夜精靈姐妹中的精英力量組成了一支強大的部隊，這些受過嚴格訓練的無畏女戰士宣誓成為卡利姆多的保衛者，也就是哨兵部隊。雖然她們喜歡在梣谷周圍的茂密森林中獨自巡邏，但哨兵們也有許多在緊急關頭可以提供幫助的同盟。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1852 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1852,'zhTW','半神塞納留斯一直住在海加爾山的月光林地附近。他的兒子——叢林守護者們對暗夜精靈保持著密切的關注，並幫助哨兵部隊維持這片大地的平衡。塞納留斯的女兒——樹妖們也開始頻頻在公開場合露面。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1853 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1853,'zhTW','雖然在梣谷巡邏的任務使泰蘭妲忙碌不已，但她仍然感到孤單寂寞。在德魯伊們沉睡著的幾百年中，泰蘭妲感到惡魔的第二次入侵不會太遠了。她預感到燃燒軍團仍然存在，預？？到他們正在天外無邊的黑暗中策劃著對暗夜精靈和艾澤拉斯的復仇。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1854 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1854,'zhTW','達斯雷瑪領導的高等精靈離開了卡利姆多併成功穿越了波濤洶湧的大漩渦。他們的船隊在這破碎的世界中徘徊了許多年，在旅行中發現了無數神奇的奧秘與失落的國度。達斯雷瑪為自己取了個“逐日者”的稱號，不懈地尋找著一個蘊藏著大量魔法能量的地方來為他的子民建造一個新的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1855 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1855,'zhTW','他的船隊最終在某塊大陸的海岸邊上靠了岸——那塊大陸後來被稱為洛丹倫。在向內陸推進的過程中，高等精靈們在安靜的提瑞斯法林地裡建立了他們的安身之所。幾年後，他們中的許多人開始發狂。據說那是因為有些惡靈正沉睡在提瑞斯法林地的下面，不過這個傳說從來也沒有被證實過。高等精靈不得不捲起鋪蓋，向北移居到了另一片充滿能量的土地上。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1856 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1856,'zhTW','當高等精靈穿越了此起彼伏、群山連綿的洛丹倫後，他們的旅行變得更危險了。由於精靈們與給予他們活力的永恆之井之間的聯絡已經完全被切斷，他們中的許多人不是在天寒地凍中病倒，就是死於極度的飢餓。然而最讓人不安的變化卻是他們已經不再擁有永恆的生命以及對元素魔法的免疫能力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1857 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1857,'zhTW','他們的身材變矮了，肌膚也失去了獨特的紫羅蘭色。儘管面對如此嚴峻的形勢，高等精靈們還是見識到了許多在卡利姆多從沒見過的奇怪物種，他們也發現了一些原始的、以在原始森林中打獵為生的人類部落，然而他們遭遇到的最可怕的威脅還是祖阿曼的那些貪婪而狡猾的森林巨魔。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1858 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1858,'zhTW','這些皮膚上長滿苔蘚的巨魔不僅可以斷肢再生，而且他們的身體即使受到了嚴重的創傷，也能很快自行癒合，不過他們的行為表明這些巨魔還只是一個野蠻邪惡的種族。阿曼尼帝國的疆土覆蓋了北洛丹倫的大部分土地，巨魔們對貿然闖入的那些不速之客施以迎頭痛擊，把他們驅離祖——阿曼的邊境。精靈們對這些惡毒的巨魔逐漸感到深惡痛絕，無論在哪裡看到他們都會將其格殺勿論。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1859 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1859,'zhTW','許多年後，高等精靈終於找到了一片可以追憶卡利姆多的土地。他們在大陸以北的森林深處建立了奎爾薩拉斯王國，並誓言要建立一個遠比他們的卡多雷同胞更強大的帝國。不幸的是，不久以後他們就發現奎爾薩拉斯其實是建在了一座受到巨魔頂禮膜拜的巨魔古城上。巨魔們幾乎在第一時間就向精靈的定居點發起了大規模的進攻。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1860 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1860,'zhTW','固執的精靈不願放棄他們剛剛獲得的土地，於是他們利用自己從永恆之井得到的魔法遏制了野蠻巨魔的瘋狂攻擊。在達斯雷瑪的領導下，他們成功地擊敗了超過己方數量10倍的阿曼尼軍隊。一些精靈想起了卡多雷的古老警示，覺得他們對魔法的使用可能會引起那已被驅逐的燃燒軍團的注意。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1861 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1861,'zhTW','因此，精靈們決定把他們的土地用結界隱藏起來，以便讓他們能夠繼續對魔法進行研究。他們在奎爾薩拉斯周圍的多個地點建造了一系列龐大的符石作為魔法結界的邊界節點，這些符石不僅可以把精靈的魔法隱藏起來以躲避來自其他位面的威脅，還可以幫助他們嚇阻迷信的巨魔軍隊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1862 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1862,'zhTW','隨著時間的流逝，奎爾薩拉斯逐漸成為了高等精靈不懈努力與魔法威力的象徵，它美麗的宮殿保持著與卡利姆多古代城市一樣的建造風格，與大自然的地形地貌完美地融合在了一起。奎爾薩拉斯成為了一顆精靈們渴望已久的耀眼珠寶。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1863 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1863,'zhTW','儘管此時逐日者王朝還保留了少許的政治權利，但統治這個王國的卻是一個名叫銀月議會的統治機構。議會由高等精靈中最偉大的7位領主組成，負責確保高等精靈領土與子民的安全。由於有防禦結界的保護，高等精靈們仍舊對卡多雷的古老警示無動於衷，並且幾乎在他們所有日常生活中都頻繁地使用魔法。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1864 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1864,'zhTW','高等精靈在他們與世隔絕的王國中和平安寧地生活了將近四千年，然而復仇心切的巨魔不是那麼容易被打敗的。他們在森林深處囤積力量，等待著他們的軍隊發展壯大的一天。終於，一支強大的巨魔軍隊從陰暗的森林中發動了攻勢，再一次大舉進犯奎爾薩拉斯。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1865 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1865,'zhTW','當高等精靈正在為生存而抵抗著巨魔大軍猛烈的衝擊時，洛丹倫大陸上的人類遊牧民們則正在為鞏固他們自己的部落領地而戰，這些原始人的部落在襲擊其他族群的定居點時絲毫不在乎什麼榮譽和種族團結。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1866 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1866,'zhTW','最終，一個名叫阿拉希的部落意識到巨魔已經成為了對人類來說不可忽視的威脅。阿拉希部落希望把所有部落收歸自己的麾下，那樣他們就能組織起一條統一戰線來對抗巨魔軍隊了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1867 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1867,'zhTW','足智多謀的阿拉希部落花了6年的時間，用計謀和武力打敗了所有與他們對立的部落。每擊敗一個部落，阿拉希部落都給予被他們征服的人民以和平的生活與平等的權利，因此，他們贏得了戰敗者的忠誠。最終阿拉希部落容納了許多各種各樣的部落，他們的部隊也迅速壯大了起來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1868 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1868,'zhTW','他們自信可以憑一己之力來擊敗巨魔軍隊，甚至若有必要還可以擊敗那些與世隔絕的精靈，阿拉希的軍閥們決定在洛丹倫南部建造一座強大的要塞城市。這個被叫做激流堡的城邦成為了阿拉希人的國家——阿拉索的首都。隨著阿拉索的繁榮昌盛，大陸各處的人類都不遠萬里來到了安全可靠的激流堡定居。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1869 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1869,'zhTW','人類團結在同一個信念下，眾多部落逐漸發展出了一個強大的文明。阿拉索國王索拉丁知道北方的精靈正在遭到巨魔持續不斷的圍攻，但是他卻拒絕用他人民的生命作賭注來冒險幫助陌生的精靈。許多月過去了，關於精靈們正在節節敗退的傳言逐漸傳遍了洛丹倫大陸。當疲憊的奎爾薩拉斯大使來到激流堡的時候，索拉丁才意識到巨魔的威脅竟然是如此巨大。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1870 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1870,'zhTW','精靈們告訴索拉丁，巨魔的軍隊非常龐大，一旦奎爾薩拉斯被巨魔摧毀，他們的軍隊馬上就會南下。絕望的精靈們由於迫切地需要軍事援助，草草地答應向那些被選中的人類傳授魔法，以此來換取他們在抵抗巨魔軍隊時為精靈提供幫助。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1871 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1871,'zhTW','雖然索拉丁對任何魔法都不信任，但出於必要性的考慮，他還是答應支援精靈們。很快就有一批精靈法師火速趕到激流堡，開始向一小群人類傳授魔法的記憶。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1872 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1872,'zhTW','精靈們發現雖然人類在掌握施法方面顯得比較笨拙，但他們對魔法卻有一種驚人的天賦。有100個人學習了一些非常基本的精靈魔法，這些人正好足夠幫助精靈對抗巨魔。精靈們深信他們的人類學徒已經為在戰鬥中提供援助做好了準備，於是就離開了激流堡回到北方，與索拉丁國王的強大軍隊並肩作戰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1873 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1873,'zhTW','精靈與人類的聯軍在奧特蘭克山腳下猛烈衝擊著在數量上有著壓倒性優勢的巨魔軍隊。戰鬥持續了許多天，但是不屈不撓的阿拉索軍隊從沒懈怠過，他們在巨魔的攻擊中從未後退一步。精靈的領主們認為是時候將他們的魔法力量施放到敵人頭上去了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1874 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1874,'zhTW','於是百多名人類魔法師與眾多的精靈巫師從空中召下天火，將巨魔軍隊包圍在了烈火之中。元素火焰阻止了巨魔傷口的重生，將他們燒成灰燼。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1875 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1875,'zhTW','巨魔的軍隊崩潰了，當他們準備逃跑的時候，索拉丁的軍隊乘勝追擊，直到最後一個巨魔士兵倒下為止。在經歷了這次慘重的失敗之後，巨魔遭到了毀滅性的打擊，從此他們再也沒能建立起新的巨魔國家。在從毀滅的邊緣拯救了奎爾薩拉斯之後，精靈向阿拉索王室與索拉丁的血脈許下了忠誠與友誼的誓言，人類與精靈在後來的年代中一直保持著和平的關係。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1876 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1876,'zhTW','由於北方沒有了巨魔的威脅，奎爾薩拉斯的精靈們開始致力於重建他們的家園，獲勝的阿拉索軍隊回到了他們南方的家園激流堡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1877 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1877,'zhTW','阿拉索的人類社會逐漸發展繁榮了起來，後來索拉丁由於擔心他的國家繼續擴張下去遲早會四分五裂，就一直努力保持激流堡在王國裡的中樞地位。在阿拉索王國經過許多年的和平發展與通商後，偉大的索拉丁壽終正寢了，阿拉索的年輕一代開始自由拓張激流堡以外的王國疆界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1878 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1878,'zhTW','最初的那100名受到精靈教導的魔法師繼續增強著他們的力量，更加細緻地研究著如何操縱法術這一神秘學科。這些魔法師起初是由於他們強大的意志與高貴的靈魂被挑選出來的，他們也始終抱著小心負責的心態來使用魔法。然而，當他們把魔法的秘密與力量傳遞到新一代的手中之後，那些年輕人對戰爭的嚴酷與自制的必要性完全沒有概念。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1879 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1879,'zhTW','年輕的魔法師們逐漸開始為了一己私利使用魔法，而不是為了保護同胞的責任。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1880 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1880,'zhTW','隨著王國的發展，新的土地被開拓，年輕的魔法師們也來到了南方。魔法師們施展著他們神秘的力量，保護他們的同胞免受野獸的襲擊，並使得在荒園上建立新的城邦成為可能。但是隨著他們的力量越來越大，他們變得越來越自以為是，與社會也變得越來越疏遠。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1881 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1881,'zhTW','阿拉索的第二個城邦達拉然在激流堡以北建立了，許多初出茅廬的巫師離開了壓抑的激流堡來到達拉然，期望在這裡能更自由地使用他們新得到的力量。這些魔法師製造了達拉然的魔法尖塔，狂熱地進行著魔法研究。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1882 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1882,'zhTW','達拉然的居民們尊重魔法師的努力研究，並且在他們的保護下建立起了一個熱鬧的貿易體制。然而，隨著越來越多的魔法師使用魔法，達拉然周圍的空間變得脆弱，開始破裂。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1883 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1883,'zhTW','由於達拉然魔法師沒有節制的使用魔法，一些在永恆之井崩潰時被驅逐的燃燒軍團爪牙被重新引回了這個世界。雖然這些相對比較弱的惡魔並沒有大批出現，不過他們還是在達拉然造成了一定的混亂。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1884 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1884,'zhTW','大多數與惡魔的遭遇都是些零散的事件，而且當政的瑪苟克拉斯議會使盡全身解數把這些事件從大眾的目光中掩蓋了起來。一些最強大的魔法師被派去活捉這些狡猾的惡魔，不過通常他們都會發現這些強大的燃燒軍團爪牙雖然只是孤身作戰，不過卻強大得遠遠超出他們所能應付的極限。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1885 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1885,'zhTW','數月後迷信的農民開始懷疑他們的巫師統治者們有意向他們隱瞞了一些可怕的事情，隨著胡思亂想的市民質疑起他們一度曾經讚美過的魔法師的動機與行動，關於革命的謠言開始到處流傳起來。由於瑪苟克拉斯議會擔心農民們發動起義，繼而導致激流堡採取一些對他們不利的行動，於是他們不得不向精靈——他們覺得唯一有可能理解自己現在面對的特殊難題的盟友——尋求幫助。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1886 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1886,'zhTW','在聽取了瑪苟克拉斯議會關於惡魔在達拉然活動的報告後，精靈們迅速把他們最強大的巫術師們派往人類的領土。精靈巫術師們研究了達拉然的能量流，然後對每件他們目擊到的惡魔活動寫了詳細的報告。他們的結論是，儘管現在只有很少的惡魔在世界上肆虐，但是如果人類繼續濫用魔法的話，燃燒軍團對這個世界來說仍然是一個不可忽視的巨大威脅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1887 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1887,'zhTW','統治奎爾薩拉斯精靈的銀月議會與達拉然瑪苟克拉斯議會的領主們達成了一個秘密契約。精靈們告訴了瑪苟克拉斯議會一些關於古卡利姆多和燃燒軍團的歷史，那些至今仍然威脅著這個世界的往事。他們告訴人類，只要他們還使用魔法，就得想辦法保護他們的子民免受燃燒軍團的威脅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1888 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1888,'zhTW','瑪苟克拉斯議會提議將他們集體的力量授予一個最強的凡人，讓他來與燃燒軍團進行一場永不終結的秘密戰爭。由於擔心人們會由於恐懼和猜疑而發生騷亂，他們強調絕不能讓大多數人類知道守護者的存在或者燃燒軍團的威脅。精靈對此表示贊同，並且成立了一個秘密社團來監督守護者的選舉以及協助遏制混亂在這個世界的抬頭。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1889 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1889,'zhTW','這個社團在陰影籠罩的提瑞斯法林地舉行秘密會議，那塊地方就是精靈們最初在洛丹倫定居的地方。因此，他們把這個秘密組織命名為提瑞斯法守護者。最強的凡人們被選為守護者，被給予包含著精靈和人類魔法的驚人力量。雖然守護者一直是獨來獨往，但是由於擁有如此強大的力量，所以無論在什麼地方，他們都可以憑一己之力來抵抗燃燒軍團。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1890 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1890,'zhTW','由於守護者的力量極端強大，所以只有提瑞斯法會有權力從具有潛質的法師中挑選足以繼承守護者衣缽的人。無論何時，當一個守護者太過衰老，或者厭倦於這場與邪惡抗衡的秘密戰爭時，議會就會選出一個新的強者，在確保萬無一失的情況下正式將守護者的力量匯入這個新代理人的體內。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1891 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1891,'zhTW','隨著時間的推移，守護者們一直暗中保證人類免受遍佈阿拉索和奎爾薩拉斯大地上的燃燒軍團爪牙的傷害。阿拉索隨著遍佈全國的魔法普及而發展繁榮著，同時，守護者們也在繼續小心謹慎地監視著惡魔的活動。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1892 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1892,'zhTW','在泰坦們離開艾澤拉斯後，他們創造出的土靈們繼續雕琢和守護著世界的深處。土靈在很大程度上不關心居住在地面上的各個種族的事務，他們只專注於探索地下世界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1893 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1893,'zhTW','永恆之井的大爆炸把艾澤拉斯世界撕裂的同時，也深深影響到了土靈。他們隨大地的痛苦而遭受到了巨大的打擊，並因此丟失了自我意識，將自己封閉在他們誕生的那些石室中。奧達曼、奧丹姆和奧杜爾是土靈最先建造的以遠古泰坦命名的城市。而現在，這些城市被深深埋到了地下，土靈在這裡沉睡了將近8000年。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1894 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1894,'zhTW','雖然還不清楚究竟是什麼驚醒了他們，但終於有一天，奧達曼的土靈們從沉睡中醒來了。這些土靈發現自己的身體在沉睡期間發生了很大的變化。他們原本像石頭一樣堅硬的皮膚變得柔軟光滑，他們控制大地和石頭的能力也變弱了很多。他們變成了更為普通的生物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1895 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1895,'zhTW','他們把自己稱作“矮人”，這些碩果僅存的土靈們離開了奧達曼城，在逐漸甦醒的艾澤拉斯世界裡到處探險。由於他們仍然被地底深處的奧秘和安全感所吸引著，因此矮人們在陸地上最高的山峰中建造了一個巨大的王國。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1896 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1896,'zhTW','他們以泰坦的建造之神卡茲格羅斯的名字為自己的的王國命名，稱之為“卡茲莫丹”或“卡茲之峰”。矮人們為自己的泰坦父親建造了祭壇，並在山峰的中央建造了一座巨大的熔爐。從此，一座被稱為鐵爐堡的城市就在這座熔爐旁興起了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1897 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1897,'zhTW','矮人天生沉迷於加工寶石和岩石，喜歡在山峰深處開礦挖掘稀有的礦藏。他們滿足於自己在地底的工作，與地面上的其他種族互無往來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1898 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1898,'zhTW','激流堡繼續扮演著阿拉索中心的角色，不過就和達拉然一樣，許多新城邦在洛丹倫大陸逐漸建立了起來。吉爾尼斯、奧特蘭克，以及庫爾提拉斯都是第一批建立起來的城邦，雖然這些城邦每個都有著他們自己的習俗和貿易活動，但他們都一致聽命於激流堡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1899 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1899,'zhTW','在提瑞斯法會謹慎警惕的監控下，達拉然成為了這片土地上主要的魔法學習中心。統治達拉然的瑪苟克拉斯議會成立了肯瑞託，這個教派專門負責記錄和研究他們發現的每一個魔法和每一件魔法物品。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1900 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1900,'zhTW','吉爾尼斯和奧特蘭克成為了激流堡強大的支持者，並發展起了強大的軍隊，他們的遠征隊一直探索到了卡茲莫丹以南的那片山嶽連綿的土地。就在這期間，人類首次遇到了古代種族矮人，他們旅行來到了矮人們的地下洞穴城市——鐵爐堡。人類和矮人分享了許多金屬鍛造和工程學方面的知識，並發現他們對戰鬥和講故事都有著共同的愛好。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1901 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1901,'zhTW','庫爾提拉斯城邦建立在洛丹倫以南一個巨大的島嶼上，他們發展出了建立在漁業和遠洋航運基礎上的繁榮貿易。隨著時間的流逝，庫爾提拉斯建立起了一支強大的商船隊，他們穿越了所有已知地區，在世界各地搜尋供交易與販賣的奇珍異寶。但是，雖然阿拉索王國越來越繁榮昌盛，但它最強大的核心卻開始分崩離析。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1902 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1902,'zhTW','此時，激流堡的領主們開始逐漸把他們的財產轉移到繁華的洛丹倫北部地方，將貧瘠的南方遺棄不顧。索拉丁國王的繼承人——阿拉希血脈中最後一個子嗣——爭論道他們不該放棄激流堡，因此招來了那些同樣迫切想要離開的高階市民的不滿。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1903 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1903,'zhTW','激流堡的領主們決定丟下他們的古城，指望到未開化的北方去尋求純潔與教化。在達拉然以北很遠的地方，激流堡的領主們建立了一個的新城邦，它被稱作洛丹倫，這整片大陸的名字便是源自這個城邦。洛丹倫成為了一個朝聖者和所有尋求內心的和平安寧者所渴望的勝地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1904 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1904,'zhTW','阿拉希的子孫們被丟在了古激流堡那崩壞的城牆中，於是他們決定到南方卡茲莫丹的岩石林立的山脈中去。許多個漫長的年頭過去了，他們終於結束了自己的旅程，在大陸北方的一個名叫艾澤拉斯的地方定居了下來。他們在一個富饒的山谷中建立了暴風王國，不久這裡就變成了一個有了自己自足能力的地方。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1905 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1905,'zhTW','還有少數戰士仍然留在激流堡中，他們決定繼續居住在那裡，守護他們古城的城市。激流堡早已不是帝國的中央了，但它逐漸發展成了一個新的城邦國家——激流堡。儘管每個城邦都在自己的管轄下繁榮了起來，阿拉索帝國卻徹底四分五裂了。隨著每個國家都發展起了他們自己的習俗與信仰，每個城邦之間的差異都越來越大。索拉丁國王統一人類的夢想最終還是隨風消散了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1906 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1906,'zhTW','就在七個人類王國之間的政治軍事鬥爭此起彼伏之時，守護者仍然履行著他們對抗混亂的職責。在這許多年中曾有多人擔任守護者，但在同一時間內只有一個人能擁有提瑞斯法會的魔法力量。作為這時代最後的守護者之一，她是一個足以抗衡邪惡與黑暗的強大戰士。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1907 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1907,'zhTW','艾格文，這個熱情的人類女孩，贏得了提瑞斯法會的認可，並被授予了守護者的披風。艾格文精力充沛地工作著，獵殺和根除每個她找到的惡魔，但是她始終對被男性壟斷的提瑞斯法會的權力表示懷疑。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1908 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1908,'zhTW','她相信由遠古的精靈和長者們掌握的議會的思想已經過於陳舊狹隘，不能下達高瞻遠矚的果斷命令來對抗混亂。亢長枯燥的談話和辯論讓她感到極度不耐煩，她渴望向上級和同伴證明自己的價值，所以往往在許多緊要關頭時作出英勇卻有失明智的事情來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1909 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1909,'zhTW','隨著她所掌握的提瑞斯法力量逐漸增強，艾格文開始注意到一些潛伏於冰雪覆蓋的諾森德大陸的強大惡魔。她千里迢迢趕到北方，進入深山中追蹤惡魔。在那裡，她發現惡魔們正在獵殺一支倖存的龍族，企圖吸取這些遠古生物天生的魔力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1910 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1910,'zhTW','這些刻意避開日新月異的人類社會的強大龍族和燃燒軍團的惡魔打得難分難解。艾格文在龍族的幫助下消滅了這些惡魔，在最後一個惡魔從這個世界消失的時候，一股巨大的風暴出現在北方。一個龐大的黑暗身影出現在諾森德上空。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1911 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1911,'zhTW','一個龐大的黑暗身影出現在諾森德上空，燃燒軍團的首領——惡魔之王薩格拉斯出現在艾格文眼前，周身散發著地獄般的能量。他告戒年輕的守護者，提瑞斯法會的時代就要結束了，這個世界將會被燃燒軍團征服。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1912 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1912,'zhTW','驕傲的艾格文相信自己有能力對抗這個神一般的惡魔，她釋放全身的力量攻擊薩格拉斯的軀體。大大出乎她意料的是，艾格文很輕鬆地擊倒了惡魔之王，併成功地摧毀了薩格拉斯的軀體。由於怕薩格拉斯的靈魂仍然徘徊不止，天真的艾格文將他的軀體殘骸封印在了一個當永恆之井爆炸時沉沒到海底的遠古大廳中。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1913 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1913,'zhTW','艾格文沒有意識到她所做的恰恰就是薩格拉斯所預期的。她在不經意間定下了艾澤拉斯世界的命運，因為薩格拉斯的靈魂已經在他的軀體死亡的瞬間潛入了艾格文孱弱的身體中。在年輕的守護者毫不知情的情況下，薩格拉斯將在她靈魂的黑暗面中潛伏很長時間。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1914 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1914,'zhTW','鐵爐堡的矮人在和平的環境中生活了很多個世紀，然而他們的山中城市疆界太有限，而他們的社會又發展得太大了。雖然強大的高山之王莫迪姆斯·安威瑪爾運用正義和智慧統治著所有的矮人，但在矮人社會中，三個強大的部族已經出現了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1915 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1915,'zhTW','作為鐵爐堡的傳統衛隊，由親王瑪多蘭·銅鬚領導的銅鬚部族和高山之王的聯絡最緊密；由親王卡德羅斯·蠻錘領導的蠻錘部族居住在山脈下方的小丘上和峭壁邊，他們希望能得到更多對城市的控制權。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1916 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1916,'zhTW','第三個強大的部族是由法師親王索瑞森領導的黑鐵部族，他們隱居在山脈礦坑的最深處，計劃著要推翻他們那些銅鬚部族和蠻錘部族的兄弟們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1917 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1917,'zhTW','三個部族保持了一段搖搖欲墜的和平狀態，但高山之王的過世讓這脆弱的和平徹底消失了。三個部族為爭奪鐵爐堡的控制權展開了一場戰爭，矮人的內戰在地下激烈地持續了很多年。最終，擁有最強大軍隊的銅鬚部族把蠻錘部族和黑鐵部族驅逐出了鐵爐堡，贏得了戰爭的勝利。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1918 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1918,'zhTW','卡德羅斯和他的蠻錘戰士向北遷徙，穿過了丹奧加茲之門，在格瑞姆巴托峰頂建造了自己的王國。蠻錘部族在那裡繁榮興旺了起來，並重建了他們的寶藏倉庫。索瑞森和他的黑鐵部族則沒有那麼好運，戰敗的恥辱讓他們更加憤怒，他們發誓一定要報復鐵爐堡。索瑞森在美麗的紅嶺山脈建造了一座城市（以他自己的名字命名）。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1919 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1919,'zhTW','生活富足和歲月的流逝並沒有消除黑鐵部族對他們兄弟的仇恨，索瑞森和他的女巫夫人莫德古德兵分兩路對鐵爐堡和格瑞姆巴托發動了進攻。黑鐵部族準備將卡茲莫丹的所有土地收歸囊中。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1920 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1920,'zhTW','黑鐵部族的軍隊橫掃了他們兩個兄弟部族的軍隊和堡壘，差點就攻下了兩個王國。但是，瑪多蘭·銅鬚親自領導他的部族擊敗了索瑞森的法師部隊。索瑞森和他的隨從不顧格瑞姆巴托的戰局逃回了自己的城市，導致莫德古德的軍隊在面對卡德羅斯和他的蠻錘部族部隊時的處境更加艱難。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1921 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1921,'zhTW','當莫德古德面對她的敵人時，她總是運用自己的力量，將恐懼深深烙進敵人的內心。陰影隨著她的命令而移動，黑暗的物體從地底深處浮現出來，潛伏在蠻錘要塞中。最終，莫德古德攻破了大門，直接開始進攻最後的堡壘。蠻錘戰士們團結一致，卡德羅斯親自上陣，在千軍萬馬中擊殺了法師女王。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1922 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1922,'zhTW','莫德古德的陣亡讓黑鐵軍隊在暴怒的蠻錘大軍面前一潰千里，他們在向南逃往自己的城市時卻遇到了從鐵爐堡趕來增援格瑞姆巴托的軍隊。剩餘的黑鐵部族部隊被兩面夾擊，全軍覆沒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1923 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1923,'zhTW','鐵爐堡和格瑞姆巴托的聯軍隨後轉向南面，準備徹底消滅索瑞森和他的黑鐵部族。但他們並沒有走多遠，索瑞森的怒火導致了洪水般的魔法波動。他為了戰鬥的勝利而開始召喚強大的超自然生物，並不顧一切地召喚沉睡於地下的遠古力量。令他震驚（並最終毀滅他）的是，他所召喚的生物遠遠比他能夠想像到的任何一個噩夢都要可怕。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1924 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1924,'zhTW','炎魔拉格納羅斯是在初建這個世界的時候被泰坦封印的火元素之王，他由於索瑞森的召喚而再次重生。拉格納羅斯在艾澤拉斯的重生粉碎了赤脊山脈，他的力量使得一座怒哮的火山拔地而起。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1925 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1925,'zhTW','形成了一座北接灼熱峽谷南連燃燒平原的火山——黑石塔。雖然索瑞森被他釋放出來的力量殺死了，但他那些倖存下來的同類們卻大多被拉格納羅斯和他麾下的元素生物們奴役了起來。至今，他們還被留在黑石塔裡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1926 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1926,'zhTW','在目睹了可怕的毀滅景象和南部山脈肆虐的火焰後，瑪多蘭國王和卡德羅斯國王止住了他們軍隊的腳步，匆忙掉頭向他們自己的國家撤退，以免面對拉格納羅斯可怕的力量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1927 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1927,'zhTW','銅鬚部族返回鐵爐堡，重建了他們榮耀的城市，蠻錘部族也返回了他們在格瑞姆巴托的家園。然而莫德古德的死在這個山丘要塞上留下了一個充滿邪惡的瑕疵，蠻錘部族的矮人們發現那裡已經不再適合居住了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1928 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1928,'zhTW','他們對於失去自己深愛的家園感到無比悲痛。銅鬚部族的國王給蠻錘部族在鐵爐堡的疆界內提供了一個棲身之所，然而蠻錘部族卻頑固地拒絕了他。卡德羅斯帶著他的子民北上來到了洛丹倫的土地，在富饒的辛特蘭森林裡居住了下來，蠻錘部族在那裡的鷹巢山上建造了自己的城市，並逐漸親近了大自然，而且甚至與當地的獅鷲獸成為了朋友。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1929 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1929,'zhTW','鐵爐堡的矮人們希望與同胞保持聯絡與貿易，於是他們建造了兩座連線著卡茲莫丹與洛丹倫之間山口的巨大拱橋——薩多爾大橋。兩個國家靠著互相通商而繁榮了起來，瑪多蘭和卡德羅斯死後，他們的兒子為緬懷父親而共同發起雕刻了兩尊巨大的雕像。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1930 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1930,'zhTW','這兩尊雕像守護著通往南方那片火山遍佈的大地的通道，它們就像是在共同警告著試圖攻打矮人王國的傢伙，提醒他們黑鐵部族為他們的罪行付出了多麼慘重的代價。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1931 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1931,'zhTW','兩個王國繼續保持了數年的密切關係，但蠻錘部族的矮人卻由於他們在格瑞姆巴托看到的恐怖景象而發生了很多改變，他們開始居住在鷹巢山的高處，而不再在深山中挖掘自己的王國。由於意識形態之間存在著巨大的差異，兩個矮人部族最終分道揚鑣了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1932 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1932,'zhTW','時光一年年地飛逝，守護者艾格文變得越來越強大，她運用提瑞斯法的能量大大延長了自己的壽命。她錯誤地認為自己已經消滅了薩格拉斯，並在接下來的九百年中繼續為保護這個世界而與惡魔之王的爪牙鬥爭。但是，提瑞斯法會最終決定終結她的守護者職責。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1933 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1933,'zhTW','議會命令艾格文回到達拉然，以便讓他們選擇新的守護者。然而艾格文並不信任議會，她決定自己選擇接班人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1934 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1934,'zhTW','驕傲的艾格文計劃生一個孩子來繼承她的力量，她決不容許提瑞斯法會像操縱她一樣操縱自己的繼承人，於是她來到南方的艾澤拉斯，在那裡，她找到了一個最佳人選：人類魔法師聶拉斯·埃蘭。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1935 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1935,'zhTW','埃蘭是艾澤拉斯國王的御用法師跟顧問。艾格文引誘了這個魔法師並讓她懷了自己的孩子。聶拉斯天生對於魔法的喜好將會深深的埋藏在這個還未出生的小孩的身上，並且會設定好這個孩子將來所要採取的悲劇步驟。提瑞斯法的力量也會深植在這個孩子的身上，直到他的身體真正長大，這股力量才會真正的覺醒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1936 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1936,'zhTW','時光飛逝，艾格文在一處與世隔絕的森林裡生下了她的兒子，他被取名為麥迪文——在高等精靈的語言中，這個詞的意思是“保守秘密的人”。艾格文相信她的兒子將成長為下一個守護者。然而不幸的是，薩格拉斯惡毒的靈魂隱藏在她的體內，並且早在她懷孕的時候就佔據了她的孩子的軀體。艾格文根本沒有想到，剛剛來到這個世界的新的守護者已經被他最大的敵人佔據了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1937 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1937,'zhTW','在確認了麥迪文正在健康活潑地成長之後，艾格文將幼小的孩子送到艾澤拉斯的宮廷中，讓他的人類父親和其他人撫養他長大。她自己則漫遊在荒野中，準備一個人渡過餘生。麥迪文健康地成長為一個強壯的孩子，但他完全沒有意識到他體內擁有多麼強大的力量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1938 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1938,'zhTW','薩格拉斯等待著時機，等待著這個年輕人體內的力量自動顯現出來。當麥迪文成長到了少年時期，他高超的魔法技巧讓他在艾澤拉斯很受歡迎。同時，他也經常和他的兩個朋友一起去探險，這兩個朋友一個是艾澤拉斯的萊恩王子，另一個是阿拉希血統的唯一傳人，安杜因·洛薩。雖然這三個小孩子經常在王國內搞惡作劇，但平民百姓都非常喜歡他們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1939 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1939,'zhTW','當麥迪文到了14歲時，他體內強大的力量覺醒了，這股力量和潛藏於他靈魂中的薩格拉斯的靈魂發生了激烈的衝突。麥迪文因此陷入了長達數年的昏睡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1940 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1940,'zhTW','當他從昏迷中醒來的時候，他發現自己已經長大成人，而他的朋友萊恩和安杜因也已經成為了艾澤拉斯的攝政王。雖然他希望運用身體裡那不可思議的力量來保護這片被自己稱做“家園”的土地，但薩格拉斯的靈魂將他的意志和情感扭向了陰暗的一面。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1941 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1941,'zhTW','薩格拉斯出現在麥迪文心中的陰暗面，他知道第二次入侵這個世界的計劃已經快要成功了，而這個最後的守護者將幫助他們完成這個計劃。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1942 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1942,'zhTW','在麥迪文降生的前後，欺詐者基爾加丹正和他的隨從們在扭曲虛空中謀劃著下一步的行動。這個狡猾的惡魔領主在他的主人薩格拉斯的命令下，計劃著燃燒軍團對艾澤拉斯世界的第二次入侵。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1943 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1943,'zhTW','這一次，他不能允許有任何的閃失。基爾加丹認為他需要先派遣一支新的力量去削弱艾澤拉斯的防禦力量，然後燃燒軍團才能輕鬆征服這個世界。如果艾澤拉斯大陸的原生種族——比如暗夜精靈和龍族——在被迫對付新的威脅時遭到損失，那麼當燃燒軍團真正入侵的時候，他們就會因為實力太弱而不能構成任何實質性的抵抗。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1944 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1944,'zhTW','正是在這個時候，基爾加丹發現了在渾沌黑暗中靜靜地漂浮著的德拉諾，一個生機盎然的世界。這片充滿田園風情的廣闊土地是有著薩滿傳統、以氏族為社會組織形式的獸人和愛好和平的德萊尼人的故鄉。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1945 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1945,'zhTW','高貴的獸人氏族在廣闊的草原上游牧、打獵，而好學的德萊尼人在高聳的懸崖和山峰上建立了原始的城市。基爾加丹意識到，只要透過恰當的培養，這些德拉諾的原住民就可以有為燃燒軍團效命的巨大潛力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1946 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1946,'zhTW','在比較了這兩個種族之後，基爾加丹認為尚武的獸人更容易受到燃燒軍團的影響而走向墮落。他採取了和很久之前薩格拉斯控制女王艾薩拉幾乎完全相同的手法奴役了年長的獸人薩滿耐奧祖。透過這個薩滿的引導，惡魔將殺戮的慾望和野性傳播到了整個獸人氏族中。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1947 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1947,'zhTW','不久之後，這個高貴的種族便被轉化成了一群嗜血的奴僕。基爾加丹驅使耐奧祖和他的子民走完墮落的最後一步：使他們完全為了追逐死亡和戰爭而存在。但是耐奧祖意識到他的人民將會被仇恨永遠束縛，基於某種原因，他拒絕聽從惡魔的命令。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1948 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1948,'zhTW','由於耐奧祖的拒絕合作而受挫的基爾加丹很快開始尋找另一個能將他的同胞交與燃燒軍團掌握的獸人。狡詐的惡魔領主最終找到了一個令他滿意的忠實門徒——耐奧祖那野心勃勃的學生，古爾丹。基爾加丹承諾將會給予古爾丹無盡的力量，並以此來換取他絕對的忠誠。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1949 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1949,'zhTW','這個年輕的獸人漸漸成為了惡魔魔法的貪婪學徒，成為了有史以來世界上最強的術士。他向其他的年輕獸人傳授這種神秘的妖術，併力求根除獸人氏族中高貴的薩滿教傳統。古爾丹向他的同胞們展示了一種新的魔法，一種可怕的、散發著死亡氣息的能量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1950 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1950,'zhTW','基爾加丹力求對獸人有著絕對的控制權，因此他幫助古爾丹建立了影子議會，這是一個秘密的宗派組織，其作用是操縱獸人氏族並利用巫術魔法在德拉諾大陸上擴張。當越來越多的獸人開始修習巫術魔法時，安寧而生機勃勃的德拉諾世界開始變得黑暗和枯萎。隨著時間的流逝，遼闊的草原留給獸人們繁衍生息的土地已漸漸萎縮，到處都是紅色的荒土。惡魔的能量正在慢慢地毀滅這個世界。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1959 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1959,'zhTW','當基爾加丹緊鑼密鼓地讓部落為入侵艾澤拉斯做好準備時，麥迪文仍然在與薩格拉斯爭奪著自己靈魂的控制權。暴風城的萊恩國王漸漸對那些侵蝕了麥迪文靈魂的黑暗氣息感到不安。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1960 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1960,'zhTW','他把自己的擔憂告知了安杜因·洛薩——阿拉希最後的血脈，萊恩國王親自任命的軍隊統帥。但是，兩人都沒有能想像到麥迪文漸漸墮入瘋狂後會帶來什麼樣的災難。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1961 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1961,'zhTW','薩格拉斯向古爾丹許諾道，如果古爾丹答應率領部落侵入艾澤拉斯，那麼他就將給予古爾丹強大的力量作為回報。他透過麥迪文之口告訴古爾丹，如果他能找到一千多年前守護者艾格文封存薩格拉斯殘骸的水下墓穴，他就可以成為世界的主宰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1962 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1962,'zhTW','古爾丹接受了薩格拉斯的條件，並決定在擊敗艾澤拉斯的原住民之後找到傳說中的古墓並索取他應得的報酬。在確認獸人們會服從他的支配之後，薩格拉斯命令獸人開始入侵行動。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1963 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1963,'zhTW','麥迪文與影子議會的術士們合力開啟了一條被稱為黑暗之門的空間通道。這個通道連線艾澤拉斯與德拉諾，並且大到足以讓整支部隊透過。古爾丹派遣獸人斥候穿過黑暗之門去偵察這塊他們即將征服的大陸，斥候所帶回的情報使影子議會確信奪取艾澤拉斯的時機已經成熟。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1964 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1964,'zhTW','杜隆坦仍然認為古爾丹的墮落將會導致部落的滅亡，他再一次向術士們提出了抗議。這位勇士聲稱術士正在背離高尚純潔的獸人精神，而他們這種不計後果的入侵最終將給獸人帶來厄運。由於古爾丹不敢冒險殺害如此著名的英雄，他就施計將杜隆坦和他的霜狼氏族流放到了新世界的邊緣地帶去了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1965 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1965,'zhTW','在被流放的霜狼氏族衝過了通道後，只有少數獸人氏族跟著去了新世界。這些獸人很快在黑色沼澤——一個位於暴風王國東面的陰暗的沼澤地帶——建立了軍事基地。當獸人開始在這塊新土地上擴張與探索時，他們立即與暴風城的人類守衛發生了衝突。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1966 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1966,'zhTW','儘管這些小衝突很快就結束了，但它們充分體現出衝突雙方各自的優勢和劣勢。萊恩與洛薩從來都無法得知獸人的確切數量，只能依靠猜測來判斷他們將要面臨的威脅有多大。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1967 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1967,'zhTW','幾年之後，大部分獸人部落都進入了艾澤拉斯，此時古爾丹認為對人類發起總攻的時機已經到了。獸人部落聚集起所有的力量對毫不知情的暴風王國發起了進攻。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1968 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1968,'zhTW','當人類與獸人的衝突在整個艾澤拉斯王國蔓延開來時，交戰的雙方都為此付出了代價。萊恩國王堅信殘忍的獸人無法征服艾澤拉斯大陸，他輕蔑地在暴風王國的首都按兵不動。然而洛薩爵士認為應該直接與敵人進行正面交鋒，這使他不得不在自己的想法與對國王的忠誠之間作出抉擇。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1969 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1969,'zhTW','最終他選擇了自己的本能，在麥迪文的年輕學徒卡德加的幫助下，洛薩爵士對麥迪文那座位於卡拉讚的法師塔發起了閃電般的突襲。卡德加和洛薩成功地擊敗了瘋狂的守護者——那個引發戰爭的罪魁禍首。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1970 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1970,'zhTW','透過毀滅麥迪文的肉身，洛薩與卡德加在不經意間將薩格拉斯的靈魂打入了深淵。純潔而善良的麥迪文的靈魂也因此得到了解放，並在星界位面中徘徊了多年。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1971 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1971,'zhTW','儘管麥迪文被擊敗了，但是獸人部落依然佔有優勢。當獸人的大軍即將獲取勝利的時候，最偉大的獸人酋長之一的奧格瑞姆·毀滅之錘開始察覺到了那股當他們還在德拉諾的時就開始在部落中蔓延的墮落力量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1972 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1972,'zhTW','他的老朋友杜隆坦從流放之地趕回來，再次向他揭露了古爾丹的背叛行為。古爾丹的殺手很快就暗殺了杜隆坦全家，只留下了他幼小的兒子。毀滅之錘不知道這個杜隆坦唯一的血脈被一個名叫埃德拉斯·布萊克摩爾的人類中尉發現，並像對待一個奴隸一樣撫養著他。$B$B那個幼小的獸人後來成為了眾所周知的最偉大的獸人領袖。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1973 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1973,'zhTW','奧格瑞姆被杜隆坦的死激怒了，他開始著手把獸人部落從邪惡的墮落中拯救出來，最終他殺死了古爾丹的傀儡布萊克漢，取而代之成為了獸人部落的首領。在他的統御下，無情的獸人最終對暴風要塞發起了攻擊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1974 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1974,'zhTW','萊恩國王嚴重低估了獸人部落的力量，他無助地看著自己的王國落入這些綠皮膚的侵略者手中。最終，萊恩被半獸人加羅娜——影子議會中最優秀的殺手之一——所暗殺。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1975 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1975,'zhTW','洛薩和他的勇士們從卡拉贊歸來，希望盡力減少人們的傷亡並拯救他們的家園。然而，他們回來得太晚了，他們熱愛的王國已經化為一片廢墟。獸人部落依然在蹂躪著每一寸土地，被迫藏匿起來的洛薩和他的同伴立下重誓，要不惜任何代價奪回他們的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1976 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1976,'zhTW','在暴風要塞被攻陷後，洛薩爵士重新集結了艾澤拉斯的殘餘部隊，並帶領著難民遠渡重洋向北方的洛丹倫大批遷徙。人類七國領袖達成了共識：如果不阻止獸人部落，他們終將征服全人類，於是這七個國家團結起來組成了洛丹倫聯盟。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1977 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1977,'zhTW','由阿拉索分裂出去的國家三千年來第一次團結在同一面旗幟之下。被指定為人類聯盟最高指揮官的洛薩爵士為迎戰即將大舉進犯的獸人部落精心準備著他的部隊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1978 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1978,'zhTW','在副官光明使者烏瑟爾、海軍上將戴林·普羅德摩爾與圖拉揚的幫助下，洛薩成功地使洛丹倫的各個非人類種族也意識到了迅速迫近的威脅。人類聯盟成功地從鐵爐堡裡的頑固矮人和一小部分奎爾薩拉斯的高等精靈那裡獲得了支援。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1979 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1979,'zhTW','由安納斯特里亞·逐日者領導的精靈對即將發生的戰爭並沒有多大興趣，然而他們仍然為了履行由契約定下的義務而趕來支援洛薩爵士，因為洛薩是阿拉希最後的血脈，是那些曾在幾個世紀前幫助過高等精靈的人類的後代。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1980 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1980,'zhTW','由奧格瑞姆·毀滅之錘領導的獸人部落從家鄉德拉諾帶來了食人魔，並招募了那些被奪走了家園的阿曼尼森林巨魔進入自己的部隊。他們發動了規模空前的戰役，席捲了由矮人統治的卡茲莫丹大陸和洛丹倫南方的區域，並毫不費力鎮壓了所有的反對力量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1981 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1981,'zhTW','第二次獸人戰爭從海上的零星衝突一直延伸到大規模的空中混戰。不知是什麼原因，獸人部落挖出了一個被稱為惡魔之魂的強大神器，並用它奴役了紅龍女王阿萊克斯塔薩。獸人部落以摧毀她珍貴的龍蛋為威脅，迫使阿萊克斯塔薩派遣她那些成年的孩子們參加戰鬥。高貴的紅龍們不得不為獸人部落戰鬥。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1982 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1982,'zhTW','戰爭遍及整個卡茲莫丹、洛丹倫和艾澤拉斯。在北線的戰役中，獸人部落將遙遠的精靈王國奎爾薩拉斯的周邊地區燒成了灰燼，這使得精靈們開始全力協助人類聯盟作戰。洛丹倫較大的市鎮都被戰事夷為平地，儘管缺乏援軍並面臨著獸人壓倒性的優勢，但是洛薩與他的同盟者還是成功遏制住了敵人前進的步伐。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1983 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1983,'zhTW','然而，在第二次獸人戰爭的最後幾天，當獸人部落對人類聯盟的勝利近在咫尺的時候，艾澤拉斯的兩個最強大的獸人之間爆發了一次可怕的分裂。當奧格瑞姆·毀滅之錘為進攻洛丹倫的首都——這將是一次可能粉碎掉人類聯盟最後的殘餘力量的進攻——作最後的準備時，古爾丹和他的追隨者擅離職守出海而去。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1984 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1984,'zhTW','獸人部落因為古爾丹的背叛而損失了將近一半駐軍，暴怒的毀滅之錘不得不後撤，因此錯過了戰勝人類聯盟的最佳機會。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1985 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1985,'zhTW','極度渴望力量的古爾丹痴迷於獲得神格，他拼命派出搜尋隊去尋找被埋葬在海底的薩格拉斯之墓，他相信在那裡隱藏著終極力量的秘密。古爾丹已經將他的獸人同胞全部出賣給燃燒軍團作為奴隸，他壓根沒有想過所謂對毀滅之錘盡職的問題。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1986 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1986,'zhTW','在暴掠氏族和暮錘氏族的支援下，古爾丹成功地在海底找到了薩格拉斯之墓。但是當他開啟這遠古地牢的大門時，古爾丹發現等待他的只有無數瘋狂的惡魔。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1987 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1987,'zhTW','為了懲罰那些臨陣叛逃的獸人，毀滅之錘命令他的部隊去追殺古爾丹並押回叛變的獸人。古爾丹為他的魯莽付出了代價，他被自己釋放的瘋狂惡魔撕成了碎片。在他們的領導者死後，叛變的氏族很快就被毀滅之錘憤怒的軍團擊潰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1988 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1988,'zhTW','雖然叛變被鎮壓了，但獸人部落已無法彌補這次內亂所帶來的損失。古爾丹的背叛給聯盟帶來的不僅是希望，還有重新集結的時間以及發動反擊的機會。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1989 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1989,'zhTW','洛薩爵士看到獸人部落內部產生了分裂，就不失時機地集合了他最後的部隊，將獸人逼回了已被毀滅的艾澤拉斯的腹地。在那裡，人類聯盟包圍了獸人在黑石塔的據點。儘管洛薩在塔底不幸戰死，但他的副官圖拉楊在最後時刻重新聚集起人類聯盟的兄弟們，將獸人部落趕進了悲傷沼澤的深處。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1990 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1990,'zhTW','圖拉楊的部隊成功地毀滅了黑暗之門——那個連通獸人的家鄉德拉諾和艾澤拉斯世界的神秘通道。被截斷補給與後援的獸人部落終於在聯盟的力量前崩潰了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1991 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1991,'zhTW','四分五裂的獸人氏族很快被趕進了戒備森嚴的俘虜收容所。雖然看起來獸人已經被完全擊敗了，但仍然有人懷疑這種和平能持續多久。此時已經赫赫有名的大法師卡德加說服聯盟的高層建立了守望堡以監視黑暗之門的廢墟，確保獸人不會再從德拉諾發動新的入侵。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1992 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1992,'zhTW','當第二次獸人戰爭的硝煙散盡之後，聯盟以積極的態度和舉措來解決獸人問題，在洛丹倫南部建立了一系列俘虜收容所，用以關押被俘的獸人。在聖騎士和經驗豐富的老兵的看守下，收容所取得了巨大的成功。雖然那些被俘的獸人煩躁不安地想要進行戰鬥，但在古老的監獄城堡德恩霍爾德要塞的控制之下，一切都顯得和平而井井有條。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1993 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1993,'zhTW','雖然那些被俘的獸人煩躁不安地想要進行戰鬥，但在古老的監獄城堡敦霍爾德要塞的控制之下，一切都顯得和平而井井有條。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1994 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1994,'zhTW','儘管如此，在地獄般的德拉諾德世界，一支新的獸人部隊已經準備好要再次血洗毫無防備的人類聯盟。古爾丹的導師耐祖奧重新將殘留的獸族氏族集結在他的旌旗下。在影月氏族的支援下，老薩滿計劃在德拉諾開啟幾扇通向新世界的傳送門。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1995 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1995,'zhTW','為了加強他的新傳送門，他需要從艾澤拉斯取得一些上古神器。於是，耐祖奧再次開啟了黑暗之門，並派出了他的嫡系部隊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1996 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1996,'zhTW','新的獸人部落在經驗豐富的酋長─戰歌氏族的格羅姆·地獄咆哮和血窟氏族的基爾羅格·亡眼─的率領下，令聯盟的防禦部隊大驚失色，他們橫掃了四周的鄉村。在耐祖奧的精密指引下，獸人迅速找到了他們需要的神器並撤回了德拉諾。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1997 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1997,'zhTW','洛丹倫王國的泰瑞納斯國王深信獸人已經準備好了對艾澤拉斯發動新一輪的入侵，於是召集了他最信賴的副官。泰瑞納斯國王命令圖拉揚將軍和大法師卡德加率領一支遠征隊穿過黑暗之門去解決獸人的威脅。圖拉揚和卡德加率領部隊開進了德拉諾，並在荒蕪的地獄火半島上與耐祖奧的氏族激烈交戰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1998 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1998,'zhTW','即使有高等精靈艾蘭里亞·風行者、矮人庫德蘭·蠻錘和勇猛的戰士達納斯·托爾貝恩的幫助，卡德加仍然無法阻止耐祖奧開啟通往其他世界的傳送門。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 1999 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (1999,'zhTW','最終耐祖奧開啟了新的傳送門，但是他沒有預見到他將為此付出可怕的代價，這個傳送門所散發出的巨大能量開始毀滅德拉諾世界。在圖拉揚的部隊為了回到艾澤拉斯拚死戰鬥時，德拉諾世界開始崩潰。格羅姆·地獄咆哮和基爾羅格·亡眼意識到耐祖奧的瘋狂計劃會毀滅他們的整個種族，於是他們集結了殘餘的獸人並逃到了艾澤拉斯。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2000 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2000,'zhTW','在德拉諾，圖拉揚和法師卡德加最終決定在他們這邊毀滅黑暗之門，雖然他們明白自己將永遠不能離開德拉諾，但是他們也知道這是確保艾澤拉斯不受影響的唯一方法。在格羅姆·地獄咆哮和基爾羅格·亡眼為了獲得自由不顧一切地在人類的部隊裡殺開一條血路時，黑暗之門在他們的身後爆炸了。對於他們，以及所有留在艾澤拉斯的獸人們來說，回到他們家鄉的希望已經永遠破滅了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2001 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2001,'zhTW','四分五裂的獸人氏族很快被趕進了戒備森嚴的俘虜收容所。雖然看起來獸人已經被完全擊敗了，但仍然有人懷疑這種和平能持續多久。此時已經赫赫有名的大法師卡德加說服聯盟的高層建立了守望堡以監視黑暗之門的廢墟，確保獸人不會再從德拉諾發動新的入侵。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2002 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2002,'zhTW','耐奧祖和他的獸人進入了扭曲虛空——這是一片在無盡的黑暗中連線著所有世界的異度空間。然而不幸的是，基爾加丹和他手下的惡魔們正在這裡等待著耐奧祖一行的到來。基爾加丹曾經發誓要讓耐奧祖為他的抗命付出代價，於是他殘忍地折磨著這位年老的薩滿祭司，將他身上的肉一片片割了下來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2003 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2003,'zhTW','基爾加丹完好地保留著耐奧祖的靈魂，讓他忍受被大卸八塊的痛苦。雖然耐奧祖哀求惡魔釋放他的靈魂並讓他痛快地死去，但惡魔只是冷酷地回答他，他們很久以前訂下的血契仍然有效，因此耐奧祖仍然有利用價值。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2004 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2004,'zhTW','獸人未能如燃燒軍團所願征服艾澤拉斯世界，這迫使基爾加丹只好建立一支新的軍隊到艾澤拉斯世界去製造混亂。這支新的軍隊不能像獸人一樣內亂不斷，它必須對燃燒軍團唯命是從、手段殘忍，並且一心一意執行他們的任務。這一次，基爾加丹不能再失敗了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2005 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2005,'zhTW','基爾加丹控制著耐奧祖那被不斷折磨的無助靈魂，並給他最後一次為燃燒軍團服務的機會，否則就讓他忍受永恆的折磨。耐奧祖又一次不顧後果地接受了惡魔提出的條件，他的靈魂被放入了一顆經過精心雕琢的冰塊中，這塊從扭曲虛空的遠方採集的冰塊如鑽石般堅硬。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2006 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2006,'zhTW','在被裝入這個冰冷的容器之後，耐奧祖感到他的思想擴充套件了數萬倍。被惡魔的混亂力量扭曲的耐奧祖成為了一個幽靈般的生物，從那一刻起，獸人薩滿祭司耐奧祖永遠消失，而巫妖之王誕生了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2007 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2007,'zhTW','忠於耐奧祖的死亡騎士和影月氏族的追隨者也被惡魔的力量轉化了。邪惡的術士們被撕成碎片並變成了骷髏般的巫妖，惡魔們用這種方法來保證即使在死後，耐奧祖的跟隨者們也會死心塌地地為他服務。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2008 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2008,'zhTW','當時機成熟時，基爾加丹向巫妖王解釋了他的計劃：耐奧祖將在艾澤拉斯散佈瘟疫，使死亡和恐懼籠罩艾澤拉斯，並最終毀滅人類文明。所有死在恐怖瘟疫下的生物都會變成亡靈，他們的靈魂將永遠被耐奧祖的意志控制。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2009 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2009,'zhTW','基爾加丹向巫妖王保證，如果他能夠完成毀滅人類世界的任務，就可以從他的詛咒中解脫出來並獲得一個全新的健康身軀。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2010 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2010,'zhTW','雖然耐奧祖急切地想要完成他的任務，但基爾加丹仍然對他的忠誠感到懷疑。惡魔將巫妖王的靈魂困在冰殼中以確保他能夠按照軍團的命令辦事，但他知道他必須時刻警惕著巫妖王。為了解決這個問題，基爾加丹召集了他的精銳惡魔守衛——吸血鬼一般的恐懼魔王——去監視耐奧祖並確保他能完成任務。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2011 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2011,'zhTW','最強大最狡猾的恐懼魔王提託迪奧斯接受了這個挑戰，他對瘟疫的效力和巫妖王在滅絕式的大屠殺上所表現的無限創造力充滿了興趣。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2012 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2012,'zhTW','基爾加丹將盛放耐奧祖靈魂的冰冷容器送回了艾澤拉斯的世界。堅硬的水晶劃過夜空，墜落在荒涼寒冷的諾森德大陸，埋入了深不見底的冰冠冰川。困著耐奧祖靈魂的冰殼被它本身撞擊地表所爆發出的巨大能量扭曲，形成了一個王座，耐奧祖那充滿復仇意念的靈魂就附著在這個王座上。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2013 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2013,'zhTW','耐奧祖開始在冰封王座的領域中釋放他的意念並與諾森德的原住生物的思想接觸。他很輕鬆地控制了許多當地生物的思想（比如冰巨魔和兇猛的雪怪），並且將他們籠罩在自己不斷擴大的陰影下。耐奧祖發現自己的精神力量幾乎是無限的，於是他使用這種力量建立了一支小型部隊，讓他們駐紮在冰冠冰川的迷宮中。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2014 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2014,'zhTW','在恐懼魔王的監視下，巫妖王控制著他越來越強大的部隊，並且在龍骨荒地的邊緣發現了一個人類的移民點。耐奧祖決定用這些毫無防備的人類來檢驗他的力量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2015 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2015,'zhTW','耐奧祖向寒冷的荒地釋放了來自冰封王座深處的亡靈瘟疫。他用意志控制著亡靈瘟疫，將它匯入人類的村莊。在不到三天的時間內，村莊中的所有人類都死了，然後在極短的時間裡，這些死去的村民變成了殭屍。耐奧祖可以感覺到他們每個人的靈魂和思想，就好像那是他自己的一樣。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2016 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2016,'zhTW','在他腦中迴盪的哀號使他變得更加強大——就好像他們的靈魂是他急需的營養品。他發現要控制這些殭屍的行動並指派他們去做任何事情都易如反掌。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2017 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2017,'zhTW','在接下來的幾個月中，耐奧祖繼續指揮他的瘟疫橫掃諾森德大陸上的每一個人類定居點。當他的亡靈軍隊日益壯大時，他知道真正的試煉就要來了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2018 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2018,'zhTW','同時，在受戰爭蹂躪的南方土地上，部落散亂的遺蹟為他們的生存奮鬥。雖然格羅姆·地獄咆哮和他的戰歌氏族躲開了被捕的命運，亡眼和他的血環氏族仍被圍捕並被安置在洛丹倫的拘留營地。儘管經歷這些代價高的暴動，營地的典獄長很快就重建了對他們野蠻攻擊的控制。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2019 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2019,'zhTW','儘管如此，在聯盟的偵察員毫無察覺的情況下，一股強大的獸人勢力仍然控制著卡茲莫丹北部的荒野。龍喉氏族的酋長——臭名昭著的術士耐克魯斯利用一個被稱為“惡魔之魂”的遠古神器控制著紅龍女王阿萊克斯塔薩和她的紅龍一族。由於控制著紅龍女王，耐克魯斯在被遺棄的蠻錘要塞格瑞姆巴托中建立起一支秘密的部隊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2020 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2020,'zhTW','他計劃利用他的部隊和強大的紅龍軍團對聯盟發動新的戰爭，從而將四散的獸人部落重新聯合起來，繼續他們對艾澤拉斯的征服行動。然而他的計劃沒有能夠實現，由人類法師羅寧領導的一個小隊毀掉了惡魔之魂，將紅龍女王阿萊克斯塔薩從耐克魯斯的控制中釋放了出來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2021 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2021,'zhTW','暴怒的紅龍將格瑞姆巴托要塞徹底摧毀，把大部分的龍喉氏族的餘黨都燒成了灰。當聯盟將倖存的獸人投進俘虜收容所時，耐克魯斯的計劃宣告破產。龍喉氏族的失敗標誌著獸人部落的末日，以及獸人狂暴嗜血的徹底終結。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2022 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2022,'zhTW','數月之後，更多的獸人囚犯被投入了收容所。隨著各地的收容所爆滿，聯盟不得不在奧特拉克山脈南部的平原上修建新的收容所。為了更好地維持和供給數目不斷增長的收容所，洛丹倫王國的泰瑞納斯國王向所有聯盟成員國徵收新的稅款。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2023 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2023,'zhTW','這項新稅和日益升級的邊界爭執使得聯盟陷入了極其不穩定的狀態。從各方面的情況看來，在人類王國最黑暗和最困難的時期簽定的那些條約隨時可能被撕毀。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2024 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2024,'zhTW','在政治騷亂的同時，許多收容所的看守開始注意到他們的獸人囚犯發生了令人困惑的變化。獸人試圖越獄逃跑的行為，甚至是他們內部的鬥毆都大幅度減少，獸人們變得越來越冷漠和嗜睡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2025 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2025,'zhTW','雖然這很難相信，但獸人——這個曾經是艾澤拉斯大陸上最具侵略性的種族——開始喪失戰鬥的慾望。這種奇怪的現象令聯盟的領導人感到莫名其妙並繼續影響著這些急劇衰弱的獸人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2026 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2026,'zhTW','一些人認為，是一種奇怪的、只會感染獸人的疾病使獸人變成了這副昏昏欲睡的樣子。但達拉然的大法師安東尼達斯提出了另一種假說：在研究了他所能瞭解的所有獸人歷史之後，安東尼達斯發現獸人已經受惡魔的力量影響長達數百年之久。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2027 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2027,'zhTW','他認為獸人早在第一次入侵艾澤拉斯之前就已經被惡魔的力量引誘而墮落了。很明顯，惡魔毒害了獸人的血液，作為交換，他們給了獸人異乎尋常的力量、耐力和侵略性。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2028 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2028,'zhTW','安東尼達斯認為獸人的反常嗜睡行為並不是疾病，而是長期以來使他們變得可怕、嗜血的惡魔法術消退的後果。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2029 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2029,'zhTW','雖然這種症狀很明顯，但安東尼達斯無法找到治療獸人目前狀況的方法，而他的許多學徒和一些著名的聯盟領導人都認為替獸人找出治療的方法純屬冒險行為。在謹慎地考察了獸人目前的神秘狀況之後，安東尼達斯認為治癒獸人的唯一途徑是透過精神的力量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2039 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2039,'zhTW','當索爾在洛丹倫釋放其同胞弟兄的時候，耐奧祖繼續在諾森德大陸鞏固他的基地，他在冰冠冰川上空建立起了一座巨大的城堡以控制龐大的亡靈軍團。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2040 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2040,'zhTW','但在巫妖王拓展他的疆域時，一個孤單、隱秘的王國開始與他的力量進行對抗。這個被稱為艾卓-尼魯布的古老的地下王國是由一個殘忍的類人蜘蛛種族建立的，他們派出精銳部隊襲擊了冰冠冰川，並使耐奧祖打消了征服他們的瘋狂念頭。耐奧祖沮喪地發現這些蜘蛛對他的心靈控制完全免疫，並且強大到足以和他的亡靈大軍一較高下。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2041 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2041,'zhTW','蛛網怪的蜘蛛之王控制著龐大的部隊，並且擁有覆蓋了諾森德一半疆域的地下隧道網路。他們的游擊戰術令巫妖王疲於奔命卻一無所得。最終，耐奧祖艱難地贏得了對蛛網怪的戰爭，在狂暴的恐懼魔王和無數不死生物戰士的進攻下，蜘蛛王國艾卓-尼魯布變成了一片廢墟。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2042 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2042,'zhTW','雖然蛛網怪對耐奧祖的精神力量免疫，但他強大的通靈能力使他能夠操縱蜘蛛戰士的屍體並讓他們為他作戰，併為這些蜘蛛戰士修建了適合他們的堡壘和建築物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2043 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2043,'zhTW','在一統諾森德大陸之後，巫妖王準備著手執行他真正的任務。巫妖王將他的意念延伸到了人類的領土，並且召喚所有願意聆聽他的聲音的黑暗靈魂……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2044 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2044,'zhTW','在世界各地都有一些強大的人類願意聽從巫妖王從諾森德發出的精神召喚，其中最著名的就是達拉然的大法師克爾蘇加德，他曾是統治達拉然的法師議會肯瑞託的一員。多年以來，克爾蘇加德一直被認為是一個異類，因為他堅持研究被禁止的通靈術。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2045 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2045,'zhTW','在熱切地學習完魔法世界中他能接觸到的所有知識後，克爾蘇加德對眼前的同輩們過時和缺乏想象力的教條感到很沮喪。在聽到耐奧祖的召喚之後，渴求黑暗知識的大法師傾盡全力與這個神秘的聲音溝通，最終發誓要從強大的巫妖王那裡學習所有他能夠學習的東西。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2046 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2046,'zhTW','克爾蘇加德放棄了他的所有財產和地位，永遠離開了肯瑞託和達拉然。在巫妖王的指示下，他變賣了所有財產，將得到的金錢都藏在一個秘密的地方。在經歷了艱難的長途跋涉之後，克爾蘇加德終於抵達了諾森德的冰凍海岸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2047 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2047,'zhTW','大法師穿越了被戰爭毀滅的艾卓-尼魯布王國的廢墟，在這裡他看到了耐奧祖的可怕力量，他開始相信投靠神秘的巫妖之王是一個明智而且利益豐厚的決定。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2048 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2048,'zhTW','在冰冷的荒野上旅行了數月之後，克爾蘇加德終於到達了冰冠冰川。他來到了耐奧祖的黑暗城堡，當沉默的亡靈守衛讓他透過時，大法師感到了強烈的震撼。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2049 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2049,'zhTW','他沿著道路一直朝下走，在冰川的最底層，他見到了冰霜王座，並且將自己的靈魂獻給了巫妖王。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2050 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2050,'zhTW','巫妖王對新的追隨者感到十分滿意。他向克爾蘇加德許諾要給他不死之身和強大的力量，以換取他的忠誠和服從。渴望黑暗知識和力量的克爾蘇加德馬上接受了他的第一個任務——深入人類世界並建立一個將耐奧祖作為神來膜拜的新教派。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2051 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2051,'zhTW','為了幫助大法師完成他的任務，耐奧祖讓他繼續保留人類的軀體。大法師出色地完成了任務，他運用幻像和宗教的力量吸引了大批被流放的洛丹倫人，並向他們描述了一個美麗的新社會——還給他們每人都送了一個可以隨時聯絡巫妖王的人偶……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2052 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2052,'zhTW','克爾蘇加德秘密回到了洛丹倫，並且在那裡活動了三年。他運用他的財富和智商聚集了一些願意跟隨他的人類並組建了一個名為“詛咒神教”的教派。他向信徒們許諾要賜予他們平等的社會地位和永恆的生命以換取他們對耐奧祖的服從。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2053 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2053,'zhTW','數月之後，大量對生活心灰意冷的人加入了他的教派。克爾蘇加德的目標——令人們放棄對光明的信仰，轉而膜拜耐奧祖的黑暗力量——很容易地就達到了。在詛咒教派不斷發展壯大的同時，克爾蘇加德也要確保洛丹倫的統治者們不會發現他們的秘密活動。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2054 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2054,'zhTW','當克爾蘇加德在洛丹倫大獲成功的時候，巫妖之王也在為進攻人類世界做最後的準備。耐奧祖將他的瘟疫能量灌入許多被稱為“瘟疫之源”的神器中，並命令克爾蘇加德將這些神器帶往洛丹倫，隱藏在那些被教派控制的村莊中。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2055 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2055,'zhTW','這些被忠誠的教徒保護著的瘟疫之源將作為產生瘟疫的源泉，源源不斷地放出瘟疫，橫掃洛丹倫北部的城市和村莊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2056 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2056,'zhTW','巫妖王的計劃運作得十分成功。許多洛丹倫北部的村民幾乎是瞬間就被感染了。與在諾森德一樣，被瘟疫接觸的人類死去，然後變成對巫妖王唯命是從的奴隸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2057 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2057,'zhTW','克爾蘇加德領導的信徒急切地希望死去併為他們的主人服務，他們希望透過這種方式變成不死之身。隨著瘟疫逐漸擴散，洛丹倫北部出現了越來越多的殭屍，克爾蘇加德管理著這支日益龐大的部隊，並稱他們為“天災”——不久之後，它就會踏進洛丹倫的大門，並把人類從這個世界上永遠抹掉。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2063 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2063,'zhTW','經過數月的漫長準備，克爾蘇加德率領他的詛咒教派向洛丹倫發起了第一輪攻擊，釋放了亡靈瘟疫。烏瑟爾和他的聖騎士們調查了受瘟疫感染的地區，希望能找到一種解救的辦法。他們不斷地努力，但是瘟疫仍然在擴散，甚至威脅到了聯盟的統一。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2064 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2064,'zhTW','經過數月的漫長準備，克爾蘇加德率領他的詛咒教派向洛丹倫發起了第一輪攻擊，釋放了亡靈瘟疫。烏瑟爾和他的聖騎士們調查了受瘟疫感染的地區，希望能找到一種解救的辦法。他們不斷地努力，但是瘟疫仍然在擴散，甚至威脅到了聯盟的統一。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2065 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2065,'zhTW','不死生物的威脅橫掃洛丹倫，國王泰瑞納斯的獨子——阿爾薩斯王子擔當起了對抗天災軍團的重任。阿爾薩斯成功地消滅了克爾蘇加德，但是不死生物的軍隊並沒有因此而減少，反而有更多陣亡的人類士兵成為了新的不死生物。面對勢不可擋的強大力量和失敗的挫折感，阿爾薩斯採取了更極端的抵抗措施。最後，阿爾薩斯的戰友告誡他，不要因此喪失了高貴的人格。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2066 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2066,'zhTW','阿爾薩斯的恐懼和決心導致了他最終的覆滅。他追蹤瘟疫的源頭直到諾森德大陸，想要徹底消除瘟疫的威脅。然而，阿爾薩斯王子最終成為了巫妖王的獵物，他拔出了被詛咒的魔劍——霜之哀傷，因為他深信這麼做可以挽救自己的臣民。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2067 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2067,'zhTW','雖然這把劍的確給他帶來了深不可測的力量，但它同時也奪取了王子的靈魂，使他變成巫妖王手下最強大的死亡騎士。徹底喪失心智的阿爾薩斯帶領天災軍團回到了自己的王國。最終，阿爾薩斯刺殺了他的父親——泰瑞納斯國王，隨後又率領巫妖王的大軍踏平了整個洛丹倫。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2068 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2068,'zhTW','雖然阿爾薩斯打敗了他目前的所有敵人，但他卻擺脫不了克爾蘇加德的鬼魂。鬼魂告訴阿爾薩斯，為了巫妖王的下一步計劃，他必須復活，方法就是把他的屍骨帶到高等精靈王國奎爾薩拉斯的太陽之井去。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2069 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2069,'zhTW','阿爾薩斯和天災軍團侵入奎爾薩拉斯，將精靈圍困在脆弱的防線後。銀月城的遊俠領袖希爾瓦娜斯·風行者奮勇戰鬥，但仍不敵阿爾薩斯。阿爾薩斯摧枯拉朽般地擊潰了精靈的部隊，順利進入了太陽之井。作為展示他的力量的手段，他把希爾瓦娜斯的遺體變成女妖，使她永遠不死，永遠向阿爾薩斯這個奎爾薩拉斯的征服者效忠。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2070 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2070,'zhTW','最後，阿爾薩斯把克爾蘇加德的屍骨浸沒在太陽之井的聖水中。儘管永恆的聖水因此受到了汙染，克爾蘇加德卻復活成為了一個法力強大的巫妖，重獲新生之後的克爾蘇加德向阿爾薩斯解釋了巫妖王的下一步計劃',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2071 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2071,'zhTW','當阿爾薩斯和他的亡靈軍隊揮師南下時，奎爾薩拉斯已是死寂沉沉。屹立了九千多年的高等精靈的王城從此不復存在。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2072 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2072,'zhTW','克爾蘇加德復活之後，阿爾薩斯就率領天災軍團殺向了達拉然。他們要在那裡得到麥迪文之書，然後用它來召喚阿克蒙德，然後阿克蒙德將親自率領燃燒軍團發起最後的進攻。就連肯瑞託的法師也無法阻止阿爾薩斯的軍隊偷到麥迪文之書。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2073 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2073,'zhTW','很快，克爾蘇加德就湊齊了施展魔法所需的物品。在距第一次入侵艾澤拉斯世界失敗的一萬年後，強大的惡魔阿克蒙德和他的部隊再次浮現在艾澤拉斯世界的上空。然而，達拉然並不是他們的最終目標。在基爾加丹的命令下，阿克蒙德和他的惡魔跟隨天災軍團到達了卡利姆多，他們計劃要摧毀世界之樹——諾達希爾。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2074 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2074,'zhTW','在這場混亂當中，一個孤獨而神秘的預言者給危難之中的弱小種族提供了指引。這個預言者不是別人，正是最後一位守護者，麥迪文，他正在努力挽救自己犯下的錯誤。麥迪文告知獸人部落和人類聯盟，危險就在眼前，雙方應該即刻聯合起來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2075 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2075,'zhTW','但是由於世代交惡，他們是不可能合作的。麥迪文不得不分別警告獸人和人類，即便是使用預言術或者欺騙的手段，也要引導他們渡過大海，前往傳說中的大陸——卡利姆多。獸人和人類很快就遇到了隱居很久的卡多雷文明。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2076 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2076,'zhTW','索爾領導獸人經歷了千辛萬苦，在卡利姆多的荒地上展開了探索。儘管友善的牛頭人凱恩·血蹄和強壯的牛頭人戰士慷慨相助，很多獸人還是開始屈服於折磨他們多年的殺戮欲。索爾的副官——格羅姆·地獄咆哮——甚至背叛了獸人部落，屈服於這種由惡魔帶來的慾望。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2077 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2077,'zhTW','格羅姆地獄咆哮和他的戰歌氏族在梣谷遇到了遠古暗夜精靈的哨兵。在確認獸人再次顯示出了他們好戰的本性之後，半神塞納留斯親自前來驅逐這些獸人。然而，地獄咆哮和他的手下被無盡的仇恨和憤怒所控制，殺死了半神塞納留斯，玷汙了古老的森林。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2078 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2078,'zhTW','最後，地獄咆哮幫助索爾打敗了瑪諾洛斯——這個當初利用自己充滿仇恨和憤怒的鮮血詛咒獸人的惡魔領主，贏回了自己的榮譽。隨著瑪諾洛斯的死去，獸人也從惡魔的詛咒中永遠解脫了出來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2079 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2079,'zhTW','當麥迪文勸說獸人和人類組成聯盟的時候，暗夜精靈依靠他們的力量獨力對抗著燃燒軍團。暗夜精靈的大祭司泰蘭妲·語風獨立奮戰，將惡魔和不死生物抵擋在梣谷外。泰蘭妲也感到她需要援兵，於是，她前去喚醒沉睡了千年的德魯伊們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2080 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2080,'zhTW','有了愛人瑪法里奧·怒風的幫助，泰蘭妲成功地加強了防禦，擊退了燃燒軍團。大自然在德魯伊的幫助下擊潰了燃燒軍團和天災軍團。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2081 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2081,'zhTW','在尋找更多沉睡的德魯伊時，瑪法里奧發現了關押他的親生兄弟伊利丹的石牢。泰蘭妲相信伊利丹將助他們一臂之力，於是就把他釋放了出來。雖然伊利丹確實幫助了他們一段時間，但他最終還是走上了自己的道路。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2082 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2082,'zhTW','暗夜精靈團結一心，堅決抵抗燃燒軍團。然而燃燒軍團一刻也沒有停止過對永恆之井的渴望，始終妄想得到世界之樹的力量。如果他們的計劃得逞，世界將在這群惡魔的手中徹底毀滅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2083 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2083,'zhTW','在燃燒軍團對梣谷展開入侵期間，伊利丹結束了他在地牢中近萬年的囚犯生涯。他曾盡力讓他的夥伴對他安心，但很快他就原形畢露，吸收了一個被稱為“古爾丹之顱”的強大術士神器的能量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2084 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2084,'zhTW','完成吸收之後的伊利丹變化成了一個擁有惡魔外表和強大力量的生物，他還獲得了古爾丹的一部分記憶，特別是關於薩格拉斯之墓——那座傳說中位於一座小島上的，埋藏著黑暗泰坦薩格拉斯遺骸的地牢。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2085 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2085,'zhTW','重新獲得力量和自由的伊利丹急於證明自己的價值。然而他碰上了基爾加丹，這個惡魔向他提出了一個難以抗拒的提議。基爾加丹對阿克蒙德在海加爾山的失敗非常惱火，不過他還有比復仇更重要的事情要做。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2086 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2086,'zhTW','在覺察到自己的傑作巫妖王變得過於強大而難以控制之後，基爾加丹命令伊利丹去終結耐奧祖，並永遠消滅天災軍團的力量。作為交易的條件，伊利丹將會得到巨大的力量並在燃燒軍團的領導者中佔有一席之地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2087 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2087,'zhTW','伊利丹同意了這個計劃，並立刻開始準備摧毀囚禁著巫妖王靈魂的冰晶塊：冰封王座。伊利丹知道他需要一件強大的神器來摧毀冰封王座，於是他準備用從古爾丹的記憶中得到的知識去尋找薩格拉斯之墓並得到黑暗泰坦的遺物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2088 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2088,'zhTW','他將那些蛇一般的納迦從黑暗的深海巢穴中召喚出來。在狡猾的首領瓦辛的帶領下，納迦幫助伊利丹尋找傳說中薩格拉斯之墓所在的破碎島嶼。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2089 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2089,'zhTW','在伊利丹和納迦出發的同時，典獄官瑪維·影歌也開始了對他的追捕。瑪維在這一萬年裡一直擔任伊利丹的看守，她相信自己可以重新抓獲伊利丹。然而，狡猾的伊利丹讓瑪維和哨兵們的努力化為泡影，？|成功竊取了薩格拉斯之眼。伊利丹帶著這個強大的神器來到魔法之城達拉然。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2090 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2090,'zhTW','城市裡的能量裝置強化了伊利丹的力量，他開始使用薩格拉斯之眼施展一個毀滅性的法術來對付位於遙遠的諾森德大陸上的巫妖王的冰冠堡壘。伊利丹的法術粉碎了巫妖王的防禦力量並割裂了世界之脊。在最後的時刻，這個毀滅性的咒語被趕來支援瑪維的瑪法里奧和女祭司泰蘭妲所阻止。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2091 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2091,'zhTW','伊利丹很清楚，基爾加丹絕對不會對他的失敗善罷甘休，便逃向荒涼的外域，這裡是德拉諾的殘留地域，曾經是獸人的家園。伊利丹決定在這裡避避風頭並計劃他的下一步行動。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2092 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2092,'zhTW','在成功地阻止了伊利丹之後，瑪法里奧和泰蘭妲回到梣谷的家園去照顧他們的人民。然而瑪維並不打算善罷甘休，她尾隨伊利丹來到外域，下決心要把他帶回去接受審判。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2093 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2093,'zhTW','此時，天災軍團已將洛丹倫和奎爾薩拉斯徹底變成了充滿劇毒的瘟疫之地。那裡只有一些小規模的聯盟抵抗力量仍在苟延殘喘。其中的一個組織主要由高等精靈組成，他們的領導者是逐日者王朝的最後一個成員，凱爾薩斯王子。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2094 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2094,'zhTW','作為一名出色的法師，凱爾小心翼翼地在幾近覆滅的聯盟中成長。高等精靈對家園的淪陷非常悲痛，為了向死去的同胞表示敬意，他們改稱自己為血精靈。當血精靈奮力遏制天災軍團的攻勢時，他們因為離開了太陽之井這個力量的源泉而備受煎熬。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2095 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2095,'zhTW','為了緩解手下們與生俱來的對於魔法的飢渴，凱爾做了件令人無法想像的事情：他接受了他們的高等精靈祖先伸出的援手，懷著找到一個新的魔法力量之源的希望加入了伊利丹和他的納迦部隊。殘餘的聯盟領袖譴責血精靈為叛徒，並將他們永遠驅逐。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2096 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2096,'zhTW','走投無路之下，凱爾和他的血精靈們只得跟隨伊利丹來到外域，並幫助他對付典獄官馬維。馬維本已將伊利丹抓獲，卻被血精靈和納迦聯手擊敗，伊利丹也被重新解放。伊利丹將外域作為自己的基地，為了向巫妖王和他的冰冠冰川要塞發起新一輪的進攻而聚集著力量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2097 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2097,'zhTW','巫妖王耐奧祖知道自己已經時日不多了。被囚禁在冰封王座之中的他懷疑基爾加丹會派出手下來毀滅自己，伊利丹的咒語造成的傷害破壞了冰封王座，巫妖王的力量因而一天天地喪失。於是，急於自保的耐奧祖將他最強大的手下——死亡騎士阿爾薩斯召喚到身邊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2098 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2098,'zhTW','阿爾薩斯的力量隨著巫妖王的虛弱而漸漸流失，他陷入了洛丹倫的一場內戰中。女妖希爾瓦娜斯·風行者領導著半數的亡靈軍團發動了一場試圖顛覆阿爾薩斯統治的政變。正當戰鬥擴散到整個瘟疫之地時，阿爾薩斯被巫妖王所召喚，領導權被移交給了他的副官克爾蘇加德。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2099 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2099,'zhTW','最終，希爾瓦娜斯和她的亡靈叛軍（他們被稱作被遺忘者）將洛丹倫都城的廢墟佔為己有。被遺忘者在都城的殘骸下建立起了自己的基地，他們發誓要擊敗天災並將克爾蘇加德和他的僕從趕出大陸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2100 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2100,'zhTW','力量遭到削弱的阿爾薩斯仍決定去援救他的主人。他到達諾森德後卻發現伊利丹的血精靈和納迦已經先他一步到了那裡。於是，阿爾薩斯和他的蜘蛛怪只得與伊利丹的部隊爭奪時間，他要率先到達冰冠冰川冰川並保護冰封王座。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2101 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2101,'zhTW','即便是在如此虛弱的情況下，阿爾薩斯最終仍以策略戰勝了伊利丹，並率先抵達了冰封王座。阿爾薩斯用他的魔劍霜之哀傷擊碎了囚禁巫妖王的冰牢，並得到了耐奧祖附魂的頭盔和胸甲。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2102 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2102,'zhTW','阿爾薩斯將擁有無盡力量的頭盔戴到了自己的頭上，成為了新的巫妖王。正如耐奧祖一直計劃的那樣，他和阿爾薩斯的靈魂合體成為一個強大的生物。伊利丹和他的軍隊被迫恥辱地逃回外域，阿爾薩斯則成了這個世界上最強大的生物之一。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2103 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2103,'zhTW','現在的阿爾薩斯作為新的不朽的巫妖王佔據著諾森德，據說他正在那裡重建冰冠冰川城堡，而他所信任的副官克爾蘇加德則統領著瘟疫之地的天災部隊。希爾瓦娜斯和她的反叛亡靈力量僅僅控制著提瑞斯法林地，那只是被飽經戰亂的洛丹倫王國的一小部分。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2104 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2104,'zhTW','儘管獲得了戰爭的勝利，但艾澤拉斯的各個種族卻發現他們的世界早已被戰爭所摧毀。天災軍團和燃燒軍團毀滅了洛丹倫的文明，卡利姆多也幾乎遭受同樣的命運。這裡有飽經創傷的森林需要治癒，有無邊的仇恨需要忘卻，人民需要新的家園來定居。戰爭重創了每一個種族，但他們無私地合作，想要創造一個新的開端。這一切都從聯盟和部落之間極為來之不易的停戰開始。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2105 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2105,'zhTW','索爾領導著獸人來到卡利姆多大陸，他們在牛頭人同胞的幫助下建立了一個新的家園。獸人們以索爾被暗殺的父親的名字將這新的國家命名為杜隆坦，他們定居下來，並試圖重建他們那一度輝煌的文明。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2106 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2106,'zhTW','現在惡魔的詛咒被終結了，部落從一股好戰的狂熱力量變為了一個鬆散的聯盟，生存與繁榮是他們的首要任務。在高貴的牛頭人和狡猾的暗矛部落巨魔的幫助下，索爾和他的獸人們期盼著一個和平的新紀元的到來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2107 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2107,'zhTW','吉安娜·普羅德摩爾手下殘存的聯盟力量定居在南卡利姆多。他們在東海岸的塵泥沼澤附近建立了簡陋的港口城市塞拉摩。人類和矮人同盟合力在這片充滿危險的土地上生存，儘管杜隆坦和塞拉摩的防禦力量彼此暫時停戰，但這個脆弱的殖民地的平靜並不意味著最終的和平。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2108 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2108,'zhTW','人類和獸人間的和平被一支抵達卡利姆多的龐大聯盟艦隊所破壞。海軍上將戴林·普羅德摩爾（吉安娜的父親）率領這支艦隊在阿爾塞斯毀滅洛丹倫之前離開了那裡。海上數月的航行令人筋疲力盡，但是普羅德摩爾仍然尋找著一切他可以找到的聯盟倖存者。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2109 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2109,'zhTW','海軍上將普羅德摩爾的艦隊對該地區的穩定造成了嚴重的威脅。作為一位在第二次戰爭中聲名顯赫的英雄，吉安娜的父親是部落的死敵，他決心在獸人站穩腳跟之前摧毀杜隆坦。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2110 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2110,'zhTW','普羅德摩爾強迫吉安娜做出一個艱難的抉擇：支援他對抗獸人並且背叛她的新同盟，或者與她的親生父親交戰來維護聯盟和部落之間來之不易的脆弱和平。在一番思想鬥爭之後，吉安娜選擇了後者，她幫助索爾打敗了她瘋狂的父親。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2111 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2111,'zhTW','不幸地是，海軍上將在吉安娜向他證明獸人已經不再是嗜血的怪物並與他和解之前就戰死了。出於吉安娜對部落的忠誠情義，獸人們同意讓她的部隊安全地回到塞拉摩的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2130 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2130,'zhTW','不幸地是，海軍上將在吉安娜向他證明獸人已經不再是嗜血的怪物並與他和解之前就戰死了。出於吉安娜對部落的忠誠情義，獸人們同意讓她的部隊安全地回到塞拉摩的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2131 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2131,'zhTW','向你致敬，戰士。我不會再奉承你的力量與勇猛，這都是些陳年舊帳了。最近你殺了多少人？我猜沒多少。你正在退步，你正在因為缺乏挑戰而變得越來越弱。$B$B我可不能讓一個戰士就這麼變成廢物，不會管別人是怎麼奉承你的，現在的事實就是：你需要接受訓練，而我可以訓練你。什麼時候你那榆木腦袋開竅了，就來找我吧，我在大獸穴外的帳篷下面。$B$B——弗朗恩，戰士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2150 AND `locale` = 'zhTW';
