INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2190,'zhTW','大約16000年以前（遠早於暗夜精靈愚蠢地召來燃燒軍團的年代），巨魔主宰了卡利姆多大陸（那個時候只有一塊大陸）的大部分割槽域。那個時候有兩個巨魔帝國並存，即東南部森林中的古拉巴什帝國，以及中部的阿曼尼帝國。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2191 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2191,'zhTW','大約16000年以前（遠早於暗夜精靈愚蠢地召來燃燒軍團的年代），巨魔主宰了卡利姆多大陸（那個時候只有一塊大陸）的大部分割槽域。那個時候有兩個巨魔帝國並存，即東南部森林中的古拉巴什帝國，以及中部的阿曼尼帝國。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2192 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2192,'zhTW','在北部有些小的部族（位於現在的諾森德地區），這些部族建立了一個叫做祖達克的小國家，但是其規模和繁榮程度從來沒有達到過南方這兩個帝國的程度。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2193 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2193,'zhTW','古拉巴什帝國和阿曼尼帝國之間並不十分友好，但是也不常交戰。那個時候，他們共同的敵人是一個異族的帝國——阿茲亞基文明。亞基是一種有智慧的昆蟲生物，它們主要統治著西部地區。這些聰明的蟲族生物具有強烈的擴張慾望，並且非常邪惡。亞基蟲類的目標就是消滅卡利姆多大陸上所有的非昆蟲生物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2194 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2194,'zhTW','巨魔與它們進行了數千年的戰爭，但是從來沒有對亞基蟲類獲得壓倒性的優勢。最終，由於巨魔的不斷攻擊，亞基帝國一分為二，它的臣民逃散到大陸北部和南部偏遠地區的聚居地去苟延殘喘。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2195 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2195,'zhTW','兩個大的亞基蟲類城市出現了。它們在北部的荒地中建立了艾卓-尼魯布，在南部沙漠中建立了安其拉。雖然巨魔們認為在卡利姆多大陸的地下還有其他亞基蟲類的聚居地存在，但是這個觀點沒有被證實過。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2196 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2196,'zhTW','隨著蟲類生物被趕走，兩個巨魔帝國又恢復了原來的狀態。雖然他們獲得了偉大的勝利，但是兩個帝國都沒有大舉擴張。然而，我們可以從古文記錄中得知，有一小部分巨魔從阿曼尼帝國脫離，在這塊黑暗大陸的中心建立了自己的殖民地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2197 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2197,'zhTW','在那裡，勇敢的先行者們發現了洶湧的永恆之井，並從中獲得了無窮的力量。據說這些巨魔就是後來的暗夜精靈，不過這個理論從來都沒有被證實過。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2198 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2198,'zhTW','即便不考慮暗夜精靈真正的起源，但他們確實在發現了永恆之井後力量大增。巨魔並沒有去努力地擴張他們的領地，而暗夜精靈卻建立了一個強大的帝國，並且迅速在卡利姆多大陸上擴張。他們使用的魔法是那些迷信的巨魔從來都沒有想像過的，因此，暗夜精靈輕鬆地完成了邪惡的亞基蟲類無法做到的事情——將兩個最偉大的帝國從世界上徹底抹掉了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2199 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2199,'zhTW','暗夜精靈系統性地瓦解了巨魔的防禦和攻擊力量。巨魔無法對抗暗夜精靈毀滅性的魔法，所以只有坐以待斃。暗夜精靈在這段時間裡體現出了和那些野蠻的巨魔一樣的狡猾和嗜血——這使得後來的種族對他們非常仇恨和輕蔑。古拉巴什和阿曼尼帝國在之後的數年內便分裂為數個小國家。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2200 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2200,'zhTW','最終，暗夜精靈被他們所試圖控制的魔法之火吞噬。他們對於魔法無節制的使用召來了燃燒軍團。惡魔摧毀了大部分的暗夜精靈文明。雖然沒有資料表明燃燒軍團也攻擊了巨魔文明，但是幾乎整個大陸都陷入了戰爭。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2201 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2201,'zhTW','在這場恐怖的戰爭（上古戰爭）的最後，永恆之井爆炸了。爆炸產生的震盪波撕裂了卡利姆多大陸。大陸的中心沉入海底，只留下一些破碎零落的陸地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2202 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2202,'zhTW','阿曼尼帝國和古拉巴什帝國的殘餘勢力分別駐留於現在的奎爾薩拉斯和荊棘谷。阿茲亞其帝國的艾卓-尼魯布和安其拉城也倖存了下來，它們位於現在的諾森德和塔納利斯。$B$B兩個巨魔文明在原始世界毀滅之後都衰落了。不屈不撓的巨魔們重建了他們被蹂躪的城市，並著手回覆昔日的輝煌。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2203 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2203,'zhTW','大爆炸之後的好幾個世紀，巨魔一族都在極端艱難的環境中度過。饑荒和恐怖對於破碎的帝國來說只是家常便飯，孤注一擲的古拉巴什巨魔尋求遠古神秘力量的幫助。雖然兩個巨魔帝國都信奉著共同的遠古諸神，但是古拉巴什卻被最黑暗的神靈支配了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2204 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2204,'zhTW','靈魂掠奪者哈卡——這個卑鄙嗜血的神靈——在聽到巨魔的召喚後決定幫助他們。哈卡將他的血賜予古拉巴什，並幫助他們將領土擴張到荊棘谷的大部分地區，以及南海的一些群島。雖然他給古拉巴什帝國帶來了巨大的力量，但是哈卡希望得到的回報也越來越多。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2205 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2205,'zhTW','這個殘忍的神要求每天都用靈魂為他祭祀。他夢想透過這樣來到真實世界，這樣他就可以吸食所有生靈的血。古拉巴什慢慢地認識到了他們曾殷勤供奉的這個神的真正面目，並奮起與之抗爭。最強大的部族紛紛起義，抵抗哈卡和他忠實的牧師——阿塔萊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2206 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2206,'zhTW','在哈卡的追隨者與古拉巴什部族間發生的恐怖戰爭只在呢喃細語中流傳。剛剛開始振興的帝國被憤怒的邪神和他叛亂的子民所釋放的魔法粉碎。正當這場戰鬥即將以哈卡獲勝而結束的時候，巨魔們摧毀了哈卡的化身，將其從物質世界流放。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2207 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2207,'zhTW','甚至連那些阿塔萊祭司都被趕離首都祖爾格拉布，被迫在一處連地圖上都未標明的北部沼澤地區中苟且偷生。在這些陰暗的沼澤中，他們為哈卡神建造了一座大神廟——阿塔哈卡神廟，並繼續在那裡為他們的主人工作著……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2208 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2208,'zhTW','內戰後倖存的古拉巴什部族繼續留在他們那已成為一片廢墟的家園裡，但是卻走上了不同的路，劈顱部族、血頂部族和暗矛部族開始在荊棘谷爭搶叢林領地。雖然他們最終達成了脆弱的和平，但仍有預言說哈卡將會在未來的某日在這個世界上重生，到那時，他將毀滅一切。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2210 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2210,'zhTW','這裡長眠著格羅姆·地獄咆哮，戰歌氏族的酋長$B$B我們人民被詛咒的開始和結束都與格羅姆息息相關。$B他的名字在我們的古語中意味著“巨人之心”，他名副其實。$B他如鐵塔一般矗立在惡魔瑪諾洛斯面前——以他的鮮血為我們贏得了自由。$B$B向你致意，我的兄長。願戰歌永不消逝。$B$B——索爾，部落的酋長',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2211 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2211,'zhTW','這裡長眠著格羅姆·地獄咆哮，戰歌氏族的酋長$B$B我們人民被詛咒的開始和結束都與格羅姆息息相關。$B他的名字在我們的古語中意味著“巨人之心”，他名副其實。$B他如鐵塔一般矗立在惡魔瑪諾洛斯面前——以他的鮮血為我們贏得了自由。$B$B向你致意，我的兄長。願戰歌永不消逝。$B$B——索爾，部落的酋長',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2217 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2217,'zhTW','紀念我永遠深愛著的傑茜·莫拉雷斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2232 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2232,'zhTW','紀念我永遠深愛著的傑茜·莫拉雷斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2233 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2233,'zhTW','答：$B$B我們必須不惜一切代價地保持計劃的秘密性！如果其他的牛頭人部族知道我們之間的聯絡的話，那後果將會是災難性的。$B$B——E',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2234 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2234,'zhTW','答：$B$B只要團結起來，我們的力量會比所有牛頭人部族聯合起來都要強大！但是，我們需要你的完全服從。記住這一點：只有當我們的計劃大功告成的時候，你和你的同胞才會得到獎勵！$B$B——R',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2250 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2250,'zhTW','答：$B$B我們從洛丹倫派來的專員不久之後就會與你會面。一旦我們找到了進行會談的合適地點，就會及時通知你。$B$B——G',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2251 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2251,'zhTW','攻擊者……來自各個方向。$B$B木喉部族是邪惡的。敵人。$B$B必須保護冬泉部族。必須把入侵者趕出我們的土地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2270 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2270,'zhTW','攻擊者……來自各個方向。$B$B木喉部族是邪惡的。敵人。$B$B必須保護冬泉部族。必須把入侵者趕出我們的土地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2271 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2271,'zhTW','納塔卡，千針石林一切安好。半人馬的麻煩還沒有解決……它們有時候會發起攻擊，但是目前還沒有形成真正的威脅。然而，似乎有訊息說半人馬氏族正在集結。$B$B我們總是會認真考慮那些團結在一起的殘忍氏族，比如半人馬……我嘗試著不去過多考慮這些問題，正如你所知的那樣……沒有什麼東西可以消解它們心中那純粹的憎恨……即使對於它們的同胞，那種憎恨也是非常強烈的。$B$B——峭壁衛兵圖林·長角',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2290 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2290,'zhTW','納塔卡，千針石林一切安好。半人馬的麻煩還沒有解決……它們有時候會發起攻擊，但是目前還沒有形成真正的威脅。然而，似乎有訊息說半人馬氏族正在集結。$B$B我們總是會認真考慮那些團結在一起的殘忍氏族，比如半人馬……我嘗試著不去過多考慮這些問題，正如你所知的那樣……沒有什麼東西可以消解它們心中那純粹的憎恨……即使對於它們的同胞，那種憎恨也是非常強烈的。$B$B——峭壁衛兵圖林·長角',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2291 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2291,'zhTW','大主教阿隆索斯·法奧$B$B光明大教堂的慈善資助者之一。$B$B雖然阿隆索斯是在洛丹倫的斯坦索姆開始擔任神職，但他一直是暴風城人民的偉大的朋友。在第二次獸人戰爭結束之後的黑暗日子中，他幫助重組了北郡兄弟會，並籌集了大量資金以供重建暴風城。$B$B這座大教堂不僅是聖光信仰的象徵，也是對他高貴精神和慷慨的紀念。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2292 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2292,'zhTW','烏瑞恩家族的萊恩國王$B$B暴風城的國王$B$B艾澤拉斯的守衛者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2293 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2293,'zhTW','聯盟艦隊指揮官$B$B暴風城的朋友',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2294 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2294,'zhTW','瑪拉·弗塔根$B$B暴風城的高階牧師，庇護了第一次大戰後逃往洛丹倫的難民。$B$B她為我們孕育了光明的未來。願她在聖光中安息。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2295 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2295,'zhTW','在記憶之年代前，溫柔的大地之母撥出金色的黎明之霧。當琥珀色的雲朵沉降之後，大地上到處都是長滿燕麥和大麥的田地。這是她工作的基礎 ─ 孕育著生命和希望的搖籃。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2296 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2296,'zhTW','大地之母的眼睛，注視著她用呼吸創造的世界。她的右眼，安舍（太陽），給予這片土地溫暖和光明。她的左眼，姆莎（月亮），給予那些躁動不安的生物以和平與睡眠。這就是雙眼的力量，每隔半天，大地之母就會閉起一隻眼睛。就這樣，她為這個初生的世界不斷進行著日夜的更替。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2297 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2297,'zhTW','當大地之母的右眼掃過金色的黎明時，她輕柔的手就開始在肥沃的原野上拂動。她的手臂拂過的地方就有高貴的人從土地中出現。舒哈魯（牛頭人）為此向他們摯愛的母親表示感謝。在充滿黎明之光的廣袤平原上，大地之母的孩子為她的優雅而祈禱，併發誓永遠稱頌她的名字，直到世界墜入永恆黑暗的那一天。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2298 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2298,'zhTW','隨著大地的孩在黎明平原上行走，他們聽到了來自大地中心的黑暗低語。它向那些孩子灌輸征伐的思想和欺騙別人的方法。許多舒哈魯因此墮入黑暗，並開始變得邪惡。他們拋棄了自己的兄弟，無知地穿行在原野上。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2299 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2299,'zhTW','大地之母的心，因為孩子們的墮落而變得沉重，她已經無法再眼睜睜地看著他們變得墮落。在悲傷之中，她摘下了自己的雙眼，將它們放在星空中任其飛翔，安希和姆莎為了撫平彼此的悲傷，只能橫穿天空而互相追逐。隨著時光的流逝，這兩個雙胞胎永遠互相追逐著。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2300 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2300,'zhTW','雖然已經無法視物，但大地之母不會遠離心靈的世界。她用她的耳朵聆聽風聲，聆聽一切穿越黎明平原的東西。她偉大的心還是和她的孩子在一起，她愛的智慧永遠不會離棄他們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2301 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2301,'zhTW','大地之母不僅把勇敢的心賦予她的孩子們，她還將熱愛狩獵的精神賜予他們。第一黎明紀元中誕生的生物是野蠻而又狂暴的，它們躲避著大地之母，在陰暗的野外尋找自己的棲身之地。舒哈魯狩獵這些野獸，並以大地之母的祝福來馴化它們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2302 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2302,'zhTW','然而，一個強大的靈魂卻一直在躲避著他們。英勇的雄鹿阿帕羅（被暗夜精靈稱為瑪洛恩）長著白色的皮毛，它的鹿角劃破天穹，它強有力的蹄子踏破世界的深淵。舒哈魯獵捕阿帕羅，直到黎明世界的角落，並撒網捕捉那頭驕傲的雄鹿。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2303 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2303,'zhTW','為了逃脫，偉大的雄鹿躍向空中。他的逃脫本應非常順利，但是他的鹿角卻掛住了天上的星星。雖然他不斷蹬踢掙扎，但是阿帕羅卻無法從天堂中掙脫。此時正在追逐安希的姆莎發現了他，她看到萬能的雄鹿在奮力掙扎，並對他一見鍾情。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2304 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2304,'zhTW','聰明的月亮與偉大的雄鹿做了筆交易——如果他愛她，並能夠為她結束孤獨的生活，她就可以解救他。$B$B姆沙愛著阿帕羅，併為他生下了一個孩子。這個孩子作為半神降生於夜晚的森林中。他被起名為塞納留斯，他漫步於正在覺醒的世界和天堂王國之間，漫步在佈滿星辰的大道上。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2305 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2305,'zhTW','隨著時間的流逝，塞納留斯長成了和他父親一樣偉岸的生物。他成為了星辰和森林的兄弟，這個偉大的獵手徘徊在世界的遠端，吟唱著黎明的和諧歌聲。所有的生物都在他的優雅和美麗面前彎腰——沒有什麼能比月亮和白色雄鹿的兒子更加完美。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2306 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2306,'zhTW','漸漸的，塞納留斯成了舒哈魯的朋友，與他們討論如何改造世界。大地的孩子們把他當作自己的兄弟，並且發誓要幫助他看護生命的田野以及大地之母所熱愛的一切。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2307 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2307,'zhTW','塞納留斯告訴大地的孩子如何與樹林進行溝通。舒哈魯成了德魯伊，他們使用各種魔法來呵護這片土地的健康。塞納留斯和數代舒哈魯一起狩獵，共同保護這片土地免受潛伏在地下的邪惡力量的傷害。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2308 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2308,'zhTW','隨著黎明薄霧的消散以及歲月的流逝，半神塞納留斯自行進入了世界的田野中。舒哈魯（牛頭人）對於他的離去感到無比悲傷，並忘卻了他教給他們的德魯伊之道。一代又一代，他們漸漸地忘卻瞭如何與樹木以及這塊土地上的生靈進行交流。地底深處的黑暗低語再次出現在他們的耳邊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2309 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2309,'zhTW','雖然大地的孩子對於邪惡的密語不再聽從，但是一個邪惡的詛咒降落在他們遊蕩的部族頭上。在黑色土地的西邊有一群兇惡的生物 ─ 半人馬。殘忍而野蠻的半人馬如瘟疫一般蜂擁而至，雖然舒哈魯在大地之母的祝福下勇敢地戰鬥，但是他們無法打敗半人馬。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2310 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2310,'zhTW','舒哈魯被迫離開自己祖居的地方，從此之後不得不像遊牧民族一樣浪跡在無邊的平原上。這種情況一直在繼續下去——破碎的舒哈魯族部族希望他們能在大地之母的指引下找到一處新的家園。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2311 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2311,'zhTW','這塊完整的翼手龍骨骼是從遙遠的安戈洛環形山運回來的。根據骨架的結構判斷，其特殊的基因還從未改變過。這塊骨架在該地區的特殊土壤中可以儲存近乎無限長的時間。',0);
