INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2371,'zhTW','達隆郡的歷史$B$B達隆郡是一座位於洛丹倫南部山脈中的村莊，這個名字來源於其西面的達隆米爾湖。鎮中的居民樸實而又勤勞，達隆郡在洛丹倫歷史上一直都是默默無聞的，直到第二次惡魔戰爭的開始。$B$B在戰鬥期間，無數英雄從這裡誕生，無數英雄在這裡隕落。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2372 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2372,'zhTW','達隆郡的戰鬥$B$B達隆郡的戰鬥發生在第二次惡魔戰爭的中期。那時，天災軍團的力量在洛丹倫的土地上橫行肆虐，達隆郡與聯盟主力部隊的聯絡被切斷，但是鎮中有一支駐軍，包括一隊白銀之手的聖騎士，以及由約瑟夫·雷德帕斯所領導的當地民兵。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2373 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2373,'zhTW','天災軍團的第一次攻擊僅僅是試探性的。小隊的骷髏和殭屍在小鎮周邊徘徊，並被很輕易地擊敗了。$B$B但是防禦部隊的堅韌並沒有讓亡靈退卻，它們繼續瘋狂地進行攻擊，一波接一波的亡靈部隊接踵而來，與達隆郡的防禦者激烈交戰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2374 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2374,'zhTW','防守部隊的力量被不斷削弱，但是白銀之手騎士團不斷支援他們。騎士團的領袖達維·克羅弗德是達隆郡的當地人，他在得知小鎮即將遭到攻擊時帶領他的追隨者來到了鎮中，與衛隊合力抵抗霍古斯的部隊。$B$B當霍古斯自己也加入戰鬥之後，他與達維正面交鋒了。他們的戰鬥持續了很久，最終達維獲勝，但是他受了重傷，在擊敗食屍鬼之王后不久死去了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2375 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2375,'zhTW','戰鬥繼續著，雷德帕斯隊長率領民兵英勇奮戰。如果不是隊長被死亡騎士馬杜克的黑暗魔法控制的話，這場戰鬥有可能獲勝的。$B$B在戰鬥中，馬杜克騎馬來到雷德帕斯面前，他使用黑暗魔法撕碎了雷德帕斯的意志，將他的靈魂扭曲成了一個邪惡的陰影。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2376 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2376,'zhTW','墮落的雷德帕斯隊長將他的邪惡力量傳染給達隆郡的守軍，那些被感染計程車兵立刻背叛了他們的同胞，並開始屠殺他們。最後他們轉向達隆郡裡，屠殺了那些躲在家中的民眾。$B$B剩餘的亡靈部隊和墮落的雷德帕斯隊長離開了已成廢墟的達隆郡，投入了洛丹倫的戰場。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2377 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2377,'zhTW','達隆郡的歷史$B$B達隆郡是一座位於洛丹倫南部山脈中的村莊，這個名字來源於其西面的達隆米爾湖。鎮中的居民樸實而又勤勞，達隆郡在洛丹倫歷史上一直都是默默無聞的，直到第二次惡魔戰爭的開始。$B$B在戰鬥期間，無數英雄從這裡誕生，無數英雄在這裡隕落。',0);
