INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2380,'zhTW','防守部隊的力量被不斷削弱，但是白銀之手騎士團不斷支援他們。騎士團的領袖達維·克羅弗德是達隆郡的當地人，他在得知小鎮即將遭到攻擊時帶領他的追隨者來到了鎮中，與衛隊合力抵抗霍古斯的部隊。$B$B當霍古斯自己也加入戰鬥之後，他與達維正面交鋒了。他們的戰鬥持續了很久，最終達維獲勝，但是他受了重傷，在擊敗食屍鬼之王后不久死去了。',0);
