INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2381,'zhTW','戰鬥繼續著，雷德帕斯隊長率領民兵英勇奮戰。如果不是隊長被死亡騎士馬杜克的黑暗魔法控制的話，這場戰鬥有可能獲勝的。$B$B在戰鬥中，馬杜克騎馬來到雷德帕斯面前，他使用黑暗魔法撕碎了雷德帕斯的意志，將他的靈魂扭曲成了一個邪惡的陰影。',0);
