INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2382,'zhTW','墮落的雷德帕斯隊長將他的邪惡力量傳染給達隆郡的守軍，那些被感染計程車兵立刻背叛了他們的同胞，並開始屠殺他們。最後他們轉向達隆郡裡，屠殺了那些躲在家中的民眾。$B$B剩餘的亡靈部隊和墮落的雷德帕斯隊長離開了已成廢墟的達隆郡，投入了洛丹倫的戰場。',0);
