INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2413,'zhTW','雪，刺眼……$B$B必須保護部族。讓他們變得強壯。強壯。$B$B不知道……',0);
