INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2414,'zhTW','火酒。$B$B更多。製作更多火酒。$B$B火酒讓冬泉部族更加強壯。打敗敵人。$B$B冬泉部族沒有盟友。冬泉部族非常強壯。擁有無窮的力量。',0);
