INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2431,'zhTW','記錄日期：未知$B$B姓名：納薩諾斯·瑪瑞斯，人類遊俠，洛丹倫的貴族。$B$B記錄：$B$B凱爾薩斯·逐日者不同意納薩諾斯·瑪瑞斯進入組織。另外，納薩諾斯是我遇到過的最具天賦的遊俠，雖然他是個人類，但是我非常樂意訓練他。$B$B（未完）',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2432 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2432,'zhTW','我這些年來一直在從事這個行業，現在我第一次感覺如此自豪。對於刺客、間諜和密探的需求從來都沒有如此強烈過。也許你認為戰爭期間會對這方面的人員有更大的需要，但事實上，戰爭並不很需要我們這樣的人——只有在和平年代才會是我們大展身手的舞臺。$B$B我聽說你來到了這一區域，如果你有時間的話，就到教堂後的馬廄旁邊來找我。$B$B——喬裡克·克里丹，潛行者訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2433 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2433,'zhTW','我打賭你原以為這是一封由你的國王或者別的什麼人書寫的信件。好吧，我承認我對偽造信件略知一二，我只是希望你能收到這封信而已。現在你對我已經有所認識了，對嗎？$B$B我在安威瑪爾裡面的壁爐旁邊等著你。等你準備好了，就來找我說話吧。我只是想跟你互相認識一下。$B$B——索姆·哈格林，潛行者訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2434 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2434,'zhTW','你好，$N。寫這封信的時候，我陷入了沉思。$B$B我們中的許多人都認為薩滿是我們的精神領袖，就好像我們的酋長一樣。其他人會認為劍和斧才是更加高貴的追求，但是不要忘了戰鬥——甚至是戰爭——是要靠那些有一技之長的人獲勝的。這就是我想要和你說的，$N。到試煉谷裡的大獸穴來找我吧。$B$B——魯瓦格，潛行者訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2435 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2435,'zhTW','我的$g兄弟:姐妹，希望這塊符石能夠安全地送到你手中。我費盡心機讓這件事情看起來不是那麼明顯，你可能甚至都沒有發現自己的揹包中有這麼一封信。看來我的計劃不錯，不是嗎？$B$B我想要你知道，我在寒脊山谷的安威瑪爾等你。我很清楚大家團結在一起的重要性，特別在眼下的緊張時期，我們更應該在一起。當你有時間的時候就來找我吧。$B$B——索姆·哈格林，潛行者訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2436 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2436,'zhTW','記住我的話，$N。現在是一個到處都充滿藉口和欺騙的時代……即使我們偉大的幽暗城也是一樣。每個忠誠於希爾瓦娜斯的人都在為了開創一個新的時代而努力，一個由被遺忘者控制的時代。雖然我們不具有魔法技能，也不會拿起武器保衛邊疆，但是這世上依然有許多事情只有我們才能做。$B$B到喪鐘鎮的旅店裡來找我吧，我會和你討論更多問題的。$B$B——大衛·提亞斯，盜賊訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2437 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2437,'zhTW','你好，我的朋友。希望這個符記可以順利地送到你手裡。上級要求我為你服務，我眼下也在幽影谷裡——就在泰達希爾的樹頂，如果你需要接受訓練，就來找我吧。$B$B在這個危險的時期，我希望我們之間保持秘密的聯絡，不然我們還能如何保護泰達希爾和我們的行規？$B$B你有空的時候就來找我吧。$B$B——弗拉胡恩·影語者，潛行者訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2438 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2438,'zhTW','你好，我的$g兄弟:姐妹。碎手氏族向你致意，並希望你在山谷中找到一個合適的接頭人。現在是對你進行考驗的時候了，所以，別以為沒有人監視你。$B$B我的職責是代表碎手評估你的技能，然後告訴他們你是否已經準備接受更大的挑戰了。$B$B當你準備好了之後，就到大獸穴最深處來找我，我會在那裡等你的。$B$B——魯瓦格，潛行者訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2439 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2439,'zhTW','告訴我，$c，你有沒有聽過獸人的咆哮？也許你曾參與在家鄉抵禦過豺狼人的襲擊，差點就被那些傢伙撕破了喉嚨？啊，這些聽上去都很可怕，不是嗎？$B$B好吧，如果你想要保護自己所熱愛的東西，那你就需要我的幫助，到北郡的修道院裡來找我吧。我的知識並非免費傳授給你的，不過如果你擁有足夠的閱歷，那我就能教給你很多東西，幫助你與威脅著暴風城的邪惡勢力作戰。$B$B——萊尼·拜舍爾，戰士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2440 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2440,'zhTW','注意：$B你必須立即向斯蘭·庫爾曼報到。他在A3區中，也就是當地居��所說的安威瑪爾那裡。在與庫爾曼接頭之後，你要著手準備參加即將來臨的戰鬥——奪回我們的家園諾莫瑞根！$B$B我們所有的努力都是為了這個最終的目的。在完成此任務之後，新的任務會很快下達給你。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2441 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2441,'zhTW','許多部族認為使用魔法或者與我們的先祖對話的能力都是不可多得的天賦，但是你應該知道，$c，你也同樣具有其他人不具備的天賦。有些人沒有足夠的力量來揮舞強大的武器，有些人沒有躲避刺客致命一擊的能力，或者無法承受一個法師所帶來的傷害，但是你可以。你非常強壯，我會幫助你變得更加強壯。到納拉其營地來找我吧。$B$B——哈魯特·雷角，戰士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2442 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2442,'zhTW','以麥格尼·銅鬚的名義，我們有很多東西要談，但是時間有些緊迫，$N。儘快到寒脊山腳下的的安威瑪爾來找我，我們要馬上開始。$B$B我可以告訴你一大堆事情，但是那些對我們都沒有用……特別是對現在的我們來說。我們當前需要關注的東西很簡單：如何抓緊一把斧子，我們護甲的重量，以及我們在戰鬥時所流的汗滴的味道。我們就從這些開始吧。$B$B——斯蘭·庫爾曼，戰士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2443 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2443,'zhTW','我們的許多族人希望靠著秘法和神聖系的法術變得更加強大，但是我們知道有更好的方法，不是嗎，$c？強大的武器是我們的聖印，堅固的盾牌是我們的法術書，緻密的煉甲是我們的智慧。$B$B雖然我們已經變成了亡靈，但我們仍然很強大，而且我們會變得更加強大。$B$B到喪鐘鎮的旅店裡來找我，我會和你談談更多與這有關的事情。$B$B——丹納爾·斯特恩，戰士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2444 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2444,'zhTW','我希望我的符印可以順利地送到你的手上，$c。我之所以寫信給你，是因為我們的人民需要那些擅長使用刀劍、月刃以及其它武器的戰士。自從我們重新和艾澤拉斯的其他種族展開接觸之後，我們身邊發生了許多事情，我們也更加需要強大的衛士。$B$B這就是我寫信給你的原因。我會告訴你更多相關的資訊，但是我希望能與你進行面對面的交流。到泰達希爾的底層來找我吧。$B$B——奧莉希亞，戰士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2445 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2445,'zhTW','魔法四準則：$B$B$B魔法是強大的。$B$B$B魔法使人墮落。$B$B魔法讓人欲罷不能。$B$B魔法會將那些扭曲虛空中的生物引至掌握魔法的人身邊。$B$B這些規則總是成立的。如果你選擇成為一名法師的話，這些規則會永遠跟隨著你。$B$B如果你愚蠢到忽視這些警告，那麼就到北郡修道院的圖書館裡來找我吧，我會在樓上等你的。$B$B——凱爾登·佈雷門，法師訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2446 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2446,'zhTW','致投身於魔法藝術的新學生：$B你將跟隨侏儒法師瑪瑞克·斯托納爾進行學習，直到你能幫助自己的同胞解決各種困難。希望你堅定而認真地準備接受嚴厲的學習過程，並慢慢與當地的居民形成良好的夥伴關係。$B$B有關你的職責與技能的更詳細情況，請直接詢問瑪瑞克·斯托納爾。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2447 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2447,'zhTW','據說墮落和邪惡隨著魔法進行傳播，但是這些與我們所遭受到痛苦比起來根本不算什麼。我們不再是軟弱無力的犧牲者了，$N。我們能夠控制自己的命運，希爾瓦娜斯已經為我們鋪好了道路——她向我們證明，我們的意志是屬於自己的。$B$B到教堂裡來找我，我會指引你進一步前進……如果你願意的話。$B$B——伊莎貝拉，法師訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2448 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2448,'zhTW','孩子，你終於覺醒。在足夠強大之後，你就可以掌握魔法的秘密了。$B$B準備好了之後就去找邁安吧，她會教你使用各種魔法，摧毀那些膽敢反對你的人。$B$B邁安在試煉谷的大獸穴中。去那裡找到她，然後你就能變得更加強大。向其他法師展示魔法是如何按照你的意志行事吧。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2449 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2449,'zhTW','人們——尤其是那些聖光的追隨者們——經常會恐嚇尋求真正力量的人，反覆強調魔法的邪惡和可怕，但並不是所有本不屬於這個世界的東西都是邪惡的，並不是所有的生物都想要主宰或聽命於他人。如果你真的足夠強大的話，他們會變成你的追隨者。$B$B我希望能和你討論更多的事情，到修道院右邊的墓地裡找我吧。$B$B——杜希拉·拉薩雷，術士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2450 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2450,'zhTW','注意：$B$B保持安靜！不要四處張望！也許有人正在盯著你。$B$B我的名字叫做阿拉瑪爾·格里姆，$N。我可以訓練那些追尋真正的知識和力量的人。上級授意我與你進行秘密的聯絡，然後向你傳授真正的魔法。$B$B如果可以的話，就到安威瑪爾的後方來找我。$B$B——阿拉瑪爾·格里姆，術士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2451 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2451,'zhTW','我用我創造出的最強大的墨水來撰寫這封信，$N。它會詛咒除你之外任何膽敢閱讀這封信的人。我就是如此的強大。我可以從扭曲虛空中召喚惡魔，我在敵人睡眠時就對他們施放了致命的詛咒，也在戰場上讓他們灰飛煙滅。現在你看到了我強大的力量，我的兄弟對此感到很滿意。$B$B到大獸穴裡面來找我吧。我會和你交流更重要的事情。$B$B——納托克，術士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2452 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2452,'zhTW','你赫然發現我們正處於困境之中，是不是，$N？被愚蠢的王子所汙染，被我們摯愛的人所拋棄。我們應該感謝美麗的希爾瓦娜斯，但對於我們來說這又如何呢？換一個主人對於我們來說沒有什麼區別，我們依然是奴隸，我就是這樣認為的。$B$B但如果我們自己是主人的話，情況又會是怎樣的呢？沒錯，你知道我說的是什麼。$B$B我們甚至與其他的被遺忘者之間還有隔閡，$N。這就是我們要繼續談談的原因。到喪鐘鎮的教堂裡來找我吧。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2453 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2453,'zhTW','強大的戰士守護著我們的家園，睿智的薩滿指引我們的靈魂，並向我們展示祖先的豐功偉績，德魯伊向我們傳達大地母親的意願。$B$B但你是我們獵人中的一員，我們瞭解世界上的種種力量，並使其為我們所用。你會找到你存在的價值以及我們人民的意願——我們部族中的一些成員需要你的指引和保護，我的職責就是讓你做好迎接這些挑戰的準備。到納拉其營地來找我吧。$B$B——蘭卡·遠箭，獵人訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2454 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2454,'zhTW','孩子，你長大了。基沙知道你正在尋求獵人之道，她已經準備教你了……如果你自己準備好了的話。$B$B到試煉谷來找我。基沙會訓練你，向你展示獵人是多麼的強大。$B$B——基沙，獵人訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2455 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2455,'zhTW','馴服野獸，強大的射擊技巧，縝密的追蹤技能——你此生還想要達成什麼樣的偉績？以上我所說的這些都需要相當的智力和耐心才能成就。$B$B獵人之道並不簡單，這一點是肯定的。即便只是要達到我們最低的要求，你也需要接受大量的訓練。這就是我找你的原因。$B$B到寒脊山腳下的安威瑪爾來找我吧，我會等著你的。$B$B——索加斯·格瑞姆森，獵人訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2456 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2456,'zhTW','願艾露恩與你同在，$N。我很高興能直接參與培養下一代獵人的工作。$B$B根據我所瞭解到的情況，你就在泰達希爾附近。如果你有時間的話，我會在泰達希爾樹上等你的。$B$B我們的長者要求我好好訓練新的獵人，使他們有能力透過即將到來的試煉。你是我的新學生之一，希望你能夠來找我。祝你一路順風。$B$B——阿亞娜·遠途，獵人訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2457 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2457,'zhTW','很高興得知又有一個基沙的$g兄弟:姐妹到試煉谷來檢驗$g他:她的能力，基沙很高興！$B$B我無須再告訴你獵人有多麼強壯和靈活——你已經知道這一點了。基沙要告訴你的是，你還需要變得更加強壯和靈活。$B$B你可以在試煉谷裡找到基沙，她會教你很多東西。她會教你如何馴服最強大的野獸，以及更多其他的東西。$B$B——基沙，獵人訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2458 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2458,'zhTW','昨天晚上，大地的精靈進入了我的夢鄉，他們告訴我你要到來的訊息，而我的任務就是幫助你。我們有很多要討論的事情——討論自然，大地之母，甚至還有暗夜精靈。但是在你到來之前，我們不會討論這些東西，我要盡我所能保證你已經為將來的試煉做好了準備。$B$B願智慧指引著你，我會在這裡等著你。$B$B——加爾特·迷霧行者，德魯伊訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2459 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2459,'zhTW','當我聽說你已經準備好了的時候，就馬上寄出了這個符記。所有塞納留斯的德魯伊都會因為我們的隊伍越來越壯大而感到高興的，森林之魂的力量似乎也在隨之變得更加強大。只要有足夠的時間和耐心，我們的力量就應該可以恢復到原來的程度。如果你準備好了，就到泰達希爾樹頂來找我。在你停留在幽暗谷的這段時間裡，我會不斷地指引你。$B$B——瑪丹特·硬木，德魯伊訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2460 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2460,'zhTW','你好，年輕的$c。微風已經把你要到這裡來的訊息告訴我了，大地也在讚揚你的強壯。現在，我們先祖的靈魂告訴我你已經到了。我們同胞們總是需要睿智而偉大的領袖，他們經常因此而尋求我們薩滿的幫助。如果你願意的話，我會向你傳授更多的知識。$B$B到紅雲台地的納拉其營地來找我吧——我們可以進一步談談。$B$B——米拉·晨行者，薩滿訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2461 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2461,'zhTW','你好，我的$g兄弟:姐妹。元素們告訴我你正在向這裡旅行，它們要我向你展示薩滿之道。我們先祖的靈魂在地下看著我們，並對你加入薩滿的行列感到非常欣慰。$B$B當你準備好了之後，就到大獸穴的入口處來找我吧。我在這裡負責訓練薩滿。希望你一路順風。$B$B——史克里克，薩滿訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2462 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2462,'zhTW','你好，我的$g兄弟:姐妹。自然的精靈告訴我，你已經做好協助我們盟友的準備了。你和元素有很深的聯絡，當你開始我的課程之後，你就變得越來越強大了。$B$B現在我要要派你去見試煉谷的薩滿訓練師，獸人史克里克。她已經知道你會去找她接受訓練了。讓我們的祖先為你而感到光榮吧。在我們再次見面之前，願你一路順風。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2463 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2463,'zhTW','我希望你可以順利地收到這封信，$c。我很榮幸可以和你對話，因為很少有人能擁有如此堅定的信念，也很少有人能理解我們是保護艾澤拉斯大陸的精英力量這一事實。$B$B記住，最重要的一點是，你的職責就是與那些想要傷害我們這個世界的邪惡勢力進行戰鬥。$B$B我已經被授權在這段時間內對你進行訓練了。當你準備好了之後就到北郡修道院裡來找我吧。$B$B——薩繆爾修士，聖騎士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2464 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2464,'zhTW','有些人害怕我們，就好像是害怕龍一般；有些人羨慕我們，甚至超過了他們對技藝最精湛的鐵匠的羨慕；有些人讚美我們在戰鬥中爆發出的力量，其他人為我們堅定的信仰而讚歎；還有些人羨慕我們能把他們都喝到爛醉！但是除此之外，$c，你還應該知道自己是保護艾澤拉斯的中堅力量。聖光給予我們力量，而我們則捍衛它的榮光。$B$B如果你想要向我詢問更多關於這片土地的事情，那我會知無不言的。到寒脊山腳下的安威瑪爾來找我吧。$B$B——布羅莫斯·格魯諾爾，聖騎士訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2465 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2465,'zhTW','你和世界的聯絡，世界和你的聯絡，這些對一個成功的牧師來說都是非常重要的。智慧與憐憫將會讓你幫助那些真正需要幫助的弱者，過於急躁和慌張的決定都會使其他人無法變得更加強壯，甚至會傷害他們。$B$B當你開始懂得以上這些話的意思時，你就需要學習新的技能和法術了。這時，就到北郡修道院的圖書館裡來找我吧。$B$B——安妮塔，牧師訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2466 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2466,'zhTW','有著聖光的支援和每天都有的新發現，現在你應該為自己是鐵爐堡的$g兒子：女兒而感到自豪了。探險者協會每天都在為那古老的問題找尋失落的答案，現在滿懷信仰的你也加入了我們的行列，與石顎怪以及其它一切膽敢威脅我們領土的邪惡力量進行戰鬥。$B$B等你有空了就來找我吧，我在山腳下的安威瑪爾。$B$B——布蘭斯托克·卡德爾，牧師訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2467 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2467,'zhTW','為你的靈魂未被放逐到扭曲虛空中而感到慶幸吧，$N。為你能值得我花時間親自書寫這個卷軸感到由衷的慶幸吧。$B$B你所認識的人，以及你曾經關心過的人，都已經不再存在了！你必須學會如何以你現在的狀態“活”下去，我建議你首先學會這件事情。$B$B如果你準備迎接試煉的話，那就到喪鐘鎮的教堂裡來找我。$B$B——黑暗牧師杜斯滕，牧師訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2468 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2468,'zhTW','我希望我的符印可以順利地寄到你手上，$c。森林之魂告訴我你即將到來，所以我立即寄出了這封信。我希望可以與你分享我的經驗，併為你將要在泰達希爾接受的各種重要使命做好準備。$B$B過去的幾年中發生了許多事情，我們要做很多事情來幫助艾澤拉斯世界的其他種族。當你準備好了之後，就到泰達希爾來找我，我會在樹屋的第二層等著你。$B$B——珊達，牧師訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2469 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2469,'zhTW','看來你成長得挺順利，孩子。擺在你面前的考驗很多，當你準備好的時候，我願意和你分享我所有的經驗。你能以多快的速度變得多麼強大，這取決於你。只有當你準備好的時候，我才可以指導你。$B$B有些人進步速度很快，而其他的則慢得多。但是你不要擔心那麼多，當你見到我之後，我們可以進行更多的討論。$B$B——肯傑，牧師訓練師',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2471 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2471,'zhTW','數千年以來，我們一直把自己和外界隔絕開來。我將是我們當中第一個站出來承認我們過去曾犯過的錯誤的精靈。人類根本就不應該接觸到魔法的知識，我對此並不否認，但是我也不會因這個由我們的前輩犯下的過錯而責怪我們自己。奎爾多雷和世界上的其他種族是可以共存的。我們必須鍛鍊自己的耐心。$B$B（未完）',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2472 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2472,'zhTW','就是因為這些，我拒絕了凱爾關於納薩諾斯·瑪瑞斯的請求。他是個無價的盟友。記住我的話。$B$B希爾瓦娜斯·風行者$B銀月城遊俠部隊指揮官',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2490 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2490,'zhTW','瑞什：$B$B你的請假要求已經被批准了。我會派候補的牛頭人戰士去你執勤的哨所接班，這樣你就可以回家和親友團聚了。在一個星期的假期過後回來報到！$B$B——馬格蘭',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2491 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2491,'zhTW','瑞什：$B$B你的請假要求已經被批准了。我會派候補的牛頭人戰士去你執勤的哨所接班，這樣你就可以回家和親友團聚了。在一個星期的假期過後回來報到！$B$B——馬格蘭',0);
