INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2530,'zhTW','根據高階執行官哈德瑞克的命令，以下物品是維持瑟伯切爾庫存的必需品：$B$B12把長劍$B9把匕首$B8面圓盾$B15把斧頭$B1000支箭$B$B這些物品必須完全備齊，這是黑暗女王的直接命令，負責執行此命令者將受到她的關注，而任何違背這一命令的行為都將被認為是違背黑暗女王的意願。',0);
