INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2551,'zhTW','萊耶：$B$B我們受到了這位冒險者的幫助。現在我派$g他:她到希利蘇斯來幫助你。請好好利用$g他:她的能力解開那個地區的謎團。議會急切地等待著你的進度報告。$B$B願塞納留斯永遠守護著你……$B$B——拉比恩',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2570 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2570,'zhTW','萊耶：$B$B我們受到了這位冒險者的幫助。現在我派$g他:她到希利蘇斯來幫助你。請好好利用$g他:她的能力解開那個地區的謎團。議會急切地等待著你的進度報告。$B$B願塞納留斯永遠守護著你……$B$B——拉比恩',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2571 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2571,'zhTW','冬幕節慶典$B$B艾澤拉斯一年中的最後一個季節在許多文化中被認為是變化的一個季節。矮人和牛頭人都在這個白雪覆蓋大地的時候傳頌著一個古老的傳說故事，並歡慶著一個辭舊迎新的時刻。艾澤拉斯的各個種族對於這個傳說故事的理解各不相同，他們傳頌這個故事的方式也因為各個種族的差異而顯得不同。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2572 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2572,'zhTW','冬天爺爺的傳奇$B$B“冬幕節”這個詞在許多文化中都來源於一個超自然的事物：冬天爺爺。他會在歲末出現在世界各地，隨之而來的是凜冽的寒風。他的甦醒意味著大地將籠罩在白雪之中，所以也有人說是冬天爺爺用冬幕籠罩了大地。雖然艾澤拉斯大陸覆蓋在白雪之中，但是其孕育的是重生和新生命的開始。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2573 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2573,'zhTW','矮人$B$B矮人一直熱衷於尋求他們的起源的秘密，他們將在這個季節舉行慶祝來作為對冬天爺爺的讚美。他們是遠古時期艾澤拉斯大陸上的泰坦的一個化身。他們宣稱自己的血管中流淌著那些神秘的生物的血液，居住在白雪皚皚的丹莫洛的矮人理所當然地認為自己受到了冬天爺爺的祝福。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2574 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2574,'zhTW','牛頭人$B$B牛頭人以他們的薩滿教義和最近融入的德魯伊信仰來理解著冬天，理解著冬幕節的傳奇。他們最主要注重於傳奇的更新，然而，在他們看來別的種族只是對這個傳奇簡單的膜拜，而非與大自然萬物和諧共存。許多牛頭人選擇這個時間來表達自己能夠在莫高雷找到新的家園而心生感激。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2575 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2575,'zhTW','舉行盛宴$B$B關於每年這個時候舉行盛宴的概念是來自於這個傳說本身。冬天爺爺在這個季節會漫步在艾澤拉斯大陸，將冬天作為其甦醒的標誌，據說他會給與那些歡迎他的人獎勵。所以，各地的人們會在冬幕節舉行盛宴來分享他們所擁有的東西。一般來說，大家會花一整天的時間盡情歡樂，舉行盛宴來辭舊迎新。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2576 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2576,'zhTW','現代習俗$B$B其他文明開始意識到冬幕節是一個歡慶的節日，雖然一些傳統和傳說中的並不完全一致。通常，人們可不會顧及太多關於節日本身的來歷，他們所關心的只是在這個節日期間可以好好慶祝並交換禮物，這就是冬幕節現在的習俗。現在冬天爺爺的形象也廣泛用在商業用途，而不是表現為一個超自然的泰坦巨人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2590 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2590,'zhTW','在長矛谷中坐落著神聖的瑪拉頓神殿。如果不是因為我犯了太多的過錯，我是不會讓你這樣一個$r來幫助我的。$B$B在只有半人馬的靈魂和我們最聖潔的祭司才能穿越的大門後面有一位無名的預言者。他是所有部族中掌管靈魂事務的最高領袖，也是所有部族中最年長的智者。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2591 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2591,'zhTW','在長矛谷中坐落著神聖的瑪拉頓神殿。如果不是因為我犯了太多的過錯，我是不會讓你這樣一個$r來幫助我的。$B$B在只有半人馬的靈魂和我們最聖潔的祭司才能穿越的大門後面有一位無名的預言者。他是所有部族中掌管靈魂事務的最高領袖，也是所有部族中最年長的智者。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2592 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2592,'zhTW','那個預言者非常強大，他能和我們先祖的靈魂進行交流。但他是個徹頭徹尾的蠢貨！他不知道自己所擁有的真正力量。他帶著靈魂墜飾——那是他力量的源泉。$B$B我知道墜飾的力量有多麼強大，但是它並不完整。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2593 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2593,'zhTW','墜飾上面的五顆寶石都遺失了。如果能找回那些寶石，並把它們安到墜飾上，那麼它的力量將遠遠高於現在。我找到了那五塊寶石，但是需要你這樣強大的$c來拿回它們。殺了那個無名預言者無疑是極度罪惡的行為，但是我要讓所有半人馬從此打消對寶石的念頭。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2594 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2594,'zhTW','墜飾上面的五顆寶石都遺失了。如果能找回那些寶石，並把它們安到墜飾上，那麼它的力量將遠遠高於現在。我找到了那五塊寶石，但是需要你這樣強大的$c來拿回它們。殺了那個無名預言者無疑是極度罪惡的行為，但是我要讓所有半人馬從此打消對寶石的念頭。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2595 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2595,'zhTW','在瑪拉頓的洞穴中徘徊著我們最早的幾位可汗的靈魂。他們是我們的父親和母親的第一批孩子，也是我們的偉大的領袖——格爾克、考爾克、瑪格拉、瑪勞杜斯和溫格。他們每個人身上都帶有一塊遺失的寶石。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2596 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2596,'zhTW','使用靈魂墜飾的力量來強迫他們顯形，並從他們那裡取得寶石！在此之後，把寶石放入靈魂墜飾之中，然後把它交給我。當我有了聯合墜飾之後，我就有足夠的力量來對我們的部族進行改革了，那樣我們就能完成先祖的遺願了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2597 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2597,'zhTW','歡迎來到魔獸世界！年輕的戰士，不要害怕這個陌生而充滿神秘的地方，你會驚奇的發現許多潛伏在陰影中的危險，許多歹徒為了蠅頭小利而準備殺了你……因此提防身邊的危險，隨時做好戰鬥的準備，你才能好好地活著！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2598 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2598,'zhTW','歡迎來到魔獸世界！年輕計程車兵啊，你已經準備好了成為一名聖騎士了嗎？很好……記住要勇敢，擊敗邪惡捍衛正義！最重要的是，要相信上帝，並且你是他的助手……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2599 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2599,'zhTW','歡迎來到魔獸世界！你管自己叫做盜賊？別搞笑了，如果你想成為一名真正的盜賊，就讓我看看你有什麼能耐，現在就去搶劫這座村莊給我看看！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2600 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2600,'zhTW','歡迎來到魔獸世界！孩子，如果你崇拜上帝，你將被救贖……如果你崇拜惡魔，你將獲得力量，但卻被上帝拋棄……所以，一定要當心，我的孩子，一定要當心！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2601 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2601,'zhTW','歡迎來到魔獸世界！這個世界對我們薩滿來說太險惡了，但是我們仍然足夠強大來贏得這場戰鬥……我們先得采取些措施，殺死這些討厭的聯盟。現在讓我看看，我們薩滿到底有多厲害！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2602 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2602,'zhTW','歡迎來到魔獸世界！我們法師是最強大的魔法使用者，我們將冰霜與火焰的力量發揮到極致，我們能夠做任何想做的事！所以，來探索魔法的精髓吧！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2603 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2603,'zhTW','歡迎來到魔獸世界！術士是一個神秘的群體……我們有最強大的魔法，忘了那些法師們吹噓說他們的法術多麼厲害等等，記住，我們術士是從法師發展而來的，所以實際上我們是更強大的！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2604 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2604,'zhTW','歡迎來到魔獸世界！部落喚醒了你的力量，我的孩子……現在你已經成為一名掌握變形之道的德魯伊了。你集合了戰士的力量、法師的智慧、薩滿的精神……我們是特立獨行的！你必須幫助你的朋友們，因為我們德魯伊是支援力量的極致！',0);
