INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2637,'zhTW','……如果可以的話，躲在窗臺或橋墩底下。找一面堅固的牆也是安全的辦法。$B$B$B<更多模糊的文字。>$B$B在五到十五……之間，使用……治療。$B$B<更多模糊的文字。>$B$B在成功的襲擊之後，好好休息接受勝利。待確實過了十至十五秒後，前往城裡展示你的……讓人們觀看崇敬。$B$B$B<瞄了一眼其餘的文字概要後讓你頭疼不已。>',0);
