INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2654,'zhTW','<HTML><BODY><H1 align=\\"center\\">軍階概述</H1><BR/>$B<IMG src=\\"Interface\\PvPRankBadges\\PvPRankAlliance\\" align=\\"left\\"/><BR/>$B<P align=\\"right\\">以下是</P>$B<P align=\\"right\\">聯盟的</P>$B<P align=\\"right\\">軍階概述</P>$B<P align=\\"right\\">其中包括</P>$B<P align=\\"right\\">部落的</P>$B<P align=\\"right\\">種族資訊</P>$B<P align=\\"right\\">每一部分</P>$B<P align=\\"right\\">都包含兩個章節</P>$B<P align=\\"right\\">軍官和士兵的軍階，都是按照由高到低的順序排列的。聯盟萬歲！</P></BODY></HTML>',0);
