INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2659,'zhTW','當你凝視著眼珠時，腦海中便浮現出戰爭的場景。$B$B似乎這場可怕的衝突發生在洛丹倫的某處。$B$B在屍橫遍野的戰場上，隱約可見一名女性，獨自與浩如煙海的天災軍團作戰。她顯得那麼絕望無助。$B$B從她手中施放的光芒瞬間便砍殺數百名不死生物。',0);
