INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2660,'zhTW','一切似乎都是徒勞。很快女祭司周圍就堆滿了農夫的屍體……倒下的屍體又站起來了。',0);
