INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2661,'zhTW','聯盟與部落的軍階$B$B<IMG src=\\"InterfacePvPRankBadgesPvPRankHorde\\"/>align=\\"left\\"/>（獸人語）你好！在這本$B$B書中$B$B列出了$B$B<P align=\\"righ\\">部落和$B$B弱小的聯盟的$B$B軍階列表。$B$B首先$B$B是部落軍階，接下來是聯盟的，$B$B其中囊括了軍官和軍階列表。按等級的高低排列，等級最高的排在首位，等級低的列於下位。$B',0);
