INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2665,'zhTW','<HTML><BODY><H1 align=\\"center\\">聯盟軍官軍階</H1><BR/><P align=\\"center\\">第一部分</P><IMG src=\\"Interface\\PvPRankBadges\\PvPRank14\\" align=\\"left\\"/><BR/><P align=\\"right\\">大元帥</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank13\\" align=\\"left\\"/><BR/><P align=\\"right\\">元帥</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank12\\" align=\\"left\\"/><BR/><P align=\\"right\\">統帥</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank11\\" align=\\"left\\"/><BR/><P align=\\"right\\">司令</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank10\\" align=\\"left\\"/><BR/><P align=\\"right\\">少校</P><BR/><BR/></BODY></HTML>',0);
