INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2666,'zhTW','一切似乎都是徒勞。很快女祭司周圍就堆滿了農夫的屍體……倒下的屍體又站起來了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2671 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2671,'zhTW','迷人的西蒙妮：$B$B西蒙妮正在汙染安戈洛環形山。不要被她的偽裝所迷惑。小心翼翼地接近她，向她發起挑戰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2672 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2672,'zhTW','瘋狂的克林弗蘭：$B$B克林弗蘭在燃燒平原上游蕩。謹慎地接近他，迫使他現出原形。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2673 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2673,'zhTW','屠殺者索倫諾爾：$B$B屠殺者索倫諾爾就潛伏在希利蘇斯的廢土上。他偽裝得很巧妙，而且非常危險。接近他，令他現出真正的面目。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2674 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2674,'zhTW','摧毀者阿託留斯：$B$B冬泉谷中的那些被阿託留斯接觸過的生物全都被他毀滅了。找到他，殺死他。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2675 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2675,'zhTW','獵人，你要多加小心，那些惡魔都不會貿然行事。如果它們覺得自己沒有絕對的勝算，就會選擇逃跑。$B$B你一定要獨自行動。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2676 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2676,'zhTW','聯盟軍階$B$B軍官$B$B大元帥$B$B元帥$B$B統帥$B$B司令$B$B少校$B$B護衛騎士$B$B騎士隊長$B$B騎士中尉$B$B騎士$B$B士官長$B$B軍士長$B$B中士',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2677 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2677,'zhTW','部落軍階$B$B軍官$B$B高階督軍$B$B督軍$B$B將軍$B$B中將$B$B勇士$B$B百夫長$B$B軍團士兵$B$B血衛士$B$B石頭守衛$B$B一等軍士長$B$B高階軍士$B$B中士',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2691 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2691,'zhTW','要束縛恐懼戰馬，你必須做三件事：$B$B製造強力召喚法陣。$B$B在法陣中開啟通往克索諾斯的傳送門，將恐懼戰馬引入我們的世界。$B$B擊敗恐懼戰馬並控制它的靈魂。$B$B下一頁將詳細描述要如何執行這些步驟。這可不是一件容易的事，但是你是有能力完成它。只要集中精神運用你的所有技能，我相信恐懼戰馬會屬於你的。$B$B繼續讀下去吧。$B——莫蘇爾·召血者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2692 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2692,'zhTW','儀式道具$B$B在開始任務之前，你必須擁有以下魔法道具：$B$B耶維爾的瓶子$B一塊黑色磁石$B克索諾斯雕文$B我的僕人戈瑟奇會為你提供這些道具，但是你得付錢。如果你還沒有集齊所有的道具，就不要試圖開始儀式。每件道具都是必需的。$B$B在下一頁，我將描述道具的使用方法。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2693 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2693,'zhTW','強力召喚法陣$B$B必須在魔法強大的地方創造出強力召喚法陣。在埃德薩拉斯的廢墟深處，就有這樣一塊地方，也叫做厄運之槌。在埃德薩拉斯關押著擁有強大力量的生物，伊莫塔爾。創造法陣的地方就在關押他的監獄底座上。$B$B殺進厄運之槌吧，取回耶維爾的瓶子。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2694 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2694,'zhTW','鈴鐺、車輪和蠟燭$B$B釋放耶維爾之後，他將佈置鈴鐺、車輪和蠟燭，為你構建法陣。儀式隨即開始，你必須保持警惕，這些道具會引匯出強大的魔法能量，而且很容易失效。在整個儀式失敗之前，你必須快速使用黑色磁石來重新啟動失效的道具。$B$B如果三件道具都失效的話，儀式也就失敗了，你就不得不從頭再來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2695 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2695,'zhTW','為了引匯出儀式所需的能量，鈴鐺、車輪和蠟燭都具備獨有的屬性。$B$B達斯莫拉的鈴鐺，一旦鈴響，可賦予術士活力和能量的法陣。$B$B黑暗戰車之輪，一旦旋轉，可保護法陣中的人物免受傷害。$B$B末日蠟燭，一旦燃燒，可對進入法陣的敵人造成可怕的傷害。$B$B因此在儀式中保持三種物品的正常運作是至關重要的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2696 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2696,'zhTW','用於重新啟動鈴鐺、車輪和蠟燭的黑色磁石需要靈魂碎片方可生效，這點你需要牢記。每次使用黑石磁石啟動一件儀式道具時，都需要消耗一片靈魂碎片。因此，在開始儀式之前，你必須收集大量的靈魂碎片。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2697 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2697,'zhTW','完成儀式$B$B你可在法陣邊緣檢視魔法符文。當九個符文全部出現時，儀式便結束了，你將看見巨大的能量從新生的法陣中湧出。$B$B你可以在那裡使用克索諾斯雕文，由此開啟通往克索諾斯的傳送門，引出一匹恐懼戰馬。$B$B打敗恐懼戰馬，釋放它的靈魂。奴役這個靈魂，你就可以隨心所欲地召喚恐懼戰馬了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2731 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2731,'zhTW','長眠於此的是霜狼氏族的第一任酋長，我們敬仰的部落酋長索爾的父親——杜隆坦。他被那些想要讓我們永遠受到奴役的同胞背叛。杜隆坦為了我們的自由而獻出了自己的生命，我們敬仰他，以及他留給我們的珍貴遺產，他偉大的兒子。$B德雷克塔爾，霜狼氏族的先知$B</BODY></HTML>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2770 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2770,'zhTW','長眠於此的是霜狼氏族的第一任酋長，我們敬仰的部落酋長索爾的父親——杜隆坦。他被那些想要讓我們永遠受到奴役的同胞背叛。杜隆坦為了我們的自由而獻出了自己的生命，我們敬仰他，以及他留給我們的珍貴遺產，他偉大的兒子。$B$B德雷克塔爾，霜狼氏族的先知$B$B</BODY>$B</HTML>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2771 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2771,'zhTW','剝洋蔥：論擊敗雷矛部族的戰略$B——德雷克塔爾著$B$B本指南記錄了大量戰術策略知識。有學識計程車兵總是依靠豐富的作戰經驗行事。本書將成為奧特蘭克山谷的戰場指南。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2772 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2772,'zhTW','第一章：前線$B$B瓦解雷矛軍隊跟剝洋蔥很相似。你必須一層層地除去洋蔥外皮，才能得到洋蔥的嫩心。$B$B主要由雷矛巡山人和聯盟哨兵組成的前線陣營都歸上尉管制。一旦前線受到攻擊，巴琳達·斯通赫爾斯上尉將帶領前線陣營加強防守。攻擊上尉，前線陣營即可崩潰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2773 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2773,'zhTW','第二章：雙塔$B$B別搞錯了，範達爾·雷矛是個狡猾的敵人，他絕不是傻子。攻破前線之後，你還需要突破第二道防線。那就是控制著丹巴達爾之外的雷矛衛兵和雷矛巡邏兵的石爐和冰翼雙塔。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2774 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2774,'zhTW','士兵，小心，雙塔之上戒備森嚴，範達爾的精英指揮官駐守在這兒。一旦你的軍隊突破防線，請確保塔中的指揮官已經……永遠地沉默了。這將是瓦解雷矛部隊的第二步。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2775 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2775,'zhTW','第三章：四名指揮官$B$B雷矛洋蔥的第三層由四名指揮官組成。範達爾無非是模仿了我們霜狼的防禦構造罷了。當然，他是不會承認這一點的……瞧，我離題了。$B$B四名指揮官負責指揮守護丹巴達爾的所有雷矛衛兵。殺死他們，雷矛衛兵就會潰不成軍了。$B$B接下來便只剩最後一層了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2776 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2776,'zhTW','第四章：丹巴達爾兵營$B$B毫無疑問地，你已經注意到雷矛的防禦佈局是為了防止強大的力量摧毀整個軍隊。是的，這正是我們自己的軍隊結構，我是不會改變自己的防禦佈局的。他們模仿我們的佈局，我們為什麼要改變呢？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2777 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2777,'zhTW','我講到哪兒了？哦，是的，丹巴達爾兵營（位於丹巴達爾內）駐紮有範達爾最信任的精英雷矛防禦者。摧毀雙塔，消滅那些企圖增援範達爾的軍隊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2778 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2778,'zhTW','尾聲$B$B至此，洋蔥只剩下嫩心：孤身一人、毫無抵抗能力的範達爾·雷矛。在殺死他之前，我們必須按照軍規要求他棄械投降。當你看到他時請記得提醒他這一點……否則就殺死他。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2779 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2779,'zhTW','霜狼牌洋蔥：雷矛的榮耀與驕傲$B——範達爾·雷矛著$B$B霜狼是什麼？答案很簡單：霜狼就是那些企圖摧毀我們偉大的帝國的野蠻人。$B$B霜狼跟洋蔥非常相似，霜狼設立了層層防禦力量；一旦外層被剝離，就會露出嫩心，這樣我們便可以就著蒜汁食用了。$B$B太美味了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2780 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2780,'zhTW','第一章：前線$B$B霜狼戰士構成了霜狼的前線防禦部隊。加爾範上尉在冰血要塞統領著所有霜狼戰士。要摧毀這層防禦，最有效的方法是佔領冰血要塞。$B$B包圍要塞，殺死加爾範上尉，前線將在頃刻之間崩潰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2781 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2781,'zhTW','第二章：冰雪和哨塔高地$B$B一旦首層防禦被摧毀，“洋蔥”的第二層防禦便暴露無遺。破壞前線附近的霜狼哨塔將削弱企圖增援的軍團和巡邏兵。$B$B哨塔部有重兵把守，塔內駐紮著德雷克塔爾的精英指揮官。必須殺死這些指揮官。這將加速瓦解霜狼防禦力量的程序。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2782 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2782,'zhTW','第三章：四名指揮官$B$B如果你遵循該指南行事，那麼現在，你已經殺死了德雷克塔爾的兩名指揮官。幹得好，士兵！他們的信心正在瓦解。你必須殺死剩下的兩名指揮官，完成命令。$B$B一旦四名指揮官陣亡，保衛霜狼要塞的霜狼軍團將潰不成軍，因為他們失去了戰鬥指揮的主心骨。現在是時候了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2783 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2783,'zhTW','第四章：東部和西部霜狼哨塔$B$B現在你離勝利只有一步之遙啦！德雷克塔爾最信任和最強大的守衛軍隊：霜狼守衛者。$B$B霜狼守衛者駐守在東部和西部霜狼哨塔中。摧毀哨塔，看看那些四散逃跑的可恥的霜狼守衛者吧。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2784 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2784,'zhTW','尾聲$B$B“將蒜汁黃油和蛋黃醬抹在洋蔥嫩心上，喝上一瓶陳年烈酒，這真是頓美餐啊。”$B$B德雷克塔爾身邊只剩下兩個愚蠢的隨從啦。佔領霜狼急救站，殺死德雷克塔爾。那時，這片土地就完全屬於強大的雷矛啦。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2785 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2785,'zhTW','我們請求你，贊達拉的贊札。$B$B祝福那些請求你的幫助的人吧，贊札。祝福那些跟贊達拉人民結盟的人。$B$B在這關鍵時刻幫助我們。賜予我們力量，打敗敵人，再次消滅哈卡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2786 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2786,'zhTW','荊棘谷釣魚大賽！$B$B時間：週日下午2點到4點。$B$B在荊棘谷的海岸邊尋找可口魚群！記得向可口魚群中投放魚鉤，這樣你就能釣到特殊的魚，而不是荊棘谷常見的魚。最快釣到40條斑點可口魚的人請將它們交到藏寶海灣的釣魚大師林格·巴斯貝特處領取獎勵！$B$B即使你不是最快的那個，也可以用它們換取獎金。如果你能釣到特殊的魚還可以獲得神秘大獎！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2787 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2787,'zhTW','他的名字為黑暗的艾澤拉斯帶來了光明。$B$B他的勇氣推翻了痛苦的高牆。$B$B白銀之手將繼承騎士的事業，為世界造福。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2788 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2788,'zhTW','他既不醉心於名望，$B$B亦不想以此獲得統治權。$B$B相反，他選擇為洛丹倫而戰，$B$B只是希望他的同胞不再捲入戰事。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2789 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2789,'zhTW','這位神聖的騎士的悲劇$B$B不會因他的逝去而終結。$B$B我們尊敬他，感謝他！$B$B烏瑟爾永遠代表著榮耀和光明！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2790 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2790,'zhTW','他的名字不會褪色。$B$B他的奉獻精神將$B$B永遠為後人指明方向。$B$B曾經的枷鎖再也無法$B阻止我們表達對他的尊敬。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2791 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2791,'zhTW','你能聽到他的咆哮嗎？$B$B一聲驚醒部落的怒吼：$B勝利或是陣亡！$B$B我們必須牢記$B他在死亡面前爆發的力量。$B他的夢想終成現實。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2792 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2792,'zhTW','危機四伏。$B$B敵人想讓我們$B再次受縛。$B$B在戰鬥時，讓我們$B懷念格羅姆·地獄咆哮$B他完成了自己的使命。$B$B永遠的格羅姆·地獄咆哮！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2793 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2793,'zhTW','從流沙之戰到現在也將近一千年了。在這場戰爭中，希利蘇斯沙漠的中心發生了一個重大的悲劇，而沉重的負擔讓範達爾·鹿盔苦惱不已。人們相信就是這些事件造成了大德魯伊最後令人厭惡的性格。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2794 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2794,'zhTW','一支古老，敏銳的種族——其拉——想要爭奪卡利姆多大陸的統治權。而自負、專制的鹿盔和他的暗夜精靈軍隊正式與它們展開了激戰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2795 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2795,'zhTW','為了抑制希利蘇斯中大量出現的昆蟲潮，暗夜精靈不分男女老少都激烈地奮戰。在安其拉的堡壘中似乎有著永無止盡的異種蠍，它們持續壯大著入侵希利蘇斯的其拉軍隊。最終，整個希利蘇斯都被包圍了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2796 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2796,'zhTW','基於一個鹿盔自己都會後悔的決定：他將年輕的瓦爾斯坦·鹿盔派去防守暗夜精靈的前哨基地南風村。可是解決令人非常難過——瓦爾斯坦在南風村敗給安其拉的軍隊那天失去了性命。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2797 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2797,'zhTW','想復仇的範達爾·鹿盔抱著無畏及堅定的決心繼續計劃著一切。希利蘇斯的戰敗會導致暗夜精靈種族重大的損失，甚至可能會失去整個世界。$B$B戰火延燒了好幾個月。整個希利蘇斯都被其拉軍侵襲了。鹿盔和他的軍隊被逼回塔納利斯。在大批軍隊被毀滅和無數無辜生命被屠殺之後，範達爾·鹿盔一直以來的自負被徹底地熄滅了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2798 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2798,'zhTW','他的驕傲被完全地粉碎，這是鹿盔第二次在人生中感到徹底的恐懼。於是，在塔納利斯，鹿盔找到了阿納克洛斯——諾茲多姆的子嗣，並請求青銅龍軍團的協助。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2799 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2799,'zhTW','一開始，阿納克洛斯拒絕讓青銅龍軍團捲入次要種族的事務之中。直到其拉莽撞地攻擊了時光之穴，阿納克洛斯才同意加入暗夜精靈的軍隊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2800 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2800,'zhTW','阿納克洛斯很快瞭解到即使是強大的青銅龍軍團也無法阻撓其拉軍隊的入侵。每當他一口氣殺掉五十隻蟲兵，就會有一百隻等著替補它們的位置。隨著暗夜精靈陣線越來越衰弱，這個威脅將會蔓延至更北方的菲拉斯荒野的跡象就越來越清楚的浮現，阿納克洛斯決定是時候該讓守護巨龍之子們都意識到這個情況。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2801 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2801,'zhTW','他首先召喚了伊瑟拉的軍團。翡翠夢境的麥琳瑟拉回應了他的召喚，接著阿萊克斯塔薩和瑪裡苟斯的軍團也被喚醒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2802 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2802,'zhTW','龍群在希利蘇斯上空的最高處碰頭：在安其拉堡壘上空的幾千尺之上。$B$B阿納克洛斯是時間之王諾茲多姆的子嗣。$B$B翡翠夢境則有麥琳瑟拉，自然之王伊瑟拉的孩子。$B$B凱雷斯特拉茲，生命之王阿萊克斯塔薩的孩子，代表紅龍軍團。$B$B亞雷戈斯是魔法之王瑪裡苟斯的孩子，代表藍龍軍團。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2803 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2803,'zhTW','巨龍們看著其拉蟲人和異種蟲的大軍源源不斷地從安其拉湧出。他們明白，沒有誰能終止這場戰爭。在神廟中，還有數以萬計的蟲類士兵嚴陣以待。隨著時間的流逝，它們的軍隊數量還在繼續膨脹，它們全部都蠢蠢欲動，想要投身血腥的殺戮。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2804 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2804,'zhTW','亞雷戈斯是第一個發現奇怪能量的人。從安其拉南邊四分之一處龐大的神廟裡放射出一絲微暗的魔法——是他們從未自其拉蟲上感受到的。他們盡全力嘗試卻沒有人可以穿過神廟找到這股能量的來源。只有巨大的力量才能這樣完整地保護它自己。或許……有某樣東西正在控制著這些昆蟲，有某樣東西甚至還正控制著其拉蟲類。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2805 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2805,'zhTW','龍群知道他們必須儘快做出回應以免世界又要經歷另一次史詩的大災難。經過審慎的深思熟慮後，他們覺得最好的行動方式就是阻止這些東西來源或其附近的軍隊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2806 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2806,'zhTW','他們決定使用暗夜精靈和巨龍軍團的本源建立一個巨大的屏障。一個可以遏制異種蠍和安其拉城內的最高統治者，還可以防止未來的侵略的魔法屏障。安其拉將會因此成為一所監獄。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2807 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2807,'zhTW','第1天$B$B我們的旅行結束。我們終於到達希利蘇斯，也就是我們要建立聯絡的地方。我們來自許多地方，要一起為不朽的事業通力合作。$B$B空氣中瀰漫著一股興奮。明天我們就要將所有的精力拿來建造與“他們”進行溝通的東西。$B$B我們將在明天建造一座風石！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2808 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2808,'zhTW','第2天$B$B建造風石的位置引起了極大的爭議。就連我們之中最聰明的人也無法百分之百確定，古老的預言裡所指的確切位置究竟是哪裡。$B$B我跟原來的北邊族群站在同一陣線，而時間絕對會證明我們是對的。說能量線會貫穿這個位置的不利角度實在是愚蠢又無知。$B$B我們早已積極地在收集建構需要的材料。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2809 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2809,'zhTW','第15天$B$B我們的付出有了代價。我們是第一個完成風石建構的軍營。如果其他那些笨蛋跟我們一起，我們就可以在一個星期之內完成這項工程！$B$B明天我們會開始召喚沃庫侖大人的儀式。他要求第一個來測試系統，我們無法反駁他，因為他很容易生氣。$B$B我希望他會對我們很滿意。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2810 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2810,'zhTW','暮光之錘緊急通告：$B$B搜尋叛徒奧泰爾的工作進展順利。我們的偵察兵已經將他的位置鎖定在西部荒野的一處洞穴中。$B$B奧泰爾的背叛行為不可饒恕，一旦他成功逃脫，將對我們的組織造成巨大的安全隱患。$B$B任何企圖隱瞞奧泰爾行蹤的人都將收到懲罰。$B$B——暮光之王艾沃蘭',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2811 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2811,'zhTW','暮光之錘緊急通告：$B$B考慮到希利蘇斯的現狀，所有分發《真正的信徒》工作必須在不少於4名全副武裝的暮光之錘成員的護送下完成。$B$B任何違反這項新規定的成員將立即受到懲罰。$B$B——暮光之王德薩克',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2812 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2812,'zhTW','暮光之錘緊急通告：$B$B以下資訊描述瞭如何使用風石與我們在深淵議會中的主人進行溝通。$B$B肆意使用風石的人將收到嚴厲的懲罰。$B$B——暮光守護者哈弗斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2813 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2813,'zhTW','深淵聖殿騎士$B$B作為一名新成員，你可以與深淵聖殿騎士建立聯絡，處理日常儀式。要記住的是，在利用風石時，你必須穿上適當的服飾，以避免啟用防禦魔符。$B$B倘若在沒有監督者在場的情況下突發緊急狀況，你有權召喚深淵聖殿騎士。$B$B關於召喚儀式的詳細資訊，請參閱上個月的《真正的信徒》。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2814 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2814,'zhTW','深淵公爵$B$B唯有那些持有身份勳章的侍僧能與深淵公爵建立聯絡，只有身份勳章的持有者本人才能使用它。$B$B如果暮光之錘的成員未經許可擅自與深淵公爵聯絡或使用身份勳章，我將親自懲罰違規者。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2815 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2815,'zhTW','高階深淵議會的首領$B$B只有暮光之王能與斯卡德諾克斯王子、大元帥維拉希斯、卡蘇姆男爵或斯古恩男爵聯絡。$B$B任何情況下，低於暮光之王等級的任何暮光之錘成員都不能與高階議會建立聯絡。若發現任何外來人員使用風石，他將立即被化為灰燼。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2816 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2816,'zhTW','教派的現狀，第92卷$B$B衷心地祝福你，我的兄弟，教派目前的狀況對我們來說是最最重要的。我們是一支軍團，我們的目標越來越接近實現。$B$B新召集的成員正在不斷聚集。讚美我們主的歌聲出現在黑海岸，他們充滿幻想地在灼熱峽谷鞠躬，他們信奉主人派往黑暗深淵的僕人，阿庫麥爾。事實上，我的兄弟和姐妹，我們所有具有這種真正信仰的人，將會遍佈艾澤拉斯！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2817 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2817,'zhTW','教派的現狀，第127卷$B$B這真是一個令人高興的一天！我們在希利蘇斯接受特訓，而且最終透過了這次特訓！$B$B報告說我們最北面營地的毀滅將會挑戰不忠實者之心，但是這次屠殺不會被視為一次悲劇。決不！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2818 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2818,'zhTW','被一名高階深淵議會的成員濺灑我們的鮮血，這是一種無上的祝福！我們必須羨慕我們倒下的朋友，他們的靈魂正安息在一頭最榮耀的野獸的胃中！$B$B讚美上古之神！讚美他們的僕人！讚美暮光之錘！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2819 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2819,'zhTW','教派的現狀，第233卷$B$B機會再次降臨，我的兄弟姐妹！塞納里奧議會，這個邪惡的自然愛好者組織現在派人來對抗我們。他們一定想要阻止我們來召喚紅色的引誘石。我們決不允許他們這麼做！$B$B紅色的石頭對於我們新的聯盟來說非常重要。我們絕對不能讓那些塞納里奧議會的蠢貨擋路。團結起來，我忠誠的朋友。團結起來！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2820 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2820,'zhTW','我們怎麼知道他們愛我們？$B$B有些人可能要問，上古之神和他們的手下怎麼會愛我們？他們難道不是經常殺戮我們嗎？如此惡毒的生物的心中怎麼會有愛？$B$B對於這個問題只有一個答案，簡單得都不需要說出來？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2821 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2821,'zhTW','信仰。信仰是所有給予我們臣服的快感的源泉。信仰可以讓我們在希利蘇斯最寒冷的夜晚感到溫暖。信仰讓我們在末日將臨的時候感受我們主的仁慈。$B$B信仰將會拯救我們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2822 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2822,'zhTW','魔法賬本',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2828 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2828,'zhTW','<HTML><BODY><IMG src=\\"Interface\\Pictures\\21037_crudemap_256\\"/></BODY></HTML>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2829 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2829,'zhTW','親愛的日記，$B$B今天，我的頭號敵人——納裡安，企圖派他的密友在他處以死刑的場地欺騙我。他的死刑，你相信嗎？$B$B我歷經千辛萬苦才想出這個惡魔般的計劃，要把他從那個該死的茅屋裡引誘出來而他卻這樣做？算了……我太生氣，不想寫了。下次再說。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2830 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2830,'zhTW','親愛的日記，$B$B我在憤怒中離開了藏身之處。我真的很生氣。我決定重新設計奴僕們的制服以反映我的不安。我現在覺得好多了但是有個東西不見了。我馬上就回來……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2831 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2831,'zhTW','親愛的日記，$B$B好了，我現在很好。我把一個傭人打到哭的跟個小女孩一樣。$B$B嗯……我現在覺得有點糟。等一下！該死的，我是個邪惡的天才！邪惡，你懂嗎？我對自己真是太失望了。下次再說。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2832 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2832,'zhTW','親愛的日記，$B$B我給了他一個擁抱並告訴他要繼續努力工作。我現在覺得好多了。這是我們之間的秘密，日記。$B$B我上次說到哪了？喔，對，納裡安！哼！！！我恨那個傢伙。畢竟，就是納裡安摧毀了所有我們在修補諾莫瑞根學院當學生時的測驗曲線。$B$B他們會把我趕出學校嗎？就我看來，諾莫瑞根已經得到它該有的教訓了！$B$B今天就寫到這裡。好好睡，日記！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2833 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2833,'zhTW','親愛的日記，$B$B我一定是老了。我完全忘記我跟你說了納裡安和他的詭計的事。總之，當我看到扮成納裡安的誘餌，我真的很生氣所以就命令二號把那個笨蛋給殺了！$B$B我進入飛行器裡開始撕毀他寶貴、愚蠢、無知的龍語書。真是愛炫耀！誰會讀龍語啊？我真是痛恨他！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2834 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2834,'zhTW','親愛的日記，$B$B抱歉，我睡著了。然後我就一邊憤怒的開著飛行器，一邊把那愚蠢的書一章章丟出去。我看到我下方的暗語峽谷裡有個惡魔，便決定要將第一章變成魔法的紙龍捲風，把它的身體碎成好幾百萬片！這是解放。魔法+紙張=樂趣。$B$B這讓我非常開心所以我決定飛到東部王國。我的第一站是熔火之心。納裡安總是一直講那邊的事！“……熔火之心怎樣怎樣，拉格納羅斯如何如何……”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2835 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2835,'zhTW','你知道嗎？如果他那麼喜歡它，或許他會去熔火之心試著把他的書拼湊起來，然後從一堆灰燼中讓那些章節再復活過來！哈！$B$B當我還在鄰近地區的時候，我發現有一些在奈法里奧斯實驗室的技術人員可能會用到這個龍語的東西。把炸彈拿開！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2836 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2836,'zhTW','已經開始變成一種運動了。我真的撕這該死的書撕到上癮了！$B$B接下來就簡單了。$B$B幽暗城，惡臭腐爛死人的家，可能有著我吃過最棒的辣椒，這樣是一章。暴風城，起司的首都，另一章。日記，你有把暴風城的起司拿來放在幽暗城的辣椒上過嗎？嘿？這應該聽起來有點警惕作用。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2837 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2837,'zhTW','我開始對這個地方感到厭倦，所以我把飛行器掉頭往回家的路走，但是在那之前我還有兩個地方要去。我載了卡札克和他的惡魔們一程，到腐爛之痕（他最討厭我這樣做）然後又去了女伯爵奧妮克希亞的煙囪。$B$B累了。去睡了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2838 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2838,'zhTW','敬啟者，$B$B我真愛我們玩的這些遊戲。$B$B我只能猜想，如果你正在閱讀這封信，你一定是因為奇蹟或神的介入才擊敗了我。很荒謬，我知道，但是更奇怪的事都在這個世界發生過。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2839 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2839,'zhTW','伴隨生命中所有事物，這個哀傷傳說中的悲劇、混亂和邪惡，都有著光榮、銀色的內襯。當你殺了我，因為你的動作是如此的緩慢無序，讓我有足夠的時間先摧毀你拯救世界唯一的希望再寫下這封信。粉碎的紅水晶粉末是你的權杖碎片唯一留下的東西。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2840 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2840,'zhTW','享用你在我貴重的收藏品中發現的復仇和怒風裝備吧。相信我說的：我很高興做了我父親沒有做的事……$B$B$B由衷的敬上，$B$B維克多·奈法里奧斯$B\\"奈法利安\\"',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2841 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2841,'zhTW','謹代表煙燻牧場，再次感謝你的調查。我們不確定馴鹿梅森在誰的手裡，但兩個都去調查也許會是個不錯的開始！$B$B時間就是金錢，朋友，我們可以解決這個案子的時間又少得非常寶貴。快點加把勁去解救它，因為這些團體都不是容易對付的。$B$B總之，接下來的2頁就是我們收到的勒索信。祝你好運……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2842 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2842,'zhTW','如果你們想要麋鹿活著回來，你們就得趕快準備好贖金。南海海盜不會好心到讓你們延遲付款，我們也知道對“你們”的象徵意義有多麼珍貴。$B$B帶1000金到塔納利斯的落帆海灣。任何企圖拯救這隻麋鹿的行為，都會讓馴鹿梅森變成桌上的菜餚。$B$B哈哈……$B$B南海海盜。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2843 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2843,'zhTW','你們那珍貴的寵物在其熱無比的灼熱峽谷表現的不太好……你們最好聰明點，不要延遲完成我們的要求。$B$B你們必須帶給我們5顆星紅寶石和總數700金——將兩者置於同一個不加註記的素面包裹裡。在一週內把包裹放在通往石壩小徑的門前。$B$B若沒有達到我們的要求，馴鹿梅森就會變成黑鐵矮人冬幕節的主菜。$B$B嗯……麋鹿……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2844 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2844,'zhTW','他那些獵犬來的比老鷹還要快，$B$B然後他吹了聲口哨，大吼，依序喊著它們的名字；“$B$B現在，毛瑟！現在，奇爾頓！現在，喬登跟卡普蘭！$B$B上，納格！上，帕度！上，古德曼跟梅森！$B$B到門廊的頂端！到牆頂！$B$B現在衝過去！衝過去！衝過去啊”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2846 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2846,'zhTW','我衷心的期望透過我的努力研究可以發現一種魔術能量的補充來源，而它對我的人民而言是安全的。太陽之井消失後，我們必須想辦法讓生活繼續，不向秘法魔法屈服。$B我相信辛多雷的未來能再次成為大家欽羨亮麗的榜樣！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2847 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2847,'zhTW','好運還沒降臨。我匯入的法術一定要傳導透過尖塔，不過我的確有一些有趣又吸引人的點子。我派我最聰明的學徒追隨調查的路徑，看看能發現什麼。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2848 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2848,'zhTW','我記筆記已經好一陣子了，但還是沒啥進展希望。我昨天在逐日島聽到其中一位學生法蘭德倫說他沒有謹記良師忠告，而向痛苦屈服。$B我得加把勁、加倍努力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2849 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2849,'zhTW','沒事。我不會放棄任何一絲希望。我們包圍了南方，而此刻辛多雷無法在這個魔法保護區放肆亂來。$B假如我設計的全新方法成功的話，我就能順利濾除邪惡、腐敗法術中的“雜質”，我已經把法術力的資料藏起來。我得持續謹慎小心。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2850 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2850,'zhTW','太神奇了！我們成功了，我們所研究的魔法精髓數量雖然不是很多，我要停擺目前大部分學徒的實驗，然後一起著手進行嶄新、有前瞻希望的研究工作。$B有了好運加持，我們應該要精煉研究過程，一石二鳥——我們全體要備足精力，以及迎接即將來臨的惡魔法術難題。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2851 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2851,'zhTW','不！當新實驗程式開始時，我的主要學徒：泰勒塞翁，突然無預警的在我眼前萎縮，屈服成這種狀態著實折磨了我的兄弟。我極力想制止，但他就這樣離我遠遠而去。除了讓他從苦痛中倖免外，我也沒別的選擇了。$B而這是研究與發明的代價，只不過這代價實在是太沉重了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2852 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2852,'zhTW','我不能再容忍了……又有2個學徒向邪惡屈服。我們已經很小心翼翼了……但我不知道是哪裡出差錯。$B我得放棄這些調查行動，從零開始。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2853 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2853,'zhTW','我來遲了。第3個學徒已不知不覺和其他人建立起邪惡的勾當。我必須容忍現狀，但當務之急是避免讓其他未受影響的學徒同流合汙。$B我要讓所有人都知道我在遠行者居所行週期安息日。這樣一來，我就可以好好構思解決難題的辦法。$B我一定要想出正確的判斷來彌補這個可怕的錯誤。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2854 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2854,'zhTW','<HTML><BODY><H1 align=\\"center\\">部落軍官軍階</H1><BR/><P align=\\"center\\">第二部分</P><IMG src=\\"Interface\\PvPRankBadges\\PvPRank09\\" align=\\"left\\"/><BR/><P align=\\"right\\">百夫長</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank08\\" align=\\"left\\"/><BR/><P align=\\"right\\">軍團士兵</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank07\\" align=\\"left\\"/><BR/><P align=\\"right\\">血衛士</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank06\\" align=\\"left\\"/><BR/><P align=\\"right\\">石頭守衛</P><BR/><BR/></BODY></HTML>',0);
