INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2856,'zhTW','<HTML><BODY><H1 align=\\"center\\">聯盟軍官軍階</H1><BR/><P align=\\"center\\">第二部分</P><IMG src=\\"Interface\\PvPRankBadges\\PvPRank09\\" align=\\"left\\"/><BR/><P align=\\"right\\">護衛騎士</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank08\\" align=\\"left\\"/><BR/><P align=\\"right\\">騎士隊長</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank07\\" align=\\"left\\"/><BR/><P align=\\"right\\">騎士中尉</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank06\\" align=\\"left\\"/><BR/><P align=\\"right\\">騎士</P><BR/><BR/></BODY></HTML>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2857 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2857,'zhTW','<HTML><BODY><H1 align=\\"center\\">聯盟士兵軍階</H1><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank05\\" align=\\"left\\"/><BR/><P align=\\"right\\">士官長</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank04\\" align=\\"left\\"/><BR/><P align=\\"right\\">軍士長</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank03\\" align=\\"left\\"/><BR/><P align=\\"right\\">中士</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank02\\" align=\\"left\\"/><BR/><P align=\\"right\\">下士</P><BR/><BR/><IMG src=\\"Interface\\PvPRankBadges\\PvPRank01\\" align=\\"left\\"/><BR/><P align=\\"right\\">步兵</P><BR/><BR/></BODY></HTML>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2858 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2858,'zhTW','安東尼·雷·斯塔克$B$B1961——2005',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2859 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2859,'zhTW','祈願火盆：使用者操作手冊$B$B如何找到鬧鬼地點$B$B介紹$B$B這些頁面介紹，包括那些捲入瓦拉薩克護符事件的墮落腐敗的鬼魂、靈魂之所在地點，雖然你救了我之前的同伴，據我推測，曾扭曲他們靈魂的惡魔厭惡迴音，仍盤懸迴盪在那些鬧鬼之處。這就是心腸惡毒的瓦拉薩克靈魂的力量。$B$B此外，火盆還可以召喚瓦拉薩克，不過，凡事還是得小心謹慎一些。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2860 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2860,'zhTW','介紹，繼續……$B$B火盆的功能就像召喚火盆一樣。只要把它放在五個鬧鬼的地方之一，它就會召喚出亡者的靈魂。$B$B另外告訴你，我知道你會有興趣，挑釁旗幟也能在黑石深淵競技場有類似的功用。到了那裡，只要有機會就替我教訓瑟爾倫和他的暴徒們。$B$B如果你有興趣瞭解更多就繼續讀下去。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2861 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2861,'zhTW','依薩利恩$B$B月之女祭司$B$B當依薩利恩決定離開居住地，她是為了去厄運之槌朝聖，那個古老的暗夜精靈城市——埃德薩拉。在那裡，有一個圖書館仍保留了豐富的知識，那裡是少數暗夜精靈儲存下來的聖所。她很想去那裡找到命運的答案，或許還有護符塊的事。我們該知道她也是法爾林·樹影的好朋友。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2862 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2862,'zhTW','依薩利恩，繼續……$B$B不幸地，當她和她的角鷹獸同伴，蒼穹，正進入城裡的時候，被奧茲恩和他的爪牙攻擊。她倒在那裡，再也沒有爬起來了。依薩利恩從未解開任何瓦薩拉克在護符裡施的邪惡魔法秘密，或許這是很好的事。$B$B奧茲恩住的露天房間就是鬧鬼的地點之一。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2863 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2863,'zhTW','莫爾·灰蹄$B$B牛頭人德魯伊和第一個倒下的人$B$B莫爾·灰蹄是隱刃裡相當勇敢且值得信賴的同伴。他成為瓦薩拉克的邪惡爪牙下第一個犧牲的人實在令人惋惜。$B$B當我們逃出瓦薩拉克的魔掌時，我們正被他的鬼魂刺客和捕獵者追趕。那場黑石塔的戰鬥十分混亂，只能這麼說。不幸地，莫爾在路上錯亂了他的腳步，雖然我猜他是被推倒的。總之，他跌進了塔的下層。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2864 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2864,'zhTW','莫爾·灰蹄，繼續……$B$B後來，我們發現莫爾並未跌死。但是我的好友最後還是沒有好下場；他被塔薩洛爾的巨魔擄為戰俘。不久，就在他被指揮官沃恩折磨的時候，一群瓦薩拉克的刺客跳了出來結束了這個任務。$B$B如果你想召喚出莫爾·灰蹄的靈魂，指揮官沃恩的房間就是鬧鬼的地方。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2865 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2865,'zhTW','賈林和索索斯$B$B欲成為血色十字軍的姊弟$B$B賈林和索索斯是我所認識最偏執的兩個人。但是他們戰鬥的技能是相當傑出的，他們是用錢買來的，也是我推斷隱刃領導者，安希恩會留住他們的原因。$B$B這對姊弟最後終於找到令他們迷戀的血色十字軍的教導和哲學。他們在我們的旅途中總是展現出極大的熱誠來殲滅天災軍團，我們也懷疑他們的家人與那個組織有關連。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2866 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2866,'zhTW','賈林及索索斯，繼續……$B$B他們發現自己面臨的試煉是加入十字軍必經的過程。他們特別有興趣的位置是騎士身分；那是需要更艱難的考驗的。後來發現索索斯其實沒有透過他最後一項考驗。賈林當然不會，她公然挑戰，堅持讓他加入她的騎士身分。據我們所瞭解，大十字軍戰士達索漢當場就在房間裡把他們都殺了。$B$B因此斯坦索姆的血色十字軍堡壘裡，赤色王座就是另一個鬧鬼的地方。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2867 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2867,'zhTW','科爾莫克$B$B雙頭巨魔巫師$B$B科爾莫克有什麼好說的？他是個有著多樣魔法的雙頭巨魔，不是個很差勁的人。我們第一次帶他進入坑窪時他是個囚犯，那是個在燃燒平原接下的任務。但是後來我們發現，他對幫助我們脫離棘手的狀況並沒有什麼益處，然後他就成為公司最早的法師之一。$B$B他奇怪的地方是他的兩個頭暀？著完全不同的個性。一個總是很開心，有一點傻氣，另一個很狡猾算計，而且眼神很像死去的人。滿嚇人的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2868 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2868,'zhTW','科爾莫克，繼續……$B$B後來，因為我們長途跋涉，科爾莫克持續暴露於巫術的魔法下。不幸的是那個可怕的東西竟然有飼養亡者靈魂的喜好，在其中獲得邪惡的喜悅，尤其在召喚贖罪島被放逐的靈魂時。$B$B在公司解散後，科爾莫克參加了通靈學院的進修課程。鬼魂刺客發現要進入學校實在是太容易了，便在他的新主人，萊斯·霜語面前殺了他。$B$B這讓萊斯·霜語的房間變成鬧鬼的地方之一，也是火盆可以成功利用的地方。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2869 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2869,'zhTW','瓦薩拉克$B$B龍語貴族和之前的黑石塔將軍$B$B在達基薩斯將軍之前，有瓦薩拉克，一個擁有強大力量的龍族術士。哨塔的領導權交替是常見的事，對我們而言不幸的是，我們正好處於最後一批的權力轉換。$B$B我們受一個藏寶海灣的地精走私者術士委任，他叫格雷姆尼克，去偷瓦薩拉克的魔法書。我們不知道他是想研讀那本書還是把它賣掉（或者兩者都有），不過現在也不重要了。重要的是我們進入黑石塔上層，到瓦薩拉克的巢穴殺了他。樂趣現在才開始。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2870 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2870,'zhTW','瓦薩拉克，繼續……$B$B我們不瞭解瓦薩拉克操縱靈魂的魔法有多強大，否則當初就不會接下這個任務了。但是我們已經接了，而且看來也是我們接的最後一個任務了。$B$B殺了瓦薩拉克，拿走他的魔法書，科爾莫克一定感應到他的護符有點不對勁。他堅持把它視為戰利品，很快地成為一個熱烈的爭論，他們甚至為了它大打出手。我們當時不知道護符裡藏有瓦薩拉克的靈魂；是後來才知道的，也讓我們很痛苦。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2871 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2871,'zhTW','瓦薩拉克，繼續……$B$B分裂護符，我們從新生的瓦薩拉克鬼魂，和他的鬼魂刺客軍隊那裡逃了出來。我們搶奪護符的聲響引起了塔裡剩下的防衛者注意！$B$B我們幾乎所有人都逃出黑石塔並以為自己安全了。但是，不管有多遠，瓦薩拉克都會派他的爪牙來追我們。隱刃在那次任務後很快就四分五裂了，然後我們就成了俎上魚肉。$B$B你一定要知道，瓦薩拉克的住所就是現在黑石塔裡比斯巨獸的房間，最後一個鬧鬼的地方。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2872 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2872,'zhTW','致所有強壯的男人和女人們：$B$B天災軍團已經回來了而我們務必要將一切瑣碎的爭吵放在一邊，並面對這個威脅。銀色黎明會讚賞任何捲起袖子，加入對抗天災軍團威脅的人。$B$B所有要保衛我們家園的人都會聚集在東瘟疫之地的聖光之願禮拜堂。團結一致，我們就能獲得勝利。$B$B名冊保管者$B銀色黎明',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2878 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2878,'zhTW','我的艾米莉，$B$B幾天前，我們攻佔了這座防禦力量薄弱的被遺忘者營地，遵照國王的命令啟程返回家園。雖然路途陰冷荒涼，我的心情卻非常愉快；因為我知道，艱難跋涉後我會在你溫柔的臂彎中得到莫大的安慰。$B$B今天我們到達海邊後發現所有的船隻都被焚燬了，回家的希望已經破滅；我們別無選擇，只能在這片無邊無際的荒野上無奈地等待死亡。$B$B艾米莉，我竭盡所能來確保你的平安……現在……我多希望能在洛丹倫好好守著你。$B$B我每時每刻都在想你。嚴寒中只有你能溫暖我的心，親愛的，沒有誰能帶走你。B$B麥克斯韋爾',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2880 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2880,'zhTW','魯本，$B$B我知道，這封信你或許永遠都無法看到；我只是不願意反覆聽著壁爐谷城牆上傳來的重擊聲，想找點事兒做罷了。亡靈軍隊就駐紮在村外，不斷地襲擊村子；我們奉命在此確保居民們的安全，等待援軍到來。$B$B在上一次攻擊中我折斷了腿骨，因此我只能無助地坐在這兒；如果敵人突破了我們的防線，那身邊的這柄長劍便是我最後的武器。這不是開玩笑……我只能聽見戰鬥和死亡的聲音。空氣中凝結著恐怖的氣氛。$B$B阿爾薩斯王子披掛上陣，在前線奮勇殺敵。要不是他在這兒，我們恐怕早就全軍覆滅了。他對這片土地和人民的熱愛感染了每一個人；能為他服務我倍感榮幸，死不足惜。$B$B戰爭越演越烈。不管腿有沒有斷，我都不能坐在這裡。我們需要每一個人。我希望你看到這些話的時候情況能樂觀些。$B$B你的朋友，$B裡格利姆',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2881 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2881,'zhTW','海琳娜，$B$B我，瓦古斯，目前仍然活著，這可能與您所預期的有所不同。我穿著這套可笑的護甲，在窮鄉僻壤奔波勞累，這真是一份令人厭惡的差事。$B$B我們奉命押送糧草前往安多哈爾。我幹嘛要擔心安多哈爾這種產量地的儲備問題？軍隊那幫傢伙的腦子怕是進水了吧。$B$B海琳娜嬸嬸，我一定會回去繼承您的遺產的，即使我受了傷或者是斷了糧，我也一定會回去繼承您的遺產。$B$B瓦古斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2882 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2882,'zhTW','親愛的亞蜜利亞，$B$B今晚我經歷了終身難忘的大事件。$B$B斯坦索姆被火海吞噬……這一切都是我們造成的。$B$B就在今晚，王子率領我們衝進城市，命令我們破門而入……殺死熟睡中的城民。他們感染了天災瘟疫，想要取阿爾薩斯王子的性命，我們不得不先發制人。$B$B那那是一場大屠殺。上百名城民在毫無防備的情況下命喪黃泉，而我們曾發誓要好好保護這座城市。我覺得難以承受：於是我逃走了。$B$B我或許是個可恥的叛徒，但是我實在無法容忍這樣的暴行。手起刀落時，我眼前總是浮現出你和孩子們的面孔。如果註定要揹負叛徒的罪名，那就讓我承擔一切吧。$B$B我希望能早些回到你身邊，但路途並不安全。我不在的時候替我傳達我的愛給我們的孩子。$B$B詹姆斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2883 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2883,'zhTW','薩姆拉，$B$B我們追隨阿爾薩斯王子一路向北，我的心情也愈發沉重起來。昔日裡王子籠罩在聖光的光輝下，現在我卻感覺這位年輕的聖騎士的心靈逐漸被黑暗力量吞噬。某種來自王子靈魂深處的夢魘正在侵淫著他的熱誠，而我對此無能為力……$B$B我們很快就要在冰寒的荒地靠岸。大多數士兵不堪嚴寒，在經歷數場惡戰之後紛紛病倒；但是阿爾薩斯告訴我們，這片極寒之地中，有人能幫他扭轉戰爭局勢。王子的這番話未能安撫軍心，他說完之後……我發現他嘴角露出詭異生硬的笑容，令人不寒而慄。$B$B為我們和我們的世界祈禱吧，薩姆拉，$B$B托爾加',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2884 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2884,'zhTW','親愛的帕米拉，$B$B明天我們將打響安多哈爾的保衛戰，恐怕這是我寫給你的最後一封信了，親愛的。我們如何能以血肉之軀與那些虎視眈眈的亡靈大軍抗衡。別擔心，儘管我們註定喪命，但是希望永存。聖光終將勝利！$B$B親愛的，面對那些來自黑暗世界的恐怖力量，我並沒有想到死亡，這點令我倍感欣慰。我會想象你躺在我的臂彎，然後平靜地離開人世。$B$B克里斯托弗',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2885 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2885,'zhTW','嗨，$N。我從那本日誌中找到了一些有用的資訊。$B$B關於詹姆斯，我仍然一無所獲。但是我發現了亞蜜利亞家族的一些情況。$B$B雖然她和她的孩子們都在戰火中喪生，但是她的兄弟亞歷山大·考德爾卻僥倖活了下來；他現在在鐵爐堡荒蕪的洞穴中研究燃燒軍團的法術。$B$B她還有一個關係親密的表姊妹迪茲·斯諾班，斯諾班現在是阿拉希盆地的戰場軍需官，通常在奧格瑪走動。$B$B你應該順路拜訪一下他們中的一位吧。我想他們對失蹤的亞蜜利亞的訊息會很感興趣的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2886 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2886,'zhTW','你好，$N。你或許會對我的研究結果感興趣的。$B$B魯本和裡格利姆……嗯，他們撇下家人去了。即使家人們已經猜到失蹤計程車兵的命運，我想你還是跑一趟親口告訴他們吧。$B$B你可以在幽暗城軍事區找到魯本的前妻喬安娜·懷特豪爾。我不確定她能不能接受這個事實，你說話的口氣可得委婉些。裡格利姆的姑媽在暴風城中做孤兒監護員，那可是格令人敬佩的職務。$B$B無論未來命運如何，祝願您的努力能夠給你帶來幸運。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2887 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2887,'zhTW','$N，希望你收到這封信時一切安好。經過仔細研究，我發現了日誌記錄者的一些資訊。$B$B薩姆拉的父親邁爾斯·威爾什帶領被遺忘者和巨魔前往雷霆崖朝拜，你可以在預見之池找到他和他的亡靈隨從。$B$B托爾加撇下他的妹妹埃莉薩去了。埃莉薩整天都呆在達納蘇斯的月神殿，我覺得她簡直是個隱士。$B$B希望你能儘快拜訪他們中的一位，$N。對於托爾加或是薩姆拉的命運，他們或許還矇在鼓裡呢。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2888 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2888,'zhTW','$N，記錄員讓我把你發現的信件還給你，我想你或許對某些新線索感興趣的。$B$B據說“瓦古斯”家族唯一的倖存者居住在塞納里奧要塞。他名叫加隆·哈金斯。$B$B下次你路經那兒的時候應該找他談談。他或許會對我們的發現感興趣的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2889 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2889,'zhTW','你好。我總算擠出時間研究了你在天災那兒找到的信件。儘管這相當耗費精力，但是我已經找到亡者尚在世間的親人了。$B$B麥克斯韋爾有個叫薩瑞娜·克羅姆溫德的姊妹，她在藏寶海灣經營一家武器店。我不清楚這兩人在血緣上有多親，但是如果你路過那兒的話，就去找她談談吧。在動盪不安的日子裡，給個準信兒也是好事。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2890 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2890,'zhTW','我終於找到了那些曾與你搏鬥計程車兵們的資料。線索非常難以追繼，這個家族的家譜記錄實在是非常不完整，不過，我最終還是挖掘到了一些親緣關係。$B$B你能相信嗎？聖光之願禮拜堂的護理者奧林其實是克里斯托弗的兒子。如果他能知道他父親的訊息，想必會安心不少。如果你願意在瘟疫之地為銀色黎明再效力一次的話，拜託，請與他談談吧。這將是一件大善之事。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2891 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2891,'zhTW','紀念聯盟最高指揮官安度因·洛薩，一個為了捍衛他的國王、他的臣民和他的家園而不惜犧牲一切的英雄……$B讓我們的敵人記住我們的名字，讓我們的夥伴為我們的犧牲而感到榮耀，我們是洛薩之子。——圖拉揚將軍',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2892 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2892,'zhTW','這裡長眠著一個勇敢的苦工。他試圖抵抗，但只來得及放了個屁。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2905 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2905,'zhTW','這裡有一個灰燼之罐。這些灰燼是我的精神，我的熱情和我的本能需要。全部都被他們摧毀了。願所有來到地獄火這淒涼土地的人都記得這死去的苦工。他為了聯盟流血流汗，被部落逼的徹底發瘋，因為那些邪惡，沒有靈魂的人將他的最愛毀滅。他們因為他的苦力而享受，願他們也因為他的憤怒而痛苦。或許不是在這個世界，而是在之後的每一個世界。這是我的宣言，我嚴肅的誓約，也是我永恆的承諾。我會為我的苦難報復。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2906 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2906,'zhTW','偵察島嶼區域並返回報告。$B$B切記千萬別被抓住！$B$B不要讓我失望，卡蒂瑞絲！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2907 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2907,'zhTW','這份草圖用“X”記號標出了沙德拉洛和其他三座神殿以及被偷走的獅鷲卵的所在地。這些記號分佈在東部神殿的南邊、東部神殿東北邊的一座小房子、接近位於中央湖東邊的聖壇，以及南部神殿的斜面，靠近“流亡”字樣的地方。$B$B羽須的日記寫著他打算將該資訊傳遞給弗斯塔德·蠻錘，並希望他能派出一批戰士來奪回被偷走的獅鷲卵。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2909 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2909,'zhTW','迪亞索魯斯，$B$B我相信你能收到這封信。這些惡魔沒有頭腦。除了考慮自己指甲和鞭子，或者用頭上的尖刺四處頂撞。我根本不敢利用他們來為我們戰鬥，那是玩火自焚！$B$B可悲的是，我卻一直希望有那麼一天，我們可以控制一些獸人，至少他們還稍許有些頭腦，知道服從命令。我們是不是應該在這附近補充一些獸人奴隸？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2910 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2910,'zhTW','有關暗夜精靈幫助德萊尼的報告是真的。他們正試圖在靠近薩提納爾北部的林歌神殿建造營地。我們應該聯合起來，在下一次滿月之前發起攻擊。如果現在能消滅掉他們，那他們將再也無法阻擋我們前進的步伐！$B$B此致，$B戈加農$B另：不要再把血墨水浪費在給我的魅魔寫情書上了！暗夜精靈少女最近很難抓到。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2911 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2911,'zhTW','迪亞索魯斯，$B$B我相信你能收到這封信。這些惡魔沒有頭腦。除了考慮自己指甲和鞭子，或者用頭上的尖刺四處頂撞。我根本不敢利用他們來為我們戰鬥，那是玩火自焚！$B$B可悲的是，我卻一直希望有那麼一天，我們可以控制一些獸人，至少他們還稍許有些頭腦，知道服從命令。我們是不是應該在這附近補充一些獸人奴隸？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2912 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2912,'zhTW','我想該是讓那些次等種族見識一下我們的力量了。西北邊的碎木崗哨是個很誘人的目標。我們應該聯合起來，在下一次滿月之前發起攻擊。如果現在能消滅掉他們，那他們將再也無法阻擋我們前進的步伐！$B$B此致，$B戈加農$B另：不要再把血墨水浪費在給我的魅魔寫情書上了！暗夜精靈少女最近很難抓到。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2913 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2913,'zhTW','雖然幾乎被擊敗$B他的勇氣仍然堅強$B拔劍出鞘$B命令地獄人群向前衝鋒$B$B因為那些暴力的日子$B不要箭，也不要劍$B尋找，不在戰鬥中也不在衝突裡，$B這是矮人領主的方法',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2914 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2914,'zhTW','……但她已經知道了。在她將自己的靈魂一點一滴的交換出去後，她已經認命的過著賤民的生活了。復仇已經值得了，或是她這樣想。$B$B但現在有個機會讓她重拾人性，所有的陌生人要交換的就是她的信任。$B$B“讓我來”，卡崔恩說。“我沒什麼好怕的。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2916 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2916,'zhTW','瓦茲德，$B$B黑暗之門再次開啟後，榮耀堡和索爾瑪得到了來自艾澤拉斯的武裝增援，我收到報告說他們計劃攻擊堡壘，同時燃燒軍團的威脅也仍然存在，這是不可接受的！$B$B不要讓鮮血熔爐的運作遇到麻煩！再那裡生產的邪獸人是我們通往勝利的鑰匙，立即增派守衛加強城牆的防守！$B$B相信我，你一定不會希望我去拜訪你。$B$B——伊利丹',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2917 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2917,'zhTW','瓦茲德，$B$B黑暗之門再次開啟後，榮耀堡和索爾瑪得到了來自艾澤拉斯的武裝增援，我收到報告說他們計劃攻擊堡壘，同時燃燒軍團的威脅也仍然存在，這是不可接受的！$B$B不要讓鮮血熔爐的運作遇到麻煩！再那裡生產的邪獸人是我們通往勝利的鑰匙，立即增派守衛加強城牆的防守！$B$B相信我，你一定不會希望我去拜訪你。$B$B——伊利丹',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2918 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2918,'zhTW','我做了這件事。我不記得我有做，但也沒有別的可能了。$B$B我以前犯過罪。我甚至還殺過一個無辜的人。但這次不同。$B$B我改變了。$B$B這些謀殺不是我的選擇。有一隻野獸住在我心裡。$B$B我會被追捕和迴避。我要躲起來。逃跑。埋葬屍體。$B$B當我真正瞭解是什麼在困擾著我時，我開始到外面走動。$B$B我感覺不到罪惡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2919 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2919,'zhTW','僕人，$B$B多年來的精心策劃毀於一旦。德萊尼和他們那可悲的領袖再一次從主人的手中僥倖逃生！他們甚至還偷走了我的船，並且讓它墜毀在艾澤拉斯世界！$B$B儘管艾瑞達間諜的計劃失敗了，但她卻可以告訴我們艾瑞達的具體位置，值得慶幸的是，德萊尼人一直不知道她的身份，我們可以繼續利用她來完成我們的計劃。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2920 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2920,'zhTW','與我們的間諜聯絡，準備向德萊尼人發起一次全面進攻，把他們統統幹掉，奪回我的飛船。你是艾澤拉斯世界唯一能與我取得聯絡，又能修復被那些野蠻人毀壞了的艾瑞達的人。$B$B不要讓我失望，侏儒。如果因為你的貪婪而影響到此次計劃，那麼你將會盼望自己早日死去，早日擺脫我對你施加的折磨。$B$B——太陽之王，凱爾薩斯·逐日者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2923 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2923,'zhTW','部落受人尊敬的領導者，$B$B我——洛瑟瑪·塞隆，奎爾薩拉斯地區統治者——非常榮幸的宣佈我們所知道的達克汗·崔希爾——天災軍團的指揮官陣亡了。$B$B達克汗在我們土地上的立足點是由辛多雷種族的評論家在先前無數次的協商中所建立的。我們希望這個事件能平撫所有你心裡可能有的異議。$B$B<署名>洛瑟瑪·塞隆',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2924 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2924,'zhTW','部落受人尊敬的領導者，$B$B我——洛索瑪·塞隆，奎爾薩拉斯地區統治者——非常榮幸的宣佈我們所知道的達克汗·崔希爾——天災軍團的指揮官陣亡了。$B$B達克汗在我們土地上的立足點是由辛多雷種族的評論家在先前無數次的協商中所建立的。我們希望這個事件能平撫所有你心裡可能有的異議。$B$B<署名>洛索瑪·塞隆',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2925 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2925,'zhTW','空間飛船維修傻瓜指南，作者：加姆斯·凱斯$B<這本書的書頁是用某種閃閃發光的材料製作的，上面的高科技圖表詳細描述了維修空間飛船的技術細節。這本小冊子的開篇題目是“向量線圈破裂的應對及避免措施”。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2926 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2926,'zhTW','$B$B備註——我們的大師常收到外域捎來訊息回覆索爾的問題。答案是，當然，是的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2927 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2927,'zhTW','備註——我們的大師常收到外域捎來訊息回覆索爾的問題。答案是，當然，是的。$B$B<這封信額外印著希爾瓦娜斯·風行者的封印。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2930 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2930,'zhTW','$N，$B$B血鑄三叉矛的創造需要許多稀有又易變的材料，才能製作出最佳手工的可怕武器。我會將材料清單從最容易到最難取得的順序排列。$B$B別忘記你也一定要在材料被接受，開始鑄造之前取得你的血騎士徽記。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2931 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2931,'zhTW','憤怒之血——為了恰當地鍛鍊武器的金屬，它一定要在憤怒之血裡被冷卻。雖然大部份惡魔的血液都有實質力量，但普通的血卻不足以鑄造你的三叉矛。$B$B謹慎詢問奧格瑪的術士之後對尋找鮮血的補給有了幫助。怒焰裂谷裡的燃刃祭司擁有一種充滿鮮血的寶珠，那就是我們要製造你武器所需的東西。我聽說那顆寶珠由一個自稱祈求者耶戈什的獸人守衛著。$B$B小心行動，所有和惡魔力量的往來都要注意。握有這樣強大的物體時你永遠也不知道會發生什麼事。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2932 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2932,'zhTW','一箱血鑄錠——只有一箱，鋼鐵是很好的金屬，但由它鑄造的武器則不值得注意。血鑄錠代表一種極好的金屬，而它的製作過程一直是個秘密。傳說任何敢觸碰並使用這個金屬的鐵匠都被詛咒了，但我們的工匠已證明這是個謬論。$B$B這個金屬的名聲增加了它的稀有度，但被遺忘者卻聲稱在影牙城堡可能有補給。一個叫做藍登·史帝威爾技藝高超的鐵匠非常好奇，便走私了一箱血鑄錠。沒人知道他把東西藏在哪裡，但我們的訊息告訴我們那名鐵匠現在被囚禁在城堡的地下城裡。用盡所有方法取得那箱血鑄錠。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2933 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2933,'zhTW','一顆被汙染的科爾寶石——博學者的墓碑記載著這些寶石曾被一些施法者用來保留他們的魔法能量，讓他們更致命。雖然純淨的寶石可以安全地被中級施法者使用，但它們對我們的目的而言仍嫌太弱。$B$B在黑暗深淵的洞穴中，納迦施法者將科爾寶石注入他們自己的黑暗力量，增強它們的力量，以便在你的三叉矛中完美地被使用。在你弄到需要的寶石之前先無情的殺了他們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2934 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2934,'zhTW','你將戴上的徽記最後一次是被晨星家族中一個勇敢無懼的血騎士所配戴。他典範的奉獻是你在軍隊中生活的好預兆。$B$B血騎士晨星對死亡之域的天災軍團要塞率領了一次大膽，但不成功的攻擊。他的屍體就在他死去的地方安息，與我們最強勁的敵手鎖在戰鬥中。找到他，$N，並將他的徽記帶來給我。你的成功會為他，為你，為所有真正的血騎士帶來榮耀。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2936 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2936,'zhTW','你發現了神龕的所在地！在進一步的偵察中，你發覺到一股強大而神奇的力量籠罩著島嶼。站在神龕之前，你感到很不舒服……甚至有一絲不安……$B$B神龕邊上的銅牌寫著：$B$B“這裡是達斯雷瑪的神龕，以此紀念一位高貴的精靈。讓所有看到它的人都牢牢地記住他作出的犧牲，因為他，我們的生命才得以延續，奎爾薩拉斯感謝他。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2937 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2937,'zhTW','我眼睜睜地看著他們無情地鞭打他，這對於那位殘忍的軍官來說似乎早已是稀鬆平常的事情。殘酷的鞭笞讓我幾乎崩潰。$B$B當我看到守備官撒魯安被他們鞭笞時，我開始哭泣。不是因為恐懼……而是因為看到一位執政官被如此折磨而感到悲傷。如果我能逃出去，如果……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2938 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2938,'zhTW','過了很長一段時間，守備官失去了知覺。他已遭受太多的嚴刑拷打。那個殘忍的傢伙——他的名字似乎是叫瑪提斯——竟然往守備官那早已傷痕累累的身體上潑灑腐水。但撒魯安並沒有清醒過來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2939 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2939,'zhTW','我想大聲尖叫，卻只能發出微微的聲音。因為剛才的反抗行動，我很快就被打倒在地。當我躺在地上時，看到瑪提斯在撒魯安的屍體旁邊來回走動，顯得非常焦慮。他曾說過如果撒魯安死於他的折磨，那個希隆娜絲會活活要了他的命。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2940 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2940,'zhTW','希隆娜絲計劃把撒魯安……$B$B<由於作者的死去，故事突然中斷了。接下去的記錄是一片空白。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2941 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2941,'zhTW','女伯爵莉亞德琳$B$B最近被俘虜的生物製造了一些麻煩，讓我們一些最重要的裝備遭到損壞。恢復一切的工作讓我的博學者和資源都大大的減少。我已將事件報告呈交給大博學者洛摩斯，但他回覆的速度很慢。我擔心沒有下列的物品我們會被迫縮減運作，而你知道那對你的騎士們而言代表著什麼。$B$B如果你可以有任何的幫助，我已在下一頁列好了材料清單。我們會感謝你的軍隊所能提供的任何協助。$B$B博學者阿斯塔樂·血誓',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2942 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2942,'zhTW','*40塊符文布$B$B*6條奧金錠$B$B*10根太陽草$B$B*5個黑暗符文$B$B*150金',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2943 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2943,'zhTW','太陽之王的公告$B$B炎鷹部隊——我親愛而忠誠的孩子們——我為你們而驕傲。你們在艾澤拉斯世界中執行的任務對於我和主人來說都是至關重要的。再過不久，風暴要塞的增援就將透過太陽之門到達秘血島。我們將奪取艾克索達，幹掉所有藍皮膚的雜種。維倫將會為他的罪行付出代價。$B$B——太陽之王，凱爾薩斯·逐日者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2944 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2944,'zhTW','<HTML><BODY><IMG src=\\"Interface\\Pictures\\24475_gordawg_256\\"/></BODY></HTML>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2945 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2945,'zhTW','$B$B$B$B$B荊棘谷的青山',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2946 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2946,'zhTW','第一天和我們預想的完全一樣。我們大部分時間都忙於為建立營地做一些必要安排。我在一條淡水河的入口處找到了一個理想的駐紮點。根據旁邊被廢棄的古老碼頭判斷，這個地方曾經有人住過，不過只有時間才能說明這裡究竟住過什麼人。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2947 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2947,'zhTW','我為這次探險召集了艾耶克·羅歐克、埃爾加丁爵士和我忠實的僕人巴尼爾·石罐。我曾經在保衛聯盟的戰鬥中與艾耶克的父親並肩作戰，看著艾耶克成長起來讓我有種很特別的感覺，她父親對她進行了嚴格的武器技能訓練。看到她熟練地使用弓箭，我不禁懷疑她的血管裡是否流淌著精靈的血。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2948 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2948,'zhTW','埃爾加丁爵士來自人類的貴族家庭。他的父親埃爾加丁伯爵以慷慨大方而著稱。第二次獸人戰爭之後，正是因為他父親的遊說和疏通，石匠公會才在重建暴風城時獲得了更好的工作條件。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2949 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2949,'zhTW','接下來的幾年，在暴風城背叛了石匠公會後，埃爾加丁爵士開始厭惡他的貴族身份。他不願因繼承了他父親的高貴血統而在貴族中獲得崇高的地位。不過我離題了。這個故事的主題不是政治文章或者人物傳記，而是要敘述我在荊棘谷的青山中獵捕的經歷……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2950 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2950,'zhTW','天一亮我們就起來了，巴尼爾開始準備早飯。我注意到艾耶克有點心煩意亂。今天的旅途將會漫長而危險，我們的狩獵行動也許會把我們帶向危險。注意力不集中就很容易導致錯誤，甚至是災難。艾耶克一直都在盯著在河邊清洗餐具的巴尼爾。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2951 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2951,'zhTW','正在我準備問艾耶克為什麼一整天都無精打采的時候，她突然從箭囊中抽出一支箭，向可憐的巴尼爾射去─當然她的目標並非巴尼爾。瞠目結舌的巴尼爾向後退了幾步，看著自己身後的一隻巨大的鱷魚浮出水面，艾耶克的箭正好射在了它的兩隻眼睛的中間。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2952 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2952,'zhTW','我們向西部進發，在繁茂的枝葉之間穿行。我們小心翼翼地走在厚厚的落葉上尋找獵物。整個早上都在令人沮喪的沉默中度過，山谷裡沒有任何激動人心的東西，連一陣微風都沒有。到了下午，探險隊開始變得不安，巴尼爾的腳步不再像一個追蹤獵物的獵手那樣謹慎，而是笨拙地踏著步，在枯葉或落枝上踩出響亮的聲音來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2953 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2953,'zhTW','埃爾加丁爵士似乎被絆了一下，將手重重地拍在巴尼爾的肩膀上。我和艾耶克瞥了一眼，以為他會責備粗心大意的巴尼爾。然而埃爾加丁爵士卻擺了擺頭，示意我們觀察旁邊的一棵倒下的大樹。那裡正有一雙炯炯有神的黑眼睛瞪著我們，眼睛下面還有一口如剃刀般鋒利的牙齒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2954 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2954,'zhTW','那是一隻雄性的荊棘谷猛虎。我還沒來得及拿起槍，埃爾加丁已經拉開他的弩，向那頭野獸射出了箭矢。這一下未能射中要害，不過還是重重地射入了猛虎的左腹。老虎想要逃跑，但是它傷得太重，只蹣跚走了幾步就被巴尼爾的斧頭擊中，倒地身亡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2955 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2955,'zhTW','這次成功的獵殺給探險隊帶來了一些愉快的心情，巴尼爾給大家倒了些蜜酒，但是這種喜悅只是暫時的。當我們準備把屍體運回營地時，叢林裡傳來了一陣可怕的嚎叫聲。在我的一生中，我從來都沒有聽到過如此可怕的、幾乎讓人全身血液都凝固的聲音。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2956 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2956,'zhTW','在遍佈岩石的懸崖上，一隻迄今為止我見過的最巨大的獵豹在晚霞的映襯中冒了出來。我笨拙地開了槍，但是那隻豹絲毫未動。它又咆哮了一聲，比第一次的聲音更大，然後就消失了。$B$B我們把東西收好，然後神色黯然地返回了營地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2957 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2957,'zhTW','我向探險隊員保證我們第二天將去狩獵黑豹，因為整個艾澤拉斯地區的豹皮都非常搶手而緊俏。正是因為有這種需求的存在，才有那麼多的獵人、陷捕者和毛皮商人以聯盟的名義勇敢地獻出了他們的生命。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2958 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2958,'zhTW','艾耶克和埃爾加丁爵士很想知道如何有效地使用矮人步槍狩獵。所以我讓這兩個對此一無所知的人類把他們的弓箭留在營地中，然後讓巴尼爾給他們裝備了一些鐵爐堡最好的武器。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2959 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2959,'zhTW','這一天，我們沿著一些新的黑豹足跡向南進發。很快我們就來到了一座架著巨大索橋的峽谷。看到這個工程奇蹟的時候，我忍不住想起了布萊恩對這一帶的描寫。我們常常認為巨魔是原始而無知的族類，然而當我認識到這座索橋所體現的精湛技術時，我開始認為巨魔的建造技術已經達到令人難以想像的地步。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2960 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2960,'zhTW','不久前，艾耶克追蹤獵豹到西南方。我們靜靜地走著，槍支隨侍在旁，等待獵物出現。附近的雜樹林一發出嫩枝劈啪聲，立刻就吸引了我們的注意力。嚴肅地看巴尼爾一眼，就足以表達我的想法。巴尼爾慢慢地壓低他的來福槍。這不是我們自己的獵殺是為了我們的人類同胞。無數只獵豹在我們冒煙的槍管下喪命。這次的獵殺是屬於人類的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2961 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2961,'zhTW','艾耶克和埃爾加丁爵士悄無聲息地用槍瞄準著正在晃動的樹叢。正午的強烈陽光照在我們身上，當埃爾加丁爵士終於扣動扳機的時候，他的額頭流下了一絲汗水。一聲槍響過後，濃密的樹葉被打得亂飛，一隻非常漂亮的大黑豹向離弦的箭一般衝向了平原。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2962 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2962,'zhTW','當黑豹沿著林木邊緣奔走時，有兩個獵人一直瞄準著它。他們互相照應著一起行動，巴尼爾看看我，用眼光詢問是否要開火，我搖了搖頭。這次狩獵行動是要鍛鍊那些人類，而不是我或者巴尼爾。埃爾加丁扣動了扳機，但沒能打中黑豹。顯然，他對獵槍所產生的強大後座力還沒有足夠的認識和準備。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2963 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2963,'zhTW','他把槍重重地往手臂上拋。槍管歪向一邊，正好落在艾耶克的槍下面。艾耶克選了精確的時機扣下她的扳機。來福槍的準心笨拙地鎖定在林木線上，發出一聲清楚的巨響。一群小鳥從天空中尖叫著飛過，分散在各個方向。一條羽狀的煙霧從樹中往天上劃過。我們畏怯地看著巨大的樹枝直直地掉落在逃跑的獵豹身上，壓斷了牠的背。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2964 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2964,'zhTW','過了幾個星期，我們的豹皮和虎皮儲備已經相當充足了。於是我決定將探險隊的注意力轉向一個新的挑戰：迅猛龍。$B$B隊伍中的兩個人類雖然十分感激我和巴尼爾對他們進行的訓練，不過他們還是決定不使用我們提供的火槍去打獵。艾耶克更喜歡她那調校完美的強弓，而埃爾加丁爵士離開營地的時候總是拿著他的弩。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2965 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2965,'zhTW','我們在黎明時動身向南出發，一路穿過了伽什廢墟。巴尼爾說他擔心會遇到血頂部族的巨魔。我告訴巴尼爾，比起生吃我們這些冒險者來，血頂部族更關心的是如何摧毀他們的敵人，劈顱部族。不過巴尼爾顯然沒有因此而感到一絲的寬慰。但是，我有一把上好膛的火槍、滿袋的黑火藥，還有三個本領高強的獵人做伴，所以我一點也不擔心會遭遇敵人的埋伏。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2966 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2966,'zhTW','我曾經在戰場上面對過巨大的煉獄火，還有從四面八方衝過來的燃燒軍團。如今對我而言，一群蠻橫的巨魔就跟丹莫洛的長耳大野兔一樣不值一提。$B$B我們平靜地穿過伽什廢墟，巴尼爾總算是放下了他那顆惴惴不安的心。我們繼續向西邊的無盡之海前進，並繞了南邊的祖昆達廢墟。當我們攀上海邊的懸崖之後，第一隻迅猛龍出現在我們面前。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2967 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2967,'zhTW','這頭野獸壓根沒有發現我們的存在，事實上，它從我們這兒收到的第一個問候就是射入它雙眼間的子彈。$B$B埃爾加丁爵士大聲歡呼，艾耶克則讚許地向我點了點頭。我從包裡拿出菸斗，想好好慶祝一番。巴尼爾奔上山坡去拖迅猛龍的屍體。我看著被擊倒的野獸，心裡就像以前每一次殺死獵物時那樣充滿著興奮和滿足。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2968 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2968,'zhTW','但是我還沒有時間體會這次獵殺的愉悅，就赫然發現山頂上出現了幾個影子─就在可憐的巴尼爾的正上方。$B$B“快跑，巴尼爾！”我大叫道。艾耶克、埃爾加丁和我立刻向追逐巴尼爾的迅猛龍射擊，一時間子彈和箭矢亂飛，混亂之中，我們當中的某人還射殺了一隻迅猛龍。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2969 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2969,'zhTW','我們匆忙射出的子彈為巴尼爾贏得了足夠的逃跑時間。他大聲叫嚷著跑下山丘，重新回到隊伍之中。我們急忙離開了叢林，因為有一群兇殘的鞭尾迅猛龍正在追尋著我們的足跡。$B$B現在攻守易位，獵手變成了獵物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2970 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2970,'zhTW','我帶著隊伍繼續往海邊走去，希望在那裡的海岸線旁找到某個可以避開迅猛龍的地方。但是在匆忙之中，我們跑到了一處危險的高地，這是個可怕的錯誤，全都是我的錯。我們停在了一個陡峭的懸崖邊，而那些迅猛龍距離我們僅有幾步之遙。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2971 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2971,'zhTW','我慢慢地向前走，高舉我的槍。我已讓這些勇敢的獵人走向死亡。我死也要保衛他們。鞭尾迅猛龍特別兇猛，牠們無情的嗜血性是出名的。牠們的數量遠遠超過我們。但我如果沒有先讓牠們灑幾滴血就讓牠們殺了我和同伴，那我會下地獄的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2972 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2972,'zhTW','艾耶克和埃爾加丁爵士拿起他們的武器，守在我的兩側，我們的背後就是大海。巴尼爾沮喪地嘆了一口長氣，然後拿起了他的斧頭。迅猛龍在慢慢地逼近，它們高傲地注視著我們，因為它們知道我們已經無路可逃了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2973 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2973,'zhTW','突然之間，奇蹟發生了。我們聽見一隻白虎清晰而可怕的吼聲從對面傳來。雖然迅猛龍數量眾多，但它們一聽到叫聲便立刻四散逃竄。那隻老虎像一道白色閃電般從我們身前跑過，撲向一隻迅猛龍。不需要任何命令和溝通，我們四個人都明白：這正是逃跑的最佳時機。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2974 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2974,'zhTW','我們一路狂奔回到了營地，絲毫不敢放慢速度。深夜，我們圍著篝火靜靜地坐在一起，大家心裡都明白，我們是被奇異的命運所拯救，這就是狩獵高手活動所帶來的風險：我們在和命運玩遊戲。然而，我們之中的每一個人都可能會在未來的某一時刻面對命運嚴峻的考驗。我這個老矮人感到高興的是，這一時刻並非發生在荊棘谷的青山中。$B$B——完——',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2975 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2975,'zhTW','蠢貨，$B$B去找食物。藍色的味道很好。蘭特瑞索說找到藍色的就行。把食物帶回去給拉普。他吃了後蠢貨再吃。沒問題吧？動作快一些，否則拉普會把你吃掉的。$B$B——拉普',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2976 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2976,'zhTW','（1）酒鬼拉里克：食人魔。他從未離開小酒店。很壞。很醜。很胖。很壞。又很胖。$B$B[下一頁]',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2977 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2977,'zhTW','（2）庫什庫什：這個從贊加沼澤來的討厭小孢子人在贊加沼澤和泰羅卡的邊界有一個蘑菇園。在“那是什麼味道”的遊戲中輸了很多金子給薩薩拉比姆。想用叫做空莖的蠢蘑菇付給薩薩拉比姆。跟他說這跟黃金一樣好！哈！$B$B[下一頁]',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2978 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2978,'zhTW','（3）弗魯恩：鴉人。輸給薩薩拉比姆許多金子。鴉人因為沒有付錢就被薩薩拉比姆殺死了。現在鴉人的鬼魂在白骨荒野的西南方漫無目的的走著。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2979 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2979,'zhTW','奧雷巴根鬚是泰羅卡森林裡一種普遍的根鬚植物，是構成泰羅卡森林的奧雷巴樹叢附近搜尋向上翻起的根莖。$B$B沼澤莓只生長在贊加沼澤。只能在安葛洛什營地找到它——就在沼澤的西北區。小心那些守衛珍貴莓子的食人魔！$B$B塔拉蕨或許是這清單上最容易取得的草藥。你可以在塔拉盆地——加拉達爾的南方找到它們，一般生長在水邊。$B$B清單上最後一種草藥是刀鋒山特有的植物。你可以在贊加沼澤北邊找到刀鋒山。龍脊草生長在守衛著刀鋒山峽谷鋸齒狀岩石地形的盡頭——等你見到了刀鋒山就會知道我在說什麼了，那個岩石地形就像是一排排的尖銳牙齒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2981 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2981,'zhTW','我的僕人，這些獸人正遇上一個小小的麻煩，我想要你親自去搞定它，我們的部隊正在進攻黑暗之門的守衛，他們的精力都被浪費在了索爾瑪。這是命令！——阿拉修斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2982 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2982,'zhTW','我的僕人，這些獸人正遇上一個小小的麻煩，我想要你親自去搞定它，我們的部隊正在進攻黑暗之門的守衛，他們的精力都被浪費在了索爾瑪。這是命令！——阿拉修斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2983 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2983,'zhTW','要讓飲用者看見彩色幻象的亡靈，就一定要收集到一些特定的材料。$B$B首先，西納格蘭的山丘戈隆的眼球，靠近燃燒軍團鑄魔營地，戰槌山的南方。$B$B在西納格蘭也可以找到大型風鵬。只有完美的品種才行！$B$B最後，在納格蘭西邊和西南邊有老邁的裂蹄牛。$B$B收集這些物品再回來找我！動作快！$B$B——尼特林',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2984 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2984,'zhTW','<翻過數頁你根本無法理解的“科學論文”後，最後一頁末有幾行字跡潦草的記錄……>$B對不起，老大。看起來虛空風暴即將要爆炸，這場爆炸會席捲外域的大部分地區。我不能完全肯定，但我想這應該和血精靈在法力熔爐所做的一切有關。幸好您建造了一艘火箭！——哥白尼$B又及，我能與您一起離開嗎？在您經過扭曲虛空的時候一定會需要一個虛空學家的！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2985 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2985,'zhTW','將軍，$B$B我們正在堅守命運階梯的防線，但燃燒軍團不斷向我軍發起攻擊。他們一定在附近部署有前沿基地，但我們的斥候仍然沒有找到它。儘管聯盟答應幫助我們，但沃還是擔心燃燒軍團強大的兵力會擊垮我們的防線。為避免黑暗之門被攻破，請盡您所能來幫助我們吧，否則我們將陷入無盡的噩夢之中。$B$B沃雷恩中將',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2986 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2986,'zhTW','當娜安妮站起身時，那個頭髮灰白的戰士狠狠地瞪了她一眼。“我想你來這裡是為了拿回殺死魚人所應得的獎勵吧？”$B$B她的視線慢慢地移到他身上那把閃閃發光的腰刀上。“那得看是什麼獎勵了，馬庫斯。”她嬉笑著撥弄她的頭髮，裝作沒看到因她的出現而帶給他的不安。“我也許不想得到任何獎勵呢。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2987 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2987,'zhTW','馬庫斯帶著恐懼和憤怒一步步走向她。“你不能跟我討價還價！”他停了一會，鼓起勇氣靠向她嬌小的身軀。他們的唇熱烈地觸碰著，瞬間將她的霜甲術化為一股灼熱的水蒸氣。$B$B“那麼，任務的下一步是什麼？”她笑著問，眼裡閃爍著興奮的光芒。$B$B<接下去的幾百頁都在寫這些，故事本身沒有任何實質性的進展。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2988 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2988,'zhTW','這個奇怪的物體看起來有點像是一個工程學的裝置，但應該是你之前從未見過的裝置。從它的外表上看，不管你覺得它是什麼東西，它一定是已經被使用過的。從附近的屍體來看，你不由得認為它就是這一切慘劇的罪魁禍首。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2989 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2989,'zhTW','指揮官，$B$B這個密碼要被送到祖魯希德那裡。在進一步的通知之前，這個物品必須在他的保管之下。$B$B——伊利丹·怒風',0);
