INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2991,'zhTW','<HTML><BODY><BR/><P>簡略翻譯版……</P><BR/><P>以光芒之名，以太陽的光芒之名，</P><P>血之後裔們啊，</P><P>敵人正長驅直入。</P><P>血之後裔們啊，</P><P>以光芒之名，</P><P>消亡的血之後裔們啊，</P><P>敵人正長驅直入。</P><P>啊，血之後裔們啊，</P><P>以太陽的光芒之名。</P><P>消亡的血之後裔們啊，</P><P>他們正長驅直入。</P><P>啊，血之後裔們啊，</P><P>以太陽的光芒之名。</P><P>太陽的光芒。</P></BODY></HTML>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 2992 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (2992,'zhTW','<HTML><BODY><BR/><P>薩拉斯語版……</P><BR/><P>Anar\'alah， anar\'alah belore，</P><P>Sin\'dorei，</P><P>Shindu fallah na.</P><P>Sin\'dorei，</P><P>Anar\'alah，</P><P>Shindu sin\'dorei，</P><P>Shindu fallah na.</P><P>Sin\'dorei，</P><P>Anar\'alah belore.</P><P>Shindu sin\'dorei，</P><P>Shindu fallah na.</P><P>Sin\'dorei，</P><P>Anar\'alah belore，</P><P>Belore.</P></BODY></HTML>',0);
