INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3039,'zhTW','不要在我的墓碑前哭泣，$B我不在那裡，我沒有長眠。$B$B我是凜冽的寒風，$B掠過諾森德的雪原。$B$B我是溫柔的春雨，$B滋潤著西部荒野的麥田。$B$B我是清幽的黎明，$B瀰漫在荊棘谷的林間。$B$B我是雄渾的鼓聲，$B飛躍納格蘭的雲端。$B$B我是溫暖的群星，$B點綴達納蘇斯的夜晚。$B$B我是高歌的飛鳥，$B留存於美好的人間。$B$B不要在我的墓碑前哭泣，$B我不在那裡，我從未長眠。',0);
