INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3054,'zhTW','犛牛人總會圍在篝火旁講述元素憤怒號角的傳說。一代又一代聽著傳說長大的戰士們總在徒勞地尋找著號角的埋藏之地。和其他人一樣，偉大的雷蹄發誓要找到這支號角，遂離開了家人和村莊。$B$B雷蹄勇敢地與嚴寒和兇猛的元素生物對抗，並獨自爬上了霜刃峰。當雷蹄爬上山頂時，北風親自出來迎接他。這位偉大的戰士深知北風是不會輕易交出號角的，便向它發出了挑戰。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3055 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3055,'zhTW','雷蹄和北風戰鬥了整整五天。在第六天破曉時，他將北風從霜刃峰趕了出去，並得到了號角。傷痕累累的雷蹄走出群山，向他居住的村莊走去。$B$B但北風聚集了一群低階元素生物，在雷蹄的家鄉附近襲擊了他。虛弱的戰士無法再次抵擋這次進攻，北風成功地報了仇。他將號角分成兩半，裹上閃閃發光的裝飾物，分別交給了兩個強大的鱷魚人酋長，作為他們權威的象徵。$B$B<原始的敘述到這裡突然結束了。但某個人，可能是馴風者巴蘭，似乎在後面加上了一些補充。>$B$B按照北風的命令，鱷魚人酋長將這些珍貴的聖物傳給了他們的子孫。直到今天，布戈布咕酋長和咕戈布咕酋長還儲存著號角的碎片。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3057 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3057,'zhTW','懸賞：赫米特·奈辛瓦里',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3065 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3065,'zhTW','元素領主的忠誠僕人，就是此時此刻。$B$B我們在黑暗中受苦太久了，等候著我們的時刻，服務我們的主人，追尋著終將來臨的末日。現在，雖然拉格納羅斯姑息的火焰燃亮了整個夜空，我們現在握有了利器，能大洪水掀起戰爭與混亂！$B$B炎魔如今被禁錮在我們的世界。他無法施展他全部的力量，但依舊令人畏懼。將和它同樣令人畏懼的敵手帶到這個世界來，他們的衝突將會掀起一場元素大戰，帶來我們所期待的末日。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3066 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3066,'zhTW','耐普圖隆的部下中，有個名叫埃霍恩的強大冰霜領主。至今他仍在聚集力量要對拉格納羅斯掀起戰爭。他只需要一個通道來進入我們的世界；一個由我們提供的通道。我們有盟友，有地點。我們也有力量與意志。$B$B和我們忠誠的新盟友與客人之間的最後協商，將會在一個安全遙遠的地方，在我們梣谷原始據點的西北邊。$B$B在這個無知的“節慶”結束前，埃霍恩將會在黑石山的深處面對拉格納羅斯。這個世界將會因為他們釋放出來的力量而傾覆。$B$B我們一切的努力都是為了這一刻。我們的主人將會再次興起，彼此征戰，並且將艾澤拉斯撕裂成碎片。$B$B我們將會活在時間的終結，我的兄弟。肩負起你的任務。努力下去。我們終將獲勝！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3067 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3067,'zhTW','古拉莫什：$B$B我已經派出復仇軍的代表前去與你會晤。杜爾希大使告訴我，還有許多像他一樣的人願意加入到我們的事業中來。請你探清他的虛實，看看是否有用得著他的地方。$B$B如果他確實對我們有幫助，我可以考慮吸收更多他們的人。$B$B不要犯傻，看完信後立即把它燒了！$B$B- M',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3068 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3068,'zhTW','（獸人語）部落的榮耀！Lok\'Tar ogar！——就是這幾個字讓我跟部落連結在一起！對任何一個部落的戰士而言，這幾個字是最神聖且基本的真理。$B$B我將我的血肉無條件獻給大酋長，我將完成所有大酋長的意志，我就是大酋長命令下的武器。$B$B從此刻起我活著，直到世界末日英勇赴死——為了部落！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3069 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3069,'zhTW','$N，$B$B如果你正在讀這封信，那就代表你還好好的活著——或者至少還有眼睛可用。$B$B我必須為這樣保密緻歉。阿格瑪要求每封信件再寄出之前都要先被讀過一遍——那裡有太多的叛徒和竊賊了，相信你從懸賞佈告上也看得出來。這裡面有許多棘手的事情，新來的警衛很可能會誤會。$B$B對一個部落計程車兵而言，失敗是絕對的。失敗代表了死亡，而死亡沒有絲毫交涉或詮釋的空間。他們只能夠冀望至少能光榮的死去。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3070 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3070,'zhTW','但勝利……勝利有許多不同的意義。也許你已經注意到了，庫卡隆先鋒全軍到齊。大酋長派了他的精英守衛來諾森德協助取勝。他們以及你和其他的英雄們，正把巫妖王和他的軍隊推向不可避免的終局。你每克服一項挑戰，我們就更靠近從世上驅逐阿爾薩斯和天災軍團一步。$B$B但這就是我們兩難的局面。因為我們在諾森德的作戰是由年輕的地獄咆哮所主導。每一次的勝利都讓此地的部落軍隊士氣高漲，然後傳遍全艾澤拉斯。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3071 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3071,'zhTW','不幸的是，地獄咆哮使用的是如此野蠻的戰術。隨著勝利漸近，地獄咆哮更加有理由認為他的方法是好的，而這將我們帶向了我們許多年都未曾接近的東西：黑暗。$B$B我已經派了我的兒子去指揮我們在憤怒之門的部隊。我知道他會光榮地作戰，而且我希望我們的部隊會注意到他的勇氣與不屈不撓，並且向他學習。他在我不能親臨的地方展現我的心靈與力量……我希望你能夠當我的耳目。我們能夠一起把這件事正確地做好。$B$B鮮血與雷霆……願你的到來能夠將兩者帶給牠們。$B$B薩魯法爾',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3072 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3072,'zhTW','我們一切的努力都是為了這一刻。我們的主人將會再次崛起，彼此征戰，並且將艾澤拉斯撕裂成碎片。$B$B我們將會活在時間的終結，我的兄弟。肩負起你的任務。努力下去。我們終將獲勝！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3073 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3073,'zhTW','女王陛下，$B$B我們發現眠月花園裡的魔網節點已經被藍龍軍團釋放出來了。他們使用湍流之針摧毀了頂石，但是他們並沒有把能量傳回魔樞，而是利用一系列焦點，強行增強能量，並將其注入碧藍巨龍聖地的地下。$B$B無庸置疑，一旦這些魔法破土而出，一定會造成悲劇性的後果。森林裡的古樹、卡魯亞克，以及該地區的其它生物均已經受到了負面影響。幸運的是，$N，也就是現在您面前的這位$c，可以幫我們追查並解決這些問題。$B$B在我看來，$N是解決龍眠神殿目前所面臨的危機的最大助力。我謙卑地懇請您將$G他她看做珍貴的資源，妥善地加以委任。$B$B您永遠的僕人，$B$B茉德拉$B大法師，六人議會成員',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3074 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3074,'zhTW','女王陛下，$B$B我們發現眠月花園裡的魔網節點已經被藍龍軍團釋放出來了。他們使用湍流之針摧毀了頂石，但是他們並沒有把能量傳回魔樞，而是利用一系列焦點，強行增強能量，並將其注入碧藍巨龍聖地的地下。$B$B無庸置疑，一旦這些魔法破土而出，一定會造成悲劇性的後果。森林裡的古樹、卡魯亞克，以及該地區的其它生物均已經受到了負面影響。幸運的是，$N，也就是現在您面前的這位$c，可以幫我們追查並解決這些問題。$B$B在我看來，$N是解決龍眠神殿目前所面臨的危機的最大助力。我謙卑地懇請您將$G他她看做珍貴的資源，妥善地加以委任。$B$B您永遠的僕人，$B$B艾薩斯·奪日者$B大法師，六人議會成員',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3075 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3075,'zhTW','嗨！$B$B我不太擅長寫信，所以監護員幫我寫信給你。我只是想跟你說謝謝。因為你是個英雄，也許有天我也能像你這樣拯救人們。$B$B好啦，我要去外頭玩了。再次謝謝你這麼善良這麼強，你也是最$g帥:美的！$B$B——你的秘密仰慕者',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3076 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3076,'zhTW','<在這個嚴重燒燬的頁面上沒有可以辨識的字。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3077 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3077,'zhTW','安圖薩悄無聲息地爬過巨大的地下隧道，緊張地回頭張望，希望能看見快速移動的礦車。“他在哪兒……”她憤怒地咕噥著。突然，她發覺身後有東西在移動，便立刻停了下來。她緊張地將眼睛眯成一條細縫，並拔出了匕首。$B$B空曠的大廳裡響起一個嘶啞的聲音：“我還以為盜賊都喜歡跟在目標身後呢。”她迅速轉身，手中的匕首刺上了一面堅不可摧的盾牌。“我還以為聖騎士都是光明正大的呢。”她充滿信心地反唇相譏道，臉上帶著得意的笑容。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3078 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3078,'zhTW','她向前傾斜著身體，大聲數著數字，直到那看不見的泡沫伴隨著破裂聲消散。“十二秒？我知道你可以堅持更久的。”$B$B纖細的手指在他的護甲下輕柔地遊走，解開了他的胸鎧，將他暴露在寒冷的空氣中。“不要擔心，我親愛的馬庫斯，今晚還沒有結束……我才剛剛開始呢。”他伸出臂膀摟住她的腰，輕吻著她的脖子，使她忍不住笑了起來。$B$B<接下來的幾頁已經被翻爛了。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3079 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3079,'zhTW','阿比迪斯將軍的日記',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3083 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3083,'zhTW','目錄$B$B第一章——死亡與你$B第二章——保持食屍鬼的體形：七個簡單的鍛鍊步驟$B第三章——驅除寒冷：選擇合適的棺材$B第四章——墓地中的承諾：五十個愛情訊號$B$B<這本書保養得很好，似乎根本就沒有人讀過>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3092 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3092,'zhTW','阿比迪斯將軍的日記',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3093 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3093,'zhTW','那個聲音對我說，“到我這裡來。”從一開始我就知道這是我在夢中聽到的聖光之聲。終於來了！在多年的祈禱和行善之後，在多年與天災軍團的不懈抗爭之後，在這麼多次的失敗和復甦之後。$B$B終於來了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3094 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3094,'zhTW','那個聲音又出現了。“到我這裡來……”聖光命令我道。$B$B我猛然醒來，渾身冰涼，但是我的房間裡並不冷。我一定要加倍努力！明天我就要告訴高階修士，讓他籌備更多的祈禱會。不能再漫不經心的了！$B$B聖光已經注意到了我們的努力。我可以感覺得到！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3095 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3095,'zhTW','這一次我是在頭腦清醒的狀態下聽到的！那個聲音非常清晰，不過足足有一分鐘的時間，在這陽光明媚的暖和日子裡，我的呼吸居然冷到了霧化的地步。一名牧師注意到了這個情況，立即跪下來進行祈禱。$B$B但是沒有其他人聽到那個聲音。至少目擊者可以證明我並沒有發瘋。也許我應該讓蘭德雷進行一些禱告？$B$B我會讓喬丹和斯崔特對他們招募新兵的尺度進行更細緻的審查。我們的組織中已經充斥了太多毫無信仰可言的人，他們一心只想著毀滅亡靈，那樣是遠遠不夠的！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3096 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3096,'zhTW','指揮官和主教都很合作，其實他們也沒有別的選擇。斯崔特主教對此顯得尤其狂熱，他談到了十字軍的復興，併發誓要揪出組織中的所有意志不堅定者。$B$B我讓他不必操之過急。我並沒有打算要毀滅十字軍，不過我確實對於“組織最虔誠的骨幹力量前往諾森德為聖光而戰”的想法非常讚賞。我擔心他與裡克拉夫的友誼正在慢慢扭曲他的心智。話說回來，他們畢竟還有些用處。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3097 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3097,'zhTW','我會將十字軍的大部隊留在這裡，繼續剿滅後方的亡靈。我想，當他們結束這曠日持久的戰鬥之後，應該會解甲歸田，從此過上寧靜和平的日子。$B$B聽起來真不錯。一直以來，我們都在這片土地上南征北戰，為了從天災的魔掌中奪回我們的家園，為了讓我們的洛丹倫重歸榮耀，為了讓一切回到天災入侵之前，回到阿爾薩斯弒君之前……回到巫妖王出現之前。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3098 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3098,'zhTW','部隊中開始流行一個傳言，說是在不遠的將來的某一天，血色十字軍將發生翻天覆地的變化。斯崔特主教還給這一天起了個名字，叫做“血色黎明”。$B$B我會關注這一情況，不過我也能感覺到它的真相。我默默地祈禱，希望它給我們帶來的是福音，而非災難。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3099 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3099,'zhTW','聖光又一次對我說話了，這次顯得非常急迫。我從夢中驚醒，那種急迫感仍然縈繞著我。我不會讓聖光失望的，不能再拖延了，我們必須馬上出發！$B$B非常巧合的是，今天下午舍雷船長為我們提供了數艘供遠航使用的新船，我不得不努力控制自己的儀態才沒顯得過於欣喜。也許這根本就不是什麼巧合？聖光表達自己意願的方式豈是我輩可以妄自揣度的。$B$B我會將“罪人的愚行”號作為我的旗艦，這名字非常合適。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3100 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3100,'zhTW','現在我終於知道為什麼聖光急切地催促我啟程了。一座天天災浮空城趁著深夜開到了我們頭頂，並降下了無數的亡靈！$B$B一個新的死亡騎士帶隊進行突襲，使我們遭受了極其慘重的代價。天災士兵從天而降，遍地都是，我們根本無法阻止起有效的防禦。$B$B恐怕我們計劃中的遠征諾森德行動，在開始之前就已經結束了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3101 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3101,'zhTW','我聽說壁爐谷及其周邊地區的部隊已經開始集結，高階指揮官加瓦爾·普布拉德準備親自領導這支部隊來救援我們。他的努力必然是竹籃打水一場空。$B$B我必須派一名最可靠的信使繞過敵軍的封鎖線去警告他。壁爐谷必須馬上做好全面的防禦準備，並召集其餘的十字軍部隊。$B$B運氣夠好的話，天黑之前信使應該就可以突出重圍了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3102 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3102,'zhTW','獻給瓦里安·烏瑞恩$B某些人口中的洛戈什“幽靈狼”$B$B在多年的流放後他奇蹟般的歸來，這些流浪與艱困反而點燃了他對聯盟的精神和勇氣。$B$B我們要勇敢地進入這些危險之地，在心中效仿他的英勇與頑強。$B$B$B——大領主伯瓦爾·弗塔根',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3103 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3103,'zhTW','第1天：那些人類垃圾看來很高興，絲毫沒有注意到我的存在，毫不意外。他們已經是俎上肉，就等著被轟炸，要我標出他們的位置只是遲早的問題罷了。$B$B第2天：繪製完畢——對我如此完美的男人來講，真是個不重要的工作。為什麼我得做這種事——他們應該叫J-Y C來做這個。他說話時的可笑口音就足以構成派他來的理由。$B$B第3天：第一口氣終於開始變得有點濁了。或許我應該在這幾天內浮向水面再吸一口氣。依舊無聊得要死——那個該死的接應訊號在哪裡？<持續的抱怨……>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3104 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3104,'zhTW','第12天：啊，鬆了一口氣的感覺真是愉快。第二口氣嚐起來像是我所嘗過最純淨的孤兒眼淚。訊號依舊沒有出現，令人費解。而我可以發誓有隻螃蟹試圖拿我的腳指當成鼓來敲。$B$B<嚷嚷變得越來越沒有意義……>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3105 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3105,'zhTW','第36天：第三口氣終於用完，我左手肘的血管在上來的時候又一次充滿了泡泡。螃蟹發出的鼓聲如今是我不變的伴侶，是我窄小黑暗地獄的打擊樂背景音。很顯然地，我被那些卑鄙的傢伙們給忘了。如果今天是J-Y在這裡，他們才不會忘記他！他們也不會把漢斯或西薇雅丟下！為什麼會忘記我？$B$B<句子在沮喪的塗鴉中結束……>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3106 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3106,'zhTW','1、如果你不喜歡它的藥效，請將計量翻倍或減半。$B$B2、如果你的毒藥無法發揮出你想要的功效，那說明你想的太美好，現實很殘酷。$B$B3、原型！原型！原型！（侏儒是很好的實驗物件。）$B$B4、毒藥雖好，可使用容易，結束難。$B$B5、簡單的成分混合在一起就能創造出無數有趣的東西。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3107 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3107,'zhTW','<筆記很難辨認，但是你可以根據粉紅色的引用作為參考……>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3109 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3109,'zhTW','爸爸又讓我照顧奧貝斯了。我想他應該想看到我被她撕成碎片吧。她不像其他人那樣喜歡我又不是我的錯——我不過是吃了一次為她準備的蘋果而已。我甚至都不知道她是怎麼知道這件事的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3110 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3110,'zhTW','致阿比迪斯將軍$B新阿瓦隆，血色領地$B$B阿比迪斯將軍：$B$B願您身體康健。我叫丹希爾·亞當斯，我是一名獵人，也是一名忠誠的血色十字軍戰士。我最近目睹了一樁奇蹟，特此寫信告知於您。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3111 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3111,'zhTW','前幾天，我和我的小隊在天災軍團橫行的病木林裡例行清剿異教徒時，天空中突然傳來了一聲震耳欲聾的巨響。在抬頭看向天空中的納克薩瑪斯時，我們吃驚得嘴都合不攏了。我要告訴您，將軍閣下，那是一個令人難以置信的場面！那座可怕的堡壘在移動。一開始速度很慢，並且伴隨著雷鳴般的轟鳴——然後“噗”的一聲——它就不見了！$B$B我說的是真的，將軍閣下，納克薩瑪斯不見了！沒了！如果這不是聖光降下的奇蹟，還能是什麼呢？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3112 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3112,'zhTW','希望接下來聖光可以審判和制裁那些邪惡而混亂的野蠻人。讚美聖光！$B$B請將這個奇蹟告知兄弟姐妹們，將軍閣下。$B$B願聖光永遠保佑您，願您傳播福音，直到永遠。$B$B您謙卑的，$B丹希爾·亞當斯$B“接近者”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3113 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3113,'zhTW','1.蓄一部濃密的大鬍子，它可以將臉上的缺陷遮蓋起來，以免為聖光所見。$B$B2.用母馬的乳汁洗手，這樣可以令雙手柔嫩光滑，以便行奉獻儀式。$B$B3.在河中沐浴，用聖光賜予我們的、光輝自然的禮物洗淨皮膚。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3114 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3114,'zhTW','4.定期更換聖袍，不要讓你的外表和氣味冒犯了聖光的僕人。$B$B5.隨時保持端正的姿勢——不要因為疲憊或懶惰而彎腰駝背。$B$B<清單中還提到了更多細節，足有好幾頁。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3115 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3115,'zhTW','高階修士蘭德雷案頭親筆：$B$B在這個戰火紛飛的黑暗年代裡，人們似乎都應該自掃門前雪，只保護自己的家人和所愛的人，不理會其他人。但這種感覺是錯誤的——沒有教廷這座希望的燈塔，絕望很快就會淹沒你家人的靈魂。一旦逃避了你應負的責任，矇昧了聖光的呼喚，所有的美食、華服和娛樂——這些可以用金錢買到的世俗享樂都不能將你的家人從發自內心的空虛中拯救出來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3116 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3116,'zhTW','獻身於教廷吧。世俗享樂的缺乏就如同對靈魂的熔鍊，燒去了其中不潔的部分，令你成為一個更高尚的存在。不要為空腹發出飢鳴、赤足踏上尖石和在冬日的寒風中瑟瑟發抖而羞愧。聖光總是透過這些苦難與靈魂取得溝通。是這些犧牲維護了那在禮拜時激勵你的、崇高的、金光閃閃、對聖光的讚美詩。$B$B放棄肉體的享樂，就能愈加接近聖光。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3117 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3117,'zhTW','放縱是一個很難說清楚的話題，但在我們生活的這個時代，它已經成為一種顯而易見的罪惡。一個錯誤的判斷，一句不經思考、衝口而出的責難，一次盛怒中的拳腳相加——這都是凡人的過失，必須經由教廷來贖罪。$B$B但這種贖罪是有代價的。對於妄言的罪，只要一些銀幣就能淨化靈魂。對肢體暴力的罪，需要一些金幣才能淨化凡人肉體上的過失。對於其他的罪惡，則需要虔誠的懺悔和更慷慨的捐獻。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3118 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3118,'zhTW','鬥毆：$B$B打對方的臉：2金幣$B打對方的下腹：3金幣$B打對方的胸口：1金幣45銀幣$B$B<詳細的罪行和對應價格清單列了足足好幾頁>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3119 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3119,'zhTW','透過勞動淨化軀體。透過禱告淨化靈魂。透過烈焰淨化你的敵人。痛苦並不是你的敵人，而是你應當擁抱、親近、並傳遞給其他無信仰者和有信仰者的朋友。$B$B抵抗聖光之道便是不潔的象徵，必須從社會中清除出去。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3120 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3120,'zhTW','將軍閣下，$B$B壁爐谷和提瑞斯法的部隊距離新阿瓦隆已經不足一天的路程。我們腳下生風，在聖光的照耀下疾馳。很快，天災軍團就將面對血色十字軍的總攻！$B$B願聖光祝福您，$B$B高階指揮官加瓦爾·普布拉德',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3121 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3121,'zhTW','救贖之路',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3122 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3122,'zhTW','那個聲音對我說，“到我這裡來。”從一開始我就知道這是我在夢中聽到的聖光之聲。終於來了！在多年的祈禱和行善之後，在多年與天災軍團的不懈抗爭之後，在這麼多次的失敗和復甦之後。$B$B終於來了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3123 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3123,'zhTW','那個聲音又出現了。“到我這裡來……”聖光命令我道。$B$B我猛然醒來，渾身冰涼，但是我的房間裡並不冷。我一定要加倍努力！明天我就要告訴高階修士，讓他籌備更多的祈禱會。不能再漫不經心的了！$B$B聖光已經注意到了我們的努力。我可以感覺得到！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3124 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3124,'zhTW','這一次我是在頭腦清醒的狀態下聽到的！那個聲音非常清晰，不過足足有一分鐘的時間，在這陽光明媚的暖和日子裡，我的呼吸居然冷到了霧化的地步。一名牧師注意到了這個情況，立即跪下來進行祈禱。$B$B但是沒有其他人聽到那個聲音。至少目擊者可以證明我並沒有發瘋。也許我應該讓蘭德雷進行一些禱告？$B$B我會讓喬丹和斯崔特對他們招募新兵的尺度進行更細緻的審查。我們的組織中已經充斥了太多毫無信仰可言的人，他們一心只想著毀滅亡靈，那樣是遠遠不夠的！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3125 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3125,'zhTW','指揮官和主教都很合作，其實他們也沒有別的選擇。斯崔特主教對此顯得尤其狂熱，他談到了十字軍的復興，併發誓要揪出組織中的所有意志不堅定者。$B$B我讓他不必操之過急。我並沒有打算要毀滅十字軍，不過我確實對於“組織最虔誠的骨幹力量前往諾森德為聖光而戰”的想法非常讚賞。我擔心他與裡克拉夫的友誼正在慢慢扭曲他的心智。話說回來，他們畢竟還有些用處。$B$B然而街上流傳的說法開始讓我思考。我相信當這支部隊集結起來的時候我會冠以他們一個新的名字。這次行動讓我們有了新的使命，基於過去鬥爭的基礎上。我會和大主教一起祈禱。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3126 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3126,'zhTW','我們的祈禱獲得了回應。高階修士因為聖光之聲的影響而動，再清楚明確不過了。$B$B我們這些北進的人——最忠誠的人——將以“血色先鋒軍”為人知曉。$B$B我們將成為進攻諾森德的先鋒！天災之禍威脅世界之冠，很快就會吞噬整個世界。是時候把戰鬥推進到巫妖王家門口了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3129 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3129,'zhTW','我驚恐地看著新阿瓦隆，心想也許這是最後一次看到這座城市了。我們的命運將在諾森德決定。不知為什麼，我的心中充滿了不祥的預感，也許這次行動可以讓我忘記這些想法。我必須摒棄雜念。$B$B血色黎明降臨了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3143 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3143,'zhTW','今天早上沒有一名信使回來向我報到，這意味著他們全都沒能抵達壁爐谷。瘟疫之地已經淪陷了，普布拉德的部隊會在曠野上遭到圍攻，全軍覆沒。$B$B今天下午，聖光向我展示了一個幻象。我看到了十字軍在這裡苦心經營的一切都被徹底摧毀，一切都已經很明白了——聖光要我立刻帶走最虔誠的信徒，讓十字軍去迎接自己的末日。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3144 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3144,'zhTW','隨後，蘭德雷說他也看到了同樣的幻象。我無法理解聖光為什麼會要求我們做出這樣一件不光彩的事情，但是我沒有資格去發問——我的職責就是服從，而且我也一定會服從。$B$B我驚恐地看著新阿瓦隆，心想也許這是最後一次看到這座城市了。我們的命運將在諾森德決定。不知為什麼，我的心中充滿了不祥的預感，也許這次行動可以讓我忘記這些想法。我必須摒棄雜念。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3145 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3145,'zhTW','如果足夠走運的話，也許高階指揮官加瓦爾·普布拉德可以躲過這一劫，把倖存者們集合起來。我是一個懦夫……一條夾著尾巴落荒而逃的喪家之犬！$B$B這次航行預計需要兩個月。其它的船隻並沒有像罪人的愚行號這樣的速度，它們運載著我們的主力部隊和輜重，並且差不多都是單帆貨船，但是它們應該可以平安抵達目的地。$B$B雖然我並不指望自己能克服暈船的毛病，但是為了聖光，我會努力克服這一點。絕對不能讓其他人看到我暈船。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3146 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3146,'zhTW','我已經有些日子沒寫日記了。即便只是堅持不病倒，對我來說也已經很費力了。下屬們開始猜測我為什麼要整天鑽在船艙裡，如果讓他們看到我這個樣子，對士氣一定大有損傷。$B$B應該不遠了。我祈禱我們快點抵達終點。已經過去了六個星期，每天的氣候彷彿都比前一天更糟糕。我真希望諾森德的氣候不至於如此惡劣，我不太習慣寒冷的天氣。$B$B聖光已經沉默很久了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3147 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3147,'zhTW','我們遭到了毫無徵兆的攻擊！從迷霧中冒出許多由巨人駕駛的長船，就像幽靈一樣！他們如死亡一般悄無聲息。$B$B我們損失了一艘船，以及船上的所有乘員。雖然只受過最基本的海戰訓練，但我們仍然以極大的勇氣頑強戰鬥。$B$B被那些巨人俘虜的同伴們的慘叫聲迴盪在海面上，隨即歸於沉寂。斯崔特主教帶領大家進行了祈禱。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3148 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3148,'zhTW','今天早上我醒來的時候，發現自己正在地圖上調整航線。是聖光指引著我的手，告訴我該駛向哪裡。$B$B就要到了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3149 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3149,'zhTW','登陸了！$B$B我從小船跳到海灘上，將我們的旗幟立了起來。聖光籠罩了我，並透過我的喉舌向所有人宣講。今天就是血色的黎明——我們等待許久的偉大日子。我們將在這裡建造新壁爐谷。我們不再是血色十字軍，而是全新的血色先鋒軍！$B$B我們將徹底淨化諾森德！天災軍團在這個世界之冠肆虐，並妄圖將我們全部吞噬，現在，我們終於等到了這個機會，可以向巫妖王的大本營進軍了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3150 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3150,'zhTW','將近一個月過去了，建築工程正在快速進行。我忙得無暇提筆寫日記。斥候彙報說，這座島嶼上到處都是龍和其它的怪獸。我們必須提高警惕，直到我們做好準備。$B$B在今天的祈禱會上，高階修士宣佈即將有一位訪客到來——聖光派他來指引我們取得勝利。$B$B我不知道該怎麼想。為什麼聖光沒有告訴我這件事？難道我不夠虔誠？難道我要被某個外來者取代了？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3151 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3151,'zhTW','今晚，海軍上將巴利·韋斯溫出現在我的面前！原來多年前他並沒有死在這裡的海岸邊。$B$B他看起來並不是很老，但我知道一定是他。他聲稱自己是整個艦隊中唯一的倖存者，而他能活下來完全是靠著聖光的庇護。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3152 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3152,'zhTW','我們徹夜長談，直到天亮。他向我保證並沒有要取代我的意圖，因為聖光指引他穿越遼闊的龍骨荒野前來的目的，是要作為我的顧問和名義上的指揮官。他聲稱諾森德即將發生巨大的變化，聯盟和部落很快就要被巫妖王釋放的瘟疫徹底毀滅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3153 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3153,'zhTW','大家對海軍上將表現出了極大的狂熱，尤其是高階修士蘭德雷和斯崔特主教。顯然，在海軍上將的睡夢中，聖光賜予了他新的祝福，而他將這種祝福分享給了蘭德雷。一些人轉職成新的祭司，他們被稱為“黑鴉祭司”。$B$B只有喬丹表現出得毫不在意。我可以理解他的想法，他大概和我一樣，覺得自己的位置受到了威脅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3154 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3154,'zhTW','我總覺得一些事情不太對勁。我說不出是哪裡有問題，但是我確實無法完全信任海軍上將。他什麼都沒有做錯，真是奇怪！不過，我還是要相信自己的直覺。$B$B我會進行祈禱，以求獲得理解。聖光為我們帶來了海軍上將，讓他指引我們走向勝利，我沒有資格質疑聖光的決定。我會繼續服從。我是虔誠的信徒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3155 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3155,'zhTW','又過去了幾個月。我們在新壁爐谷的建築工程取得了長足的進展，城牆和兵營已經接近完工。卡列基那夥人真是神奇的建築工。$B$B我無法靜下心來寫日記，出於某些原因，我在試圖避免把心思用在這方面。聖光已經有一段時間沒有與我溝通了，但是海軍上將安慰我，說這並不是什麼值得擔心的事情。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3156 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3156,'zhTW','我的部下報告說，一小撮被遺忘者在北邊的山上建造了一座營地。在那座山的另一邊，聯盟已經開始動工修築更大規模的基地。$B$B海軍上將說我們應該放任他們發展。部落的多股部隊已經在西邊集結，如果我們貿然發動攻擊，他們一定會前來救援。我對此感覺不好，但是他的話不無道理。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3157 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3157,'zhTW','女妖之觸$B$B斯克爾扎德緊張地掃視著柱子腳。就如他所計劃的那樣，他看見她獨自在她的房間裡飄浮游蕩。深夜潛入女妖的地盤，他的這個決定是否正確呢？如果被發現，他肯定會被通靈師們打趴下的。更糟的是，他甚至不知道自己的感情是否會有回報，而辛德娜爾夫人又是出了名的暴躁。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3158 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3158,'zhTW','當殭屍見到她美麗的身影時，些許懷疑立刻被拋到了腦後。她臉上那些流膿的傷口和疤痕更突顯出她典型的精靈特徵——顯示出她活著時的樣子。一層破布包裹著她那纖細的手指，勉強掩蓋住紫色的、近乎半透明的皮膚，更加凸顯了她冰冷而優雅的軀體。她那無腿的殘軀坐在藍色的能量球上，飄浮在離冰冷的花崗岩地板數寸的空中。斯克爾扎德略微放鬆了一點，擦了擦從他那突出的眉骨上交替流下的汗水和腐液。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3159 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3159,'zhTW','她似乎沒有發現他的存在，徑直滑到房間裡唯一的窗戶前，俯視著戰場。她的眼前是一片狼藉。六個小時前，這裡還回蕩著人類孩子的尖叫哭喊，而現在……只剩下了甜蜜寂靜的死亡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3160 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3160,'zhTW','微風吹起了她的頭髮，頑皮地擺弄著她空洞的眼窩周圍那些如蟲子般糾結的捲髮。斯克爾扎德突然發覺自己已經迷醉地探出了身子。他立即縮回了柱子後面，害怕被黑暗慟哭者看到。她確實看到了他——但他完全沒有必要害怕。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3161 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3161,'zhTW','“斯克爾扎德，”她說，“我一直在等你。你今天在戰場上的表現非常出色。”女妖羞怯地看著自己腐爛的右肩，讓自己的裹布略微往下滑了一點。“現在你該……得到獎賞了。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3162 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3162,'zhTW','<後面的幾頁似乎粘在一起了。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3163 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3163,'zhTW','暴怒者塔泰克。$B$B天災軍團創造的最強大的憎惡之一。他是寒冰之王亞門納爾的造物，在剃刀高地的基地建設過程中發揮了顯著的推動作用。塔泰克憑藉一己之力，在殺死1200多名野豬人後才轟然倒地。他立下的顯赫戰功讓亞門納爾迅速召集起一支亡靈野豬人大軍，最終建立起天災軍團在卡利姆多的第一座大型前哨站。塔泰克的部分殘骸得以重獲新生，被組裝成一隻名叫暴食者的憎惡，也就是亞門納爾現在的副官。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3164 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3164,'zhTW','旅行者奧布拉赫$B$B傑出的建築師，納克薩瑪斯概念構想的主導者，曾親自規劃阿徹魯斯的建設工事。奧布拉赫原本是一名地位低下的骷髏苦工，但是他憑藉卓越的才華，迅速晉升為克爾蘇加德最信賴的顧問之一。$B$B奧布拉赫始終恪守求學之道，遊歷世界以汲取新的知識。他早期的構想帶有濃烈的蛛怪建築風格，受獸人術士的魔法影響也頗深。數年前人們最後一次看見他時，他正在前往西部大陸卡利姆多的途中，計劃考察辛艾薩莉廢墟。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3165 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3165,'zhTW','受詛者迪奧多爾$B$B人類通靈師，詛咒教派的首批成員之一，在第一次獸人戰爭中，迪奧多爾因戰功顯赫而被授予英雄勳章。他曾率領天災軍團的一支分遣隊，成功地對血色修道院發動了第一次和第二次夏季攻勢。在第三次（也是最後一次）夏季攻勢中，對方識破了他慣用的進攻策略，戰局驟然發生逆轉。血色十字軍擊退了天災軍團，迪奧多爾也在混戰中不幸喪命。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3166 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3166,'zhTW','狂熱者基爾凱森$B$B強大的巫妖，直接彙報給巫妖王陛下。他身經百戰，因戰功顯赫而被授予老兵勳章。基爾凱森策劃並主導了一項代號為“血腥攻勢”的、針對聖光之願禮拜堂的大規模襲擊行動。儘管天災軍團佔據了壓倒性的優勢，但是他率領的軍隊很快就遭到了有效的反擊，傷亡慘重。基爾凱森未能躲過瑪克斯韋爾·泰羅索斯男爵的致命一擊，他的殘骸再也無法重新組裝起來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3167 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3167,'zhTW','來自西諾森德$B$B冰冠冰川的航空偵察中隊彙報，他們與巫妖領主基爾溫特的通訊突然中斷了。中隊的首席情報主管，天災工程師卡洛蒙稱，“我們最後一次看見基爾溫特時，他正駕駛著塔爾拉瑪斯在北風苔原上空執行一項機密任務。診斷儀器顯示他隨身攜帶的通訊水晶運轉正常……但是我們能聽到的……只有死一般的寂靜。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3169 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3169,'zhTW','來自東部王國，死亡裂口$B$B教官拉蘇維奧斯在本週早些時候發表宣告，重申了對叛亂以及違抗軍令的懲罰措施。“任何膽敢違背天災軍團的死亡騎士都將遭受比死亡更加殘酷的命運。他們將承受永無止境的痛苦和折磨——我會親自確保這一懲罰措施的順利執行。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3171 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3171,'zhTW','來自龍骨荒野$B$B瓦拉納王子正在挑選一位傑出的死亡騎士，計劃委派他率領一支精英部隊前往諾森德中部的龍骨荒野，向盤踞在那片冰凍平原上的紅龍軍團發動攻擊。王子在最近一次公開致辭中指出，“你們的訓練課程近乎完成。是時候對生命的守護者宣戰了！我們要讓龍骨荒野成為紅龍軍團的埋骨地！”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3172 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3172,'zhTW','雅立史卓莎，紅龍女王，堪稱天災軍團在諾森德最強大的仇敵。有訊息稱她最近一直在組建軍隊，據說是為了對付藍龍軍團。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3173 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3173,'zhTW','來自幽暗城$B$B據幽暗城的線報稱，部落正在調兵遣將，準備遠征諾森德。“部落正在將部署在外域的駐軍大量調回艾澤拉斯。如今他們正在積極備戰，計劃對冰冠堡壘發動攻擊。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3174 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3174,'zhTW','此外，派駐幽暗城的密探稱，被遺忘者的皇家鍊金師協會最近活動頻繁。“目前尚未收到確認資訊，據說鍊金師協會的瘟疫研究工作已經取得了突破性的進展。當然這僅僅是傳聞，但是建議全軍儘量對被遺忘者鍊金師敬而遠之。”',0);
