INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3206,'zhTW','姓名：軟弱$B狀態：掛了*$B備註：這個死亡騎士的名字簡直是在挑釁天災軍團的尊嚴。被巫妖王親自幹掉了。$B$B*巫妖王下令將這個死亡騎士的屍體燒成灰，扔進人類的廁所裡。巫妖王對他的名字感到非常憤怒。',0);
