INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3209,'zhTW','姓名：米妮塔麗絲$B狀態：在行動中失蹤$B備註：我們必將找到她，將她挫骨揚灰。',0);
