INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3210,'zhTW','姓名：$N$B狀態：生存$B備註：為了表彰天災指揮官$N一舉消滅提瑞斯法和壁爐谷的十字軍部隊的赫赫戰功，巫妖王親自授予他一頂天災巨盔。在$N的凌厲攻勢下，十字軍無一倖存。目前被派往攻打銀色黎明。$B$B<接下來還有數百頁。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3211 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3211,'zhTW','阿徹魯斯的大廚臃屍為你烹製精美食物。他以能為偉大的天災軍團提供食物，並使他們更加強大而自豪。不要冒犯臃屍，不然他將拒絕為你供應食物。$B$B守則：$B$B死亡騎士優先享用，食屍鬼需排隊等候。$B$B不要把你身邊的食屍鬼吃掉。要先把盤子裡的食物吃掉。$B$B可以在食物中加入自帶的蛆蟲和蝨子。這並不會冒犯到臃屍。$B$B你手裡有蟲子？給臃屍吧！$B$B可以吃人類或精靈或其它白肉。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3212 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3212,'zhTW','盡情吃喝，不用注意禮儀和整潔。如果臃屍看到有人使用餐巾，臃屍會羞愧地低下頭。$B$B可以將腐爛得不夠充分的食物帶回去。臃屍可以免費提供三個胳肢窩。$B$B可以用手或劍進食。不要把手或劍也吃下去。$B$B殭屍應該多嚐嚐其它菜式，不要總想著腦子。$B$B不要把自己吃了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3213 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3213,'zhTW','冰霜巨龍復活紀實$B$B這些巨大的骨骼幾乎被雪淹沒了，但那突出的，因瀕死的痛苦而扭曲的利爪是不會有人認錯的。巫師們一言不發地聚集到一起，在巨龍的屍體四周圍成一圈。他們靜靜地站了一會兒，夾雜著雪花的寒風圍繞著他們呼嘯。然後，儀式就開始了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3214 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3214,'zhTW','冰封的遺骨中飄出邪惡的光球，厚厚冰雪逐漸裂開，直到巨大的遺骸完全顯露出來。隨著通靈主宰安提沃克的一個手勢，整副骨架顫慄著爬上地面，慢慢組合成型。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3215 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3215,'zhTW','巫師們頌唸咒語的音調開始提高，將知覺和情感植入它的殘骸。當巨龍本能地抵抗這種墮落的復活時，強烈的扭曲感令它的身體痛苦萬分。隨著一聲刺破天際的嘶鳴，這頭野獸終於屈服了。它那坑坑窪窪的肋骨裡燃燒起冰冷的火焰。這火焰沿著四肢傳遍全身，令它那空洞的眼窩平添了幾分詭異。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3216 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3216,'zhTW','通靈主宰走上前去，說道：“巫妖王賜予你新生，命你為天災軍團效力。你將成為我們散播死亡的有力工具，你要將痛苦播撒到敵人的村莊裡，享用生者的血肉，負載最傑出的死亡騎士。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3217 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3217,'zhTW','冰霜巨龍盯著他們，馴服地低下了頭。儀式就此完成。巨龍後退幾步，飛了起來，閃光的雙翼如刀鋒組成的巨扇劃過天空。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3218 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3218,'zhTW','我注意到，一些新生的死亡騎士可能受到了生前記憶的困擾。我懇請這些不安的人不要再庸人自擾。沒有人比我更加厭惡自己生前所犯的錯誤。而在天災軍團，我找到了救贖。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3219 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3219,'zhTW','出於無知，我曾當過聖騎士，發誓要侍奉那該死的聖光。由於盲目地相信了那些關於希望的謊言，我丟下了妻子和兩個年幼的女兒，去搜尋當地的天災軍團。我們的小隊在森林裡搜尋了幾個星期，但每次都無功而返。冬季降臨時，我們仍然對敵人一無所知。於是我們兩手空空地踏上了歸程。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3220 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3220,'zhTW','當我們翻過最後一座山時，眼前卻是一片恐怖的景象。整座村莊都被燒成了廢墟。我連忙跑回家去，看到門外插著一根臨時趕製的門閂。但是我當時太悲傷了，沒有注意到這一點。我衝進房裡，發現我的家人就蜷縮在地上，面目都被燒得無法辨認了。我痛苦地轉過身去，看見門上有許多抓痕，都是她們在極度的痛苦之中抓出來的。其中最細的那些是我最小的女兒抓的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3221 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3221,'zhTW','我後來才知道，當我們離開後，附近傳出了流言，說瘟疫攜帶者就藏在村子附近。血色十字軍把所有的居民圍了起來，並把他們活活燒死。面對這駭人聽聞的罪惡行徑，我當時所迸發的憤恨之情，直到今天還沒有減弱分毫。我發誓要追殺那些十字軍戰士，讓他們在我憤怒的長劍下受盡折磨。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3222 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3222,'zhTW','最後，我和其他隊員又集合到了一起。我發覺有些隊員和我一樣沮喪憤怒，但長官們仍命令我們向最近的一座崗哨進發。夜幕降臨後不久，我們聽到森林裡傳出了亡靈邪惡的冷笑，一群天災軍團的部隊襲擊了我們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3223 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3223,'zhTW','我機械地殺戮著它們。但每倒下一個敵人，附近的山嶺中就會有兩個新的敵人衝出來。這正是那批被我們追殺的天災軍團，但現在我們隊伍不整，措手不及。我的戰友們因受傷力竭而紛紛倒下。天災軍團的人數實在是太多了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3224 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3224,'zhTW','當那致命的一擊來臨時，我想起了和女兒們在這片樹林裡玩耍的情景。這令我感到無盡的仇恨。我為什麼要留著這些記憶？它們全是幻影，我只是在逃避現實的痛苦和死亡。我的女兒們都死了，天災軍團在這裡橫行。死亡才是所有凡人的最終下場。靠力量去對抗它的人，註定都要失敗。只有那些另闢蹊徑、利用死亡之力的人才能獲得成功……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3225 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3225,'zhTW','我當即發誓效忠巫妖王，他才是這個時代註定的勝利者。他讓我從那可恨的、痛苦的人類情感中解放出來。我獲得了新生，成為了死亡騎士。任何力量都不能打倒我和我的同胞們。任何失敗的痛苦都不足以動搖我冰冷的決心。我得到了天災的淨化，我渴望以死亡的力量橫掃艾澤拉斯。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3226 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3226,'zhTW','歡迎加入天災軍團。既然你已經接受了自己真正的使命，你會發現自己業已擺脫各種凡人的束縛，獲得了巨大的自由。你再也不用把時間浪費在討厭的睡眠上，不再極度需要阻擋自然環境對你造成的影響，甚至不需要剪頭髮和指甲！這是多麼愉快的事啊！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3227 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3227,'zhTW','但是，作為亡靈，還是需要注意一些瑣碎的細節：$B$B· 要隨時注意自己的腐爛情況。雖然它有時可以嚇倒你的敵人，但在揮劍時斷落的手臂只會給你造成麻煩。$B$B· 學會熱愛自己身上的臭氣。有人說它噁心，但我們管這叫自然。$B$B· 避開活的動物，尤其是狗。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3228 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3228,'zhTW','· 注意你的身體結構。萬一你把下巴裝錯，你可能會被分派到一些不需要清晰語言的職位上。這些職位通常都不怎麼光彩。$B$B· 飲酒的樂趣已經徹底喪失了。我對此深感遺憾。$B$B· 每天用鮮血洗澡，可以讓生物遠離你（但在血里加泡泡是會被鄙視的）。$B$B· 避免彩妝。它們對我們的膚色完全沒有作用。$B$B· 任它是什麼款式的褲子，都不會再讓你顯胖了，所以穿上它們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3229 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3229,'zhTW','食屍鬼的禮儀$B傷口清理及回收利用指南',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3230 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3230,'zhTW','繃帶$B$B流血比平日多三倍的傷口應用繃帶包紮起來。可以按照個人喜好挑選繃帶的布料。許多食屍鬼都喜歡符文布，因為紫色的符文布浸透鮮血後，會變成噁心的暗紅色。但人們也不能忽視亞麻布那種極其流行的泛黃色澤。實驗精神才是最重要的！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3231 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3231,'zhTW','痂與創口$B$B結痂、流膿的創口是一種風尚，可以很好地傳達出你多變的心情。但不要保留太久！不把痂摳破就太浪費了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3232 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3232,'zhTW','蟲子$B$B哦，你就不能留著它們嗎？它們吃得又不多，而且對你那蒼白的風度和濃烈的臭氣有很好的增強作用。但如果你被蜜蜂或黃蜂包圍了，請立即到最近的屠宰場去求助。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3233 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3233,'zhTW','肢體的丟失$B$B混亂的戰鬥期間並不是接續斷肢的合適場所和時間。請儘量靠你剩餘的肢體完成戰鬥。你只要讓侍僧看一看，我們很快就能為你找到最合適的新肢體。在緊急情況下，可以向同伴借肢體用！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3234 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3234,'zhTW','同類相食$B$B為了避免過早吞吃任何天災軍團的個體，你必須在它倒在地上並且死亡至少5秒後才可以吃它！侍僧的床鋪不能算作“地上”！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3235 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3235,'zhTW','第1條：$B$B大將軍的熱情激起了農民的狂熱！十字軍的艦隊每天都在變得強大，我們的人數也大幅成長。在我們的弓弦上有著一柄強大的武器等著進攻諾森德，以此來讓我們終結這無止盡的戰鬥。我們的處境艱困，但是血色堡壘陷入火海，我無法不聞到身後死亡的氣息。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3236 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3236,'zhTW','第15條：$B$B阿比迪斯失去了她的判斷力——她試圖在十字軍中製造分裂，又只希望以一小群最虔誠的人進攻巫妖王的大本營！難道她打算放著新亞法隆和提爾之手陷入火海，然後帶著我們最後的防衛者駛向世界的盡頭？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3237 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3237,'zhTW','第23條：$B$B清晨十分的明亮，男男女女在礦坑和農地上工作，十字鎬和鋤頭也隨之閃閃發光。一道陰影降臨——一座浮空城——這不是納克薩瑪斯。天災軍團就在附近駐紮，而阿比迪斯下令要我們戰到最後一人。難道我發誓忠於聖光只是為了要替阿比迪斯逃跑的時候殿後？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3238 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3238,'zhTW','<一張潦草畫成的地圖被夾在日記的最後一頁。看來作者打算要遊過洛丹倫的東北海岸，在提瑞斯法林地登陸！>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3239 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3239,'zhTW','我警告過你們，再讓我發現戰靴上沾滿汙漬，需要耗費大量時間清理的話，你們必將受到嚴厲的懲罰！從今往後，所有惡鬼打掃糞便的工作時間和工作量都要加倍！$B$B——教官拉蘇維奧斯',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3240 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3240,'zhTW','這真是絕妙的諷刺。生者用他們最噁心的特點來描述亡者——不可救藥的奴性、殘暴，以及精神空虛。我們為主上效勞！生者不也是奴僕嗎？他們要服從國王、督軍、德魯伊、祭司、神靈、民眾甚至野獸的指令。而我們只臣服於巫妖王無上的意志，尊貴的陛下將引領我們成長為所向披靡的征服者！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3241 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3241,'zhTW','人類付出過許多努力，但是他們的世界仍然充斥著無盡的悲劇、殘忍的暴行、背叛和自私自利。而在天災軍團中，只有高效率的合作模式。無論生死，都選擇為巫妖王效勞吧。尊貴的陛下將引領你實現輝煌的成就！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3242 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3242,'zhTW','團結協作的熱情溫暖了我們冰冷的軀殼。天災軍團的所有成員都致力於執行巫妖王陛下的意志。再看看人類，衛兵們拒絕讓那些躲避戰亂的鄰國難民進入城門，無情的呵斥聲中傳來深深的寒意！生者難道不該全都情同手足嗎？不，他們按照心靈的冷漠程度劃出了三六九等。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3243 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3243,'zhTW','天災軍團必將崛起，我們的敵人必將淪陷！倒下的生者會不斷地加入我們的行列，直到這世界臣服於冰封的王座！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3244 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3244,'zhTW','我終於贏得了教會的賞識，獲准進入通靈學院！就在今天，榮耀的亡者之路將拉開帷幕！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3245 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3245,'zhTW','通靈學院的日子比我想象中要單調得多。房間裡散落著未經整理的研究資料，凌亂的書頁被隨意地疊在一起，將廢棄的蠟燭化開，滴上蠟油封印好。構造體、幽靈和惡魔在骯髒的大廳裡遊蕩。老實說，這根本不是我所期望的通靈師的生活！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3246 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3246,'zhTW','今天，一群強盜闖入了通靈學院，一路殺向墓穴。他們很快來到了大廳。就在強盜們肆意殺害一隊學徒時，旁邊的學徒竟然視而不見，繼續研習著通靈術！如果他們聯合禦敵，摧毀一支軍隊都不在話下，卻被這樣一群烏合之眾砍成了渣。蠢貨！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3247 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3247,'zhTW','今天，在黑暗院長加丁授課時，又有一群入侵者從觀察室闖進了墓穴！這個卑鄙的傢伙居然躲在書架後面傻笑，眼睜睜地看著入侵者殺害了學院中的所有教官！然後他突然跳出來，大聲喊著“正在上課！”他是不是瘋了？我強烈要求轉去斯坦索姆！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3248 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3248,'zhTW','今天，我成為了斯坦索姆的一名圖薩丁亡靈法師！我很好奇，為什麼沒有人來撲滅滿城的火焰呢？導師還要求我學習連線屠宰房大門的通靈塔系統，我心中真是一百個不情願。如果我們不想讓人靠近屠宰房的話，為什麼不鎖上大門呢？把門鎖上很麻煩嗎？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3249 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3249,'zhTW','我逐漸瞭解到斯坦索姆凡事都慢半拍的原因，這一切都是拜瑞文戴爾所賜。這位傲慢的“男爵”整天無所事事地騎著骷髏馬在城裡轉悠。他把斯坦索姆當成了遊樂園，每個下午都會花上幾個小時，將學徒、僕從和構造成編成小分隊，再派駐到城市的各個角落去！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3250 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3250,'zhTW','今晚，男爵的下午茶閱兵禮結束後，一隊入侵者……不，是善良的救星對斯坦索姆的城門發動了攻擊。我催促男爵立即鎖上城門，但是他沒有采納我的建議，還向我保證說“別擔心，駐守通靈塔的僕從們會保護屠宰房的！”於是我胡亂收拾了行李，趁亂從後門溜走了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3251 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3251,'zhTW','看來我做出了明智的抉擇。眺望斯坦索姆城中騰起的滾滾濃煙，我慶幸自己及時撤離，撿回了性命。除了從男爵身上偷來的徽記之戒，斯坦索姆的冒險經歷真是一無所獲。不過，一封蓋有男爵印章且言辭工整的冒牌推薦信應該可以讓我在納克薩瑪斯謀得一份體面的工作。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3252 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3252,'zhTW','從今天開始，我就在天災軍團的兵工廠裡當差啦！納克薩瑪斯充滿了活力。當我得知他們使用複雜且過時的機械裝置為至關重要的傳送裝置充能時，不禁感到一絲悲哀，但是這座浮空城看上去還是很牢固的。很快，我將注意力轉移到了研究工作上，一切進展順利，直到我誤闖進了蛛魔的地盤……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3253 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3253,'zhTW','地穴領主總是喋喋不休。每次聽到它那低沉的聲音，我就覺得毛骨悚然。阿努佈雷坎頻頻邀請我參觀它的“大廳”，我不得不躲藏在格拉斯房間後面那根破碎的管道里，以避開它的視線。我快瘋掉了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3254 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3254,'zhTW','這座死氣沉沉的浮空城也想征服艾澤拉斯世界？就靠一群無能的廢物和腐爛的屍體嗎？我實在看不出這些缺乏獨創性的傢伙在面對危機時能展示出基本的自衛能力！噁心的蛛魔整天從我腳邊爬過，甚至做夢都會被它們嚇醒，我卻對此束手無策！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3255 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3255,'zhTW','我繼續在天災軍團的浮空城裡任職，就在生活逐漸走上軌道時，冒險家們衝進了納克薩瑪斯，開始屠殺我的同事。唉，我一直心儀於法琳娜手下那位漂亮的紅髮學徒，地穴領主卻禁止我跟她攀談，如今她已經躺倒在血泊中！我恨透了這個地方，等我晉級成為亡靈之後，我就要離開這裡。戰鬥的時刻來臨了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3256 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3256,'zhTW','接二連三地遭遇挫折後，我才意識到是自身的標準偏高的緣故。我對自己的要求過於嚴格，甚至超越了天災軍團中的高階官員。由於社會統治階級與生俱來的固執性，他們是很難在有效的變革與現有的質疑聲中達成平衡的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3257 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3257,'zhTW','幸運的是，天災軍團為那些不滿統治政策以及因某些疾病（拿我來說，就是死亡）而行動不便的人提供了低端的就業機會。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3258 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3258,'zhTW','我終於意識到一條真理。死亡降臨時，只有透徹心扉的寒冷，沒有想象中的滿足感和頓悟。我擺脫了俗世的職責，卻體會不到如釋重負的輕鬆，因為我的心中空無一物。我只是我而已。如果能與一位擁有高貴仁慈之心的敵人大戰一場，我希望他能宣洩出滿腔的怒火，將我砍倒在地！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3259 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3259,'zhTW','浮空城已經被召回了冰冠堡壘。我們重新著手籌備物資以及招募軍隊，納克薩瑪斯再次充滿了活力！我有了煥然一新的感覺，彷彿自己獲得了新生。主上的意志在指引我。我很清楚自己該站在哪裡，當勇士們蜂擁而至的時候，將由我來測試他們的實力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3260 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3260,'zhTW','腦子腦子腦子。腦子！！！我要腦子！！！！！！！！！！$B$B<如此重複了四十多頁。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3261 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3261,'zhTW','這是我的符文劍：世界上有許多符文劍但這一把是我的$B作者:女公爵布勞繆克絲$B$B你好，死亡騎士。教官拉蘇維奧斯大概已經向你闡釋了死亡騎士存在的意義與價值，而這僅僅是你們要掌握的初級課程。接下來，就由我來介紹死亡騎士最為珍視的武器：符文劍。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3262 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3262,'zhTW','如果你不能自如地掌控符文劍，那麼它只是一件徒有其表的鈍器。你們是不可分割的整體；一旦分離，你和你的符文劍都會淪至脆弱無力。如果你發現手中沒有符文劍，那麼你唯一要做的，就是迅速獲取一把新的符文劍。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3263 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3263,'zhTW','死亡騎士憑藉符文劍執行自己的意志，令所有膽敢與巫妖王抗衡的生靈嚐到恐懼與痛楚的滋味。像你們這般年輕的死亡騎士，肩負著執行巫妖王意志的重要使命，而你們手中的符文劍也被賦予了輔佐巫妖王成就霸業的榮耀。因此，我希望你們嚴格遵守以下三條原則： ',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3264 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3264,'zhTW','1）劍在手。符文劍是你身體的延展，而你的身體屬於巫妖王。$B$B2）劍在心。符文劍昭示著你的意志，而你的意志也屬於巫妖王。 $B$B3）劍在魂。符文劍中流淌著死亡的氣息，直透你的靈魂。而你的靈魂將執行巫妖王的意志。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3265 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3265,'zhTW','巫妖王在學習過程中，你們會發現自己不得不接受某些與主修課程截然不同的訓練。對此，我只想說明一點：所有的受訓課程都有其特殊的價值，如果因為所謂的“自傲”而放棄學習，那麼你很快就會像那些不願意接受全面訓練的死亡騎士一樣，在戰鬥中付出生命的代價。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3266 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3266,'zhTW','你們中的某些人很快就會發現，他們能將自身的力量匯入符文劍，使其成為強而有力的武器。但是，達到這種程度是不夠的。如果符文劍僅僅是你彙集全部能量的工具，相信我，你還遠遠沒有發揮出它應有的威力。最厲害的死亡騎士憑藉自身意志的延展，就能激發並支配符文劍固有的力量。死亡騎士和他手中的符文劍將以統一的意志、軀體和目的而戰，任何膽敢阻擋他們去路的蠢貨，都註定要化為灰燼。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3267 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3267,'zhTW','另一些人會發現，注入冰霜能量的符文劍能發揮出極致的威力。如此一來，符文劍的寒氣越重，它所施放的力量也就越強大。死亡騎士們，你們要學習支配的這種力量，正是充斥於我們宏偉的冰冠堡壘中的冰霜能量。在操縱冰霜能量的死亡騎士面前，敵人將喪失逃生的機會。他們的移動速度會因寒冷而減慢，攻擊和施法也很難發揮出原本的實力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3268 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3268,'zhTW','還有一些人會發現，利用疾病和瘟疫摧毀敵人才能喚醒符文劍真正的力量。這也屬於死亡騎士的特殊潛能，值得你們深入學習。面對敵人堅固的防禦力量，一開始你們或許會覺得難以攻破；但是任何防禦力量都有其隱蔽的弱點。只要找到弱點，一切就會迎刃而解。你們要記住，洛丹倫王國的覆滅源於一場瘟疫。在這場悄然無聲的戰鬥中，我們沒有損耗一兵一卒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3269 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3269,'zhTW','天災軍團法令$B克爾蘇加德著$B$B第一章$B$B凡人種族的愚蠢造就了天災軍團的誕生。我們的力量源於那些企圖消滅天災軍團的人與生俱來的原罪。這些所謂的“英雄”透過某種正中我們下懷的手段贏得了他們假想中的勝利；殊不知，這樣的行徑註定將導致未來的敗局。事實上，這短暫的“勝利”只是讓他們愈發地意識到，如果不採取這種被他們斥為卑鄙無恥的手段，天災軍團早已擊潰他們。無論輸贏，天災軍團實際上都贏得了最終的勝利。一旦他們認識到這毋庸置疑的真理，就必然會臣服於我們的意志。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3270 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3270,'zhTW','偉大的主人巫妖王亦是在本部法令下誕生的。$B$B征服即腐化。所謂腐化，就是利用你手中的武器，採取所有可能的辦法，顛覆一切正義、希望以及生命的象徵。世間的生命體大抵有著相似的弱點，這些致命的缺陷必將導致他們的覆滅：希望意味著愚蠢的信仰，正義意味著盲目的狂熱，生命意味著脆弱的情感。一旦認清凡人渴望生存的信念，就要毫不猶豫地摧毀這種可悲的期望。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3271 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3271,'zhTW','一旦掌握最直接的腐化手段，就意味著你攀上了智慧的巔峰。在大多數情況下，瓦解敵人的心理防線，肢解他們的機能器官或是直接散播瘟疫病菌都是行之有效的腐化手段。但是，巫妖王不會滿足於戰勝大部分凡人，而是要整個世界都臣服在他的權威之下。如果你耗費了過量的資源，只為扭曲一名普通農夫的心智，這就是愚蠢的行徑了，因為瘟疫病菌就能達到同樣的效果。當然，如果你打算用如此簡單的手段來對付那些歷經磨難、意志堅定的敵人，這也是不明智的決策。任何強大的存在，都有其致命的弱點；獲勝的關鍵便在於你是否擁有洞察一切的智慧。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3272 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3272,'zhTW','天災軍團法令$B$B第二章$B$B生者對天災軍團最大的誤解在於，他們固執地認為我們的嗜好是“邪惡”的行徑。為了打擊敵人計程車氣，我們允許這種誤解的存在，同時亦主動地宣揚這種論調。天災軍團超越了生命本身的桎梏，這就是凡人種族永遠無法達到如我們這般繁盛的根本原因。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3273 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3273,'zhTW','舉例來說：情感與榮耀有何真正的意義呢？這些不過是生者尋求存在感的工具，讓他們覺得活著是一件“美好”的事。然則，生存的信念有其致命的弱點。情感的束縛令他們忽視了邏輯與理智的分析；榮耀的羈絆讓他們不惜呼叫一切可用的資源，也要勉力投身於毫無勝算的戰鬥，只為換取那“永垂不朽”的虛名。我們如此熱心地扮演著惡棍的角色，甚至甘願將天災軍團塑造成毫無理性的化身，就是要激發他們最可怕的缺憾。但是凡人種族對此卻渾然不覺，這一點連我都覺得匪夷所思。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3274 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3274,'zhTW','不明是非無法被“淨化”，憎恨無法被“治癒”或是“舒緩”，貪婪無法被“驅散”，憤怒無法被“消除”。我們集所有的“邪惡”於一身，居然還有人堅信他們能夠擊潰並徹底剷除天災軍團。凡人種族揹負著難以救贖的原罪，我們的旗幟將屹立不倒，他們則註定要臣服於巫妖王的意志。$B$B我，克爾蘇加德，亦是在這條準則下誕生的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3275 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3275,'zhTW','天災軍團法令$B$B第三章$B$B天災軍團擁有無限的潛能。但是，我們難免會犯錯。你必須清楚地認識到自己的極限並熟識你所能支配的全部資源。在任何情況下，都要給自己留一條退路。必要時毫不猶豫地犧牲掉那些渴望彰顯忠心的奴僕，這就是天災軍團哲學體系的基礎理論。除主人之外，一切向他人昭示英雄主義、犧牲精神以及同胞情誼的行為將被視為輕率之舉，違者必將受到嚴懲。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3276 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3276,'zhTW','外界流傳著關於天災軍團的另一種謬論：我們的力量源於生前殘存的意志。他們將天災軍團視為寄生蟲的進化形態，指出一旦脫離擁有生命力的宿主，我們就會在轉瞬間灰飛煙滅。同樣，基於天災軍團自身的利益，我們並未對外界否認如此無知的言論；但是，真相與這種可笑的謬論有著天壤之別。面對這個充滿紛爭的世界，我們只是在不斷的進化中逐漸適應了殘酷的生存法則。對天災軍團而言，所有因意見分歧、人口膨脹、個體特點、自私自利、目光短淺甚至死亡本身引發的憂患都不足為懼。我們遵從主人的意志，主人則賜予我們渴望的一切。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3277 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3277,'zhTW','不可否認，我們從多種被同化的文明中汲取了建築、科技以及物理學方面的知識。和天災軍團所有的“邪惡”行徑一樣，這種做法純粹是出於實用主義。天災軍團沒有時間，也沒有意向建立自己的文明。如果某位成員摒棄其它思潮的影響，創造出了全新的文明理論，那麼他勢必會對自己的成果抱有很高的期望，並渴望得到他人的認可與傳播。如此一來，必然會因個體差異而引發嚴重的分歧。文明的缺陷就在於個體的獨創性；但是在處理建築以及裝置這類簡單的問題時，我們允許一定程度的創意加工。你們的職責不在於質疑手中的資源或是對其追根溯源，而是懂得如何利用它們。 ',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3278 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3278,'zhTW','天災軍團代表著大地的意志。所有的生命體都將臣服於我們的意志，僅僅是因為：他們需要我們，他們渴望得到我們的救贖。天災軍團的準則不可妥協，天災軍團的戒律不可豁免。我們是萬物輪迴的必然環節：死亡。生命終將走向死亡，而亡靈將在死亡中誕生。生者越快地認識到這一亙古不變的真理，他們就能越快地實現蛻變。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3279 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3279,'zhTW','小的們，聽從主人的號令！巫妖王派我來全權管理祖達克的天災部隊。我們要做的就是消滅一切。$B$B消滅一切！！！$B$B我們正在死亡曠野對所有的屍體進行處理，然後把它們派去澤爾拉瑪斯的納瓦留斯王子手下，加強天災軍團的實力。在達庫魯的管理下，什麼都不會浪費的！$B$B很快我們就將變得前所未有的強大！不久之後，祖達克和古達克就將屬於天災軍團！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3280 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3280,'zhTW','很久以前，當北風獨自統治這片山區的時候，有一個強大的犛牛人酋長。他的兄弟妄圖佔有這些土地。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3281 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3281,'zhTW','酋長的這個兄弟名叫雷蹄。他鼓足勇氣，前去征服風暴峭壁，想要推翻它的合法統治者，北風。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3282 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3282,'zhTW','雷蹄潛入北風的王國中心，並伏擊了它，他的陰謀差點就得逞了。但北風在雷蹄的背叛中活了下來，並殺死了這個犛牛人，以懲罰他的入侵行為。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3284 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3284,'zhTW','<大部分書頁已經缺失或是嚴重汙損了。只有最初的幾頁尚可辨認，上面留有“達琉斯·奧利安”的字樣。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3285 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3285,'zhTW','20年，12月2日$B$B今年的冬天非常寒冷。無論我在長袍下加多少層衣服，仍然冷得彷彿骨頭都結冰了一樣。導師們說天氣很快就會轉暖，但我不是很相信。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3286 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3286,'zhTW','今天早上，一些來自安多哈爾附近農場的農夫被送進了紫羅蘭城堡的醫護室。不太清楚他們患了什麼病，但是我無意中聽到他們當中的一個人說自己有虛弱和反胃的症狀。希望導師能選我去幫忙醫治這些農夫。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3287 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3287,'zhTW','2小時後$B$B真走運！有一位導師通知我去照顧來自安多哈爾的那些農夫。我要趁此機會好好表現一下我的學習成果。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3288 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3288,'zhTW','6小時後$B$B事情似乎並不像我想象得那樣輕鬆而愉快。農夫們的病情正在迅速惡化。其中一人的皮膚上出現了大範圍的潰爛和水泡，我已經用紫羅蘭城堡中最有效的草藥和膏藥對重症者進行了醫治，接下來的幾小時內應該可以看到一些明顯的改善。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3289 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3289,'zhTW','10小時後$B$B情況迅速超出了我們的控制能力。所有患者的體表都佈滿了膿瘡，裡面流出黃色的液體。幾乎所有人都昏了過去，少數幾個還有意識的病患說他們感到全身麻痺，關節處有強烈的灼燒感。所有病患的眼睛中都出現了渾濁的乳白色。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3290 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3290,'zhTW','我們緩解病情惡化速度的努力宣告失敗。學徒們開始私下裡交流，認為這種疾病可能是某種魔法的效果。導師立即下令禁止進行這種荒謬的討論。許多學徒都找藉口逃出了醫護室，因為他們害怕這種疾病會穿透我們的防護結界，感染我們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3291 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3291,'zhTW','我出門去散步了一會兒，但沒過幾分鐘就不得不跑回室內去。我的手和腳凍得有些麻木了，耳朵和鼻子則表現出凍傷的症狀。下一次我要多加小心一點。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3292 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3292,'zhTW','13小時後$B$B聖光保佑我們。$B$B病患的眼睛和耳朵開始大出血，導師們認為他們不出一個小時就會死亡。所有試圖醫治這種疾病的努力全部失敗，我已經儘可能地幫助他們減輕痛苦了。只希望在他們死後，我們可以獲得更多有關這種疾病的知識，以便醫治後來者。血肉之軀如何能承受如此可怕的折磨？我準備一直在這裡待到最後一刻。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3293 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3293,'zhTW','更糟糕的是，衛兵發現有一名一年級學徒死在了花園裡。具體原因未知，但是有傳言說他是被凍死的。我不認為近十年來達拉然有這麼冷過——可能從來都沒有。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3294 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3294,'zhTW','18小時後$B$B來自安多哈爾的農夫全部死亡。我心想，他們終於可以安息了，但是我很快就發現自己錯了。最後一個農夫斷氣之後，沒過幾分鐘，可怕的事情就發生了。他們的屍體不知為何突然動力起來，開始向醫護室裡的法師——也包括我——爬行。短暫的驚慌之後，有一位導師開始組織大家抵抗這些行屍走肉。很快，它們就被我們的魔法擊潰了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3295 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3295,'zhTW','我們的損失非常小。有幾個學徒被抓傷了，其中一個有很深的咬傷，需要縫合。衛兵很快抵達現場，將我和其他學徒送回了各自的房間。我試圖詢問這到底是怎麼回事，但他們一句話都不說。當我們走過大廳的時候，我看到有幾對衛兵拿著武器，嚴陣以待。所謂戰爭，應該就是這種感覺吧？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3296 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3296,'zhTW','當我被帶到自己的房間之後，衛兵告訴我把門鎖上，除非有導師親自來通知我，否則不許出門。這時怎麼了？這個世界瘋了嗎？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3297 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3297,'zhTW','24小時後$B$B我已經二十四小時沒有閤眼了。我困得要死，但是我的房間太冷，沒法入睡。我想辦法聯絡到了幾個同樣被關在房間裡的學徒，從他們那裡得知了紫羅蘭城堡全面戒備的原因。導師們正在全面搜查那個操縱農夫屍體的通靈師。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3298 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3298,'zhTW','自從克爾蘇加德的事情之後，從未有通靈師在達拉然活動過。我希望那個造成了今天這場恐慌的罪魁禍首很快就能被繩之以法。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3299 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3299,'zhTW','38小時後$B$B隔離結束，我們這些學徒終於可以走出自己的房間了。操縱死屍的通靈師終究還是沒有被抓到，但是導師們確信，他根本就不在紫羅蘭城堡，也不再達拉然城內。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3300 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3300,'zhTW','我們已經恢復了研究這種疾病的工作。但是由於大部分屍體都被焚化了，研究進展很慢。導師們已經召喚吉安娜·普羅德摩爾女士前來幫助我們進行研究，她應該今晚就會傳送過來。我聽說她是一位非常美麗的女士，希望與她共事可以讓我不再去留意這該死的嚴寒。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3301 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3301,'zhTW','<這本日記的其它部分已經嚴重損毀，無法閱讀了。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3302 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3302,'zhTW','法師問答$B$B問：我的朋友們都說，學習魔法併成為法師會讓我變得瘦弱，女士們也不會喜歡我。這是真的嗎？$B——忐忑不安的吉米·唐森',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3303 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3303,'zhTW','答：不要擔心，吉米。你的朋友們所持有的這種偏見，是由極少數又懶惰又不按時攝取營養的法師造成的。你完全可以在保持最佳體能狀態的同時，還擁有充裕的時間去探索宇宙的奧秘。即便是肯瑞託的成員，也都會在緊張而忙碌的工作之餘，透過嚴格的飲食管理和充足的體能鍛鍊，保持非常好的身材。$B而且，哪有女人不喜歡變形術的？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3304 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3304,'zhTW','問：我的家長不支援我當法師。他們說奧術魔法是非常危險的東西，會把我引向更加危險的魔法，比如惡魔法術。我不想賣掉自己的靈魂。他們說的是真的嗎？$B——約瑟夫·溫特斯$B$B答：你的家長多慮了。雖然有一些人聲稱有法師投奔惡魔或者通靈術，但是從來沒有證據可以證明這一點。請向你的家人強調，在學習魔法的過程中絕對不會出現任何偏差。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3305 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3305,'zhTW','問：我最近開始學習奧術魔法，但是朋友們總是嘲笑我。他們總是叫我幫他們用魔法制造食物和飲料，還讓我把他們傳送到他們想去的地方。人們什麼時候才能開始尊重我呢？$B——“鞋墊”喬治·亞當$B$B答：去學習炎爆術。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3306 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3306,'zhTW','有人將法師斥為思想狹隘、自私自利的群體。希望你明白，沒有什麼比這更離譜的指控了。法師都是富有同情心的善良人；我們孜孜不倦地追尋知識與力量，為的只是讓你們的生活更加舒適！法師能為你提供什麼服務？我很高興你能這麼問！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3307 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3307,'zhTW','· 上臺演講的時候情緒緊張？哪怕想象你的聽眾只穿著內衣也不奏效？把他們想象成綿羊呢？還是不行？我們可以將你的聽眾都變成綿羊。$B$B· 讓你的法師朋友對你施放減速魔法吧，隨時停下來聞聞玫瑰花的香味。這在賽跑時也很有用哦！$B$B· 傳送是最別緻的旅行方式。如果你不想毀掉第二次約會的機會，就別讓自己沾染虛空幼龍的臭味。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3308 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3308,'zhTW','· 如果你有一位法師朋友，那麼你永遠不會感到飢餓或乾渴。魔法制造的食物不含脂肪！$B$B· 讓麥酒保持冰爽的最佳方式是使用冰凍過的酒杯嗎？你應該試試被寒冰箭打過的酒杯。$B$B· 研究表明，大多數文學鉅著的作者在奮筆疾書的時候都受到了奧術智慧的影響。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3309 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3309,'zhTW','· 每年都讓法師們集體施放暴風雪，製造一個歡樂的白色冬幕節。（警告：在施放暴風雪的過程中，請不要待在室外，否則可能導致指尖輕微的刺痛感以及痛苦的死亡。）$B$B記住：如果情況有異，法師可以閃現逃走。$B$B這本小冊子印刷在魔法制造的書頁上。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3346 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3346,'zhTW','很久很久以前，有一位既不會施放火球術，又不會施放變形術，更不會施放寒冰箭的法師。當他施放造水術的時候，會造出泥巴來。如果他對誰施放了奧術智慧，那個人就會變得更笨。他的老師們一致同意，這位名叫巴古多夫的學生，是達拉然最糟糕的法師。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3347 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3347,'zhTW','巴古多夫滿懷著希望刻苦學習。他在同學們面前一口氣喝下了好多好多法力藥水，以為這樣可以提高他的魔法技能。但唯一的結果，卻是他好多次在重要的祈禱儀式上打嗝，或者把同學的長袍燒著，又或者把老師的鬍子變成羊毛。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3348 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3348,'zhTW','在巴古多夫第一次參加考試的時候，考官要求他施放一個冰甲術。當他開始施法的時候，其他學生都很害怕地蜷縮在座位上。一層藍色的迷霧籠罩著年輕的巴古多夫，看起來他好像成功了。但是很快，他就開始發抖和打噴嚏，大家終於明白了，原來他對自己施放了霜寒刺骨。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3349 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3349,'zhTW','有一天，巴古多夫在花園裡散步，心裡想著他是不是根本不是一塊當法師的料。他看著在周圍玩耍的小孩子，回憶起了自己的夢想：成為一名強大的施法者。“沒錯，”他心想，“我一定可以成功的。我只需要更加刻苦勤奮！”於是巴古多夫開始尋找可供練習魔法的目標，並注意到了一棵不太尋常的樹。巴古多夫鼓起勇氣，對這棵樹施放了一個法術，然後閉上眼睛，不敢去看這個法術的結果。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3350 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3350,'zhTW','最後他終於睜開眼睛，哎呀！那棵樹變成了一位漂亮的暗夜精靈。“成功啦？”巴古多夫大聲喊道，“變形術成功啦！我果然還是可以當法師的呀！”$B$B暗夜精靈感到很迷惑，但是隨即就明白了是怎麼回事。她對巴古多夫溫柔地笑了笑，說道：“我是一名德魯伊，孩子。我們可以隨意變成別的模樣。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3351 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3351,'zhTW','巴古多夫的臉紅得像蘋果一樣，急忙轉身走開，卻一不小心踩到了自己的長袍，在大街上摔了個跟頭。路上的其他人都大笑起來，巴古多夫急忙把自己的尖帽子戴好，低著頭羞愧地回到了自己的宿舍。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3352 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3352,'zhTW','那個暗夜精靈在原地站了一會兒，心裡想著剛才那個男孩子的事情。當她準備離開的時候，被腳下的某樣東西絆了一下，差點摔倒。她低頭一看，在剛才還空無一物的地上，不知什麼時候出現了一簇閃閃發光的魔皇草，它的花瓣正在慢慢伸展開來，綻放成為一朵美麗的鮮花。她驚訝地看著這朵花，然後恍然大悟地抬起頭，向巴古多夫離開的方向望去，但是那位年輕的法師已經不見蹤影了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3353 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3353,'zhTW','第1篇$B$B我還沒搞清楚到底是怎麼回事，災難就已經降臨到了我們頭上。大地劇烈地震顫，我們那些美麗的高塔——自從第二次戰爭以來就矗立在達拉然的高塔——崩塌了。$B$B我隱約記得，當我父親的臉龐消失在倒塌的腳手架後面時，我發出了尖叫，但是我卻什麼都聽不到。在萬分的恐懼中，我仍然想起了自己受過的魔法訓練。如果我能延緩這場災難就好了……但是什麼法術都放不出來，一股惡魔的力量將我的魔法牢牢地禁錮了起來。一切都完了。我閉上眼睛，絕望地等待著。但是不知為何，我仍然活著。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3354 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3354,'zhTW','第2篇$B$B廢墟不斷地崩塌顫動，持續了數個小時。每次天搖地動的時候，我都以為這就是結束了，但它卻沒有要結束的樣子。我蜷縮在一道拱門下，那裡以前是可以看到繁華街道的地方。我有多少次站在那裡，看著姐姐抱著各種貨物從街上回來？現在我的面前卻只剩下了灰塵和石塊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3355 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3355,'zhTW','第4篇$B$B我必須對肯瑞託抱有信心。達拉然的大法師們不會拋棄他們的子民。這些困住我的廢墟，對於強大的法師來說只不過是小菜一碟而已。我一定會得救，我一定會完成魔法訓練，成為他們之中的一員。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3356 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3356,'zhTW','第5篇$B$B沒有任何其他人或是我的家人的跡象。我反反覆覆地呼喚著他們，但頭頂上只有死一般的沉寂。我不知道自己是受到了祝福還是詛咒。我的心想要安靜下來，隨其他人長眠，而我的腦子裡卻充滿了恐懼。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3357 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3357,'zhTW','第6篇$B$B天色越來越暗，空氣越來越稀薄。我召喚出的那道暗淡的魔法照明燈火飛進了我的眼睛。我沒法再寫下去了，必須儲存體力，以備不時之需。我相信這些潦草的記錄可以打破這道我無法打破的沉寂，我將會變成一個聲音，輕聲歌唱著穿越這黑暗的深淵，漸漸低沉下去，直到變成輕柔的耳語，在天空中消逝。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3358 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3358,'zhTW','<由大法師安斯雷姆·魯因親自書寫>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3359 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3359,'zhTW','異彩紛呈的魔法可以用來實現多種目的。魔法研究者發現，想要深入理解魔法的基礎原理，最簡單且最有效的方式就是將這門神秘的學科劃分為八種不同的子科目。我們將這些子科目稱為魔法的“學派”，便於法師們逐一學習並選擇其中一門學派作為主要的研究方向。當然，也有不少法師嘗試掌握所有的魔法學派，只是極少有人能達成這個宏偉的目標。我們將在本書中對魔法的八大學派展開討論，並介紹各個學派在實踐中產生的佼佼者。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3360 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3360,'zhTW','魔法的各個學派可以相互融合，從而誕生蘊含多種能量源的可怕法術。我們將在本書集的後續章節中談論到部分強效法術，但是融合不同型別的魔法有可能引發極端嚴重的後果——尤其對初學者而言。$B$B你們將在本書中學到魔法學派的基礎知識。請謹記：禁止濫用魔法。禁止在沒有導師監督的情況下自行實踐。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3361 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3361,'zhTW','<由大法師安斯雷姆·魯因親自書寫>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3362 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3362,'zhTW','防護系致力於研究各種保護性的魔法，是年輕法師必修的重要課程之一。最常見的防護系法術是法力護盾，它將少量的法力值轉化為魔法屏障，保護施法者免受傷害。運用得當的話，法力護盾甚至能夠抵消最為可怕的攻擊——但是，從初窺門徑到爐火純青，其難度也是不言而喻的。法師們通常要經過數月的練習，才能正確地召喚法力護盾。因此，防護系中有一些更為基礎的法術可供選擇。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3363 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3363,'zhTW','一系列的“元素護盾”法術被髮明出來幫助法師，免於旅行中可能受到的攻擊。這些法術需要的能量遠少於法力護盾，同時也更容易維持，但是效力不及法力護盾。例如霜甲術，僅僅只會降低攻擊的效率，而不能完全抵擋。其他更精深的護盾法術則有較多的優點——例如，魔甲術能幫助法師回覆魔法能量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3364 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3364,'zhTW','如果在旅途中遭遇危險，法師們可以使用一系列的“元素護甲”化解敵人的攻勢。施放這些法術所需的魔法能量比法力護盾少得多，護甲的持續時間也更長，但是抵消傷害的能力遠不如法力護盾。例如冰霜護甲，它不能完全地阻止攻擊，只能在一定程度上降低此次攻擊造成的傷害。高階的護甲法術能為施法者提供更多益處。例如法師護甲，它可以幫助施法者更快地恢復魔法能量。$B$B奧術魔法的研習者在行事風格上比較激進，因此我們經常會遇到魔法能量輕微失控的情況。這就是“結界”法術存在的價值。結界法術能快速而有效地保護施法者，使其免受特定型別的元素傷害——當施法者嘗試研習其他學派的魔法時，很可能造成元素傷害。因此，儘早學習防護系魔法是至關重要的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3365 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3365,'zhTW','凱爾薩斯·逐日者是著名的防護系魔法研習者之一。他在魔法學派的各個領域都有不俗的表現，對防護系魔法的領悟力更是出類拔萃。凱爾薩斯王子獨創了一種異化的法力護盾，達拉然中至今無人能夠超越這項成就。另一位知名人物是奧法師杜安。杜安所掌握的護盾法術實現了塑能系與防護系魔法的完美結合，使他在引導範圍攻擊法術時不受任何干擾。這種“魔爆術”可以讓杜安進入近乎無敵的狀態，為他贏得寶貴的準備時間。但是，只有極少數的法師能夠在確保自身安全的前提下施放出這樣的法術。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3366 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3366,'zhTW','<由大法師安斯雷姆·魯因親自書寫>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3367 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3367,'zhTW','顧名思義，召喚系是指各種召喚生物與物品的魔法。當你身處僻靜的荒野時，是否渴望喝上一杯清涼的泉水？朋友，召喚系魔法發揮作用的時候到了。對法師來說，製造一片新鮮的麵包或是一杯清水是最愉悅的體驗。儘管向法師開口吧！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3368 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3368,'zhTW','精通召喚系魔法的研習者可以一次性召喚出好幾杯甚至一桶清水。少數膽大的巫師偶爾會嘗試擺脫容器的桎梏，單獨召喚水——召喚水元素的魔法由此誕生。水元素是巫師最好的朋友。（地獄犬則根本不是！）召喚出的水元素在作戰時是強大的盟友，平日裡是不錯的傾聽者，嚐起來也很美味！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3369 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3369,'zhTW','一些巫師選擇了研習與眾不同的召喚系魔法。對那些希望利用召喚系魔法作戰的法師而言，巴琳達·斯通赫爾斯上尉就是他們的榜樣。當代最著名的召喚系大師要數大法師聶拉斯·埃蘭。他不僅可以同時召喚出多個水元素，還改良了蘋果氣泡酒的配方。此外，聶拉斯·埃蘭並不是可笑的小丑。這就是魔法的魅力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3370 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3370,'zhTW','<由大法師安斯雷姆·魯因親自書寫>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3371 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3371,'zhTW','占卜系是用於資訊收集的魔法派系。精通占卜魔法的法師能夠看清遠處的目標，甚至觀測到通常情況下肉眼不可見的隱形目標。最常用的占卜系魔法就是占卜術，它可以洞察極其遙遠的目標，即使目標來自另一個位面。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3372 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3372,'zhTW','在此我要提醒所有學徒：占卜池不是你們的玩具。禁止將其作為“按次付費”偷窺異性學徒的工具。違者嚴懲不貸。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3373 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3373,'zhTW','富有傳奇色彩的大法師麥迪文堪稱有史以來最偉大是占卜大師。他身處艾澤拉斯，卻能洞察德拉諾世界發生是一切變故——他的眼界或許早已超越了我們所在的位面。麥迪文所能操縱的力量究竟有多強大，恐怕也僅限於世人的猜測了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3374 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3374,'zhTW','<由大法師安斯雷姆·魯因親自書寫>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3375 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3375,'zhTW','增強是利用魔法能量強化物品或者施法者的過程，其效果分為暫時性和永久性兩種。增強系法術雖然難以掌握，但它們的功效性也是有目共睹的。很少有因研習這種法術而導致自我毀滅的案例，因此我鼓勵你們選擇這一魔法派系。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3376 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3376,'zhTW','解離是驅散或是移除魔法的過程。作為法師最重要的法術之一，驅散魔法可以扭轉失敗的法術所可能導致的災難性後果。此外，解離可以永久分解一件魔法物品。分解過程中產生的獨特法力結晶可用於增強其它物品，使其具備魔法能力。雖然解離實踐可能耗資巨大，但是對年輕的法師而言，這通常被視為了解增強魔法的最佳途徑。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3377 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3377,'zhTW','在介紹防護系魔法的佼佼者時，我們提到了凱爾薩斯·逐日者的名字，他同樣被譽為當代最傑出的增強系大師之一。凱爾薩斯王子不僅能夠創造強大的魔法武器，還能遠端操控這些武器，讓它們實現獨立戰鬥。這使得孤身應戰的王子如同多出了好幾位守護者，瞬間即可扭轉戰局。這的確是一種有效的防禦方式。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3378 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3378,'zhTW','無敵的$B$B阿爾薩斯·米奈希爾王子受人敬愛的戰馬$B$B一生忠誠且有一顆崇高的心，願你安息。$B$B純潔溪水和油綠草地，一個忠實的朋友。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3379 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3379,'zhTW','<由大法師安斯雷姆·魯因親自書寫>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3380 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3380,'zhTW','幻象系是矇蔽事實真相的藝術。幻象的迷霧能讓施法者的影像和聲音變得難以捕捉，如同從這個世界消失了一般；或是將某個區域的景象扭曲成截然不同的模樣。幻象魔法通常用於偽裝或是操控他人，但是請注意，占卜系中存在能夠破除幻象魔法的法術。因此，將全部精力傾注在幻象魔法的研習上顯然是不可行的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3381 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3381,'zhTW','和世俗的觀念相反，幻象魔法並非簡單廉價的小把戲。隱形術是戰鬥法師不可或缺的保命技能之一。他們經常身陷險境，因此必須掌握快速而有效的戰略性撤退手段。幻象魔法還可用於迷惑敵人，讓對方誤判你的位置，甚至令他們自相殘殺。這實屬不易，但是精通幻象魔法的大師能夠成功地離間敵人——同時將自己的敵人轉變成盟友。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3382 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3382,'zhTW','前大法師詹迪斯·巴羅夫——願她的靈魂得以安息——是一位極具天賦的幻術師。她發明了多重幻象魔法，施放後可以在不同的位置呈現多個影像。這些影像不僅在外形上與本體相差無幾，而且能同步模擬本體的一舉一動，使敵人難以捕捉她真正的位置。這種作戰方式近乎完美。但是，“近乎”就是不完美。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3383 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3383,'zhTW','<由大法師安斯雷姆·魯因親自書寫>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3384 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3384,'zhTW','通靈系涉及亡者魔法的範疇。研習通靈魔法屬於嚴重違法行為，請避免牽涉其中。考慮到我們有必要簡單地瞭解敵人操縱的魔法，我才在編著本書時引入了對通靈系的介紹——需要強調的是，通靈魔法的研習者統統是我們的敵人。通靈師及其追隨者都是生者的敵人。我們將不惜一切代價消除他們的影響。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3385 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3385,'zhTW','除了復活死者，通靈魔法還可以實現其它更復雜的功能。我們將通靈系視為邪惡的魔法領域。強大的通靈師可以施放腐蝕性的疾病，或是將暗影能量轉化成灼燒血肉之箭，或是利用死亡的力量讓生者不寒而慄。通靈術甚至被用於重鑄亡靈生物的軀體。即使它們的肢體被摧毀，也能在重組後再次投入戰鬥。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3386 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3386,'zhTW','前大法師克爾蘇加德算得上是近代最有名的通靈師。他在天災軍團的初次崛起以及洛丹倫的淪陷中都扮演了重要的角色。如今，已成為巫妖的克爾蘇加德統治著浮空城納克薩瑪斯。他的存在宣告了一場迫在眉睫的危機。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3387 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3387,'zhTW','<由大法師安斯雷姆·魯因親自書寫>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3388 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3388,'zhTW','轉化系是第九個也是最後一個魔法學派。轉化魔法可以讓法師操控時間和空間，是所有學派中最常用以及最實用的魔法。轉化魔法的標誌性法術要數變形術，它能讓法師將某件物品，或是某個人變成別的東西。變形術的效果並不是永久性的，這對很多學徒來說無疑是一件幸事。我曾多次目睹那些粗心的學徒被變成了綿羊、豬甚至落得更糟糕的下場——不要問我“糟糕”是什麼意思。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3389 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3389,'zhTW','轉化魔法的另一標誌性法術是傳送術。最基礎的傳送魔法是閃現術，它也是公認的最實用的法術之一。閃現術可用於快速逃離敵人的追擊，或是讓粗心的法師不至於失足墜崖。除非迫不得已，不要試圖利用閃現術來避免摔死的危險。這種小把戲一旦失誤，就足以讓你搭上性命。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3390 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3390,'zhTW','在施放傳送術之前，請再次確認你的目的地。我們對傳送術的目的地進行限定是有原因的——在“飛行狀態”下施放傳送術通常會導致法師被困死在牆壁、椅子或是另一名法師體內。我沒有開玩笑。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3391 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3391,'zhTW','操縱時間的法術同樣屬於轉化系的範疇。緩落術是避免摔死的絕佳方案（在這種情況下遠比閃現術可靠），它的實用性可謂經久不衰。高階奧術師可以學習令敵人減速的法術。我還聽說有加速效果的法術，可惜未曾見過。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3392 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3392,'zhTW','吉安娜·普羅德摩爾是轉化系魔法的大師。她對普通的大規模傳送術進行了改良，輕而易舉就能將軍隊轉移到別處。這種法術使得她在戰場上更加變幻莫測。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3393 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3393,'zhTW','伊露絲蒂爾·綠葉著$B$B停手！想想自己在做什麼。奧術魔法真的適合你嗎？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3394 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3394,'zhTW','真相：$B$B· 每年，危險的魔法都會導致數百萬的死亡案例。$B· 奧術魔法容易上癮。一旦開始研習，就很難罷手。$B· 人們普遍認為，掌握簡單的魔法並沒有壞處，但是他們難以剋制不斷學習更高難度魔法的衝動，甚至有人因此沉迷於惡魔法術。$B· 在分娩時施放魔法會危害胎兒的健康。$B· 濫用魔法將導致暴力或是熱衷於通靈術。$B· 奧術魔法一點都不酷。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3395 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3395,'zhTW','因此我們啟動了名為“反對濫用魔法教育”的專案（簡稱M.A.R.E.，旨在向世人展示濫用魔法的危險後果。我們的目標是讓所有人都意識到：沒有魔法也能生存。生活的樂趣是無所不在的，例如花藝或是藤藝。這些難道不是令人興奮的娛樂方式嗎？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3396 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3396,'zhTW','此外，該專案為魔法沉迷者提供了一系列的康復課程，幫助他們迴歸正常的社會生活。經過近6年的努力，我們與艾露恩姐妹會以及塞納里奧議會建立了密切的關係。這些組織有能力並且樂意幫助世人迅速擺脫魔法沉迷的病症。記住，關愛自己，就從現在開始！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3397 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3397,'zhTW','艾澤拉斯世界充滿各種各樣的挑戰，想要維持安全且不受魔法困擾的生活方式是很難的。我們可以指引你找到這樣一條安全而舒適的道路。許多人已經從我們推崇的，涵蓋多種魔法替代品元素的生活方式中獲益。你不想成為下一個嗎？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3398 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3398,'zhTW','覺得不太高興？需要一些能量？那很多能量如何？熱呼呼燃燒的能量如何？$B$B試試皮洛可全新的熔岩衝擊。你會愛上它的甜蜜新鮮滋味和巨大純粹的能量。需要快速恢復精神？沒問題！即使在最疲倦時熔岩衝擊也能幫你快速充電。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3399 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3399,'zhTW','受重傷了嗎？我們能支援你！熔岩衝擊能給你額外的能量讓你逃出生天！*$B喜歡火嗎？曾想像過若能喝下液態火該有多棒？如果是，你將會愛上皮洛可全新的熔岩衝擊！嚐嚐燃燒吧的滋味吧！$B$B*最近的研究顯示熔岩衝擊不能以任何形式治療傷口。熔岩衝擊有可能讓你從隨機位置大量出血。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3400 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3400,'zhTW','警告：熔岩衝擊並不適合所有人。孕婦，兒童，或有可能懷孕的婦女在服用熔岩衝擊必須先諮詢醫生。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3401 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3401,'zhTW','“可能產生的副作用包括：口乾舌燥，肚子痛，乾眼症，消化不良，背痛，骨骼與關節疼痛，輕微外皮損傷，內出血，暫時性瘋狂，熔岩衝擊上癮症，魔法上癮症，縱火狂症，對蜘蛛恐懼症，閃電眼，心悸，發燒，流產，失眠，對冷鐵虛弱症，歇斯底里，腦袋中出現隨機歌曲，哮喘，惡魔附身，頭痛，腳痛，無法正確的使用字母“R”，和死亡。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3402 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3402,'zhTW','注意：連續喝下多瓶熔岩衝擊可能會導致自燃。$B$B$B立刻試試最新的熔岩衝擊！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3403 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3403,'zhTW','安東尼達斯成為某位肯瑞託議會成員的學徒時，還是一個稚氣未脫的小男孩。他是一名堅強的學生，如飢似渴地閱讀著達拉然圖書館的大量書籍。在學院中進修短短几年之後，他就從同輩中脫穎而出，並贏得了他們的讚美，以及長者們的尊敬。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3404 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3404,'zhTW','在12歲時，安東尼達斯發表了題為《將時光回溯旅行理論應用於精確魔法實踐的分枝法》的論文，並因此獲得了肯瑞託至高智慧綬帶。他是該獎項有史以來最年輕的獲得者。隨後，管理議會批准他進入肯瑞託高階研究及啟蒙學院，他也是有史以來獲得官方批准的最年輕者。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3405 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3405,'zhTW','隨著安東尼達斯繼續成長，他繼續學習並精進自己的魔法技藝。安東尼達斯在防禦魔法領域的過人天賦和智慧，使得他成為了六人議會的理想候選人，而他也最終順利進入了六人議會。安東尼達斯不僅非常睿智和公正，還擁有淵博的知識。他很快就成為了達拉然最有影響力的人物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3406 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3406,'zhTW','在第二次戰爭之前，艾澤拉斯各國的領袖聚集在洛丹倫，討論獸人入侵的問題。大法師安東尼達斯代表六人議會出席了此次峰會，並明確了達拉然效忠聯盟的立場。他還關注著極有才華的年輕法師卡德加的狀況，後者在第一次戰爭期間曾是麥迪文的學徒。第二次戰爭結束後，安東尼達斯將卡德加晉升為大法師，並任命他為進入黑暗之門、調查德拉諾的指揮官。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3407 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3407,'zhTW','第二次戰爭之後，安東尼達斯調查了獸人的異常虛弱狀態，並基於研究成果發表了一系列論文：《戰爭的因果：對獸人虛弱狀態的全面研究》、《獸人習俗、社會學和心理學行為在第二次戰爭前後的對比》、《對邪能魔法的系統及歷史的實驗研究，以及它們與獸人種族的關聯》。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3408 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3408,'zhTW','這些報告並沒有得出確定的結論。安東尼達斯自己也曾表示，為獸人尋找醫治此種疾病的途徑幾乎是不可能的。他最後指出：獸人只能透過精神方面的途徑來回歸健康的生活方式。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3409 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3409,'zhTW','在第二次戰爭結束之後，聯盟大規模修建收容所關押獸人，並提高稅收以支援收容所的運作，這使得脆弱的聯盟開始承受巨大的壓力。由於缺乏共同的敵人，從第一次戰爭開始為了抵抗獸人而精誠合作的聯盟諸國，又一次為了彼此之間的政治分歧而爭吵不休。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3410 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3410,'zhTW','另外，一種瘟疫開始在北方肆虐。經過調查之後，安東尼達斯發現有一個名叫克爾蘇加德的肯瑞託成員在研習通靈術，並且推測北方的瘟疫是某種魔法的產物。以大法師安東尼達斯為首的達拉然統治者建議對發生瘟疫的區域進行隔離。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3411 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3411,'zhTW','由於懼怕這一舉措可能帶來的後果，泰瑞納斯國王沒有聽從他們的建議。在這種情勢下，一位先知來到了年邁的大法師安東尼達斯面前。他發出了有關瘟疫的警告，並告訴安東尼達斯：整個艾澤拉斯都要淪陷了。先知建議安東尼達斯前往西方的卡利姆多大陸，這是唯一可以拯救他的子民的途徑。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3412 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3412,'zhTW','但是安東尼達斯此時已經年屆七旬。他依然是一位智者，但也愈發地食古不化、固步自封。儘管他的學徒吉安娜·普羅的摩爾女士感覺到了這位先知的強大力量，並建議他聽取先知的建議，但安東尼達斯仍然對先知的話一笑置之。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3413 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3413,'zhTW','大法師決定繼續在達拉然城研究這股肆虐北方的瘟疫。請參閱《大法師安東尼達斯的日記》中有關瘟疫研究的記載。最終，他派遣吉安娜實地調查瘟疫。與吉安娜結伴而行的是阿爾薩斯·米奈希爾王子。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3414 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3414,'zhTW','在安東尼達斯想方設法阻止瘟疫繼續蔓延的同時，阿爾薩斯卻陷入了瘋狂，他在斯坦索姆大開殺戒，並前往諾森德追殺恐懼魔王瑪爾加尼斯。在安東尼達斯找到治癒瘟疫的方法之前，阿爾薩斯就與巫妖克爾蘇加德一起，率領亡靈軍隊向南方挺進，掃蕩了提瑞斯法和洛丹倫，並壯大了自己的勢力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3415 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3415,'zhTW','很快，他們就來到了安東尼達斯的城門前，意圖踏平達拉然，奪取麥迪文之書，並召喚阿克蒙德。安東尼達斯擋在阿爾薩斯和他的亡靈大軍面前，拒絕放棄麥迪文之書和達拉然城。他運用自己舉世無雙的防禦魔法，降下了一道魔法屏障。任何接觸到這道屏障的亡靈都會被摧毀（這道屏障是我們現在所使用的防禦屏障的早期版本）。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3416 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3416,'zhTW','悲哀的是，這還遠遠不夠。阿爾薩斯找到了解除屏障的方法。他直接殺入達拉然，殘忍地殺害了安東尼達斯。克爾蘇加德和阿爾薩斯進入紫羅蘭城堡，奪取了麥迪文之書，並召喚了阿克蒙德。亡靈軍隊撤出達拉然去尋找新的目標之後，阿克蒙德摧毀了整座城市，將城中的魔法高塔夷為一片殘垣斷壁。安東尼達斯的達拉然城頃刻之間遭受了滅頂之災。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3417 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3417,'zhTW','[後記]$B$B安東尼達斯為了保衛他唯一的家園而犧牲，他的事蹟為生者樹立了一個光輝的榜樣。他的成就、勇氣和記憶，是百經磨難的舊世界為我們留下的珍貴遺產，也是我們開創新時代的基石。在這個戰火紛飛的世界中，新的聯盟仍然屹立不到。它雖然仍很脆弱，卻是我們紀念這位洛丹倫最勇敢的兒子和最偉大的英雄的最佳方式。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3419 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3419,'zhTW','小兔毛毛的故事$B$B作者：耶比託·喬巴斯，玩具製造商$B$B<整本書中都印有大幅的彩色圖片，圖片旁寫著簡短易懂的句子。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3420 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3420,'zhTW','很久很久以前，有一隻小兔子。他的名字叫毛毛。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3421 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3421,'zhTW','他每天都吃花瓣。“花瓣真好吃！”毛毛這樣對他的朋友說。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3422 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3422,'zhTW','他的朋友叫嗚嗚。嗚嗚是一隻狼。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3423 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3423,'zhTW','嗚嗚喜歡跟著毛毛到處跑，看他吃東西。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3424 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3424,'zhTW','有一天，毛毛正在吃草，嗚嗚跳過來抓住毛毛，啊嗚一口把他吃掉了。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3425 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3425,'zhTW','“毛毛真好吃！”嗚嗚解釋說。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3426 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3426,'zhTW','這個故事教育我們：不要和狼做朋友。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3432 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3432,'zhTW','十月八日。$B$B如同我之前提過的，我對於某些派系的法術那可怕的潛在危險性，與這類法術幾乎毫無管理機制的現狀，感到非常厭惡及反感。更糟的是，廣泛研究顯示，這些不安定系別有一股趨勢：在越來越容易習得並且施展的同時，法術所產生的效力也越來越強大。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3433 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3433,'zhTW','我的一個學生今天問我，“為何當惡魔傳送門能有兩倍大小和十倍時效時，我們還要在傳統傳送門上加諸各種限制？”這名學生還不懂理論與實際之間的抽象概念，但這問題讓我思考其中矛盾之處：當魔法存在那麼多令傳統魔法相形失色的變種時，練習傳統魔法的未來在哪？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3434 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3434,'zhTW','我盡我最大的努力，去抑制惡魔魔法和死靈魔法在這的發展，但同時我也被這些法術所擁有的龐大潛能所困惑。我拒絕相信這些法術/u。但是當你親眼目睹巨大的煉獄火，抑或遼闊的土地在舉手之間枯萎，我害怕，我的信念將從我同儕心目中的真理，轉變成教條。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3435 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3435,'zhTW','十月十六日。$B$B我把注意力轉移到在北方肆虐的瘟疫。我把我大部分的課堂都取消以研究這個可怕的異變。$B我非常小心謹慎的取得了一些受感染的穀物。令我驚訝的是，我馬上注意到，這個包裹顯得十分無害。沒有任何變色，也沒有明顯的味道，其他捆穀物也沒有任何變異。$B我立刻清楚的知道為何瘟疫會如此迅速的散播。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3436 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3436,'zhTW','十月十七日。$B進一步的研究指出了令人困擾的結論，與甚至更令人困擾的意涵。$B初級測試顯示瘟疫對非人生物僅有非常有限的效果。症狀包括了疲倦，噁心，發燒，輕微幻覺，但甚少導致死亡。但一旦來到人體組織，瘟疫一致且以空前的速度演變成壞疽。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3437 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3437,'zhTW','這種致命有效率的殺人瘟疫，僅僅在人類口糧中發現，絕不可能是巧合。當然這兩件事之間可能沒有關連，但我依然決定派出更多資源來找尋瘟疫的發源地。我害怕在瘟疫背後有隻無形之手在推動。過幾天，我將在長考之後，派出代替我的人去調查。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3438 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3438,'zhTW','十月十八日。$B$B我忽略了一個重大關鍵，一個非常巧妙地隱藏起來的關鍵。因此我得到了兩大結論：瘟疫是為了殺人而存在，而且是人為之物。$B瘟疫長時間的肆虐造成了屍體復甦活動的現象。因為這個現象非常不明顯，我將其認為微弱的副作用。但是，這股能量十分持久且不曾減弱。我因而靈光一閃，一道清晰的訊息浮出：屍體在等待在某人，或某物。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3439 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3439,'zhTW','當時我並沒有任何證據，但我依然不斷追尋。我用我有限的死靈法術知識對屍體下了一些詛咒。那時我並不想令死者復活，只不過是想改變或分辨屍體輻射出來的能量。想像一下，當屍體跳起來攻擊我的時候，我有多麼驚嚇。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3440 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3440,'zhTW','我馬上把屍體焚化，但我現在後悔了。不過我也證明了我的理論：屍體（同理可以延伸到瘟疫）在等待更進一步的指示。很明顯的因瘟疫而死的人不過是在他們墳中淺眠，等待一個能喚醒他們的死靈法師。$B$B簡而言之，毫無疑問的瘟疫是由魔法所造成的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3441 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3441,'zhTW','十月二十號。$B$B我決定派出我最信任的學徒，吉安娜·普羅德摩爾去調查瘟疫起源。根據我的研究，我相信只有我最好的學徒，才能應付任務中未知的危機。她將會隨身攜帶一份這本日誌、與一些瘟疫研究資料的複製。當然我會公開這些資訊，警告人們小心這個即將到來的威脅。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3442 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3442,'zhTW','我希望我能親自調查，但泰瑞納斯固執的反對。我認為沒有什麼比立刻隔離北方疫區更重要。無論如何，我對吉安娜的機敏有絕對的信心。我懷疑除了她或我之外還有任何人能阻止瘟疫的蔓延。$B$B——安東尼達斯——$B<這裡被蓋上代表六人議會的緘印>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3443 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3443,'zhTW','我們並不想顛覆船隻、地精飛艇和飛行坐騎這類傳統交通工具的價值。它們具備了廉價、實用以及安全等諸多優點。正常情況下，傳送門一樣可以保障旅行者的安全；當然，它在速度上擁有極大的優勢。然而歷史經驗告訴我們，一旦為公眾開放傳送服務，勢必會對整個社會群體造成負擔。在肯瑞託議會研發並維護的所有重要法術（包括變形術）中，傳送術最應該得到極端嚴格的限制（除非遇到緊急情況）。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3444 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3444,'zhTW','為何要如此麻煩呢？首先，魔網能量線不是平白無故從天上掉下來的。遍佈艾澤拉斯世界的能量線都承載著巨大的交通流量，因此必須定期更換。我們向法師徵收傳送門材料的購買稅，並鼓勵他們向使用傳送服務的旅客收取同等金額的費用。但是，微乎其微的稅金只能勉強支付能量線的原料費，尚不足以填補鉅額的時間成本。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3445 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3445,'zhTW','記住，最常用的傳送門就是最有效的：運輸大量旅客的單一傳送門反而不會對魔網能量線造成額外的承載壓力。我們非常鼓勵這種做法，並制定了“傳送門資源共享”方案。該計劃正式執行後，那些一次性為不少於五名旅客提供傳送服務的法師將享受稅收減免的優惠政策。請參閱最新一期的《肯瑞託月刊》，瞭解傳送門資源共享方案的詳細內容。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3446 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3446,'zhTW','其次，在合理使用的前提下，傳送門的安全性堪與地精飛艇媲美（從地精工程實踐的經驗來看，前者的安全係數大概還高出一些）；但是如果使用不當的話，傳送門則很可能引發嚴重的後果。以下是正確使用傳送門的法規：',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3447 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3447,'zhTW','第一條：除肯瑞託議會指定的傳送區域外，禁止開啟通往其它任何區域的傳送門。傳送法術最大的弊端在於它具有不可預估的潛在風險。對法師而言，他們輕而易舉就能召喚任意傳送門。因此我們認為，要制止這種高危行徑，只能頒佈死刑令進行嚴懲。$B擁有D——6號特別許可證的法師不受以上法規的限制，但是肯瑞託議會很少頒發這種特殊的許可證。關於D——6號特別許可證的申領資格，請諮詢你的傳送門訓練師。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3448 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3448,'zhTW','第二條：選擇合適的位置召喚並正確使用傳送門。禁止在他人腳下開啟傳送門。禁止反覆進出傳送門。禁止將傳送門視為垃圾處理器、護盾、雨傘以及任何元素遮罩體。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3449 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3449,'zhTW','禁止縮回已經穿過傳送門的肢體。禁止從內側以及外側“拉扯”傳送門的邊緣。傳送門不具備“操縱柄”這樣的便利裝置，因此破壞其邊界的做法是相當危險的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3450 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3450,'zhTW','第三條：禁止強迫或哄騙他人穿過傳送門。這樣做不僅將導致現有顧客大量流失，還可能引發不可思議的嚴重後果（請參見第2條法規）。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3451 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3451,'zhTW','第四條：禁止讓處於變形狀態的人穿過傳送門。這樣做將無一例外地引發爆炸事件。在《變形術使用條款及細則》中亦涵蓋了此條法規。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3452 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3452,'zhTW','第五條：禁止移除傳送法術的液體過濾效果。傳送門固有的隔水性使法師在水下也能開啟傳送門。為了便於水元素進出傳送門，法師在施法時可選擇性地遮蔽隔水功能。禁止在水下召喚傳送門時移除該效果！我們有責任提醒法師們不要忘記編號為34——zz的中重度災難：公元24年，湖畔鎮乾旱以及鐵爐堡洪災事件。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3453 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3453,'zhTW','第六條：傳送門的標準尺寸為3碼1尺零3又3/4寸長，2碼8尺零9又15/16寸寬。擁有8年以及8年以上優秀傳送服務記錄的法師將有機會得到肯瑞託議會頒發的G——16號特別許可證，可召喚兩倍於標準尺寸的傳送門。關於G——16號特別許可證的申領資格，請諮詢你的傳送門訓練師。$B$B<接下來還有數百頁關於正確使用傳送門的法規。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3454 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3454,'zhTW','物種改變一直是個頗具爭議的話題。學術界普遍認為這種魔法極有可能被濫用並釀成災難，肯瑞託議會也因此遭到眾多的非議與責難。這些年來，變形術的研究工作始終受到嚴密的監控，並曾多次面臨取締的危機；但是近來，我們所承受的壓力卻呈現出指數級的增長趨勢。為了獲准繼續使用該法術，我們必須制定相應的法規，以減少越來越多因使用不當造成的事故數量。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3455 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3455,'zhTW','第一條：禁止將低等智慧生物變成高等智慧生物——雖然變形過程中很少伴隨大腦機能的轉變，但是這種情況偶爾也會發生。在人腦智慧的作用下，像蛇或是狼這樣貪慾極重的野獸可以將它們的掠食天性發揮到極致，而這並不是我們希望看到的結果。我們有責任提醒法師們不要忘記編號為12651——b的輕度災難：巴索洛姆——全副武裝的熊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3456 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3456,'zhTW','第二條：選擇簡單的物種作為變形術的結果——許多缺乏管束的法師學徒對某些奇異的物種抱有極大的興趣，這種做法直接導致肯瑞託議會劃撥的保險索賠金額越來越高，因此我們不得不將它們納入違禁範疇。在任何情況下，綿羊都是可接受的變形後物種，當然我們還支援其它若干種常見物種（請參閱最新一期的《肯瑞託月刊》瞭解詳細的列表）。在變形術研習中使用軟泥怪、虛靈和異種蠍將受到嚴厲的懲罰，龍類生物更是莫大的禁忌。因此，接下來要談到的是……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3457 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3457,'zhTW','第三條：變形過程中產生的畸形生物必須得到及時而又隱蔽的處理——就公眾所能承受的心理底線而言，他們沒有必要目睹變形術事故造就的恐怖怪物。肯瑞託議會充分理解這類意外的不可避免性。儘管如此，民間關於類人鯨、半人魚半精靈、兩棲狼人、會飛的軟泥怪、半雞半松鼠、獅鷲－角鷹獸－雙足飛龍嵌合體、其拉兔以及臭名昭著的“藍白兩色小方塊”的目擊報告依然令我們揹負著難堪的罵名。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3458 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3458,'zhTW','第四條：禁止將能力較弱的生物變成能力較強的生物——這條法規看似普通，我們有責任提醒法師們不要忘記編號為8761——e的中重度災難：大法師約翰·奎恩特——被生病的鹿異變而成的熔核巨人化成了一灘血水。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3459 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3459,'zhTW','第五條：禁止對任何正在穿越傳送門的生物施放變形術——這樣做將無一例外地引發爆炸事件。在《傳送門純粹理性批判：關於正確使用傳送門的備忘錄》中亦涵蓋了此條法規。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3460 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3460,'zhTW','第六條：禁止對無生命的物體施放變形術！——真不敢相信肯瑞託議會竟然會收到此類事件的報告，這種惡劣的行徑曾導致一場編號為1——a的高危重度災難：“以朕的王國換一匹馬——不要將王國變成馬匹的一百五十個理由。”$B$B<接下來還有數百頁關於正確使用變形術的法規。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3461 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3461,'zhTW','在任何時候，法師們都必須遵守肯瑞託議會就短距離瞬間傳送所制定的特殊條款與細則。本法規旨在引導如何正確地掌握該旅行方法，以確保傳送過程的安全性和便利性。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3462 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3462,'zhTW','第1條：禁止閃現到已被他人佔據的空間。如教科書上所說，施法者在閃現的瞬間，其目標位置的空氣和水等物質將被替換到起始位置。該法術簡單而高雅的特點使它得以廣泛的利用：閃現術真正的魔法原理卻在於用施法者目標位置的物質取代施法者的身體組織——也就是說，施法者發生位移僅僅是該法術的副作用。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3463 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3463,'zhTW','由於閃現術的施法姿勢非常優雅，因此在大多數情況下，法師們會自覺地避免撞上他人的尷尬。雖然肯瑞託議會耗費大量資源構築的傳送法術體系已然接近完美，但是蓄意瞬移到他人所在的空間仍可能導致三種嚴重後果：施法者取代目標，目標取代施法者或是施法者與目標占據同一空間並嵌合成聯體怪物，這種在混沌中誕生的異形就連天災軍團也不願接納。想要避免上述慘劇的發生，請在施放閃現術之前謹慎選擇你的目標區域。那麼，接下來要談到的是……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3464 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3464,'zhTW','第二條：看看你要去哪兒！在成堆的事故報告中，肯瑞託議會發現因觸犯第1條法規而導致的不幸事件屢見不鮮，因此不得不將該法規從原來的第8條提到了第2條，以顯示其重要程度。我們充分理解意外的不可避免性，但是某些事故一旦發生，就很難彌補了。總之，請法師們謹記，穿越星界位面之前要先看兩邊！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3465 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3465,'zhTW','第三條：禁止閃現到你看不見的空間。從內容上講，這僅僅是上一條的補充規定。但是法師們頻繁地以各種理由觸犯該法規，肯瑞託議會不得不將其單獨列出，希望能引起足夠的重視。和第2條法規一樣，我們也曾多次收到因瞬移失敗導致的事故報告。部分法師承認，他們會有意識地嘗試穿牆而過或是進入黑暗位面，甚至在逃避追捕時會慌不擇路地企圖閃現到箱子裡躲起來。這樣的行為真是愚蠢到了極點。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3466 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3466,'zhTW','固體物質自身的結構非常緊密，足以使其形成……固體。與空氣和水這樣易分離易交換的物質不同，固體物質的內聚力將被轉移到施法者體內。肯瑞託議會有責任列出所有記錄在案的，關於閃現進入固體物質的輕度災難。請記住它們，以免犯下同樣的錯誤：',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3467 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3467,'zhTW','10012—c案例：用火烤的方法從斯奎布里·齒坑的屁股上取下高腳椅。事故附帶的燒傷情況已控制到最低。$B$B19798—g案例：用腐蝕液從耶努斯·基連的頭部取出3根秘銀支撐棒。感謝皇家鍊金師協會（RAS）捐贈的腐蝕液。副作用：被腐蝕的頭皮產生了無法醫治的脫髮現象。$B$B14761—aa案例：用地精伐木機對塞西婭·瓦勒比和一座穀倉進行分離。不幸的是，事故附帶的損害相當嚴重。但是僅剩一手一腳的瓦勒夫人依然過著幸福的生活。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3468 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3468,'zhTW','16616—x案例：使用來自鐵爐堡大熔爐的岩漿將哈蘭德·威爾森從圖拉揚將軍的雕像上分離。事故附帶中度損害。哈蘭德先生並未受到傷害，但是附近一所學校的孩子目睹了熔化將軍雕像的全過程，這種場景對他們幼小的心靈造成了難以癒合的創傷。$B$B11773—c案例：從辛妮拉·紅刃的軀幹上取下6顆多汁的西瓜。事故附帶的損害已控制到最輕。我們成功地搶救出4顆完好無損的西瓜，並將其捐給了當地的孤兒院。$B$B<接下來還有數百頁關於此類案件的記錄>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3469 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3469,'zhTW','正如你們所知，肯瑞託議會歷來將扭曲虛空向物質世界的延伸區域作為擱置物體的場所。從不穩定的魔法精華到破碎的秘法能量碎片，再到成套的護甲以及強大的武器，漂浮在扭曲虛空中的物件可謂五花八門，琳琅滿目。但是，最近我們在其中發現了垃圾和廢棄物的存在。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3470 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3470,'zhTW','扭曲虛空是虛無的廣袤空間，但這絕不是將其視為垃圾場的理由！你們所掌握的傳送門以及傳送法術象徵著特權與責任，如果不小心將午餐的殘渣帶進了傳送門，則很可能在艾澤拉斯世界引發災難性的後果！請在跨越傳送門後檢查你隨身攜帶的物品，如有遺失，立即向肯瑞託議會彙報。關於傳送門的使用守則，請參閱最新版本的《傳送門備忘錄－正確使用傳送門的守則》。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3471 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3471,'zhTW','倘若這種惡劣的行徑愈演愈烈，我將不得不頒佈法令，要求所有使用傳送門的旅客在啟程前取下他們的武器裝備以及私人衛生用品。如果再讓我發現自己的講稿漂浮在一堆垃圾中，我會親自將所有學徒的腦袋變成紙糊的帽子！$B$B——大法師安斯雷姆·魯因',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3472 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3472,'zhTW','來自尊貴的大法師安斯雷姆·魯因的案頭',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3473 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3473,'zhTW','我儘量輕描淡寫地講述這起事故，但是請不要懷疑我為此痛心疾首的事實——我們恐怕再也看不見學徒阿戈勒了。最近大法師阿塔瑞克採取了速成訓練法，他給我派來的學徒全都是些遲鈍的傻瓜，甚至連最基本的造水術都不會！我還指望他們將來勝任魔法師的工作呢，可悲的是，阿戈勒這孩子連跑腿的差事都辦不好。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3474 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3474,'zhTW','奧特蘭克山脈的綠草青翠欲滴，泡製熱茶時加上一些，泥土的清香味頓時撲面而來。我很懷念這種味道，就讓這孩子去浮空城的邊緣處尋找新鮮的野草。就在我忙於為另一名笨拙的學徒收拾殘局時——對，他點燃了一塊擁有200年曆史的掛毯——腦海中突然閃過了阿戈勒再也回不來的念頭。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3475 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3475,'zhTW','我這才回想起來，在我交代差事的時候，阿戈勒笑得跟傻子似的，但是我很快就催他上路了。今天早晨，我凝視著浮空城下方的冰凍廢土，不覺走了神。寒風吹走了我手中一份重要的便函，因此我讓助手下去取。她驚惶失措地回來了，並告訴我說阿戈勒的屍體躺在苔原的低窪地裡。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3476 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3476,'zhTW','直到我在阿戈勒的長袍裡發現了一袋魔草，才明白這孩子親手將自己送上了絕路。我告訴他“把周圍的野草統統給我啃回來”，他竟然真的去啃了。接下來的事，我不說你也該猜到了吧。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3477 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3477,'zhTW','<這個傳單剛被貼上。石頭上許多漿糊殘渣顯示這裡曾被貼了許多傳單。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3478 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3478,'zhTW','仔細聽！$B$B魔法和你的認知有極大的出入。魔法所帶來的危險遠超過任何好處！問你的長者，以得知真相。趁還來得及時趕快行動！在你把自然毀壞得無法修補前學習掌握自然，並分享萬物的平衡。$B$B<一個你沒見過的印章蓋在傳單下面。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3479 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3479,'zhTW','圖勒·鴉爪$B$B儘管有不同的說法，但是最近在提瑞斯法林地和銀松森林發生的一系列事件表明，圖勒·鴉爪充分顯示了他投靠天災軍團的決心。洛丹米爾湖的芬里斯城堡中可能隱藏著一些線索，但是眼下我們必須將注意力集中到別的事情上。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3480 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3480,'zhTW','岡瑟爾·阿坎努斯$B$B岡瑟爾大概是在第三次戰爭（即天災戰爭）中喪命的，隨後他就成為了天災軍團的一員。$B$B岡瑟爾擁有我最喜歡的菸斗。如果再讓我碰見他，我一定會驚喜萬分的！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3481 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3481,'zhTW','比索·埃斯沙德$B$B比索在第三次戰爭中喪命。據說他已經成為被遺忘者的一員；在任何情況下，都應該將他視為部落的間諜。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3482 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3482,'zhTW','蕾安娜，$B$B你不在我身邊的日子可謂分分秒秒，如蟻噬心。醒著的時候，我每時每刻都在期盼你的觸碰，渴望感受你甜蜜而溫柔的愛撫。$B你深邃而明亮的雙眸燃燒著火焰一般的熱情，是如此地令人炫目；就連夜空中耀眼的星辰也無法與它們媲美。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3483 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3483,'zhTW','蕾安娜，$B$B凝視著日漸消瘦的蛾眉月，我的指尖充滿了對新月的期盼。就讓這漆黑的悵惘最終與夜空融為一體，遮蔽所有的光亮，掩蓋我們罪惡的愉悅。$B我願緊緊地依偎在你身旁，哪怕無法呼吸，直到無法呼吸……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3484 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3484,'zhTW','蕾安娜，$B$B黃昏降臨，陪伴我的卻只有黑夜的寒風。昔日我們碰面的小樹林一片死寂；我在僵硬的灌木叢中艱難地穿行，任憑那些瘦骨嶙峋的枝椏抽打我的身體，只為尋覓你的芳蹤。$B我愛你有多深，心就有多痛。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3485 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3485,'zhTW','蕾安娜，$B$B郵差拒絕將我的書信送到你手中，你能想象我有多震驚嗎！難道，我對你的愛是個錯誤？過去寫給你的每封信件，我都小心翼翼地保留了一份副本。我翻看著這疊厚厚的書信，實在找不出所謂畸戀的理由。如果那名該死的郵差堅持認為我心愛的戀人拒絕接收我的信件，我就親手將這封書信送到你面前！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3486 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3486,'zhTW','親愛的先生，$B$B蕾安娜女士已經明確表示，在任何情況下她都不願意接收你發來的訊息。因此，你不得再與蕾安娜女士有任何信件往來。$B蕾安娜女士還希望我轉告你，關於你不合時宜的變形術引發的事故，雖然很有趣，但是她不願意再次經歷類似的遭遇。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3487 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3487,'zhTW','達拉然餐飲指南$B$B達拉然重建後不久，伊吉·魔光的旅店——英雄之家就正式對外營業了。城裡的居民以及遊客紛紛湧來，迫不及待地放下武器，啃起了大塊的硬麵包！店裡擺放了很多座位，價錢公道，吧檯還提供來自世界各地的美酒，讓你喝個心滿意足。無論如何，一定要品嚐這裡的招牌菜蜜餞鹿肉！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3488 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3488,'zhTW','如果你不喜歡喧鬧的場所，可以選擇達拉然中部的“霍克噗克”。這家露天旅店很好找，你可以點一份便餐，和鄰桌的朋友分享旅途的見聞，享受舒適愜意的氛圍。神情疲憊的奧術師學徒是霍克噗克的常客，因此你可以在這裡欣賞到自動烹製的食物，而且它們都相當美味哦！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3489 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3489,'zhTW','如果你只想要一張床和一杯酒，那就去骯髒的野獸！昏暗的吧檯散發著陣陣惡臭，形形色色的可疑人物在這裡頻繁進出。選單上的推薦美味是鹹乳酪；客房裡髒得厲害，恐怕得用一打魔法掃帚和水桶才能將床鋪打掃乾淨。真是再適合部落的傢伙們不過了！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3490 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3490,'zhTW','<殘缺不全的日記中夾雜著模糊難辨的書頁。>$B$B尼科萊會怎麼想呢？我根本沒有想過要告訴他聲音的事，反正我在他面前也說不出話來。或許那聲音就是我的意識吧……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3491 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3491,'zhTW','……迴盪在我腦海中的聲音不是迴音；它令我感到寬慰，似乎有好多話要說。它與頭疼正相反（如果你能理解的話）。每次我聽到它，就會有許多念頭湧上心頭，令我感覺一陣溫暖。比如：我知道圖書管理員藏有神秘的資料，但是這聲音告訴我，她其實在研習惡魔法術，不過她對惡魔的瞭解卻少得可笑。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3492 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3492,'zhTW','我的意識果然是正確的。就魔法學校傳授的那些低階法術來說，我表現出了超常的領悟力。別的學徒只能製造出一片餅乾，而我卻能做出一道大餐。尼科萊看得出我身上的變化。他害怕了嗎？我的意識告訴我，年長的法師們將這種反應稱為尊敬。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3493 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3493,'zhTW','我能找到他……他肯定在北方！我看得一清二楚。救贖並非是不可能的。還沒有到無可挽回的地步。我能讓他重獲新生，甚至變得更好！我體內的能量在繼續增長，我相信我有能力讓所有人過上幸福的日子！爸爸媽媽還有尼科萊……我們可以快樂地生活在一起……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3494 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3494,'zhTW','尼科萊害怕我。雖然他嘴上不說，但是惶恐的眼神出賣了他。沒什麼，我的意識告訴我，尊敬和害怕是相同的情緒。如果他離開了我，我會讓任何膽敢從我手中奪走他的人嚐到生不如死的滋味。姐妹們，他們終將為我們所有。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3495 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3495,'zhTW','……我受到了威脅，如果不將他的貓恢復原貌，他們就會舉報甚至驅逐我。一隻老貓有什麼了不起的？我本可以這樣對付他的。他當著尼科萊的面挑釁我，而他們居然敢如此維護他？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3496 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3496,'zhTW','媽媽竟敢斥責我。她難道不知道我是誰嗎？我聽見他在呼喚我。這座城市，還有這些人都不值得我停留。廚房裡堆滿了糧食，遠遠超出我的需要。媽媽和尼科萊，還有那隻該死的貓……他們將服從我的意志，永遠和我待在一起。我從媽媽的梳妝檯上拿走了所有的金幣，只有我能幫助他。$B$B<剩下的書頁都是空白的。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3497 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3497,'zhTW','你覺得你會施法？新手法師問答集',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3498 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3498,'zhTW','波——一種積極熱情的交配呼喚。$B我能替你做什麼？——這裡賣酒。$B您好——一種具威脅性的戰吼，特別是伴隨著揮手或鞠躬時。$B你好嗎？——你媽真的是隻蜥蜴嗎？$B為了國王的榮耀，朋友！——我真的很餓！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3500 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3500,'zhTW','——以火攻火！$B即使對手是烈焰生物，你依然能憑藉火球術制服它。儘管朝它發射火球吧！結果可能會讓你大吃一驚哦。$B$B——為勝利著盛裝！$B研究表明，講究衣飾儀容的法師所取得的成就遠遠超越那些衣著陳舊而低廉的法師。最近你有購置新款的法袍嗎？$B$B——認清你扮演的角色！$B乍看起來，你的法杖像是一把致命的近戰武器，但它不是。讓那些身披閃亮鎧甲的傢伙站在前面吧。然後……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3501 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3501,'zhTW','——友軍火力！$B不要疑惑，朝你的朋友開火吧！如果未能命中就對啦！你的奧術飛彈大概不會擊中你的朋友。$B$B——找一份工作！$B訓練技能的最佳途徑是詢問他人是否需要幫助。當你意識到竟然有如此多的人想要僱傭一位好法師時，你就會感到驚訝了！與你之前的想法相反，即便是運送包裹這樣簡單的工作，也能幫助你成長為一名優秀的施法者。$B$B——蹲點日常！$B你大概聽說過有的法師為了提高施法熟練度，會採取機械式反覆殺怪的做法，通常他們會一次性處理掉大批怪物。這不失為一種合理而有效的途徑，但是如果長期沉迷於此的話，你的腦子就會爛掉。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3502 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3502,'zhTW','問：我不能施放任何法術。我應該怎麼辦？$B$B答：你很可能是脫水了。如果在施放某種你確信自己已經掌握的法術時遇到困難，請嘗試喝下一杯水！適量補充水份對有效施法是至關重要的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3503 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3503,'zhTW','問：我不能施放火焰衝擊！幾秒前我明明成功地施放了火焰衝擊，但是現在不行了。幫幫我。$B$B答：不能施放法術？是不是幾秒前剛剛施放過？某些法術是不能連續施放兩次的。在等待期間不如挑些別的法術來試試。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3504 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3504,'zhTW','問：我在衣帽間偷看了朋友的法術書，發現他掌握的法術比我多！為什麼會這樣？$B$B答：首先，這種情況是絕對正常的。記得經常和你的訓練師談談。他/她或許能教你一些新的咒語。如果訓練師拒絕教給你更多的知識，那麼你就需要勤加練習目前已經掌握的法術。要有耐心，你一定會學到新的法術的！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3505 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3505,'zhTW','問：同事們所能造成的傷害似乎都遠勝於我。要怎麼樣才能趕上他們，而不至於被視為蠢貨呢？$B$B答：傷害並不能決定一切。你可以透過別的方式輔助團隊，奧術餐桌就是一個很好的例子。如果這樣還行不通的話，或許你並不適合研習奧術理論。聽說狩獵技巧更加容易掌握！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3506 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3506,'zhTW','第1篇$B$B首先做一下自我介紹。我是大法師瓦格斯，肯瑞託派往德拉諾的第一批遠征軍的領袖。我們與聯盟部隊共同穿越了黑暗之門，目前已經在法蘭倫平原——也就是獸人的嘲顱氏族的家園——建立了營地，將其命名為肯瑞瓦村。真是個秀色可餐的好地方！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3507 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3507,'zhTW','第42篇$B$B魔網能量的開發在有條不紊地進行著，結果非常令人滿意。我們驚訝地發現艾澤拉斯和德拉諾的魔網結構有著諸多相同之處，也許這意味著兩個世界中的魔法能量本是同源。$B$B我的同事納比留斯報告說，嘲顱氏族在這一地區與聯盟簽訂了休戰協定。獸人總是不能信任的，我對自己說：“這可以將我們引向天堂，也可以將我們引向地獄。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3508 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3508,'zhTW','第205篇$B$B大部分聯盟部隊已經撤回了艾澤拉斯。希望圖拉揚將軍能夠將我們精心準備的報告安全送回達拉然。$B$B耐奧祖毫無節制地開啟傳送門的行為，已經將法蘭倫平原撕裂了。在扭曲虛空的侵蝕下，這片綠色的丘陵地帶迅速崩塌。我必須想辦法回到以前的地方去！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3509 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3509,'zhTW','第1363篇$B$B十四年過去了，肯瑞瓦村仍然屹立不倒。我們每天聚餐一次，由魯米拉斯提供魔法食品。達斯利克的魔法之劍很好地保護了村莊不受外敵侵害。德拉諾的毀滅從某種意義上講反而是一件好事，因為隨後發生的神奇事件比我們意料中的還要有趣！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3510 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3510,'zhTW','第1969篇$B$B<這一頁寫得非常潦草，與前面那些漂亮的筆跡形成了鮮明的對比。>$B$B我們遭到了攻擊……凱爾薩斯的軍隊……足有數千人！！$B$B飛行的船隻……比我見過的任何一艘飛艇都要巨大……奇特的魔法能量……還有某種魔法炸彈……$B$B我對法師塔施放了一個防護結界……沒有其他人的訊息……$B$B<筆跡在這裡中斷了>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3511 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3511,'zhTW','第1970篇$B$B凱爾薩斯的部隊突襲了我們，把我困在了肯瑞瓦村的塔中。一臺奧術魔像守在下面的門口，專門看著我。我可以隨心所欲地進行研究，但是卻永遠都不能離開！$B$B雖然凱爾薩斯的魔法中斷了我與外界的聯絡，但是我能感覺到，我的學徒拉文德維爾仍然活著。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3512 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3512,'zhTW','老巫師的年鑑：聯盟$B$B作為一個歷來與聯盟交好的組織，肯瑞託議會似乎沒有必要編著關於聯盟各個種族的指導手冊。在我看來卻並非如此——只有經過深入剖析，我們才能真正地瞭解其他種族。——老巫師著',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3513 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3513,'zhTW','人類——人類是適應能力最強的種族，他們中的某些人可以熟練地操縱難度極高的魔法。史上最傑出的法師排行榜上，人類法師總能名列前茅。舉個更具說服力的例子，老巫師本人就是人類。$B$B矮人——矮人對魔法的領悟能力還算差強人意，在研習高階巫術時卻時常遇到難以逾越的障礙。雖然他們將注意力更多地轉移到神職事業上，但是極少數的矮人依然對奧術或是通靈術有所涉獵。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3514 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3514,'zhTW','侏儒——侏儒是能力卓越的奧術師。嚴格說來，他們躋身於舉世聞名的施法者行列，在肯瑞託議會中始終佔有一席之地。$B$B暗夜精靈——雖然暗夜精靈儘量避免操縱奧術能量，就如同他們躲避天災軍團一樣，但是德魯伊教派所掌握的魔法依舊是首屈一指的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3515 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3515,'zhTW','德萊尼人——這個古老的種族為聯盟帶來了強大的巫師和操縱聖光的騎士。近來，他們在踏上卡利姆多大陸後又接納了薩滿教義。$B$B高等精靈——高等精靈操縱的魔法極其強大。他們對魔法的洞察力堪與其他種族（包括人類）媲美。在海加爾山之戰中湧現出的英雄們就包括多名高等精靈牧師。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3516 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3516,'zhTW','老巫師的年鑑：部落$B$B直到前幾年，我對部落的瞭解仍然僅限於種種逸事趣聞，大部分的資訊甚至是我從有限的對戰經驗中推斷出來的。但是近年來，對於聯盟與部落的紛爭，肯瑞託議會採取了更為中立的姿態，因此我對部落以及他們使用的魔法也有了更多更準確的瞭解。——老巫師著',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3517 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3517,'zhTW','獸人——儘管體魄強健，獸人仍然擁有優秀的魔法操縱能力。他們之中極少誕生出色的奧術師，但是獸人歷來崇尚和平的薩滿教義，近年來則將注意力轉移到了術士的黑暗魔法以及通靈術的研究上。$B$B牛頭人——牛頭人很少嘗試使用奧術魔法，但是他們對自然法術卻有著與生俱來的悟性。和許多崇尚自認的種族一樣，許多牛頭人選擇了薩滿之道。此外，高階牛頭人德魯伊們的能力堪與達納蘇斯的大德魯伊們媲美。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3518 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3518,'zhTW','巨魔——巨魔歷來是野蠻與暴躁的代名詞，但是他們對魔法藝術的理解力著實令我感到詫異。在那次巨魔帝國之旅中——我曾遊歷過祖阿曼，祖爾法拉克和祖達克三座著名的巨魔城市，我發現他們的施法者種類繁多，從巫醫到暗影祭司再到動物之神的膜拜者。說到崇拜動物神靈，這點倒是與德魯伊教義極其相似。$B$B亡靈——亡靈操縱魔法的能力與生者幾乎幾乎無差異……甚至更為出色。希爾瓦娜斯女王率領的被遺忘者尤其突出，熱誠與激情令他們的施法技巧爐火純青。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3519 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3519,'zhTW','血精靈——長期暴露在魔法能量下對血精靈產生了難以磨滅的影響。這些體態優雅、嗜魔成癮的生靈能迅速掌握各種魔法學派的教義。最近他們走上了“血騎士”之道，勉強算上是聖騎士教義的一種形式吧。$B$B犛牛人——和表親牛頭人一樣，犛牛人也醉心於研習自然法術。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3520 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3520,'zhTW','老巫師的年鑑：其他支援奧術研究的種族$B$B魔法的運用不僅出現在聯盟和部落的種族中。許多居住在艾澤拉斯世界的生物也對奧術研究表現出了濃烈的興趣。——老巫師著',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3521 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3521,'zhTW','納迦——相比之下，男性納迦更適合近戰攻擊，女性納迦則是出色的巫師，她們懂得靈活地支配水和冰的力量。說到納迦，就不得不提到艾薩拉女王，她被譽為艾澤拉斯歷史上最強大的魔法操控者之一。$B$B蛛魔——只有高階蛛魔領主才具備運用魔法的能力。但是在天災軍團的攻勢下，許多被瘟疫感染的蛛魔都淪為了可怕的通靈師。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3522 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3522,'zhTW','食人魔——食人魔本事德拉諾的原住民，如今他們的足跡卻遍佈各個大陸。大多數食人魔恪守著戰士或是遊蕩者的道路，只有極少數醉心於魔法研習。古加爾是第一位食人魔法師，他可以隨心所欲地操縱強大的魔法（除此之外，他在其他領域的能力也異常卓越）。$B$B薩特——這些危險的生物擁有與暗夜精靈相似的面部特徵以及扭曲的惡魔軀體。他們能熟練地運用惡魔魔法，因此頗具殺傷力。接近薩特時請隨時保持警惕。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3523 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3523,'zhTW','藍龍——作為瑪裡苟斯的的子嗣，藍龍是操縱奧術能量的行家。某些藍龍對凡人巫師非常友善，甚至可能結為魔法研究的絕配夥伴，例如富有冒險精神的卡雷苟斯。不幸的是，最近來自北方大陸的傳言稱，生活在那裡的藍龍變得格外仇視其他的施法者。此次異常事件的原因尚未可知。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3524 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3524,'zhTW','老巫師的年鑑：崇尚薩滿教義的種族$B$B我的足跡遍及艾澤拉斯世界；在我接觸過的群落中，有許多崇尚薩滿教義的種族。他們的社會文明比較落後，通常過著更為原始的生活。——老巫師著',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3525 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3525,'zhTW','野豬人——生活在卡利姆多大陸的少數野豬人因他們的地卜術而聞名於世，地卜術則被視為薩滿教義的原始形態。某些被瘟疫感染的野豬人在死後也能操縱這種魔法。$B$B豺狼人——奇特的種族。當年我路過赤脊山時，憑藉一段簡單的咒語，就博得了當地豺狼人氏族首領的好感。而那段咒語，就連達拉然魔法學校的小孩都會念誦。整整一天，這位首領將我視為他最好的朋友；直到咒語失敗，他才氣急敗壞地派了獵手來追殺我。總之，豺狼人將注意力更多地集中到元素薩滿教義上，這點值得我們長期關注。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3526 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3526,'zhTW','半人馬——女性半人馬傾向於使用黑暗而墮落的薩滿祭司魔法，男性半人馬則很少出現施法者。$B$B狼獾人——初看起來，這種外貌類似狼獾的生物顯得非常原始。但是，他們的氏族首領往往由強大的薩滿祭司擔任。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3527 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3527,'zhTW','鱷魚人——雖然鱷魚人與狼獾人是不共戴天的仇敵，但是雙方的社會體系幾乎如出一轍。簡單枯燥的差事通常交給戰士負責，氏族首領則必須是精通薩滿教義的鱷魚人。$B$B熊怪——最近，似乎很少聽說熊怪成為薩滿祭司的事情。薩滿教義在那些擁有自由意志的熊怪氏族中較為常見。此外，某些擁有自由意志的熊怪甚至掌握了基本的變形法術，如同受過訓練的德魯伊。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3528 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3528,'zhTW','老巫師的年鑑：大地的子民$B$B薩滿祭司教義並非唯一以自然為核心的魔法。生活在艾澤拉斯世界的許多種族都掌握著其它源於自然界能量，且不同於薩滿教義的法術。這些來源相同的法術究竟屬不屬於薩滿魔法，始終是肯瑞託議會在紫羅蘭城堡大廳中爭論的焦點之一。——老巫師著',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3529 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3529,'zhTW','海象人——表面上看，海象人使用的魔法與薩滿教義驚人地相似。肯瑞託的學者至今未能破解海象人魔法的來源。$B$B狗頭人——這些原始的生物只能操縱簡單的自然魔法。少年時代的經驗告訴我，少數狗頭人也能施放出頗具威脅性的大火球來，不過僅此而已。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3530 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3530,'zhTW','野生梟獸——這種身披羽毛的巨獸有許多名字，例如月夜梟獸、梟頭熊和熊身梟。它們性格溫和，能操縱與暗夜精靈德魯伊教義類似的自然魔法。$B$B鷹身人——這種聒噪的女性鳥人善於施放元素風暴魔法。由於1）她們一見到入侵者就會發動攻擊，2）很難辨別她們刺耳的尖叫聲，3）沒有人能夠忍受巢穴中散發的惡臭，因此我們隊鷹身人魔法的來源知之甚少。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3531 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3531,'zhTW','魚人——多年的研究表明，這種謎一般的生物只能操縱最基礎的魔法。不要被它們看似愚蠢的外表所迷惑。魚人擅長施放大地與水元素派系的法術，而且它們的數量仍在繼續增長。$B$B龍蝦人——學術界普遍認為龍蝦人是一種原始的生物，它們對水元素派系的魔法擁有與生俱來的領悟力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3532 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3532,'zhTW','老巫師的年鑑：不使用魔法的生物$B$B魔法並非對所有的物種都適用。許多非智慧動物以及低階物種憑藉獨特的生存法則，依然在這個世界繁衍生息了數千年。$B$B某些種族雖然已經形成有序的社會體制但是他們將注意力集中到了別的事業上，傾向於不使用魔法。對這些不依賴魔法依然能夠繁榮發展的種族，肯瑞託議會必須表示理解，這點對我們至關重要。——老巫師著',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3533 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3533,'zhTW','地精——地精對魔法持懷疑態度，他們更喜歡研究科技。和同樣涉足科技領域的侏儒不同，地精缺乏對奧術魔法的理解和重視。但是有地精嘗試過將魔法與科技產品融合，確實產生了有趣的結果。$B$B穴居人——對這種原始的生物而言，魔法超出了他們的領悟能力。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3534 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3534,'zhTW','猛獁人——魔法對體型龐大的猛獁人缺乏吸引力。猛獁人施法者極其罕見，且傾向於遵循薩滿教義。我和猛獁人打過交道，你很難挫敗他們那股寧死不屈的傲氣，而他們厚厚的毛皮甚至能抵禦數發寒冰箭的攻擊。$B$B維庫人——這些來自諾森德的半巨人原本對魔法一無所知，但是巫妖王將部分維庫人訓練成了可怕的通靈師。我還聽說過關於“符文魔法”的種種傳聞，可惜至今沒有機會深入研究這項有趣的課題。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3535 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3535,'zhTW','大領主，$B$B$N成功地帶領我們對抗來自天譴岸地的天災軍團，並使我們得以開始向冰冠冰川進軍。$B$B泥瓦匠帶滿了足以興建正義要塞的材料，這都多虧了$N和$g他:她在水晶之歌森林的戰功。$B$B還剩下最後一個挑戰——北伐軍之峰。我希望從這個最讓我們苦惱的地方劃下這個時代的終章。$B$B我們等待著您的命令，大人。$B$B願聖光保護您。$B$B——古斯塔夫',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3536 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3536,'zhTW','陛下，$B$B仁慈的王，願聖光永駐您的身心。請允許我貿然懇求您暫緩對這名戰敗的勇士的裁決，容我說上一番話。$B$B這位持信人本是聯盟的英雄。雖然$g他:她渾身散發著惡臭，看上去像是天災軍團的成員，但是她擁有勇士的靈魂。而這靈魂，是最近才與$g他:她的軀體再次融合的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3537 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3537,'zhTW','$N代表這一支新生的、誓與巫妖王抗衡的勢力，$g他:她是黯刃騎士團的成員。是的，陛下，他們這些死亡騎士已經將自己的舊主子視為仇敵。大領主亞歷山德羅斯·莫格萊尼之子——灰燼使者成為了他們的領袖。黯刃騎士團與我們有著共同的目標，那就是徹底摧毀天災軍團。$B$B您或許不會接納$N以及黯刃騎士團加入聯盟的提議，但是請您對此表示寬容。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3538 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3538,'zhTW','陛下，請不要忘記，鮮血與榮耀與我們同在。$B$B大領主提里奧·弗丁敬上',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3539 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3539,'zhTW','大酋長，$B$B偉大的大酋長，願聖光永駐您的身心。請允許我貿然懇求您暫緩對這名戰敗的勇士的裁決，容我說上一番話。$B$B這位持信人本是部落的英雄。雖然$g他:她渾身散發著惡臭，看上去像是天災軍團的成員，但是（她）擁有勇士的靈魂。而這靈魂，是最近才與$g他:她的軀體再次融合的。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3540 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3540,'zhTW','$N代表著一支新生的、誓與巫妖王抗衡的勢力，$g他:她是黯刃騎士團的成員。是的，薩魯法爾，他們這些死亡騎士已經將自己的舊主子視為仇敵。大領主亞歷山德羅斯·莫格萊尼之子——灰燼使者成為了他們的領袖。黯刃騎士團與我們有著共同的目標，那就是徹底摧毀天災軍團。$B$B您或許不會接納$N以及黯刃騎士團加入部落的提議，但是請您對此表示寬容。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3541 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3541,'zhTW','索爾，請不要忘記，鮮血和榮耀與我們同在。$B$B大領主提里奧·弗丁敬上$B$B又及，請代我向伊崔格致意，並告知他我很需要一名得力的獸人前往諾森德幫助我打理事務——當然，這需要徵求您的同意。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3542 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3542,'zhTW','大法師安東尼達斯，肯瑞託的大魔導師$B$B名為達拉然的偉大城市再次屹立於此——一個賦予聖潔的達拉然之子，關於韌性與意志的試煉。$B$B你的犧牲不會毫無價值，最親愛的朋友。$B$B$B以愛與榮耀之名，$B$B吉安娜·普羅德摩爾',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3543 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3543,'zhTW','年復一年，我被關在這個魔法監獄中。今晚，我就要潛逃出去。我備齊了脫逃的一切所需。$B$B<墨跡因為浸水而暈開，模糊了信件的一部分。>$B$B為什麼我得在這個鬼地方這麼久？我到底做了什麼才受此懲罰？日復一日，這些問題在我腦海中打轉。為什麼有人會落得如此下場？$B$B<墨跡因為浸水而暈開，模糊了信件的一部分。>$B$B也許我會在來生了解這個答案。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3544 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3544,'zhTW','你找到了一樣神秘物體的失事殘骸。在火焰之後，你可以辨認出一個標記“M：1815212085”。你忍不住好奇這個東西究竟從何而來……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3545 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3545,'zhTW','匆匆翻閱那些幾乎要碎開的書頁，只記載了一些在瓦爾甘牧場的生活。季節的變換，莊稼種植與收割的記錄，以及孩子的出生與去世。$B$B整個記錄在短而破碎的瘟疫描述後嘎然而止。沒有一個孩子能長大到完成騎士的訓練，就算他們有人在瘟疫後倖存。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3546 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3546,'zhTW','日記的前半部分似乎是庫珀先生的生意帳本。一串串手寫數字記錄了木桶的生產與銷售情況。銷售物件主要是月溪鎮的居民，另外還有暴風城中的幾家客戶。$B$B後半部分似乎是庫珀先生的日記，他在裡面提到了要將家族生意交給自己的弟弟打理的想法。你發現這本日記並沒有提到任何孩子的事。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3547 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3547,'zhTW','<看來阿爾卡馮一直保持寫日記的習慣。這本日記似乎是用好幾種語言寫下的。封面上貼著一張標籤。>$B$B部落：$B保衛要塞：$4024w$B佔領要塞：$4022w$B$B聯盟：$B固守要塞：$4025w$B佔領要塞：$4023w$B$B第10天$B$B造物主都已離開。我留了下來繼續看守。$B——阿爾卡馮',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3548 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3548,'zhTW','第10500天：$B$B大廳裡很安靜，也很空虛。$B我原本以為造物主是要我看守大廳的，但是他們從未明確這樣說過，“阿爾卡馮，看守大廳……”或許我負責看守廳外也沒關係吧？看守外面可能麻煩會少些。我決定了——我現在負責看守大廳以及廳外。下個月就開始履行我的新職責。$B——阿爾卡馮$B$B第20120天：$B$B廳外比大廳廣闊多了。大廳周圍橫亙著懸崖和高山。我現在非常自信，造物主一定是要我也看守這片地方的。但願造物主不會知道我前十年荒廢在了大廳裡。$B——阿爾卡馮',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3549 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3549,'zhTW','第1051213天：$B$B我今天想出了一個新遊戲，我把它叫作“踢鬼”。我今天能把它從要塞正前方踢到大路上。我要試著在明年前把它弄到河對面去。$B——阿爾卡馮$B$B第2145617天：$B$B今天那些小綠人又來了。我已經將他們也歸入我看守的職責範疇了。$B——阿爾卡馮$B$B第2145657天：$B$B那些小綠人在這裡建起了更多的建築。許多看起來還不錯。我想我這週會跟他們談談，並感謝下他們。$B——阿爾卡馮$B$B第2145666天：$B$B我今天為小綠人修建額外建築的事特意感謝了一名小綠人。他告訴我說，他很快會帶更多的綠人來讓我看守——好像是他們的大部隊。$B我非常高興能有更多的東西可讓我看守了。$B——阿爾卡馮',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3550 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3550,'zhTW','Detailed here in are all of the locations used to secret our information within Loch Modan while awaiting pickup. Should you manage to obtain any documents from the Explorer\'s League or their allies， place them in one of these locations and one of our messengers will pick the package up within the week for delivery to our base of operations.$B$BOnce you have memorized all of the locations within this book， burn it so that it cannot be obtained by our enemies. Should you suspect for any reason that our enemies might be suspicious of your activities， burn the book immediately. By no means should this ever fall into enemy hands， lest our routes of communication be compromised.$B$BFor Ragnaros！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3551 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3551,'zhTW','Location 1：Western Loch Dock\\n\\r\\n\\rNortheast of Thelsamar， there is a small dwelling and a dock that are utilized by dwarves on occasion during fishing season. Store the package in a watertight container under the dock， out of sight.$B$BDrop offs and pickups from this location should occur only at night as to reduce risk of being witnessed by fishermen in the area. This dropoff point will recieve reduced priority during the fishing season for obvious reasons.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3552 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3552,'zhTW','Location 2：Grizzlepaw Den\\n\\r\\n\\rSouth of Thelsamar， there is a large hill. On the south side of the hill， there is a path leading to the cave at the top. Store packges behind the rocks in the back of the cave.$B$BPlease refrain from continued use of this cave as a shelter and/or hideout. Utilizing this cave for such compromises the security of our packages and our messenger routes.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3553 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3553,'zhTW','Location 3：Shanda\'s Lair\\n\\r\\n\\rThere is a small hovel to the southwest of the excavation site that once belonged to a reclusive hermit.$BShanda\'s residence in this cave， however， has driven all potential inhabitants away. Just outside the mouth of the cave serves as a perfect drop point.$B$BAs a reminder， Shanda is an enormous murderous spider the size of two dwarves. Do not drop documents IN the cave， even if Shanda is not currently present she will be， given time.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3554 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3554,'zhTW','Location 4：Ironband\'s Cubby\\n\\r\\n\\rA side passage in the heart of Ironband\'s Excavation Site leads up to a well——hidden and disused alcove. Hidden right under the noses of the Explorer\'s league， this is a prime dropoff spot.$B$BThe Troggs have distracted the Explorer\'s League， but do not forget they are still hostile to us. Take care when accessing the site at night， Troggs may be waiting in ambush.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3555 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3555,'zhTW','Location 5：Mo\'grash Skull Idol\\n\\r\\n\\rThis stone skull idol seems like part of the ogre grounds， but is further south than the ogres actually roam. Place documents at the base of it.$B$BDo NOT place documents IN the mouth of the skull idol. Several documents have been permanently lost this way， as well as one hand， mysteriously.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3556 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3556,'zhTW','Location 6：The Grove in the Loch\\n\\r\\n\\rA small grove of three saplings in the center of the Loch serves as a well——isolated drop off point.$B$BDraining of the Loch has left this space slightly less isolated. The crocolisks have helped to mitigate this.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3558 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3558,'zhTW','建築工程的第一階段已經完工了。韋斯溫上將命令我的一隊部下前往北方確立了一處落腳點。他不願意詳細解釋，只是說他是受到“指引”才這麼做的。$B$B今天下午，我們抓到了四個被遺忘者的間諜，他們都是從怨毒鎮來的。我打算讓裡克拉夫拷問他們。如果我們只抓住了四個，又有多少間諜漏網並且混跡在我們當中呢？$B$B為什麼我覺得事情逐漸變得明朗了起來？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3559 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3559,'zhTW','Durak，$B$BThis $R has assisted me IN collecting enough fel fire TO launch an assault ON the elves.$B$BThe projectiles will be devastating——but impossible TO control. I need a way TO direct their trajectory.$B$BI\'m sure to be forgiven for meddling with demonic powers once Splintertree is saved……$B$BDraaka',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3561 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3561,'zhTW','<The Apothecary\'s notes are scribbled in a cramped hand， with complex alchemic formulas interspersed among childlike doodles of skulls and lightning bolts. Squinting， you can make out parts of a recent passage：>$B$B……most magnificent corruption， embedding itself deep within living tissue. Extremely contagious when <several words are smudged> via food chain. Today\'s tests confirm it is only partially biological in origin. Foulhoof， my <illegible> companion， preoccupied with vengeance and blind to the more \'constructive\' applications of his <a greenish ichor stains the remainder of the paragraph.> Research progresses slowly. Hope my companions at Althalaxx fare better.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3562 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3562,'zhTW','小侏儒透過欄杆，凝視著魔法屏障下的達拉然。$B$B“陽臺上的風景真美啊。你快來看看！”$B$B馬庫斯漫不經心地撓了撓鬍子拉碴的下巴，深深地吸了一口氣，朝塔薇走來。他腿上的護甲嘎吱作響。$B$B“英雄之家旅店還不賴啦。不過房間裡的東西你或許會更感興趣。”$B$B塔薇蹦跳著跑進房間，隨即撲到了那張大床上。她盯著馬庫斯，調皮地眯起她那雙又大又圓的眼睛，燦爛的笑容開始透出一絲邪氣。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3563 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3563,'zhTW','“想要再找個伴兒嗎？”她柔聲問道，雙手交織，開始了一場複雜的召喚儀式。直到她感到背後傳來溫暖的氣息，這才停了下來。$B$B剎那間，馬庫斯的臉變得煞白，緊張地嚷嚷道：“這……這不太好吧。”$B$B塔薇滿懷疑惑地轉過頭去，只見一隻骯髒的地獄獵犬已經蓄勢待發，死盯著衣冠不整的聖騎士，口水都流到了地板上。$B$B“啊，不是的！我不是這個意思。”她一邊驅逐著這隻飢餓的惡魔，一邊結結巴巴地解釋道：“對不起，我其實不擅長這個……”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3564 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3564,'zhTW','馬庫斯一把握住她的雙手，安慰道：“沒關係。那你擅長什麼呢？”$B$B她揚起頭，瞳孔中燃燒著新生的火焰，暗影能量順著她的雙手注入馬庫斯體內，令他痛苦地跪倒在地。$B$B“嗯，我擅長痛苦系法術。”',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3565 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3565,'zhTW','馬庫斯咬緊牙關，揮起一道聖光，迅速恢復了力量。$B$B塔薇不安地盯著他，只見馬庫斯重新站了起來，他灑下的陰影吞沒了塔薇嬌小的身軀。他伸出手來，將一股正義的力量傳入塔薇體內。她顫抖了幾秒，雙目才恢復了神智。$B$B“我最近才走上了……懲戒之路。”$B$B塔薇臉上又露出了惡作劇般的笑容：“嗯，似乎會很有趣呢。”$B$B<剩下的內容需要999級才能閱讀。>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3566 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3566,'zhTW','Grimfang，$B$BI report to you from Splintertree， and the news is unpleasant.$B$BThe post was recently attacked by the kaldorei， which prevented any reports from being delivered.$B$BThe siege has been broken， but many were lost and another attack looks imminent.$B$BWe shall continue sending elves to their graves as long as fate permits.$B$B——Kadrak',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3567 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3567,'zhTW','<br /><br />In Memory</h1><br />Shaldyn， Gershala， Volcor</h1>and those who never made it home.</h1>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3568 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3568,'zhTW','<The small grave marker is lovingly inscribed with orcish runes.><br /><br />$B$B$B$B$B——BELOVED OLGRA——<br />$B$B$B$B$B$B$B$BWife of Mankrik<br /><br />$B$B$BIt took forever to find you<br />$B$B$B$B$BAnd now you are gone',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3569 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3569,'zhTW','科勒博士，$B$B我們的黑騎士沒有能完成他的任務，將他殘破的身軀從錦標賽中取回，用你的法術將他復活，我們將利用銀白十字軍和他們追隨者的力量來對抗他們。$B$B俘虜他們，利用他們的靈魂增強我們僕人的力量。抓住北伐軍戰士庫爾，他的輕率魯莽是非常有名的，將他作為祭品放到你的祭壇上，他的靈魂會讓黑騎士獲得恐怖的力量。然後將重生的黑騎士帶到我這裡來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3570 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3570,'zhTW','Day One：\\r\\n\\r\\nGot on a ship called Draka\'s Fury.$BWe\'re taking the special cargo to a far away place across the ocean.$BI have the duty to clean stuff on the ship and scout when we get to land.\\r\\n\\r\\nBetter work than searching for Alliance rogues and druids in Orgrimmar.\\r\\n\\r\\nThe food is not as good， but the grog tastes the same.$BDurotar has already slipped out of sight.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3571 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3571,'zhTW','Day Two：\\r\\n\\r\\nThe food and rocking of the ship do not agree with me！\\r\\n\\r\\nThere is much to clean as there are many of my brothers who are sick.$BThis does not seem like a good idea to me， but if he needs to go， we will gladly follow him to the bottom of the sea.\\r\\n\\r\\nLet us hope that it does not come to that.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3572 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3572,'zhTW','Day Three：\\r\\n\\r\\nThe sea lashes the ship very heavily.$BThe captain had us take down the sails.$BWe are like a child\'s toy in the middle of gigantic waves.\\r\\n\\r\\nI may not like the ocean， but I kept my food down today like a true warrior.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3573 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3573,'zhTW','Day Four：\\r\\n\\r\\nThere are two small islands on the horizon.$BThe captain says that we will sail just past them.$BHe does not want to stop.$BThere is an edge to his voice that I do not like.$BIt sounds like fear.\\r\\n\\r\\nThere was much to do…… what？$BThere are sounds of explosions outside.$BI am going above deck to see what it is.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3574 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3574,'zhTW','Day ？？：\\r\\n\\r\\nI washed up on the rocky shore of an island.$BIt must be one of the two that I saw before.$BMost of my brothers are dead.$BThere is no sign of our special cargo.$BI fear the worst and cannot believe my thoughts.\\r\\n\\r\\nI do not know how many days have passed.$BOne， possibly two？$BSurely not more.$BThe Alliance cowards came at us， hiding from behind the larger of the two islands.$BThere were too many of them， though we might have sunk one.\\r\\n\\r\\nI saw another ship sail right through the battle and get torn apart.$BGoblins， I think.$BFools！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3575 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3575,'zhTW','Day ？？and one：\\r\\n\\r\\nWe have a makeshift camp atop the island.$BAggra has asked me to look for other survivors on the western shore.$BKilag is to take a small group across the top looking for Alliance.$BAlready a few have attacked us.$BThey will not stop coming until they are all dead.$BOr we are.\\r\\n\\r\\nThere are sounds of goblins off in the distance， and I can see the wreckage of their ship.$BThey are noisy.$BI will watch them later.$BFirst， I have found a cavern and strange sounds like animals and mining coming from within it.\\r\\n\\r\\nI will investigate.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3576 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3576,'zhTW','Attn：Mrs. Gadgetspring$B$BThe industrial——strength laxative agent you requested is enclosed. My condolences on the fate of Mr. Blimo Gadgetspring after his encounter with the cliff giant. I\'m curious why you\'re opting for a laxative in an effort to recover him， as opposed to some sort of vomit——inducing agent？It seems to me you\'re doing Mr. Gadgetspring a disservice. Good luck with your endeavor！$B$B——Lomac Gearstrip',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3577 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3577,'zhTW','Welcome to the Secret Lab， Azshara\'s most engaging new tourist destination！<br /><br /><br />Have you ever wondered where secrets come from？<br /><br /><br />Deep in the resource——rich forests of scenic Azshara， goblin scientists are hard at work inventing the secrets of tomorrow for you to enjoy today！For just a small up——front fee you and the whole family can get a front——row seat and watch as skilled goblin engineers probe and taunt the very fabric of the cosmos.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3578 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3578,'zhTW','Why are we here？What makes us intelligent？How many kilo——fraps of volatile energy can we compress into a cubic ounce of dangerously explosive rocket fuel before it goes critical and unleashes a shockwave capable of tipping the planet off its axis？We can find out together. Your secret lab awaits！<br /><br /><br /><The remaining 36——pages of the brochure consist of complicated legal waivers and a gift shop ordering form.>',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3579 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3579,'zhTW','Those of us who are agile of mind， but not quite so agile of body， must find…… alternative methods of self——preservation.$BMany such people choose to pursue a career in matters magical.$B$B$N， I\'ve been observing you， and you have a mind like a steel trap.$BHowever， to thrive in this time of upheaval， a person such as yourself will need to master the arcane arts.$BAnd to master the arcane arts， you\'re going to have to talk to me.$B$BCome speak with me in Anvilmar.$BWe\'ve much to discuss.$B$B——Teegli Merrowith',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3580 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3580,'zhTW','Know this：a shaman must never demand power to do so would arouse the anger of the elements， and a shaman without the elements\' protection is nothing.$BThose that follow the path of the shaman must never forget this most vital tenet.$B$BHowever， a shaman that works in a respectful union with the elements wields a power rivaled by few.$BIf you feel you have the humility to do so， come visit with me in Anvilmar.$BI will teach you——much like I myself was taught——how to work with the elements of fire， earth， wind， water， and the wild.$B$B~Teo Hammerstorm',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3581 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3581,'zhTW','\\"Roleplaying\\"\\n\\nGood roleplaying skills are essential. No Genius Gnomish gal wants a giant bore. Regale her with tales of your future cross——continental adventures：\\n\\n$B\\"You and me， babe， we\'re gonna fly to Kalimdor， etch our names into the side of Teldrassil and spend the rest of our lives swinging from the trees in Un\'goro Crater.\\"\\n\\n\\"Storytelling\\"\\n\\nShare stores of your exciting future together！The more implausible， the better. Nothing gets a Gnomish girl excited like an ambitious plan. It also makes for great conversation starters！\\n\\n$B\\"With our brilliant minds combined， we could retake Gnomeregan. …… why haven\'t we retaken Gnomeregan anyways？\\"',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3582 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3582,'zhTW','\\"Teasing\\"\\n\\nTeasing is the art of making fun of a woman in a humorous way. Be careful， you can easily go too far. Calling her a \\"Goblin Ganking Gnat\\">will leave you walking home wearing that Green Gordok Grog you just bought. Try something a bit more subtle. \\n\\nIf she acts childish and refuses to stop jumping onto tables in the middle of the bar try：\\n\\n\\"I hear there\'s an opening for star entertainer at the Stormwind orphanage.\\"\\n\\nIf she won\'t stop talking about herself playfully try：\\n\\n\\"Where\'s your off switch？\\"\\n\\nIMPORTANT NOTE：Gnomish girls do NOT have an off switch. Attempting to find it may result in the loss of life， limbs or wallet.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3583 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3583,'zhTW','Are your tastes more exotic？\\nDo you desire someone a little out of this world？\\nAre hooves your thing， but succubi a little too much for you？\\n\\nRead on， my friend……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3584 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3584,'zhTW','I\'d just arrived off the boat to Azuremyst when I stopped a group of Draenei dames around the ripe young age of 230. They were laughing and having a great time. What luck， still on the docks and I\'d found exactly the type of fun， energetic Draenei women I wanted to meet on this trip. \\n\\nAt first a bit anxious， I breathed deeply and reminded myself， \\"they too are here in Azeroth on vacation， looking to meet new people and have a great time.\\"\\n\\nSure enough， they were delighted to see one devilishly charming Gnome like myself in the Exodar. It even turned out we were both staying near the Vault of Lights. We exchanged deep， penetrating glances into each others eyes， promising to meet again near A\'dal later that night. ',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3585 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3585,'zhTW','The next day， I met another beautiful Draenei woman——the gleam of her horns gave only the gentlest of glimpses into her refined tastes. I asked why she was visiting the Exodar， when in shock， she told me she wasn\'t visiting——she lived here. \\n\\nThe words I spoke to myself before returned to my mind：\\n\\n\\"She is on vacation， looking to meet amazing people and have a great time.\\"$B\\nI had it all wrong， she wasn\'t on vacation at all！Then suddenly， the grinding gears of my mind clicked：$BI\'d been claiming to myself that they were so receptive because they were on vacation. What a gnollish excuse！\\n\\nI\'m a fun， interesting guy who any sensible minded girl would love to group with， on vacation or not！Now when I meet Draenei girls， I remind myself of the simple truth：\\n\\n\\"She too is looking to meet people and have a great time.\\"',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3586 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3586,'zhTW','The following 497 pages of this dictionary consistent entirely of oddly angled pictures taken from a Super Snapper FX 2000. ',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3587 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3587,'zhTW','How to date a Dwarven woman：\\n\\n1. Ask her to buy you a drink.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3588 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3588,'zhTW','Let\'s be honest. Since the end of the Third War， Night Elf girls have heard it all.$BIn fact， they\'d already heard it all long before you or I was born. \\n\\nIf you want to engage the mind of a Night Elf girl， you\'re going to have to stand out. Sure， we\'ve all heard the tales of Night Elf lasses dancing on mailboxes and stripping to pay for Nightsaber training. True or not， if you want to light that lovely lady\'s lips up with a smile， you gotta be unique， memorable and confident. \\n\\nStart off by showing that you\'re looking for more than a gal with looks. Sure， she can bounce， she can dance， but can she hold a decent conversation？$BDoes she even understand the proper use of a samophlange？Does she know how to have a fun time？\\n\\nThere\'s nothing worse than bringing a Night Elf to a party， only to watch her stand awkwardly by herself， breaking conversation only to lament the loss of her Highborne sister during the War of the Ancients.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3589 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3589,'zhTW','There\'s nothing like wooing the heart of a human girl. Infinitely forgiving， endlessly caring and fantastically fun， human girls have been the downfall of countless heroes throughout the ages.（See Chapter 3：\\"Jaina Proudmoore and the men who loved her\\"）\\n\\nHowever， generation after generation has proven it takes something more than just money， looks or an epic suit of armor to attract the woman of your dreams. Not even the power of Gnomish invention can help you here. \\n\\nTo truly charm the heart of another， you should possess these qualities.\\n\\n* Be Fun & Friendly\\n* Be a Challenge\\n* Be a Man\\n\\n',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3590 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3590,'zhTW','Be Fun & Friendly\\n\\nEver have at friend who shows up at your house and brings everybody down？Yep. Everyone does. Does he get invited back to the parties？Not unless he\'s bringing the ale. If you want to be an attractive person， live an attractive lifestyle. \\n\\nYou\'ll find that the more you enjoy socializing with others， the more they will enjoy socializing with you！\\n\\nThere\'s no faster way to ruin a girl\'s night than bringing in that needy， apologetic vibe. Let it go， embrace the fun and your confidence will soar.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3591 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3591,'zhTW','Be a Challenge\\n\\nToo many Gnomes these days walk with their head slung low， shuffling along sadly from tavern to tavern， hopelessly holding on these limiting beliefs that no human girl would ever want them. They rush into the tavern， shower her with compliments and free drinks， then go home dejected. \\n\\nWell， let me be the first to tell you， friend， when you give your self away so cheaply， you diminsh the value of your unique， exquisite personality. You\'ve been told by society that you are not the prize， that women will never acknowledge you， that you must beg for love and attention.\\n\\nThey are wrong. Don\'t give your affection away so freely. Instead of asking yourself， \\"Does she like me？\\">ask yourself instead， \\"Do I like her？\\">\\n\\nChallenge her——show her you\'re looking for a girl who offers more than a pretty face. If she can\'t keep up with your life， move on. If she shows she\'s got something to offer， you\'re at the beginning of a beautiful thing. ',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3592 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3592,'zhTW','Be a Man\\n\\nIn an age where we\'ve been banished from our homes， forced to fight for our very survival and faced down horrors never before known to Azeroth， you would think that the nature of manhood would be better understood. \\n\\nSadly， the art of masculinity has been lost， washed away in the glitz and glamor of battle. However， all is not lost！With practice and confidence， you can come back in touch with yourself. \\n\\nOnce you\'ve met the human girl of your dreams and she\'s shown herself to be worthy of your affections：\\n\\n* Take the lead——show her everything that is beautiful about your world\\n* Hold her hand——develop a close， affectionate relationship\\n* Show respect——for yourself， for her and for the world around you\\n\\nAbove all：\\n\\n* Be responsible\\n',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3593 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3593,'zhTW','Troubleshooting\\n\\nWhile everything doesn\'t always go the way you expect， that\'s what make life unpredictable and exciting. However， there\'s a few tips to help you a long way in improving your life. Here\'s some common blunders：\\n\\n* Don\'t chase\\n* Don\'t be needy\\n* Don\'t get stuck on someone who dislikes you\\n\\nThese all stem from a core belief that women you must have the woman you\'re talking to right now. Break free——there\'s many women out there in this beautiful world and if one doesn\'t work out， let go. You\'ll find you become more attractive the less clingy you are. \\n',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3594 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3594,'zhTW','<Crawgol\'s handwriting is large and uneven， little better than a childlike scrawl.>$B$BThe sillu——scilla——<Several misspellings are crossed out> silithid are bug——type animals， not vegetables（at least without a fight）. They live in the under the ground， except when they are not. Some of them fly？（I think）.$B$BThey taste REAL BAD.$B$BMost silithid are made of bug parts. They have between none and eightish legs（depending on how they died？）',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3595 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3595,'zhTW','Burning makes them die. They have shells（called &#65533cara pieces&#65533 because they are made from cara obviously）that can\'t be stabbed unless you do it hard.$B$BThey can dig fast but I don\'t know how fast because they dig in the dirt.$B$BTHE ORIGIN OF THE SILITHID$B$BAlmost all silithid come from holes， usually in the ground.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3596 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3596,'zhTW','結合了五大龍群的意志來鑄造稜彩之劍確實是很罕見的。而這些武器中最卓越的就是奎爾塞拉與奎爾德拉這一對劍。$B$B在龍後阿萊克斯塔薩的智慧下，她將這兩把劍分別送給了艾澤拉斯的精靈族。奎爾塞拉由一位英勇的卡多雷戰士所持有，而奎爾德拉則交付給奎爾多雷的勇士。$B$B兩把劍都在不同的持有者手中流傳，讓它的魔法來強化持劍者的力量……',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3597 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3597,'zhTW','你必須前往銀色領地的最上層會見奧術師泰巴林。他會將一本彌足珍貴的書籍託付給你。請謹慎行事，同時用你的生命來守護這本書。儘快將它帶到奎爾德拉之眠交給卡萊迪斯·亮矛吧。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3598 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3598,'zhTW','你必須前往骯髒野獸旅店會見魔導師哈瑟爾。他會將一本彌足珍貴的書籍託付給你。請謹慎行事，同時用你的生命來守護這本書。儘快將它帶到奎爾德拉之眠交給麥雷昂·陽炎吧。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3599 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3599,'zhTW','Emperor Thaurissan，\\n$B$BBelow is my account of my most recent finding here in Un\'Goro Crater.$BAfter the Cataclysm hit， I stopped my current project and began sweeping the Crater for new potential dig sites.$BCuriously， the Crater wasn\'t hard hit by the Cataclysm， but I did find what appeared to be a monstrous mandible peeking out of the ground in Terror Run！',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3600 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3600,'zhTW','It appears to be an ancestor of the dinosaurs that live here.$BI\'ve spent the last several weeks digging it out， and it has been my most exciting dig yet.$BBy my calculations， this beast must be nearly 300 feet long， from tip to tail.$BThat\'s longer than some of the largest dragons， and FAR larger than any dino that currently exists here in the Crater.',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3601 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3601,'zhTW','The going has been slow， mainly because I\'ve needed to cover up my work behind me.$BThat blasted goblin， Nilminer， still has cronies digging in the area， and I mustn\'t risk any news of this discovery leaking before I send my final results back to Blackrock Mountain.$BThis may be the key piece of information that tells us what the Titans were doing in Un\'Goro！$B$BRegards，$B$BDurrin Direshovel',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3602 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3602,'zhTW','第214586日：$B小綠人帶了更多人來，他們彼此指著，然後開始打了起來！$B$B我縮減我的看守職責，躲回殿堂中以策安全，但我帶了很多他們的小東西回來，免得我這段時間太無聊。$B——阿爾卡馮$B$B第214620日：$B情況越來越糟。我不確定造物者希望我怎麼做。我試著在殿堂中待著，那些暴力的傢伙一天闖進來好幾次。他們拿走了我的小東西。$B——阿爾卡馮',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3603 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3603,'zhTW','第2147021日：$B我的兄弟們回來了！結果是他們睡在其他關閉的殿堂中。$B$B我有點不高興他們放我一個人做所有的看守工作，不過我還是跟他們分享了我那些閃亮亮的小東西，畢竟我實在厭倦了一個人還有老是被攻擊。$B——阿爾卡馮$B$B第2147060日：$B暴力的小人開始攻擊我的兄弟們，真糟糕。不過他們現在很少來煩我了，這是不糟糕的。$B$B我想那些傢伙大概是想要我送給他們的閃亮小東西。我感覺好有罪惡感。$B——阿爾卡馮',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3604 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3604,'zhTW','作為被遺忘者，我們同巫妖王作戰，我們同聯盟作戰……某些時候我們還得和部落的盟友們爭鬥。$B我們種族人數很少，我們面臨著極大的困難……但我們必將生存下來並取得勝利。$B$B作為一名獵人，你會在不遠的將來做這些事情，拿著弓，身邊有你的動物夥伴。$B你的力量並非來自玄妙的巫術和虛無縹緲的力量，而是來自於你在陸地上生存的能力。$B$B獵人之路就在你的面前。$B$B從我這裡開始，你的訓練導師。$B$B它會在哪裡結束……我們尚未知曉。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3605 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3605,'zhTW','獻給在冰凍荒原與天災軍團作戰而喪生的勇士們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3608 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3608,'zhTW','給所有血色十字軍的軍官與士兵的緊急通知：$B天災軍團的間諜莉莉安·沃斯從我們的監獄裡逃走了。$B她是高度危險人物，見到後立即擊殺。$B她已經殺掉了我們15個人。$B沒有受傷的。$B不要試圖抓住她。$B如果你試圖活捉，你的結局只有一個：死亡。$B她是我們十字軍的敵人，必須立即消滅。$B$B擊殺者能獲得高階祭司的1000金幣獎勵。$B如果有問題，向你的上級詢問。$B$B~BV',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3610 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3610,'zhTW','其他人不瞭解我們。$B他們假裝與我們相處得很融洽，但並不是。$B哪怕是術士都害怕我們。$B$B因為我們瞭解彼此。$B獸人法師聯盟！$B我和你$B阿爾法……好吧無論你叫什麼！$B哈哈哈！$B$B我們會讓他們看看我們的能耐。$B來找我，我會和你分享一些我已經掌握的奧術秘訣。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3611 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3611,'zhTW','當火焰吞噬艾澤拉斯，你會在哪裡？$B$B我們知道沒有人喜歡老是想著逼近的末日，但是考慮之後的發展仍是必須的。$B$B我們的賢者們預言了末日的來臨，只有做好準備的人才能活下來。我們可以幫你在清洗世界敗類的狂野火焰中生存下來。也該是尋找心靈寧靜的時候了，不是嗎？',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3612 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3612,'zhTW','你一定聽過“好景不常在”這句話，而你在艾澤拉斯的生活也是如此。再過不久，當元素重返來奪回它們與生俱來的權利，整個世界就會陷入混亂。$B$B但是你不用害怕，因為在這種痛苦的時刻，你不是非死不可。我們可以幫你昇華到新的生活方式，超越死亡，超越恐懼，甚至超越凡人無能為力的境況。今天就加入我們吧。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3613 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3613,'zhTW','我們活在動盪的年代。戰爭、侵略和饑荒橫掃了整個世界，但真正的考驗尚未來臨：艾澤拉斯的終結。$B$B你要怎樣面對你珍視的一切被摧毀？答案是你不需要。帶著你的朋友和家庭來我們的聚會並跟著我們一起學習如何在末日中生存下來。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3614 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3614,'zhTW','奧格瑪的市民們，提防滿街頭的占卜師和先知，不要被他們的狂歡所吸引——他們只是想在我們真正敵人來臨前削弱我們。',0);
DELETE FROM `page_text_locale` WHERE `ID` = 3622 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3622,'zhTW','需要大芒果文字',12340);
